const EXERCISES=[{"id":"0001","name":"3/4 sit-up","category":"waist","equipment":"body weight","instruction_steps":{"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors","lower back"],"target":"abs","image":"images/0001-2gPfomN.jpg","gif_url":"videos/0001-2gPfomN.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0002","name":"45° side bend","category":"waist","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart and your arms extended straight down by your sides.","Keeping your back straight and your core engaged, slowly bend your torso to one side, lowering your hand towards your knee.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/0002-Hy9D21L.jpg","gif_url":"videos/0002-Hy9D21L.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0003","name":"air bike","category":"waist","equipment":"body weight","instruction_steps":{"en":["Lie flat on your back with your hands placed behind your head.","Lift your legs off the ground and bend your knees at a 90-degree angle.","Bring your right elbow towards your left knee while simultaneously straightening your right leg.","Return to the starting position and repeat the movement on the opposite side, bringing your left elbow towards your right knee while straightening your left leg.","Continue alternating sides in a pedaling motion for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0003-1ZFqTDN.jpg","gif_url":"videos/0003-1ZFqTDN.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1512","name":"all fours squad stretch","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Start on all fours with your hands directly under your shoulders and your knees directly under your hips.","Extend one leg straight back, keeping your knee bent and your foot flexed.","Slowly lower your hips towards the ground, feeling a stretch in your quads.","Hold this position for 20-30 seconds.","Switch legs and repeat the stretch on the other side."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"quads","image":"images/1512-qBcKorM.jpg","gif_url":"videos/1512-qBcKorM.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0006","name":"alternate heel touchers","category":"waist","equipment":"body weight","instruction_steps":{"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Extend your arms straight out to the sides, parallel to the ground.","Engaging your abs, lift your shoulders off the ground and reach your right hand towards your right heel.","Return to the starting position and repeat on the left side, reaching your left hand towards your left heel.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/0006-qaZVsGk.jpg","gif_url":"videos/0006-qaZVsGk.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0007","name":"alternate lateral pulldown","category":"back","equipment":"cable","instruction_steps":{"en":["Sit on the cable machine with your back straight and feet flat on the ground.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Lean back slightly and pull the handles towards your chest, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","rhomboids"],"target":"lats","image":"images/0007-4IKbhHV.jpg","gif_url":"videos/0007-4IKbhHV.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1368","name":"ankle circles","category":"lower legs","equipment":"body weight","instruction_steps":{"en":["Sit on the ground with your legs extended in front of you.","Lift one leg off the ground and rotate your ankle in a circular motion.","Perform the desired number of circles in one direction, then switch to the other direction.","Repeat with the other leg."]},"muscle_group":"ankle stabilizers","secondary_muscles":["ankle stabilizers"],"target":"calves","image":"images/1368-uL9CsKm.jpg","gif_url":"videos/1368-uL9CsKm.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3293","name":"archer pull up","category":"back","equipment":"body weight","instruction_steps":{"en":["Start by hanging from a pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Engage your core and pull your shoulder blades down and back.","As you pull yourself up, bend one arm and bring your elbow towards your side, while keeping the other arm straight.","Continue pulling until your chin is above the bar and your bent arm is fully flexed.","Lower yourself back down with control, straightening the bent arm and repeating the movement on the other side.","Alternate sides with each repetition."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/3293-72BC5Za.jpg","gif_url":"videos/3293-72BC5Za.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3294","name":"archer push up","category":"chest","equipment":"body weight","instruction_steps":{"en":["Start in a push-up position with your hands slightly wider than shoulder-width apart.","Extend one arm straight out to the side, parallel to the ground.","Lower your body by bending your elbows, keeping your back straight and core engaged.","Push back up to the starting position.","Repeat on the other side, extending the opposite arm out to the side.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders","core"],"target":"pectorals","image":"images/3294-A9qxk2F.jpg","gif_url":"videos/3294-A9qxk2F.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2355","name":"arm slingers hanging bent knee legs","category":"waist","equipment":"body weight","instruction_steps":{"en":["Hang from a pull-up bar with your arms fully extended and your knees bent at a 90-degree angle.","Engage your core and lift your knees towards your chest, bringing them as close to your elbows as possible.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","back"],"target":"abs","image":"images/2355-uWpxD4v.jpg","gif_url":"videos/2355-uWpxD4v.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2333","name":"arm slingers hanging straight legs","category":"waist","equipment":"body weight","instruction_steps":{"en":["Hang from a pull-up bar with your arms fully extended and your legs straight down.","Engage your core and lift your legs up in front of you until they are parallel to the ground.","Hold for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","back"],"target":"abs","image":"images/2333-PXTIwgu.jpg","gif_url":"videos/2333-PXTIwgu.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3214","name":"arms apart circular toe touch (male)","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart and arms extended to the sides.","Keeping your legs straight, bend forward at the waist and reach down towards your toes with your right hand.","As you reach down, simultaneously lift your left leg straight up behind you, maintaining balance.","Return to the starting position and repeat the movement with your left hand reaching towards your toes and your right leg lifting up behind you.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps","calves"],"target":"glutes","image":"images/3214-RtyAsy1.jpg","gif_url":"videos/3214-RtyAsy1.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3204","name":"arms overhead full sit-up (male)","category":"waist","equipment":"body weight","instruction_steps":{"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Extend your arms overhead, keeping them straight.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is upright.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors","lower back"],"target":"abs","image":"images/3204-NAkmgdx.jpg","gif_url":"videos/3204-NAkmgdx.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0009","name":"assisted chest dip (kneeling)","category":"chest","equipment":"leverage machine","instruction_steps":{"en":["Adjust the machine to your desired height and secure your knees on the pad.","Grasp the handles with your palms facing down and your arms fully extended.","Lower your body by bending your elbows until your upper arms are parallel to the floor.","Pause for a moment, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/0009-PAgTVaK.jpg","gif_url":"videos/0009-PAgTVaK.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0011","name":"assisted hanging knee raise","category":"waist","equipment":"assisted","instruction_steps":{"en":["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core muscles and lift your knees towards your chest, bending at the hips and knees.","Pause for a moment at the top of the movement, squeezing your abs.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0011-03lzqwk.jpg","gif_url":"videos/0011-03lzqwk.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0010","name":"assisted hanging knee raise with throw down","category":"waist","equipment":"assisted","instruction_steps":{"en":["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your knees towards your chest, keeping your legs together.","Once your knees are at chest level, explosively throw your legs down towards the ground, extending them fully.","Allow your legs to swing back up and repeat the movement for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors","lower back"],"target":"abs","image":"images/0010-8K0w2yA.jpg","gif_url":"videos/0010-8K0w2yA.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1708","name":"assisted lying calves stretch","category":"lower legs","equipment":"assisted","instruction_steps":{"en":["Lie on your back with your legs extended.","Bend one knee and place your foot flat on the ground.","Using your hands or a towel, gently pull your toes towards your body, feeling a stretch in your calf.","Hold the stretch for 20-30 seconds.","Release the stretch and repeat on the other leg."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"target":"calves","image":"images/1708-GxDwDX0.jpg","gif_url":"videos/1708-GxDwDX0.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1709","name":"assisted lying glutes stretch","category":"upper legs","equipment":"assisted","instruction_steps":{"en":["Lie on your back with your legs extended.","Bend your right knee and place your right ankle on your left thigh, just above the knee.","Grasp your left thigh with both hands and gently pull it towards your chest.","Hold the stretch for 20-30 seconds.","Release and repeat on the other side."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"target":"glutes","image":"images/1709-yn0LjwL.jpg","gif_url":"videos/1709-yn0LjwL.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1710","name":"assisted lying gluteus and piriformis stretch","category":"upper legs","equipment":"assisted","instruction_steps":{"en":["Lie on your back with your legs extended.","Bend your right knee and place your right ankle on your left thigh, just above the knee.","Grasp your left thigh with both hands and gently pull it towards your chest.","Hold the stretch for 20-30 seconds.","Release the stretch and repeat on the other side."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"target":"glutes","image":"images/1710-RQNVT10.jpg","gif_url":"videos/1710-RQNVT10.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0012","name":"assisted lying leg raise with lateral throw down","category":"waist","equipment":"assisted","instruction_steps":{"en":["Lie flat on your back with your legs extended and your arms by your sides.","Place your hands under your glutes for support.","Engage your abs and lift your legs off the ground, keeping them straight.","While keeping your legs together, lower them to one side until they are a few inches above the ground.","Pause for a moment, then lift your legs back to the starting position.","Repeat the movement to the other side.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors","obliques"],"target":"abs","image":"images/0012-UGhRD1A.jpg","gif_url":"videos/0012-UGhRD1A.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0013","name":"assisted lying leg raise with throw down","category":"waist","equipment":"assisted","instruction_steps":{"en":["Lie flat on your back with your legs extended and your arms by your sides.","Place your hands under your glutes for support.","Engage your core and lift your legs off the ground, keeping them straight.","Raise your legs until they are perpendicular to the ground.","Lower your legs back down to the starting position.","Simultaneously, throw your legs down towards the ground, keeping them straight.","Raise your legs back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors","quadriceps"],"target":"abs","image":"images/0013-VX5YKR5.jpg","gif_url":"videos/0013-VX5YKR5.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0014","name":"assisted motion russian twist","category":"waist","equipment":"medicine ball","instruction_steps":{"en":["Sit on the ground with your knees bent and feet flat on the floor.","Hold the medicine ball with both hands in front of your chest.","Lean back slightly, engaging your abs and keeping your back straight.","Slowly twist your torso to the right, bringing the medicine ball towards the right side of your body.","Pause for a moment, then twist your torso to the left, bringing the medicine ball towards the left side of your body.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques","lower back"],"target":"abs","image":"images/0014-r7cT9YD.jpg","gif_url":"videos/0014-r7cT9YD.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0015","name":"assisted parallel close grip pull-up","category":"back","equipment":"leverage machine","instruction_steps":{"en":["Adjust the machine to your desired weight and height.","Place your hands on the parallel bars with a close grip, palms facing each other.","Hang from the bars with your arms fully extended and your feet off the ground.","Engage your back muscles and pull your body up towards the bars, keeping your elbows close to your body.","Continue pulling until your chin is above the bars.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/0015-vrhHa6D.jpg","gif_url":"videos/0015-vrhHa6D.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0016","name":"assisted prone hamstring","category":"upper legs","equipment":"assisted","instruction_steps":{"en":["Lie face down on a mat or bench with your legs fully extended.","Have a partner or use a resistance band to secure your ankles.","Engage your hamstrings and lift your legs towards your glutes, keeping your knees straight.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","lower back"],"target":"hamstrings","image":"images/0016-VedGSby.jpg","gif_url":"videos/0016-VedGSby.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1713","name":"assisted prone lying quads stretch","category":"upper legs","equipment":"assisted","instruction_steps":{"en":["Lie face down on the ground with your legs extended.","Bend your left knee and reach back with your left hand to grab your left foot or ankle.","Gently pull your left foot towards your glutes, feeling a stretch in your left quad.","Hold the stretch for 20-30 seconds, then release.","Repeat with your right leg."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"quads","image":"images/1713-YUYAMEj.jpg","gif_url":"videos/1713-YUYAMEj.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1714","name":"assisted prone rectus femoris stretch","category":"waist","equipment":"assisted","instruction_steps":{"en":["Lie face down on the ground with your legs straight.","Bend your right knee and reach back with your right hand to grab your right foot or ankle.","Gently pull your right foot or ankle towards your glutes, feeling a stretch in the front of your right thigh.","Hold the stretch for 20-30 seconds.","Release and repeat on the other side."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps"],"target":"abs","image":"images/1714-2Ryn564.jpg","gif_url":"videos/1714-2Ryn564.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0017","name":"assisted pull-up","category":"back","equipment":"leverage machine","instruction_steps":{"en":["Adjust the machine to your desired weight and height settings.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Hang with your arms fully extended and your feet off the ground.","Engage your back muscles and pull your body up towards the handles, keeping your elbows close to your body.","Continue pulling until your chin is above the handles.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/0017-kiJ4Z2K.jpg","gif_url":"videos/0017-kiJ4Z2K.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1716","name":"assisted seated pectoralis major stretch with stability ball","category":"chest","equipment":"assisted","instruction_steps":{"en":["Sit on a stability ball with your feet flat on the ground and your back straight.","Hold a stability ball with both hands and extend your arms straight out in front of you.","Slowly lower the stability ball towards your chest, feeling a stretch in your pectoral muscles.","Hold the stretch for a few seconds, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/1716-RoV1Rfa.jpg","gif_url":"videos/1716-RoV1Rfa.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1712","name":"assisted side lying adductor stretch","category":"upper legs","equipment":"assisted","instruction_steps":{"en":["Lie on your side with your legs straight and stacked on top of each other.","Bend your bottom leg slightly for stability.","Place your top foot on a stable surface, such as a bench or step.","Keeping your top leg straight, slowly lower it towards the ground, feeling a stretch in your inner thigh.","Hold the stretch for 20-30 seconds.","Return to the starting position and repeat on the other side."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"adductors","image":"images/1712-hC6oYY5.jpg","gif_url":"videos/1712-hC6oYY5.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1758","name":"assisted sit-up","category":"waist","equipment":"assisted","instruction_steps":{"en":["Sit on the edge of a bench or have someone hold your feet down.","Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/1758-aumB2IV.jpg","gif_url":"videos/1758-aumB2IV.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1431","name":"assisted standing chin-up","category":"back","equipment":"leverage machine","instruction_steps":{"en":["Adjust the machine to your desired assistance level.","Stand on the foot platform and grip the handles with an overhand grip, slightly wider than shoulder-width apart.","Keep your chest up and shoulders back, engage your core, and slightly bend your knees.","Pull your body up by flexing your elbows and driving your elbows down towards your sides.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/1431-7OeHptV.jpg","gif_url":"videos/1431-7OeHptV.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1432","name":"assisted standing pull-up","category":"back","equipment":"leverage machine","instruction_steps":{"en":["Adjust the machine to your desired weight and height settings.","Stand facing the machine with your feet shoulder-width apart.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Engage your lats and biceps, and pull yourself up towards the handles.","Pause for a moment at the top, squeezing your back muscles.","Slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/1432-f4xtKBj.jpg","gif_url":"videos/1432-f4xtKBj.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0018","name":"assisted standing triceps extension (with towel)","category":"upper arms","equipment":"assisted","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold a towel with both hands behind your head.","Keep your elbows close to your ears and your upper arms stationary.","Slowly extend your forearms upward, squeezing your triceps at the top.","Pause for a moment, then slowly lower the towel back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0018-7HcfMBP.jpg","gif_url":"videos/0018-7HcfMBP.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0019","name":"assisted triceps dip (kneeling)","category":"upper arms","equipment":"leverage machine","instruction_steps":{"en":["Adjust the machine to your desired weight and height.","Kneel down on the pad facing the machine, with your hands gripping the handles.","Lower your body by bending your elbows, keeping your back straight and close to the machine.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0019-J60bN17.jpg","gif_url":"videos/0019-J60bN17.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2364","name":"assisted wide-grip chest dip (kneeling)","category":"chest","equipment":"leverage machine","instruction_steps":{"en":["Adjust the machine to your desired height and secure your knees on the pad.","Grasp the handles with a wide grip and keep your elbows slightly bent.","Lower your body by bending your elbows until your upper arms are parallel to the floor.","Push yourself back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/2364-PnZJIrk.jpg","gif_url":"videos/2364-PnZJIrk.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3220","name":"astride jumps (male)","category":"cardio","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart.","Bend your knees and lower your body into a squat position.","Jump explosively upwards, extending your legs and arms.","While in the air, spread your legs apart and bring your arms out to the sides.","Land softly with your feet shoulder-width apart, bending your knees to absorb the impact.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"cardiovascular system","image":"images/3220-f9lVSSI.jpg","gif_url":"videos/3220-f9lVSSI.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3672","name":"back and forth step","category":"cardio","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart.","Step forward with your right foot, bending your knee and lowering your body into a lunge position.","Push off with your right foot and step back to the starting position.","Repeat the movement with your left foot, alternating legs with each step.","Continue stepping back and forth, maintaining a steady pace.","Repeat for the desired duration or number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","glutes","calves"],"target":"cardiovascular system","image":"images/3672-fNGumX0.jpg","gif_url":"videos/3672-fNGumX0.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1314","name":"back extension on exercise ball","category":"back","equipment":"stability ball","instruction_steps":{"en":["Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall or other stable surface.","Position your hands behind your head or crossed over your chest.","Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your heels.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","hamstrings"],"target":"spine","image":"images/1314-qLpO4vV.jpg","gif_url":"videos/1314-qLpO4vV.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3297","name":"back lever","category":"back","equipment":"body weight","instruction_steps":{"en":["Start by hanging from a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart.","Engage your core and pull your shoulder blades down and back.","Bend your knees and tuck them towards your chest.","Slowly lift your legs up, keeping them straight, until your body is parallel to the ground.","Hold this position for a few seconds, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms","core"],"target":"upper back","image":"images/3297-GaSzzuh.jpg","gif_url":"videos/3297-GaSzzuh.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1405","name":"back pec stretch","category":"back","equipment":"body weight","instruction_steps":{"en":["Stand tall with your feet shoulder-width apart.","Extend your arms straight out in front of you, parallel to the ground.","Cross your arms in front of your body, with your right arm over your left arm.","Interlock your fingers and rotate your palms away from your body.","Slowly raise your arms up and away from your body, feeling a stretch in your back and chest.","Hold the stretch for 15-30 seconds, then release.","Repeat on the opposite side."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","chest"],"target":"lats","image":"images/1405-chfnQnM.jpg","gif_url":"videos/1405-chfnQnM.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1473","name":"backward jump","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart.","Bend your knees slightly and jump backwards, pushing off with both feet.","Land softly on the balls of your feet, bending your knees to absorb the impact.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes","calves"],"target":"quads","image":"images/1473-SaDOwk7.jpg","gif_url":"videos/1473-SaDOwk7.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0020","name":"balance board","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Place the balance board on a flat surface.","Step onto the balance board with one foot, ensuring it is centered.","Slowly shift your weight onto the foot on the balance board, keeping your core engaged.","Maintain your balance and stability as you hold the position for a desired amount of time.","Repeat the exercise with the other foot."]},"muscle_group":"calves","secondary_muscles":["calves","hamstrings","glutes"],"target":"quads","image":"images/0020-xAySMB0.jpg","gif_url":"videos/0020-xAySMB0.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0968","name":"band alternating biceps curl","category":"upper arms","equipment":"band","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold the band with an underhand grip, palms facing up.","Keep your elbows close to your sides and slowly curl one arm up towards your shoulder, squeezing your biceps at the top.","Lower the arm back down to the starting position and repeat with the other arm.","Continue alternating arms for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0968-3omWx6P.jpg","gif_url":"videos/0968-3omWx6P.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0969","name":"band alternating v-up","category":"waist","equipment":"band","instruction_steps":{"en":["Lie flat on your back with your legs straight and your arms extended overhead, holding the band.","Engage your abs and lift your legs and upper body off the ground simultaneously, reaching your hands towards your toes.","As you lower your legs and upper body back down, switch the position of your legs, crossing one over the other.","Repeat the movement, alternating the position of your legs with each repetition.","Continue for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0969-ztAa1RK.jpg","gif_url":"videos/0969-ztAa1RK.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0970","name":"band assisted pull-up","category":"back","equipment":"band","instruction_steps":{"en":["Attach the band to a pull-up bar or sturdy anchor point.","Step onto the band and grip the bar with your palms facing away from you, hands slightly wider than shoulder-width apart.","Hang with your arms fully extended, keeping your core engaged and your shoulders down and back.","Pull your body up towards the bar by squeezing your shoulder blades together and driving your elbows down towards your hips.","Continue pulling until your chin is above the bar, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/0970-r1XNRYB.jpg","gif_url":"videos/0970-r1XNRYB.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0971","name":"band assisted wheel rollerout","category":"waist","equipment":"band","instruction_steps":{"en":["Kneel on the floor and hold the handles of the band with both hands, palms facing down.","Place the band on the ground in front of you and position your hands shoulder-width apart.","Engage your core and slowly roll the wheel forward, extending your body as far as you can while maintaining control.","Pause for a moment at the furthest point, then slowly roll the wheel back towards your knees to return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"lower back","secondary_muscles":["lower back"],"target":"abs","image":"images/0971-zhF9lW4.jpg","gif_url":"videos/0971-zhF9lW4.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1254","name":"band bench press","category":"chest","equipment":"band","instruction_steps":{"en":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the band handles with an overhand grip, slightly wider than shoulder-width apart.","Extend your arms fully, pushing the bands away from your chest.","Slowly lower the bands back down to your chest, keeping your elbows at a 90-degree angle.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1254-khlHMqs.jpg","gif_url":"videos/1254-khlHMqs.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0980","name":"band bent-over hip extension","category":"upper legs","equipment":"band","instruction_steps":{"en":["Attach the band to a sturdy anchor point at ankle height.","Stand facing away from the anchor point with your feet shoulder-width apart.","Step back to create tension in the band, keeping your knees slightly bent.","Hinge at the hips and lean forward, maintaining a neutral spine.","Extend your right leg straight back, squeezing your glutes at the top.","Lower your right leg back down and repeat with the left leg.","Continue alternating legs for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"target":"glutes","image":"images/0980-wSScovH.jpg","gif_url":"videos/0980-wSScovH.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0972","name":"band bicycle crunch","category":"waist","equipment":"band","instruction_steps":{"en":["Lie flat on your back with your hands behind your head and your knees bent.","Lift your feet off the ground and bring your right knee towards your chest while simultaneously twisting your torso to bring your left elbow towards your right knee.","Straighten your right leg while bringing your left knee towards your chest and twisting your torso to bring your right elbow towards your left knee.","Continue alternating the twisting motion, as if you are pedaling a bicycle, while keeping your core engaged throughout the movement.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors","obliques"],"target":"abs","image":"images/0972-tZkGYZ9.jpg","gif_url":"videos/0972-tZkGYZ9.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0974","name":"band close-grip pulldown","category":"back","equipment":"band","instruction_steps":{"en":["Attach the band to a high anchor point, such as a pull-up bar or sturdy beam.","Stand facing the anchor point and grab the band with an underhand grip, hands shoulder-width apart.","Step back to create tension in the band, keeping your feet hip-width apart.","Engage your core and keep your back straight as you pull the band down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the band back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/0974-DptumMx.jpg","gif_url":"videos/0974-DptumMx.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0975","name":"band close-grip push-up","category":"upper arms","equipment":"band","instruction_steps":{"en":["Place a band around your upper arms, just above the elbows.","Assume a push-up position with your hands directly under your shoulders and your body in a straight line from head to heels.","Bend your elbows and lower your chest towards the ground, keeping your elbows close to your sides.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0975-ufaxB52.jpg","gif_url":"videos/0975-ufaxB52.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0976","name":"band concentration curl","category":"upper arms","equipment":"band","instruction_steps":{"en":["Sit on a bench or chair with your legs spread apart and your feet flat on the ground.","Hold one end of the band in your hand and step on the other end with your foot on the same side.","Lean forward slightly and rest your elbow on the inside of your thigh, just above the knee.","With your palm facing up, slowly curl your hand towards your shoulder, keeping your upper arm stationary.","Pause for a moment at the top, then slowly lower your hand back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0976-kmVVAfu.jpg","gif_url":"videos/0976-kmVVAfu.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3117","name":"band fixed back close grip pulldown","category":"back","equipment":"band","instruction_steps":{"en":["Attach the band to a fixed point above you, such as a pull-up bar or sturdy beam.","Sit down on a bench or chair facing the band, with your feet flat on the ground and your knees bent.","Grasp the band with a close grip, palms facing towards you.","Keep your back straight and engage your core.","Pull the band down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, feeling the contraction in your lats.","Slowly release the band back to the starting position, maintaining control throughout the movement.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/3117-4LoWllp.jpg","gif_url":"videos/3117-4LoWllp.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3116","name":"band fixed back underhand pulldown","category":"back","equipment":"band","instruction_steps":{"en":["Attach the band to a sturdy anchor point above your head.","Stand facing the anchor point with your feet shoulder-width apart.","Grasp the band with an underhand grip, hands slightly wider than shoulder-width apart.","Step back to create tension in the band, keeping your arms fully extended.","Engage your core and squeeze your shoulder blades together.","Pull the band down towards your chest, leading with your elbows.","Pause for a moment at the bottom of the movement, feeling the contraction in your lats.","Slowly release the tension in the band and return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","rhomboids","rear deltoids"],"target":"lats","image":"images/3116-ZH68exZ.jpg","gif_url":"videos/3116-ZH68exZ.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0977","name":"band front lateral raise","category":"shoulders","equipment":"band","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing down.","Keep your arms straight and lift the band up in front of you until your arms are parallel to the ground.","Pause for a moment at the top, then slowly lower the band back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"traps","secondary_muscles":["traps","upper back"],"target":"delts","image":"images/0977-sTg7iys.jpg","gif_url":"videos/0977-sTg7iys.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0978","name":"band front raise","category":"shoulders","equipment":"band","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing down.","Keep your arms straight and slowly raise them forward until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0978-TFA88iB.jpg","gif_url":"videos/0978-TFA88iB.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1408","name":"band hip lift","category":"upper legs","equipment":"band","instruction_steps":{"en":["Lie on your back with your knees bent and feet flat on the ground.","Place a resistance band just above your knees.","Engage your glutes and core muscles.","Press your heels into the ground and lift your hips off the floor, squeezing your glutes at the top.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps"],"target":"glutes","image":"images/1408-E4R8Hz1.jpg","gif_url":"videos/1408-E4R8Hz1.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0979","name":"band horizontal pallof press","category":"waist","equipment":"band","instruction_steps":{"en":["Attach the band to a sturdy anchor point at waist height.","Stand perpendicular to the anchor point with your feet shoulder-width apart.","Grasp the band handle with both hands and step away from the anchor point to create tension in the band.","Bring your hands to your chest, keeping your elbows bent and close to your body.","Engage your core and maintain a stable stance.","Extend your arms straight out in front of you, pushing the band away from your body.","Hold the extended position for a few seconds, focusing on maintaining tension in your core.","Slowly bring your hands back to your chest, resisting the pull of the band.","Repeat for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques","glutes"],"target":"abs","image":"images/0979-9pa4H5m.jpg","gif_url":"videos/0979-9pa4H5m.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0981","name":"band jack knife sit-up","category":"waist","equipment":"band","instruction_steps":{"en":["Lie flat on your back with your legs straight and your arms extended overhead, holding the band.","Engage your abs and lift your legs and upper body simultaneously, bringing your hands towards your feet.","Pause for a moment at the top, then slowly lower your legs and upper body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0981-KCBKjma.jpg","gif_url":"videos/0981-KCBKjma.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0983","name":"band kneeling one arm pulldown","category":"back","equipment":"band","instruction_steps":{"en":["Attach the band to a sturdy anchor point above your head.","Kneel down and hold the band with one hand, palm facing down.","Extend your arm fully overhead, keeping your elbow slightly bent.","Engage your lat muscles and pull the band down towards your side, bringing your elbow towards your ribcage.","Pause for a moment at the bottom, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},"muscle_group":"biceps","secondary_muscles":["biceps","rhomboids"],"target":"lats","image":"images/0983-pmnrOp0.jpg","gif_url":"videos/0983-pmnrOp0.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0985","name":"band kneeling twisting crunch","category":"waist","equipment":"band","instruction_steps":{"en":["Attach the band to a sturdy anchor point at waist height.","Kneel down facing away from the anchor point and hold the band with both hands, keeping your elbows bent and close to your sides.","Engage your abs and slowly twist your torso to one side, bringing your hands towards your opposite hip.","Pause for a moment, then slowly return to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/0985-225x2Vd.jpg","gif_url":"videos/0985-225x2Vd.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0984","name":"band lying hip internal rotation","category":"upper legs","equipment":"band","instruction_steps":{"en":["Lie on your back with your legs straight and a resistance band looped around your feet.","Bend your knees and bring them towards your chest, keeping your feet together.","Slowly rotate your knees outwards, away from each other, while keeping your feet together.","Pause for a moment at the end of the rotation, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps"],"target":"glutes","image":"images/0984-vIICElP.jpg","gif_url":"videos/0984-vIICElP.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1002","name":"band lying straight leg raise","category":"waist","equipment":"band","instruction_steps":{"en":["Lie flat on your back with your legs straight and your feet together.","Place the band around the arches of your feet and hold the ends of the band with your hands.","Engaging your abs, lift both legs off the ground until they are perpendicular to the floor.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/1002-bbLR7fB.jpg","gif_url":"videos/1002-bbLR7fB.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0986","name":"band one arm overhead biceps curl","category":"upper arms","equipment":"band","instruction_steps":{"en":["Stand with your feet shoulder-width apart and place one end of the band under your foot.","Hold the other end of the band with your arm fully extended overhead, palm facing forward.","Keeping your upper arm stationary, curl your forearm towards your shoulder, squeezing your biceps.","Pause for a moment at the top, then slowly lower your forearm back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"forearms","secondary_muscles":["forearms","shoulders"],"target":"biceps","image":"images/0986-UNAB8ak.jpg","gif_url":"videos/0986-UNAB8ak.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0987","name":"band one arm single leg split squat","category":"upper legs","equipment":"band","instruction_steps":{"en":["Stand with your feet hip-width apart and place a resistance band around your ankles.","Extend one leg forward and rest the top of your foot on a bench or step behind you.","Hold onto a support with one hand for balance.","Bend your standing leg and lower your body down into a squat position, keeping your knee in line with your toes.","Push through your heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."]},"muscle_group":"glutes","secondary_muscles":["glutes","hamstrings"],"target":"quads","image":"images/0987-arsYEd3.jpg","gif_url":"videos/0987-arsYEd3.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0988","name":"band one arm standing low row","category":"back","equipment":"band","instruction_steps":{"en":["Attach the band to a stable anchor point at waist height.","Stand facing the anchor point with your feet shoulder-width apart.","Hold the band with one hand, palm facing inward, and step back to create tension in the band.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Pull the band towards your waist, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release the band back to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},"muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"target":"upper back","image":"images/0988-km0sQC0.jpg","gif_url":"videos/0988-km0sQC0.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0989","name":"band one arm twisting chest press","category":"chest","equipment":"band","instruction_steps":{"en":["Attach the band to a sturdy anchor point at chest height.","Stand with your side facing the anchor point and grab the band with one hand.","Step away from the anchor point to create tension in the band.","Position your feet shoulder-width apart and slightly bend your knees.","Bring your hand holding the band across your body, towards the opposite shoulder.","While maintaining tension in the band, push your hand forward and away from your body, extending your arm.","Slowly return to the starting position and repeat for the desired number of repetitions.","Switch sides and repeat the exercise with the other hand."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/0989-c16nYGA.jpg","gif_url":"videos/0989-c16nYGA.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0990","name":"band one arm twisting seated row","category":"back","equipment":"band","instruction_steps":{"en":["Sit on a bench or chair with your feet flat on the ground and your back straight.","Hold the band with one hand and extend your arm fully in front of you.","Keeping your back straight, pull the band towards your body by bending your elbow and squeezing your shoulder blades together.","At the same time, twist your torso towards the side of the pulling arm.","Pause for a moment at the top, then slowly release the tension in the band and return to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]},"muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"target":"upper back","image":"images/0990-DKBwJrL.jpg","gif_url":"videos/0990-DKBwJrL.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0991","name":"band pull through","category":"upper legs","equipment":"band","instruction_steps":{"en":["Attach a resistance band to a sturdy anchor point at ground level.","Stand facing away from the anchor point with your feet shoulder-width apart.","Step forward to create tension in the band, keeping your knees slightly bent.","Hinge at the hips and push your glutes back, maintaining a slight bend in your knees.","Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.","Drive your hips forward and squeeze your glutes to return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"target":"glutes","image":"images/0991-VtTbiP3.jpg","gif_url":"videos/0991-VtTbiP3.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0992","name":"band push sit-up","category":"waist","equipment":"band","instruction_steps":{"en":["Attach the band securely to a stable anchor point.","Lie flat on your back with your knees bent and feet flat on the ground.","Hold the band with both hands and extend your arms straight up towards the ceiling.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","chest"],"target":"abs","image":"images/0992-zFzbBfL.jpg","gif_url":"videos/0992-zFzbBfL.gif","attribution":"���� Gym visual — https://gymvisual.com/"},{"id":"0993","name":"band reverse fly","category":"shoulders","equipment":"band","instruction_steps":{"en":["Attach the band to a stationary object at chest height.","Stand with your feet shoulder-width apart and hold the band with both hands in front of you.","Keep your arms straight and lift them out to the sides until they are parallel to the ground.","Squeeze your shoulder blades together at the top of the movement.","Slowly lower your arms back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"upper back","secondary_muscles":["upper back","trapezius"],"target":"delts","image":"images/0993-sTfvVsG.jpg","gif_url":"videos/0993-sTfvVsG.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0994","name":"band reverse wrist curl","category":"lower arms","equipment":"band","instruction_steps":{"en":["Sit on a bench or chair with your feet flat on the ground.","Hold the band with an overhand grip, palms facing down, and wrap it around your fingers.","Rest your forearms on your thighs, with your wrists hanging off the edge.","Slowly curl your wrists upward, squeezing your forearms.","Pause for a moment at the top, then slowly lower your wrists back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"forearms","image":"images/0994-Ezpnw9d.jpg","gif_url":"videos/0994-Ezpnw9d.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0996","name":"band seated hip internal rotation","category":"upper legs","equipment":"band","instruction_steps":{"en":["Sit on a chair or bench with your back straight and feet flat on the ground.","Place a resistance band around your thighs, just above your knees.","Keep your knees bent at a 90-degree angle and your feet shoulder-width apart.","Engage your glutes and slowly rotate your knees outward, pushing against the resistance of the band.","Pause for a moment at the end of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps"],"target":"glutes","image":"images/0996-9gbyYKk.jpg","gif_url":"videos/0996-9gbyYKk.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1011","name":"band seated twist","category":"waist","equipment":"band","instruction_steps":{"en":["Sit on the ground with your legs extended in front of you and your back straight.","Wrap the band around your waist and hold the ends with both hands.","Engage your abs and slowly twist your torso to one side, keeping your back straight and your feet on the ground.","Pause for a moment at the end of the twist, then slowly return to the starting position.","Repeat the twist to the other side.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/1011-S1JXDAG.jpg","gif_url":"videos/1011-S1JXDAG.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0997","name":"band shoulder press","category":"shoulders","equipment":"band","instruction_steps":{"en":["Stand with your feet shoulder-width apart and place the band under your feet.","Hold the band with your palms facing forward and raise your hands to shoulder height, elbows bent.","Press the band overhead, fully extending your arms.","Pause for a moment at the top, then slowly lower the band back to shoulder height.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0997-peAeMR3.jpg","gif_url":"videos/0997-peAeMR3.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1018","name":"band shrug","category":"back","equipment":"band","instruction_steps":{"en":["Stand with your feet shoulder-width apart and place the band under your feet, holding the ends with your hands.","Keep your arms straight and relaxed, and let the band hang in front of your thighs.","Engage your traps by shrugging your shoulders upward, lifting the band as high as possible.","Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"traps","image":"images/1018-trmte8s.jpg","gif_url":"videos/1018-trmte8s.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0998","name":"band side triceps extension","category":"upper arms","equipment":"band","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold the band with both hands, palms facing down.","Extend your arms straight out to the sides, keeping them parallel to the ground.","Slowly bend your elbows and bring your hands towards your shoulders, keeping your upper arms still.","Pause for a moment, then slowly extend your arms back out to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0998-obe5LMq.jpg","gif_url":"videos/0998-obe5LMq.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0999","name":"band single leg calf raise","category":"lower legs","equipment":"band","instruction_steps":{"en":["Stand with your feet hip-width apart and place the band around the ball of your left foot.","Hold onto a stable object for balance if needed.","Slowly raise your left heel off the ground, lifting your body weight onto the ball of your foot.","Pause for a moment at the top, then slowly lower your left heel back down to the starting position.","Repeat for the desired number of repetitions, then switch to the right leg."]},"muscle_group":"ankles","secondary_muscles":["ankles","feet"],"target":"calves","image":"images/0999-9JprnPh.jpg","gif_url":"videos/0999-9JprnPh.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1000","name":"band single leg reverse calf raise","category":"lower legs","equipment":"band","instruction_steps":{"en":["Stand with your feet hip-width apart and place the band around the ball of your foot.","Hold onto a stable object for balance.","Slowly raise your heel off the ground, lifting your body weight onto the ball of your foot.","Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other leg."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"calves","image":"images/1000-QsSQWbf.jpg","gif_url":"videos/1000-QsSQWbf.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1001","name":"band single leg split squat","category":"upper legs","equipment":"band","instruction_steps":{"en":["Stand with your feet hip-width apart and place a resistance band around your ankles.","Take a big step forward with your right foot and a smaller step back with your left foot.","Bend your knees and lower your body until your right thigh is parallel to the ground, keeping your left knee slightly above the ground.","Push through your right heel to return to the starting position.","Repeat on the other side."]},"muscle_group":"glutes","secondary_muscles":["glutes","hamstrings"],"target":"quads","image":"images/1001-y8bYM8w.jpg","gif_url":"videos/1001-y8bYM8w.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1004","name":"band squat","category":"upper legs","equipment":"band","instruction_steps":{"en":["Stand with your feet shoulder-width apart, with the band placed just above your knees.","Keeping your chest up and core engaged, push your hips back and bend your knees to lower into a squat position.","Make sure your knees are tracking over your toes and your weight is in your heels.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/1004-TUZLh71.jpg","gif_url":"videos/1004-TUZLh71.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1003","name":"band squat row","category":"upper legs","equipment":"band","instruction_steps":{"en":["Attach the band to a sturdy anchor point at waist height.","Stand facing the anchor point with your feet shoulder-width apart.","Hold the band handles with your palms facing each other and your arms extended in front of you.","Bend your knees and lower into a squat position, keeping your back straight and chest lifted.","From the squat position, pull the band handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps","back"],"target":"glutes","image":"images/1003-w1NOByi.jpg","gif_url":"videos/1003-w1NOByi.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1005","name":"band standing crunch","category":"waist","equipment":"band","instruction_steps":{"en":["Attach the band to a sturdy anchor point at waist height.","Stand facing away from the anchor point with your feet shoulder-width apart.","Hold the band with both hands and bring it up to your chest, keeping your elbows bent and close to your body.","Engage your abs and slowly crunch forward, bringing your chest towards your knees.","Pause for a moment at the top of the crunch, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/1005-Kzg30R7.jpg","gif_url":"videos/1005-Kzg30R7.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1022","name":"band standing rear delt row","category":"shoulders","equipment":"band","instruction_steps":{"en":["Stand with your feet shoulder-width apart and place the band under your feet.","Hold the band handles with your palms facing each other and your arms extended in front of you.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Pull the band towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids","biceps"],"target":"delts","image":"images/1022-tc5dYrf.jpg","gif_url":"videos/1022-tc5dYrf.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1007","name":"band standing twisting crunch","category":"waist","equipment":"band","instruction_steps":{"en":["Stand with your feet shoulder-width apart and place the band around your upper back, crossing it in front of your chest.","Hold the ends of the band with your hands, keeping your elbows bent and close to your sides.","Engage your abs and twist your torso to one side, bringing your elbow towards the opposite knee.","Pause for a moment, then return to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/1007-euq4pwp.jpg","gif_url":"videos/1007-euq4pwp.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1008","name":"band step-up","category":"upper legs","equipment":"band","instruction_steps":{"en":["Place a band around your thighs, just above your knees.","Stand facing a step or platform with your feet hip-width apart.","Step up onto the platform with your right foot, pushing through your heel.","Extend your left leg behind you, keeping it straight.","Lower your left foot back down to the ground.","Repeat with your left foot stepping up onto the platform.","Continue alternating legs for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/1008-d5bTEPV.jpg","gif_url":"videos/1008-d5bTEPV.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1009","name":"band stiff leg deadlift","category":"upper legs","equipment":"band","instruction_steps":{"en":["Stand with your feet shoulder-width apart and place the band around your ankles.","Hold the band with both hands in front of your thighs, palms facing your body.","Keeping your back straight and your core engaged, hinge at the hips and slowly lower your upper body towards the ground.","As you lower, push your hips back and allow your knees to bend slightly.","Lower the band towards the ground, feeling a stretch in your hamstrings.","Pause for a moment at the bottom, then engage your glutes and hamstrings to lift your upper body back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"target":"glutes","image":"images/1009-kuMiR2T.jpg","gif_url":"videos/1009-kuMiR2T.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1023","name":"band straight back stiff leg deadlift","category":"upper legs","equipment":"band","instruction_steps":{"en":["Stand with your feet shoulder-width apart and place the band around your upper legs.","Hold the band with both hands in front of your thighs, palms facing your body.","Keeping your back straight and your knees slightly bent, hinge at the hips and lower the band towards the ground.","Feel the stretch in your hamstrings as you lower the band.","Engage your glutes and hamstrings to lift your body back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"target":"glutes","image":"images/1023-lHeUULr.jpg","gif_url":"videos/1023-lHeUULr.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1010","name":"band straight leg deadlift","category":"back","equipment":"band","instruction_steps":{"en":["Stand with your feet shoulder-width apart and place the band around your feet.","Hold the band with both hands, palms facing your body, and keep your arms straight.","Engage your core and maintain a slight bend in your knees.","Slowly hinge forward at your hips, keeping your back straight and chest lifted.","Lower the band towards the ground while keeping your legs straight.","Pause for a moment at the bottom, then squeeze your glutes and hamstrings to return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"spine","image":"images/1010-KUaoUV8.jpg","gif_url":"videos/1010-KUaoUV8.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1012","name":"band twisting overhead press","category":"shoulders","equipment":"band","instruction_steps":{"en":["Stand with your feet shoulder-width apart and place the band under your feet.","Hold the band handles at shoulder height with your palms facing forward.","Engage your core and press the band overhead, fully extending your arms.","As you press, twist your torso to one side, keeping your hips stable.","Pause for a moment at the top, then return to the starting position.","Repeat the press and twist on the opposite side.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/1012-u4bAmKp.jpg","gif_url":"videos/1012-u4bAmKp.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1369","name":"band two legs calf raise - (band under both legs) v. 2","category":"lower legs","equipment":"band","instruction_steps":{"en":["Stand with your feet shoulder-width apart and place a resistance band under both feet.","Hold the ends of the band with your hands for stability.","Raise your heels off the ground as high as possible, using your calves.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"ankles","secondary_muscles":["ankles","feet"],"target":"calves","image":"images/1369-jl6uxZV.jpg","gif_url":"videos/1369-jl6uxZV.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1013","name":"band underhand pulldown","category":"back","equipment":"band","instruction_steps":{"en":["Attach the band to a high anchor point, such as a pull-up bar or sturdy beam.","Stand facing the anchor point with your feet shoulder-width apart.","Grasp the band with an underhand grip, hands slightly wider than shoulder-width apart.","Extend your arms fully overhead, keeping your elbows slightly bent.","Engage your lats and pull the band down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/1013-k6tUeqS.jpg","gif_url":"videos/1013-k6tUeqS.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1014","name":"band v-up","category":"waist","equipment":"band","instruction_steps":{"en":["Lie flat on your back with your legs straight and your arms extended overhead, holding the band.","Engaging your abs, lift your legs and upper body off the ground simultaneously, reaching your hands towards your toes.","Pause for a moment at the top, then slowly lower your legs and upper body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/1014-H6ETwO9.jpg","gif_url":"videos/1014-H6ETwO9.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1015","name":"band vertical pallof press","category":"waist","equipment":"band","instruction_steps":{"en":["Stand with your feet shoulder-width apart and wrap the band around a sturdy object at chest height.","Hold the band with both hands and step away from the anchor point, creating tension in the band.","Position yourself perpendicular to the anchor point, with your side facing the band.","Extend your arms straight out in front of you, keeping your hands at chest height.","Engage your core and press the band away from your chest, fully extending your arms.","Hold the position for a few seconds, then slowly bring the band back towards your chest.","Repeat for the desired number of repetitions, then switch sides."]},"muscle_group":"obliques","secondary_muscles":["obliques","glutes"],"target":"abs","image":"images/1015-G7PXMlT.jpg","gif_url":"videos/1015-G7PXMlT.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1016","name":"band wrist curl","category":"lower arms","equipment":"band","instruction_steps":{"en":["Sit on a bench or chair with your feet flat on the ground.","Hold the band with both hands, palms facing up, and rest your forearms on your thighs.","Slowly curl your wrists upward, squeezing your forearms.","Pause for a moment at the top, then slowly lower your wrists back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","triceps"],"target":"forearms","image":"images/1016-vUTfFHw.jpg","gif_url":"videos/1016-vUTfFHw.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1017","name":"band y-raise","category":"shoulders","equipment":"band","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing inwards.","Keep your arms straight and lift them up and out to the sides, forming a 'Y' shape with your body.","Squeeze your shoulder blades together at the top of the movement.","Slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"traps","secondary_muscles":["traps","rhomboids"],"target":"delts","image":"images/1017-aHDy5O5.jpg","gif_url":"videos/1017-aHDy5O5.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0023","name":"barbell alternate biceps curl","category":"upper arms","equipment":"barbell","instruction_steps":{"en":["Stand up straight with your feet shoulder-width apart and hold a barbell in each hand, palms facing forward.","Keep your upper arms stationary and exhale as you curl the weights while contracting your biceps.","Continue to raise the barbells until your biceps are fully contracted and the barbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale as you slowly begin to lower the barbells back to the starting position.","Repeat for the desired number of repetitions, alternating arms."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0023-Yza7XrQ.jpg","gif_url":"videos/0023-Yza7XrQ.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0024","name":"barbell bench front squat","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Start by standing with your feet shoulder-width apart and the barbell resting on your upper chest, just below your collarbone.","Hold the barbell with an overhand grip, keeping your elbows up and your upper arms parallel to the ground.","Lower your body down into a squat position by bending at the knees and hips, keeping your back straight and your chest up.","Pause for a moment at the bottom of the squat, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes","calves"],"target":"quads","image":"images/0024-Y7YcmIJ.jpg","gif_url":"videos/0024-Y7YcmIJ.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0025","name":"barbell bench press","category":"chest","equipment":"barbell","instruction_steps":{"en":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.","Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Lower the barbell slowly towards your chest, keeping your elbows tucked in.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/0025-EIeI8Vf.jpg","gif_url":"videos/0025-EIeI8Vf.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0026","name":"barbell bench squat","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Set up a barbell on a squat rack at chest height.","Stand facing away from the rack, with your feet shoulder-width apart.","Bend your knees and lower your body down into a squat position, keeping your back straight and chest up.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and step back, ensuring your feet are still shoulder-width apart.","Lower your body down into a squat, keeping your knees in line with your toes.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves"],"target":"quads","image":"images/0026-W9pFVv1.jpg","gif_url":"videos/0026-W9pFVv1.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1316","name":"barbell bent arm pullover","category":"back","equipment":"barbell","instruction_steps":{"en":["Lie flat on a bench with your head at one end and your feet on the floor.","Hold a barbell with a shoulder-width grip and extend your arms straight above your chest.","Lower the barbell behind your head while keeping your arms slightly bent.","Pause for a moment, then raise the barbell back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","chest"],"target":"lats","image":"images/1316-cA9FuWG.jpg","gif_url":"videos/1316-cA9FuWG.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0027","name":"barbell bent over row","category":"back","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and knees slightly bent.","Bend forward at the hips while keeping your back straight and chest up.","Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Pull the barbell towards your lower chest by retracting your shoulder blades and squeezing your back muscles.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0027-eZyBC3j.jpg","gif_url":"videos/0027-eZyBC3j.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2407","name":"barbell biceps curl (with arm blaster)","category":"upper arms","equipment":"barbell","instruction_steps":{"en":["Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up.","Place your upper arms against the arm blaster, keeping your elbows close to your torso.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the barbell until your biceps are fully contracted and the bar is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/2407-aee2Fcj.jpg","gif_url":"videos/2407-aee2Fcj.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0028","name":"barbell clean and press","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and the barbell on the floor in front of you.","Bend your knees and hinge at the hips to lower down and grip the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Drive through your heels and extend your hips and knees to lift the barbell off the floor, keeping it close to your body.","As the barbell reaches your thighs, explosively extend your hips, shrug your shoulders, and pull the barbell up towards your chest.","As the barbell reaches chest height, quickly drop under it and catch it at shoulder level, with your elbows pointing forward and your palms facing up.","From the catch position, press the barbell overhead by extending your arms and pushing the barbell straight up.","Lower the barbell back down to the starting position and repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes","shoulders","triceps"],"target":"quads","image":"images/0028-SGY8Zui.jpg","gif_url":"videos/0028-SGY8Zui.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0029","name":"barbell clean-grip front squat","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Start by standing with your feet shoulder-width apart and the barbell resting on your upper chest, with your elbows pointing forward.","Lower your body by bending your knees and pushing your hips back, as if you are sitting back into a chair.","Keep your chest up and your back straight as you lower down, making sure your knees do not go past your toes.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to stand back up, extending your hips and knees.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves","core"],"target":"glutes","image":"images/0029-qi996YS.jpg","gif_url":"videos/0029-qi996YS.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0030","name":"barbell close-grip bench press","category":"upper arms","equipment":"barbell","instruction_steps":{"en":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows close to your body.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0030-J6Dx1Mu.jpg","gif_url":"videos/0030-J6Dx1Mu.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0031","name":"barbell curl","category":"upper arms","equipment":"barbell","instruction_steps":{"en":["Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing forward.","Keep your elbows close to your torso and exhale as you curl the weights while contracting your biceps.","Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale as you slowly begin to lower the bar back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0031-25GPyDY.jpg","gif_url":"videos/0031-25GPyDY.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0032","name":"barbell deadlift","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and the barbell on the ground in front of you.","Bend your knees and hinge at the hips to lower your torso and grip the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Keep your back straight and chest lifted as you drive through your heels to lift the barbell off the ground, extending your hips and knees.","As you stand up straight, squeeze your glutes and keep your core engaged.","Lower the barbell back down to the ground by bending at the hips and knees, keeping your back straight.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"target":"glutes","image":"images/0032-ila4NZS.jpg","gif_url":"videos/0032-ila4NZS.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0033","name":"barbell decline bench press","category":"chest","equipment":"barbell","instruction_steps":{"en":["Lie on a decline bench with your feet secured and your head lower than your hips.","Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/0033-GrO65fd.jpg","gif_url":"videos/0033-GrO65fd.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0034","name":"barbell decline bent arm pullover","category":"back","equipment":"barbell","instruction_steps":{"en":["Lie down on a decline bench with your head lower than your hips and your feet secured.","Hold a barbell with a pronated grip (palms facing away from you) and extend your arms straight above your chest.","Lower the barbell behind your head in a controlled manner, keeping your arms slightly bent.","Pause for a moment, then raise the barbell back to the starting position by contracting your lats.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","chest"],"target":"lats","image":"images/0034-hMEptv0.jpg","gif_url":"videos/0034-hMEptv0.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0035","name":"barbell decline close grip to skull press","category":"upper arms","equipment":"barbell","instruction_steps":{"en":["Lie on a decline bench with your head lower than your feet and hold a barbell with a close grip.","Lower the barbell towards your forehead by bending your elbows, keeping your upper arms stationary.","Pause for a moment, then extend your arms to press the barbell back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0035-LMGXZn8.jpg","gif_url":"videos/0035-LMGXZn8.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1255","name":"barbell decline pullover","category":"chest","equipment":"barbell","instruction_steps":{"en":["Lie down on a decline bench with your head lower than your hips and your feet secured.","Hold the barbell with a pronated grip (palms facing away from you) and your hands slightly wider than shoulder-width apart.","Extend your arms above your chest, keeping a slight bend in your elbows.","Lower the barbell in an arc motion behind your head, feeling a stretch in your chest and shoulders.","Pause for a moment, then return the barbell to the starting position by reversing the motion.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1255-9sgNE2O.jpg","gif_url":"videos/1255-9sgNE2O.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0036","name":"barbell decline wide-grip press","category":"chest","equipment":"barbell","instruction_steps":{"en":["Lie on a decline bench with your feet secured and your head lower than your hips.","Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.","Lower the barbell to your chest, keeping your elbows out to the sides.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/0036-hl8DUh8.jpg","gif_url":"videos/0036-hl8DUh8.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0037","name":"barbell decline wide-grip pullover","category":"back","equipment":"barbell","instruction_steps":{"en":["Lie on a decline bench with your head lower than your hips and your feet secured.","Hold a barbell with a wide grip and extend your arms straight above your chest.","Lower the barbell behind your head in a controlled manner, keeping your arms straight.","Pause for a moment, then raise the barbell back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","chest"],"target":"lats","image":"images/0037-Hj4FOCd.jpg","gif_url":"videos/0037-Hj4FOCd.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0038","name":"barbell drag curl","category":"upper arms","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up.","Let the barbell hang at arm's length in front of your thighs.","Keeping your upper arms stationary, curl the barbell up towards your chest by contracting your biceps.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0038-IENzBdA.jpg","gif_url":"videos/0038-IENzBdA.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1370","name":"barbell floor calf raise","category":"lower legs","equipment":"barbell","instruction_steps":{"en":["Place a barbell on the floor in front of you.","Stand with the balls of your feet on the edge of the barbell, with your heels hanging off.","Hold onto a stable object for balance if needed.","Raise your heels as high as possible, using your calves to lift your body.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"target":"calves","image":"images/1370-2IHEa2T.jpg","gif_url":"videos/1370-2IHEa2T.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0039","name":"barbell front chest squat","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Start by standing with your feet shoulder-width apart, toes slightly turned out.","Hold the barbell in front of your chest with your hands shoulder-width apart, elbows pointing forward.","Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves","core"],"target":"glutes","image":"images/0039-IeTIEqg.jpg","gif_url":"videos/0039-IeTIEqg.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0041","name":"barbell front raise","category":"shoulders","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold a barbell in front of your thighs with an overhand grip.","Keep your arms straight and lift the barbell forward and upward until it reaches shoulder level.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","triceps"],"target":"delts","image":"images/0041-b2Uoz54.jpg","gif_url":"videos/0041-b2Uoz54.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0040","name":"barbell front raise and pullover","category":"chest","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down.","Keep your arms straight and raise the barbell in front of you until it reaches shoulder height.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Next, lower the barbell behind your head, keeping your arms straight.","Pause for a moment at the bottom, then raise the barbell back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"deltoids","secondary_muscles":["deltoids","triceps"],"target":"pectorals","image":"images/0040-33AzZeV.jpg","gif_url":"videos/0040-33AzZeV.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0042","name":"barbell front squat","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Start by standing with your feet shoulder-width apart, toes slightly turned out.","Hold the barbell in front of your shoulders, resting it on your collarbone and shoulders.","Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves","core"],"target":"glutes","image":"images/0042-zG0zs85.jpg","gif_url":"videos/0042-zG0zs85.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0043","name":"barbell full squat","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, toes slightly turned out.","Hold the barbell across your upper back, resting it on your traps or rear delts.","Engage your core and keep your chest up as you begin to lower your body down.","Bend at the knees and hips, pushing your hips back and down as if sitting into a chair.","Lower yourself until your thighs are parallel to the ground or slightly below.","Keep your knees in line with your toes and your weight in your heels.","Drive through your heels to stand back up, extending your hips and knees.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves","core"],"target":"glutes","image":"images/0043-qXTaZnJ.jpg","gif_url":"videos/0043-qXTaZnJ.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1461","name":"barbell full squat (back pov)","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, toes slightly turned out.","Hold the barbell across your upper back, resting it on your traps or rear delts.","Engage your core and keep your chest up as you begin to lower your body down.","Bend at the knees and hips, pushing your hips back and down as if sitting into a chair.","Lower your body until your thighs are parallel to the ground or slightly below.","Keep your knees in line with your toes and your weight in your heels.","Drive through your heels to stand back up, extending your hips and knees.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves","core"],"target":"glutes","image":"images/1461-DhMl549.jpg","gif_url":"videos/1461-DhMl549.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1462","name":"barbell full squat (side pov)","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, toes slightly turned out.","Hold the barbell across your upper back, resting it on your traps or rear delts.","Engage your core and keep your chest up as you begin to lower your body down.","Bend at the knees and hips, pushing your hips back and down as if sitting into a chair.","Lower your body until your thighs are parallel to the ground or slightly below.","Keep your knees in line with your toes and your weight in your heels.","Drive through your heels to stand back up, extending your hips and knees.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves","core"],"target":"glutes","image":"images/1462-iYzB0Cz.jpg","gif_url":"videos/1462-iYzB0Cz.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1545","name":"barbell full zercher squat","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and toes slightly turned out.","Hold the barbell in the crooks of your elbows, with your hands gripping the barbell for stability.","Engage your core and keep your chest lifted as you lower your hips back and down into a squat position.","Keep your knees in line with your toes and your weight in your heels.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Drive through your heels to stand back up, squeezing your glutes at the top of the movement.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves","core"],"target":"glutes","image":"images/1545-vR1vold.jpg","gif_url":"videos/1545-vR1vold.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1409","name":"barbell glute bridge","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Start by lying flat on your back on the ground with your knees bent and feet flat on the floor.","Place a barbell across your hips, holding it securely with both hands.","Engage your glutes and core muscles, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders.","Pause for a moment at the top, squeezing your glutes.","Slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"target":"glutes","image":"images/1409-qKBpF7I.jpg","gif_url":"videos/1409-qKBpF7I.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3562","name":"barbell glute bridge two legs on bench (male)","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Start by sitting on the edge of a bench with your upper back resting against it and your feet flat on the ground, hip-width apart.","Place a barbell across your hips, holding it securely with both hands.","Engage your glutes and core muscles, then press through your heels to lift your hips off the bench, creating a straight line from your knees to your shoulders.","Pause for a moment at the top, squeezing your glutes.","Slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","core"],"target":"glutes","image":"images/3562-qg2PGl6.jpg","gif_url":"videos/3562-qg2PGl6.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0044","name":"barbell good morning","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Start by standing with your feet shoulder-width apart and the barbell resting on your upper back.","Keeping your back straight and your core engaged, hinge forward at the hips, pushing your buttocks back as if you were trying to touch the wall behind you with your glutes.","Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.","Pause for a moment, then return to the starting position by squeezing your glutes and pushing your hips forward.","Repeat for the desired number of repetitions."]},"muscle_group":"lower back","secondary_muscles":["lower back"],"target":"hamstrings","image":"images/0044-XlZ4lAC.jpg","gif_url":"videos/0044-XlZ4lAC.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0045","name":"barbell guillotine bench press","category":"chest","equipment":"barbell","instruction_steps":{"en":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lower the barbell slowly towards your neck, keeping your elbows pointed outwards.","Pause for a moment when the barbell is just above your neck.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/0045-GXoaSgn.jpg","gif_url":"videos/0045-GXoaSgn.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0046","name":"barbell hack squat","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Start by standing with your feet shoulder-width apart and your toes slightly turned out.","Hold the barbell behind your legs, resting it on your upper thighs.","Lower your body by bending at the knees and hips, keeping your back straight and your chest up.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0046-5VCj6iH.jpg","gif_url":"videos/0046-5VCj6iH.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1436","name":"barbell high bar squat","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, toes slightly turned out.","Place the barbell on your upper back, resting it on your traps.","Engage your core and keep your chest up as you begin to squat down, pushing your hips back and bending your knees.","Lower yourself until your thighs are parallel to the ground, or as low as you can comfortably go.","Drive through your heels to stand back up, extending your hips and knees.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves","core"],"target":"glutes","image":"images/1436-Gnfo4FM.jpg","gif_url":"videos/1436-Gnfo4FM.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0047","name":"barbell incline bench press","category":"chest","equipment":"barbell","instruction_steps":{"en":["Set up an incline bench at a 45-degree angle.","Lie down on the bench with your feet flat on the ground.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows at a 45-degree angle.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/0047-3TZduzM.jpg","gif_url":"videos/0047-3TZduzM.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1719","name":"barbell incline close grip bench press","category":"upper arms","equipment":"barbell","instruction_steps":{"en":["Set up an incline bench at a 45-degree angle.","Lie down on the bench with your feet flat on the ground.","Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows close to your body.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/1719-gx7s7uF.jpg","gif_url":"videos/1719-gx7s7uF.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0048","name":"barbell incline reverse-grip press","category":"upper arms","equipment":"barbell","instruction_steps":{"en":["Set up an incline bench at a 45-degree angle.","Lie back on the bench and grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart.","Unrack the barbell and lower it towards your upper chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0048-641mIfk.jpg","gif_url":"videos/0048-641mIfk.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0049","name":"barbell incline row","category":"back","equipment":"barbell","instruction_steps":{"en":["Set up an incline bench at a 45-degree angle.","Lie face down on the bench with your chest against the pad and your feet flat on the ground.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and your core engaged.","Pull the barbell towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0049-dmgMp3n.jpg","gif_url":"videos/0049-dmgMp3n.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0050","name":"barbell incline shoulder raise","category":"chest","equipment":"barbell","instruction_steps":{"en":["Set up an incline bench at a 45-degree angle.","Sit on the bench with your back against the pad and feet flat on the ground.","Hold a barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell up to shoulder height, keeping your elbows slightly bent.","Slowly raise the barbell overhead, extending your arms fully.","Pause for a moment at the top, then slowly lower the barbell back to shoulder height.","Repeat for the desired number of repetitions."]},"muscle_group":"deltoids","secondary_muscles":["deltoids","trapezius"],"target":"serratus anterior","image":"images/0050-xi0yckC.jpg","gif_url":"videos/0050-xi0yckC.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0051","name":"barbell jefferson squat","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and toes slightly turned out.","Hold the barbell with an overhand grip, resting it on the front of your body, just below your waist.","Step your left foot forward and your right foot back, keeping your feet shoulder-width apart.","Bend your knees and lower your body down into a squat position, keeping your back straight and chest up.","Push through your heels to stand back up to the starting position.","Repeat the movement, alternating your forward and back foot with each repetition."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0051-pkSoCW9.jpg","gif_url":"videos/0051-pkSoCW9.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0052","name":"barbell jm bench press","category":"upper arms","equipment":"barbell","instruction_steps":{"en":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lower the barbell to your chest, keeping your elbows tucked in close to your body.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0052-ZsiqXYa.jpg","gif_url":"videos/0052-ZsiqXYa.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0053","name":"barbell jump squat","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Start by standing with your feet shoulder-width apart, holding a barbell across your upper back.","Lower your body into a squat position by bending your knees and pushing your hips back.","Once you reach the bottom of the squat, explode upwards by jumping off the ground.","As you jump, extend your hips, knees, and ankles, pushing through your toes.","Land softly back into the squat position and immediately repeat the movement for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0053-1gFNTZV.jpg","gif_url":"videos/0053-1gFNTZV.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1410","name":"barbell lateral lunge","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a barbell across your upper back.","Take a big step to the side with your right foot, keeping your left foot planted.","Bend your right knee and lower your body down into a lunge position, keeping your left leg straight.","Push off with your right foot and return to the starting position.","Repeat on the other side, stepping with your left foot."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/1410-py1HSzx.jpg","gif_url":"videos/1410-py1HSzx.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1435","name":"barbell low bar squat","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and the barbell resting on your upper back.","Keeping your chest up and core engaged, slowly lower your body by bending your knees and pushing your hips back.","Continue lowering until your thighs are parallel to the ground or slightly below.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/1435-bTpEUcm.jpg","gif_url":"videos/1435-bTpEUcm.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0054","name":"barbell lunge","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Start by standing with your feet shoulder-width apart and a barbell resting on your upper back.","Take a step forward with your right foot, keeping your torso upright.","Lower your body by bending your right knee until your thigh is parallel to the ground.","Push through your right heel to return to the starting position.","Repeat with your left leg, alternating legs for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0054-t8iSghb.jpg","gif_url":"videos/0054-t8iSghb.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1720","name":"barbell lying back of the head tricep extension","category":"upper arms","equipment":"barbell","instruction_steps":{"en":["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold a barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.","Keeping your upper arms stationary, slowly lower the barbell behind your head by bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/1720-yg8Totb.jpg","gif_url":"videos/1720-yg8Totb.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0055","name":"barbell lying close-grip press","category":"upper arms","equipment":"barbell","instruction_steps":{"en":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with a close grip, hands shoulder-width apart, palms facing towards your feet.","Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Slowly lower the barbell towards your chest, keeping your elbows close to your body.","Pause for a moment when the barbell touches your chest, then push it back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0055-EcaV7aL.jpg","gif_url":"videos/0055-EcaV7aL.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0056","name":"barbell lying close-grip triceps extension","category":"upper arms","equipment":"barbell","instruction_steps":{"en":["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Grasp the barbell with a close grip, hands shoulder-width apart, palms facing up.","Extend your arms fully, lifting the barbell above your chest.","Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.","Pause for a moment at the bottom, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0056-HJ63mSO.jpg","gif_url":"videos/0056-HJ63mSO.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0057","name":"barbell lying extension","category":"upper arms","equipment":"barbell","instruction_steps":{"en":["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.","Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0057-EMpUwRI.jpg","gif_url":"videos/0057-EMpUwRI.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0058","name":"barbell lying lifting (on hip)","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Lie flat on your back on a bench with your feet flat on the ground and your knees bent.","Hold the barbell with an overhand grip and position it on your hips.","Engaging your glutes, lift your hips off the bench until your body forms a straight line from your knees to your shoulders.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps"],"target":"glutes","image":"images/0058-SNFfUff.jpg","gif_url":"videos/0058-SNFfUff.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0059","name":"barbell lying preacher curl","category":"upper arms","equipment":"barbell","instruction_steps":{"en":["Sit on a preacher bench with your chest against the pad and your arms extended over the edge, holding a barbell with an underhand grip.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0059-SYJ4Bkt.jpg","gif_url":"videos/0059-SYJ4Bkt.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0061","name":"barbell lying triceps extension","category":"upper arms","equipment":"barbell","instruction_steps":{"en":["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.","Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.","Pause for a moment at the bottom, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0061-iZop9xO.jpg","gif_url":"videos/0061-iZop9xO.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0060","name":"barbell lying triceps extension skull crusher","category":"upper arms","equipment":"barbell","instruction_steps":{"en":["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.","Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.","Pause for a moment when the barbell is just above your forehead, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0060-h8LFzo9.jpg","gif_url":"videos/0060-h8LFzo9.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0063","name":"barbell narrow stance squat","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and toes pointing slightly outward.","Hold the barbell across your upper back, resting it on your traps or rear delts.","Engage your core and keep your chest up as you slowly lower your body by bending your knees and pushing your hips back.","Continue lowering until your thighs are parallel to the ground or slightly below.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0063-elhhVgj.jpg","gif_url":"videos/0063-elhhVgj.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0064","name":"barbell one arm bent over row","category":"back","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, knees slightly bent, and hold a barbell with one hand using an overhand grip.","Bend forward at the hips, keeping your back straight and your head in a neutral position.","Pull the barbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.","Lower the barbell back down to the starting position in a controlled manner.","Repeat for the desired number of repetitions, then switch to the other arm."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0064-Jsgsc27.jpg","gif_url":"videos/0064-Jsgsc27.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0065","name":"barbell one arm floor press","category":"upper arms","equipment":"barbell","instruction_steps":{"en":["Lie flat on your back on the floor with your knees bent and feet flat on the ground.","Hold the barbell with one hand, palm facing up, and extend your arm straight up over your chest.","Slowly lower the barbell towards your chest, keeping your elbow close to your body.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0065-vtusOWT.jpg","gif_url":"videos/0065-vtusOWT.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0066","name":"barbell one arm side deadlift","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a barbell in one hand with an overhand grip.","Keep your back straight and your core engaged.","Bend at the hips and lower the barbell towards the outside of your leg, keeping your arm straight and your chest up.","Lower the barbell as far as you can while maintaining good form.","Pause for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps","lower back"],"target":"glutes","image":"images/0066-2DxtqHL.jpg","gif_url":"videos/0066-2DxtqHL.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0067","name":"barbell one arm snatch","category":"shoulders","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, toes pointing slightly outwards.","Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Bend your knees and lower your hips into a squat position, keeping your back straight and chest up.","Explosively extend your hips, knees, and ankles, driving the barbell upwards.","As the barbell reaches chest level, pull it upwards with your arm, keeping it close to your body.","Rotate your elbow under the barbell and extend your arm fully overhead, locking out your elbow.","Lower the barbell back down to the starting position in a controlled manner.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"traps","secondary_muscles":["traps","forearms","core"],"target":"delts","image":"images/0067-xHKN2s8.jpg","gif_url":"videos/0067-xHKN2s8.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0068","name":"barbell one leg squat","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold a barbell across your upper back.","Lift one foot off the ground and extend it forward, keeping it parallel to the ground.","Bend your standing leg and lower your body down as if sitting back into a chair, keeping your chest up and your back straight.","Lower yourself until your thigh is parallel to the ground, then push through your heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."]},"muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves"],"target":"quads","image":"images/0068-uKyN64F.jpg","gif_url":"videos/0068-uKyN64F.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0069","name":"barbell overhead squat","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and toes slightly turned out.","Hold the barbell with a wide grip, positioning it overhead with your arms fully extended.","Engage your core and lower your body down into a squat position, keeping your chest up and knees tracking over your toes.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves","core"],"target":"quads","image":"images/0069-gfk9kD4.jpg","gif_url":"videos/0069-gfk9kD4.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1411","name":"barbell palms down wrist curl over a bench","category":"lower arms","equipment":"barbell","instruction_steps":{"en":["Sit on a bench with your feet flat on the ground and your forearms resting on your thighs, palms facing down.","Hold a barbell with an overhand grip, hands shoulder-width apart.","Lower the barbell towards the ground by flexing your wrists, keeping your forearms stationary.","Pause for a moment at the bottom, then slowly raise the barbell back up by extending your wrists.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","brachialis"],"target":"forearms","image":"images/1411-yzYH9pI.jpg","gif_url":"videos/1411-yzYH9pI.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1412","name":"barbell palms up wrist curl over a bench","category":"lower arms","equipment":"barbell","instruction_steps":{"en":["Sit on a bench with your feet flat on the ground and hold a barbell with an underhand grip, palms facing up.","Rest your forearms on the bench, allowing your wrists to hang off the edge.","Keeping your forearms stationary, exhale and curl your wrists upwards as far as possible.","Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"target":"forearms","image":"images/1412-SJAA2IQ.jpg","gif_url":"videos/1412-SJAA2IQ.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3017","name":"barbell pendlay row","category":"back","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and your knees slightly bent.","Bend forward at the hips, keeping your back straight and your chest up.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Pull the barbell towards your upper abdomen, squeezing your shoulder blades together.","Lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/3017-r0z6xzQ.jpg","gif_url":"videos/3017-r0z6xzQ.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1751","name":"barbell pin presses","category":"upper arms","equipment":"barbell","instruction_steps":{"en":["Set up a barbell on a power rack at chest height.","Stand facing the barbell and position yourself underneath it, with your feet shoulder-width apart.","Grip the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and hold it directly above your chest, with your arms fully extended.","Lower the barbell down towards your chest, keeping your elbows tucked in close to your body.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/1751-bndCa3Q.jpg","gif_url":"videos/1751-bndCa3Q.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0070","name":"barbell preacher curl","category":"upper arms","equipment":"barbell","instruction_steps":{"en":["Sit on a preacher bench with your upper arms resting on the pad and your chest against the support.","Grasp the barbell with an underhand grip, slightly wider than shoulder-width apart.","Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0070-qOgPVf6.jpg","gif_url":"videos/0070-qOgPVf6.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0071","name":"barbell press sit-up","category":"waist","equipment":"barbell","instruction_steps":{"en":["Lie flat on your back on a mat with your knees bent and feet flat on the ground.","Hold the barbell with an overhand grip, resting it on your chest.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","chest"],"target":"abs","image":"images/0071-wnEscH8.jpg","gif_url":"videos/0071-wnEscH8.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0072","name":"barbell prone incline curl","category":"upper arms","equipment":"barbell","instruction_steps":{"en":["Set up an incline bench at a 45-degree angle.","Lie face down on the bench with your chest and stomach resting against it.","Hold a barbell with an underhand grip, shoulder-width apart.","Extend your arms fully, allowing the barbell to hang down towards the floor.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the barbell until your biceps are fully contracted and the bar is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0072-WLvTAv5.jpg","gif_url":"videos/0072-WLvTAv5.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0073","name":"barbell pullover","category":"back","equipment":"barbell","instruction_steps":{"en":["Lie flat on a bench with your head at one end and your feet on the floor.","Hold a barbell with a shoulder-width grip and extend your arms straight above your chest.","Keeping your arms straight, lower the barbell behind your head in a controlled manner until you feel a stretch in your lats.","Pause for a moment, then raise the barbell back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","triceps"],"target":"lats","image":"images/0073-i6LWjok.jpg","gif_url":"videos/0073-i6LWjok.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0022","name":"barbell pullover to press","category":"back","equipment":"barbell","instruction_steps":{"en":["Lie flat on a bench with your head at one end and your feet on the ground.","Hold the barbell with a pronated grip (palms facing away from you) and extend your arms straight above your chest.","Keeping your arms straight, lower the barbell behind your head in an arc-like motion until you feel a stretch in your lats.","Pause for a moment, then reverse the motion and press the barbell back to the starting position above your chest.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","chest","shoulders"],"target":"lats","image":"images/0022-znLogoF.jpg","gif_url":"videos/0022-znLogoF.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0074","name":"barbell rack pull","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Set up a barbell on a rack at knee height.","Stand with your feet shoulder-width apart, toes pointing slightly outwards.","Bend at the hips and knees to lower yourself down and grip the barbell with an overhand grip, hands shoulder-width apart.","Engage your core and lift the barbell by extending your hips and knees, pulling your shoulders back and squeezing your glutes at the top.","Lower the barbell back down to the starting position by bending at the hips and knees.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"target":"glutes","image":"images/0074-za9Ni4z.jpg","gif_url":"videos/0074-za9Ni4z.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0075","name":"barbell rear delt raise","category":"shoulders","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Raise the barbell out to the sides, keeping your arms straight, until they are parallel to the ground.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"traps","secondary_muscles":["traps","rhomboids"],"target":"delts","image":"images/0075-Ln9iTbU.jpg","gif_url":"videos/0075-Ln9iTbU.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0076","name":"barbell rear delt row","category":"shoulders","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and knees slightly bent.","Hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Bend forward at the hips, keeping your back straight and chest up.","Pull the barbell towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids","biceps"],"target":"delts","image":"images/0076-S9zHIvU.jpg","gif_url":"videos/0076-S9zHIvU.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0078","name":"barbell rear lunge","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Start by standing with your feet shoulder-width apart and a barbell resting on your upper back.","Take a step backward with your right foot, landing on the ball of your foot.","Bend both knees to lower your body until your left thigh is parallel to the ground.","Push through your left heel to return to the starting position.","Repeat with the other leg."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0078-VaP75jl.jpg","gif_url":"videos/0078-VaP75jl.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0077","name":"barbell rear lunge v. 2","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold a barbell across your upper back.","Take a step backward with your right foot, landing on the ball of your foot.","Bend both knees to lower your body until your left thigh is parallel to the ground.","Push through your left heel to return to the starting position.","Repeat with the other leg."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0077-62Nw60O.jpg","gif_url":"videos/0077-62Nw60O.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0079","name":"barbell revers wrist curl v. 2","category":"lower arms","equipment":"barbell","instruction_steps":{"en":["Sit on a bench with your feet flat on the ground and your knees bent.","Hold a barbell with an overhand grip, palms facing down, and your hands shoulder-width apart.","Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Keeping your forearms stationary, exhale and curl your wrists upward as far as possible.","Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","brachialis"],"target":"forearms","image":"images/0079-qDnGfDb.jpg","gif_url":"videos/0079-qDnGfDb.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2187","name":"barbell reverse close-grip bench press","category":"upper arms","equipment":"barbell","instruction_steps":{"en":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with a reverse grip, hands shoulder-width apart.","Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Slowly lower the barbell down towards your chest, keeping your elbows close to your body.","Pause for a moment when the barbell is just above your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/2187-YqJw82s.jpg","gif_url":"videos/2187-YqJw82s.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0080","name":"barbell reverse curl","category":"upper arms","equipment":"barbell","instruction_steps":{"en":["Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down.","Keep your upper arms stationary and exhale as you curl the barbell upward, contracting your biceps.","Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale as you slowly lower the barbell back to the starting position, keeping your upper arms stationary.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0080-xNrS20v.jpg","gif_url":"videos/0080-xNrS20v.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0118","name":"barbell reverse grip bent over row","category":"back","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and knees slightly bent.","Hold a barbell with an overhand grip, palms facing down, and hands slightly wider than shoulder-width apart.","Bend forward at the hips, keeping your back straight and chest up, until your torso is almost parallel to the floor.","Pull the barbell towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0118-SzX3uzM.jpg","gif_url":"videos/0118-SzX3uzM.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1256","name":"barbell reverse grip decline bench press","category":"chest","equipment":"barbell","instruction_steps":{"en":["Lie on a decline bench with your feet secured and your head lower than your hips.","Grasp the barbell with a reverse grip, slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1256-DotAgEF.jpg","gif_url":"videos/1256-DotAgEF.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1257","name":"barbell reverse grip incline bench press","category":"chest","equipment":"barbell","instruction_steps":{"en":["Set up an incline bench at a 45-degree angle.","Lie down on the bench with your feet flat on the ground.","Grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1257-DU7I633.jpg","gif_url":"videos/1257-DU7I633.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1317","name":"barbell reverse grip incline bench row","category":"back","equipment":"barbell","instruction_steps":{"en":["Set up an incline bench at a 45-degree angle.","Sit on the bench facing the backrest with your chest against it.","Grab the barbell with a reverse grip (palms facing down) and hands slightly wider than shoulder-width apart.","Keep your back straight and core engaged.","Pull the barbell towards your upper abdomen, squeezing your shoulder blades together.","Pause for a moment at the top of the movement.","Slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/1317-8d8qJQI.jpg","gif_url":"videos/1317-8d8qJQI.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1721","name":"barbell reverse grip skullcrusher","category":"upper arms","equipment":"barbell","instruction_steps":{"en":["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold the barbell with a reverse grip, palms facing towards your face, and your hands shoulder-width apart.","Extend your arms straight up over your chest, keeping your elbows in and your wrists straight.","Slowly lower the barbell towards your forehead by bending your elbows, keeping your upper arms stationary.","Pause for a moment at the bottom, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"triceps","image":"images/1721-yRLPCLu.jpg","gif_url":"videos/1721-yRLPCLu.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0081","name":"barbell reverse preacher curl","category":"upper arms","equipment":"barbell","instruction_steps":{"en":["Sit on a preacher bench with your chest against the pad and your arms extended straight down, holding a barbell with an overhand grip.","Keeping your upper arms stationary, exhale and curl the barbell upward while contracting your biceps.","Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0081-4LIG9xr.jpg","gif_url":"videos/0081-4LIG9xr.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0082","name":"barbell reverse wrist curl","category":"lower arms","equipment":"barbell","instruction_steps":{"en":["Sit on a bench with your feet flat on the ground and hold a barbell with an overhand grip, palms facing down.","Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Slowly curl your wrists upward, bringing the barbell towards your body.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","brachialis"],"target":"forearms","image":"images/0082-LsZkfU6.jpg","gif_url":"videos/0082-LsZkfU6.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0084","name":"barbell rollerout","category":"waist","equipment":"barbell","instruction_steps":{"en":["Kneel on the floor and hold a barbell with both hands, shoulder-width apart.","Roll the barbell forward, extending your arms and keeping your core engaged.","Continue rolling forward until your body is fully extended and your arms are overhead.","Pause for a moment, then slowly roll the barbell back towards your knees, maintaining control.","Repeat for the desired number of repetitions."]},"muscle_group":"lower back","secondary_muscles":["lower back"],"target":"abs","image":"images/0084-7M66AVi.jpg","gif_url":"videos/0084-7M66AVi.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0083","name":"barbell rollerout from bench","category":"waist","equipment":"barbell","instruction_steps":{"en":["Start by kneeling on the floor with a barbell placed on a bench in front of you.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Keeping your core engaged and your back straight, slowly roll the barbell forward, extending your arms in front of you.","Continue rolling the barbell forward until your body is fully extended and your arms are overhead.","Pause for a moment at the fully extended position, then slowly roll the barbell back towards your body, returning to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"abs","image":"images/0083-Gxg9lDc.jpg","gif_url":"videos/0083-Gxg9lDc.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0085","name":"barbell romanian deadlift","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and your toes pointing forward.","Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Bend at the hips, keeping your back straight and your knees slightly bent.","Lower the barbell towards the ground, keeping it close to your body.","Feel the stretch in your hamstrings as you lower the barbell.","Once you feel a stretch in your hamstrings, push your hips forward and stand up straight.","Squeeze your glutes at the top of the movement.","Lower the barbell back down to the starting position and repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"target":"glutes","image":"images/0085-wQ2c4XD.jpg","gif_url":"videos/0085-wQ2c4XD.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0086","name":"barbell seated behind head military press","category":"shoulders","equipment":"barbell","instruction_steps":{"en":["Sit on a bench with your back straight and feet flat on the ground.","Hold the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and bring it down to shoulder level, behind your head.","Press the barbell upward until your arms are fully extended.","Lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0086-ngPpyRS.jpg","gif_url":"videos/0086-ngPpyRS.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0087","name":"barbell seated bradford rocky press","category":"shoulders","equipment":"barbell","instruction_steps":{"en":["Sit on a bench with your back straight and feet flat on the ground.","Hold the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell to shoulder height, keeping your elbows slightly bent and pointing forward.","Press the barbell overhead, fully extending your arms.","Lower the barbell back to shoulder height and repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0087-0dCyly0.jpg","gif_url":"videos/0087-0dCyly0.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0088","name":"barbell seated calf raise","category":"lower legs","equipment":"barbell","instruction_steps":{"en":["Sit on a bench with your feet flat on the floor and a barbell resting on your thighs.","Place the balls of your feet on a raised platform, such as a block or step.","Position the barbell across your thighs and hold it securely with your hands.","Keeping your back straight and your core engaged, lift your heels off the ground by extending your ankles.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps"],"target":"calves","image":"images/0088-ktsFQAZ.jpg","gif_url":"videos/0088-ktsFQAZ.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1371","name":"barbell seated calf raise","category":"lower legs","equipment":"barbell","instruction_steps":{"en":["Sit on a bench with your feet flat on the floor and a barbell resting on your thighs.","Place the balls of your feet on a raised platform, such as a block or step.","Lower your heels as far as possible, feeling a stretch in your calves.","Raise your heels as high as possible, contracting your calves.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"target":"calves","image":"images/1371-ipvgBnC.jpg","gif_url":"videos/1371-ipvgBnC.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1718","name":"barbell seated close grip behind neck triceps extension","category":"upper arms","equipment":"barbell","instruction_steps":{"en":["Sit on a bench with your back straight and feet flat on the ground.","Hold the barbell with a close grip behind your neck, palms facing forward.","Keep your elbows close to your head and slowly lower the barbell towards the back of your head.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/1718-4CBIBOM.jpg","gif_url":"videos/1718-4CBIBOM.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0089","name":"barbell seated close-grip concentration curl","category":"upper arms","equipment":"barbell","instruction_steps":{"en":["Sit on a bench with your feet flat on the floor and hold a barbell with an underhand grip, hands shoulder-width apart.","Rest your upper arms against your inner thighs, just above your knees, and let the barbell hang down in front of you.","Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders, contracting your biceps.","Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0089-1V1gj1u.jpg","gif_url":"videos/0089-1V1gj1u.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0090","name":"barbell seated good morning","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Sit on a bench with your feet flat on the ground and a barbell resting on your upper back.","Keep your back straight and your chest up.","Slowly hinge forward at the hips, lowering your torso towards the ground.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"target":"glutes","image":"images/0090-d960PgE.jpg","gif_url":"videos/0090-d960PgE.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0091","name":"barbell seated overhead press","category":"shoulders","equipment":"barbell","instruction_steps":{"en":["Sit on a bench with your back straight and feet flat on the ground.","Hold the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and bring it to shoulder level, with your elbows bent and palms facing forward.","Press the barbell overhead by extending your arms fully.","Pause for a moment at the top, then slowly lower the barbell back to shoulder level.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0091-kTbSH9h.jpg","gif_url":"videos/0091-kTbSH9h.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0092","name":"barbell seated overhead triceps extension","category":"upper arms","equipment":"barbell","instruction_steps":{"en":["Sit on a bench with your back straight and feet flat on the ground.","Hold a barbell with an overhand grip, hands shoulder-width apart, and raise it overhead.","Lower the barbell behind your head by bending your elbows, keeping your upper arms close to your head.","Pause for a moment, then extend your arms to raise the barbell back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0092-5uFK1xr.jpg","gif_url":"videos/0092-5uFK1xr.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0094","name":"barbell seated twist","category":"waist","equipment":"barbell","instruction_steps":{"en":["Sit on a flat bench with your feet flat on the ground and your knees bent.","Hold a barbell with both hands in front of your chest, keeping your elbows slightly bent.","Engage your core and slowly twist your torso to one side, keeping your back straight.","Pause for a moment at the end of the twist, then slowly rotate back to the starting position.","Repeat the twist to the other side.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques","lower back"],"target":"abs","image":"images/0094-dFSNDOA.jpg","gif_url":"videos/0094-dFSNDOA.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0095","name":"barbell shrug","category":"back","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold a barbell in front of you with an overhand grip.","Keep your arms straight and your back straight throughout the exercise.","Lift your shoulders up towards your ears as high as possible, squeezing your traps at the top.","Hold for a moment, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"traps","image":"images/0095-dG7tG5y.jpg","gif_url":"videos/0095-dG7tG5y.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0096","name":"barbell side bent v. 2","category":"waist","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold a barbell with both hands, palms facing down.","Keep your back straight and core engaged throughout the exercise.","Slowly bend your torso to the right side, lowering the barbell towards your right knee.","Pause for a moment, then return to the starting position.","Repeat the movement on the left side.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques","lower back"],"target":"abs","image":"images/0096-i4JkUaL.jpg","gif_url":"videos/0096-i4JkUaL.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0098","name":"barbell side split squat","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Stand with your feet wider than shoulder-width apart, toes pointing slightly outward.","Hold a barbell across your upper back, resting it on your traps.","Engage your core and keep your chest up as you lower your body down into a squat position, bending at the knees and hips.","As you lower, push your knees out to the sides and keep your weight on your heels.","Lower until your thighs are parallel to the ground, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves"],"target":"quads","image":"images/0098-W31mMjd.jpg","gif_url":"videos/0098-W31mMjd.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0097","name":"barbell side split squat v. 2","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Stand with your feet wider than shoulder-width apart, toes pointing slightly outwards.","Hold a barbell across your upper back, resting it on your shoulders.","Take a big step to the side with your right foot, keeping your left foot planted.","Bend your right knee and lower your body down into a squat position, keeping your chest up and your back straight.","Push through your right heel to return to the starting position.","Repeat on the other side, stepping out with your left foot.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves"],"target":"quads","image":"images/0097-HUEqZ1y.jpg","gif_url":"videos/0097-HUEqZ1y.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1756","name":"barbell single leg deadlift","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Stand with your feet hip-width apart, holding a barbell in front of your thighs with an overhand grip.","Shift your weight onto your left foot and lift your right foot slightly off the ground.","Hinge forward at the hips, keeping your back straight and your right leg extended behind you for balance.","Lower the barbell towards the ground, keeping it close to your body and your left leg slightly bent.","Pause for a moment at the bottom, then engage your glutes and hamstrings to lift your torso back up to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"target":"glutes","image":"images/1756-gEyURal.jpg","gif_url":"videos/1756-gEyURal.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0099","name":"barbell single leg split squat","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a barbell across your upper back.","Take a large step forward with one leg, keeping your torso upright.","Lower your body by bending your front knee and hip, while keeping your back leg straight.","Continue lowering until your front thigh is parallel to the ground.","Pause for a moment, then push through your front heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."]},"muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves"],"target":"quads","image":"images/0099-gGNQmVt.jpg","gif_url":"videos/0099-gGNQmVt.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2799","name":"barbell sitted alternate leg raise","category":"waist","equipment":"barbell","instruction_steps":{"en":["Sit on a bench with your back straight and hold a barbell across your thighs.","Keeping your legs straight, lift one leg up as high as possible while keeping the other leg on the ground.","Lower the raised leg back down and repeat with the other leg.","Continue alternating legs for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/2799-G7xoEzr.jpg","gif_url":"videos/2799-G7xoEzr.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2800","name":"barbell sitted alternate leg raise (female)","category":"waist","equipment":"barbell","instruction_steps":{"en":["Sit on a bench with your back straight and hold a barbell across your thighs.","Place your hands on the sides of the bench for support.","Keeping your legs straight, lift one leg up as high as possible while keeping it parallel to the ground.","Lower the leg back down and repeat with the other leg.","Continue alternating legs for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors","quadriceps"],"target":"abs","image":"images/2800-BCs0G2F.jpg","gif_url":"videos/2800-BCs0G2F.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0100","name":"barbell skier","category":"shoulders","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold a barbell in front of your thighs with an overhand grip.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.","Simultaneously lift the barbell up towards your shoulders while jumping slightly off the ground.","As you reach the top of the movement, quickly reverse the motion and lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","core"],"target":"delts","image":"images/0100-4Leypho.jpg","gif_url":"videos/0100-4Leypho.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0101","name":"barbell speed squat","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, toes slightly turned out.","Hold the barbell across your upper back, resting it on your traps or rear delts.","Engage your core and keep your chest up as you lower your hips back and down, as if sitting into a chair.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Drive through your heels to stand back up, squeezing your glutes at the top.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0101-euI1BwR.jpg","gif_url":"videos/0101-euI1BwR.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2810","name":"barbell split squat v. 2","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Start by standing with your feet shoulder-width apart, holding a barbell across your upper back.","Take a large step forward with your right foot, keeping your torso upright.","Lower your body by bending your knees and hips until your right thigh is parallel to the ground.","Pause for a moment, then push through your right heel to return to the starting position.","Repeat with your left leg forward for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves"],"target":"quads","image":"images/2810-HBYyX94.jpg","gif_url":"videos/2810-HBYyX94.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0102","name":"barbell squat (on knees)","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Start by kneeling on the ground with your knees hip-width apart and your toes pointing forward.","Place a barbell across your shoulders, gripping it with an overhand grip and your hands slightly wider than shoulder-width apart.","Engage your core and keep your chest lifted as you slowly lower your body down by bending your knees, keeping your back straight.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves"],"target":"quads","image":"images/0102-oR7O9LW.jpg","gif_url":"videos/0102-oR7O9LW.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2798","name":"barbell squat jump step rear lunge","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Start by standing with your feet shoulder-width apart, holding a barbell across your upper back.","Lower your body into a squat position by bending your knees and pushing your hips back.","Explode upwards, jumping off the ground as high as you can.","Land softly on your feet and immediately step back with one leg into a reverse lunge.","Lower your body down until your front thigh is parallel to the ground, keeping your back straight.","Push through your front heel to return to the starting position.","Repeat the jump and lunge sequence on the other leg.","Continue alternating legs for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves"],"target":"quads","image":"images/2798-RYcV1kH.jpg","gif_url":"videos/2798-RYcV1kH.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0103","name":"barbell standing ab rollerout","category":"waist","equipment":"barbell","instruction_steps":{"en":["Stand upright with your feet shoulder-width apart and hold the barbell with both hands in front of your thighs.","Engage your core and slowly roll the barbell down towards the ground, keeping your back straight and your arms extended.","Continue rolling the barbell forward until your body is fully extended and your hands are directly above your head.","Pause for a moment, then slowly roll the barbell back towards your thighs, maintaining control and keeping your core engaged.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","lower back"],"target":"abs","image":"images/0103-xnInPfE.jpg","gif_url":"videos/0103-xnInPfE.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0104","name":"barbell standing back wrist curl","category":"lower arms","equipment":"barbell","instruction_steps":{"en":["Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip.","Rest the barbell on the back of your hands with your palms facing down and your fingers pointing towards your body.","Keeping your upper arms stationary, exhale and curl your wrists upwards as far as possible.","Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"target":"forearms","image":"images/0104-2qTvJAZ.jpg","gif_url":"videos/0104-2qTvJAZ.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0105","name":"barbell standing bradford press","category":"shoulders","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold the barbell in front of your shoulders with an overhand grip.","Press the barbell overhead, fully extending your arms.","Lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0105-dCPESfR.jpg","gif_url":"videos/0105-dCPESfR.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1372","name":"barbell standing calf raise","category":"lower legs","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and place a barbell across your upper back.","Raise your heels off the ground as high as possible, using only your toes.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"calves","image":"images/1372-8ozhUIZ.jpg","gif_url":"videos/1372-8ozhUIZ.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0106","name":"barbell standing close grip curl","category":"upper arms","equipment":"barbell","instruction_steps":{"en":["Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, hands close together.","Keep your elbows close to your torso and your upper arms stationary throughout the movement.","Exhale as you curl the weights while contracting your biceps. Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale as you slowly begin to bring the barbell back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0106-4dUn2iv.jpg","gif_url":"videos/0106-4dUn2iv.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1456","name":"barbell standing close grip military press","category":"shoulders","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold the barbell with an overhand grip, hands slightly closer than shoulder-width apart.","Lift the barbell to shoulder height, keeping your elbows close to your body.","Press the barbell overhead, extending your arms fully.","Lower the barbell back to shoulder height.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/1456-wdRZISl.jpg","gif_url":"videos/1456-wdRZISl.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2414","name":"barbell standing concentration curl","category":"upper arms","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold a barbell in one hand, palm facing up.","Rest your opposite hand on your thigh for support.","Keeping your upper arm stationary, exhale and curl the weight up towards your shoulder.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the weight back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/2414-vsMcDi9.jpg","gif_url":"videos/2414-vsMcDi9.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0107","name":"barbell standing front raise over head","category":"shoulders","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a barbell in front of your thighs with an overhand grip.","Keep your back straight and engage your core.","Slowly raise the barbell in front of you, keeping your arms straight and your palms facing down.","Continue lifting until the barbell is slightly above shoulder level.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0107-S8mo30S.jpg","gif_url":"videos/0107-S8mo30S.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0108","name":"barbell standing leg calf raise","category":"lower legs","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and place a barbell across your upper back.","Raise your heels off the ground as high as possible, using your calves.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"calves","image":"images/0108-rGwhJ5o.jpg","gif_url":"videos/0108-rGwhJ5o.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0109","name":"barbell standing overhead triceps extension","category":"upper arms","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip.","Raise the barbell overhead, fully extending your arms.","Keeping your upper arms close to your head, slowly lower the barbell behind your head by bending your elbows.","Pause for a moment, then raise the barbell back to the starting position by extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0109-dZl9Q27.jpg","gif_url":"videos/0109-dZl9Q27.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0110","name":"barbell standing reverse grip curl","category":"upper arms","equipment":"barbell","instruction_steps":{"en":["Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up.","Keep your elbows close to your torso and your upper arms stationary.","Exhale and curl the weights while contracting your biceps, bringing the barbell as close to your shoulders as possible.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0110-LWuA3aZ.jpg","gif_url":"videos/0110-LWuA3aZ.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0111","name":"barbell standing rocking leg calf raise","category":"lower legs","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold a barbell across your upper back.","Raise your heels off the ground as high as possible, balancing on the balls of your feet.","Slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps"],"target":"calves","image":"images/0111-6HiHHe0.jpg","gif_url":"videos/0111-6HiHHe0.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0112","name":"barbell standing twist","category":"waist","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold a barbell in front of your chest with both hands, palms facing down.","Engage your core and keep your back straight throughout the exercise.","Slowly twist your torso to the right, pivoting on your feet and hips, while keeping your lower body stable.","Pause for a moment at the end of the twist, then slowly return to the starting position.","Repeat the twist to the left side.","Continue alternating twists for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques","lower back"],"target":"abs","image":"images/0112-yQe5HpE.jpg","gif_url":"videos/0112-yQe5HpE.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1629","name":"barbell standing wide grip biceps curl","category":"upper arms","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold a barbell with an underhand grip, hands wider than shoulder-width apart.","Keep your back straight and your elbows close to your torso.","Exhale and curl the barbell up towards your shoulders, keeping your upper arms stationary.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the barbell back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1629-faHKVkK.jpg","gif_url":"videos/1629-faHKVkK.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1457","name":"barbell standing wide military press","category":"shoulders","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold the barbell with an overhand grip, slightly wider than shoulder-width.","Lift the barbell to shoulder height, keeping your elbows slightly in front of the bar.","Press the barbell overhead, extending your arms fully.","Lower the barbell back to shoulder height and repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/1457-Kyd9Rz5.jpg","gif_url":"videos/1457-Kyd9Rz5.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0113","name":"barbell standing wide-grip curl","category":"upper arms","equipment":"barbell","instruction_steps":{"en":["Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip, hands wider than shoulder-width apart.","Let the barbell hang at arm's length in front of your thighs, with your palms facing away from your body.","Keeping your upper arms stationary, exhale and curl the barbell upward by contracting your biceps.","Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms","shoulders"],"target":"biceps","image":"images/0113-NdIb5Z1.jpg","gif_url":"videos/0113-NdIb5Z1.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0114","name":"barbell step-up","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Stand in front of a bench or step with a barbell resting on your upper back.","Place one foot on the bench or step, ensuring your entire foot is in contact with the surface.","Push through your heel and step up onto the bench or step, fully extending your hip and knee.","Pause briefly at the top, then lower yourself back down to the starting position.","Repeat with the opposite leg.","Continue alternating legs for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0114-Kxquu2E.jpg","gif_url":"videos/0114-Kxquu2E.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0115","name":"barbell stiff leg good morning","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and your knees slightly bent.","Hold the barbell across your upper back, resting it on your traps.","Keeping your back straight, hinge forward at the hips, pushing your glutes back.","Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.","Engage your glutes and hamstrings to return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"target":"glutes","image":"images/0115-JrOHAZc.jpg","gif_url":"videos/0115-JrOHAZc.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0116","name":"barbell straight leg deadlift","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and your toes pointing forward.","Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Bend at your hips and lower the barbell towards the ground, keeping your back straight and your knees slightly bent.","Lower the barbell until you feel a stretch in your hamstrings.","Engage your hamstrings and glutes to lift the barbell back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","lower back"],"target":"hamstrings","image":"images/0116-hrVQWvE.jpg","gif_url":"videos/0116-hrVQWvE.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0117","name":"barbell sumo deadlift","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Stand with your feet wider than shoulder-width apart, toes pointing outwards.","Place a barbell on the ground in front of you, centered between your feet.","Bend your knees and lower your hips, keeping your back straight and chest up, to grip the barbell with an overhand grip.","Engage your core and drive through your heels to lift the barbell off the ground, extending your hips and knees simultaneously.","As you lift, keep your chest up and back straight, and push your hips forward to fully engage your glutes.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position, maintaining control throughout the movement.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps","lower back"],"target":"glutes","image":"images/0117-KgI0tqW.jpg","gif_url":"videos/0117-KgI0tqW.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3305","name":"barbell thruster","category":"shoulders","equipment":"barbell","instruction_steps":{"en":["Start by standing with your feet shoulder-width apart, holding a barbell at shoulder height with an overhand grip.","Lower into a squat position by bending your knees and pushing your hips back.","As you reach the bottom of the squat, explosively drive through your heels to stand up, simultaneously pressing the barbell overhead.","Lower the barbell back to shoulder height as you lower back into the squat position.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","glutes","hamstrings","core"],"target":"delts","image":"images/3305-f7Y9eDZ.jpg","gif_url":"videos/3305-f7Y9eDZ.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0120","name":"barbell upright row","category":"shoulders","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Let the barbell hang in front of your thighs, arms fully extended.","Keeping your back straight and core engaged, exhale and lift the barbell straight up towards your chin, leading with your elbows.","Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"traps","secondary_muscles":["traps","biceps"],"target":"delts","image":"images/0120-UDlhcO8.jpg","gif_url":"videos/0120-UDlhcO8.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0119","name":"barbell upright row v. 2","category":"shoulders","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Let the barbell hang in front of your thighs, arms fully extended.","Keeping your back straight, exhale and lift the barbell straight up towards your chin, leading with your elbows.","Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"traps","secondary_muscles":["traps","biceps"],"target":"delts","image":"images/0119-83HoW9X.jpg","gif_url":"videos/0119-83HoW9X.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0121","name":"barbell upright row v. 3","category":"shoulders","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Let the barbell hang in front of your thighs, arms fully extended.","Keeping your core engaged and back straight, exhale as you lift the barbell straight up towards your chin, leading with your elbows.","Pause for a moment at the top, then inhale as you slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"traps","secondary_muscles":["traps","biceps"],"target":"delts","image":"images/0121-fI18Rbc.jpg","gif_url":"videos/0121-fI18Rbc.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0122","name":"barbell wide bench press","category":"chest","equipment":"barbell","instruction_steps":{"en":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Lower the barbell slowly towards your chest, keeping your elbows slightly flared out.","Pause for a moment when the barbell touches your chest, then push it back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/0122-JsKq9so.jpg","gif_url":"videos/0122-JsKq9so.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1258","name":"barbell wide reverse grip bench press","category":"chest","equipment":"barbell","instruction_steps":{"en":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the barbell with a wide reverse grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Lower the barbell slowly towards your chest, keeping your elbows tucked in and your wrists straight.","Pause for a moment when the barbell touches your chest, then push it back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1258-945zpRg.jpg","gif_url":"videos/1258-945zpRg.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0124","name":"barbell wide squat","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Stand with your feet wider than shoulder-width apart, toes pointing slightly outward.","Hold the barbell across your upper back, resting it on your traps or rear delts.","Engage your core and keep your chest up as you lower your body down into a squat, pushing your hips back and bending your knees.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves"],"target":"quads","image":"images/0124-s7HX1BY.jpg","gif_url":"videos/0124-s7HX1BY.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0123","name":"barbell wide-grip upright row","category":"shoulders","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands wider than shoulder-width apart.","Let the barbell hang in front of your thighs, arms fully extended.","Keeping your back straight, exhale and lift the barbell straight up towards your chin, leading with your elbows.","Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"traps","secondary_muscles":["traps","biceps"],"target":"delts","image":"images/0123-RgJDRR1.jpg","gif_url":"videos/0123-RgJDRR1.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0126","name":"barbell wrist curl","category":"lower arms","equipment":"barbell","instruction_steps":{"en":["Sit on a bench with your feet flat on the ground and your forearms resting on your thighs, holding a barbell with an underhand grip.","Allow the barbell to roll down to your fingertips, keeping your wrists straight.","Slowly curl the barbell up towards your forearms by flexing your wrists.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","brachialis"],"target":"forearms","image":"images/0126-82LxxkW.jpg","gif_url":"videos/0126-82LxxkW.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0125","name":"barbell wrist curl v. 2","category":"lower arms","equipment":"barbell","instruction_steps":{"en":["Sit on a bench with your feet flat on the ground and your knees bent.","Hold a barbell with an underhand grip, palms facing up, and your hands shoulder-width apart.","Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Slowly curl your wrists upward, bringing the barbell towards your forearms.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","brachialis"],"target":"forearms","image":"images/0125-6kSxYnw.jpg","gif_url":"videos/0125-6kSxYnw.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0127","name":"barbell zercher squat","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and toes slightly turned out.","Hold the barbell in the crooks of your elbows, with your hands gripping the bar for stability.","Engage your core and keep your chest lifted as you lower your hips back and down into a squat position.","Keep your knees in line with your toes and your weight in your heels.","Pause for a moment at the bottom of the squat, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves","core"],"target":"glutes","image":"images/0127-LSTChY9.jpg","gif_url":"videos/0127-LSTChY9.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3212","name":"basic toe touch (male)","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart and your arms by your sides.","Bend forward at the waist, keeping your back straight and your knees slightly bent.","Reach down towards your toes with your hands, keeping your legs as straight as possible.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","calves"],"target":"glutes","image":"images/3212-BbfB8Gb.jpg","gif_url":"videos/3212-BbfB8Gb.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0128","name":"battling ropes","category":"shoulders","equipment":"rope","instruction_steps":{"en":["Stand with your feet shoulder-width apart and knees slightly bent.","Hold one end of the rope in each hand, with your palms facing each other.","Raise your arms to shoulder height, keeping your elbows slightly bent.","Begin making alternating waves with the ropes by rapidly raising and lowering each arm.","Continue for the desired duration or number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms","core"],"target":"delts","image":"images/0128-RJa4tCo.jpg","gif_url":"videos/0128-RJa4tCo.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3360","name":"bear crawl","category":"cardio","equipment":"body weight","instruction_steps":{"en":["Start on all fours with your hands directly under your shoulders and your knees directly under your hips.","Lift your knees slightly off the ground, keeping your back flat and your core engaged.","Move your right hand and left foot forward simultaneously, followed by your left hand and right foot.","Continue crawling forward, alternating your hand and foot movements.","Maintain a steady pace and keep your core tight throughout the exercise.","Continue for the desired distance or time."]},"muscle_group":"core","secondary_muscles":["core","shoulders","triceps"],"target":"cardiovascular system","image":"images/3360-0Yz8WdV.jpg","gif_url":"videos/3360-0Yz8WdV.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1259","name":"behind head chest stretch","category":"chest","equipment":"assisted","instruction_steps":{"en":["Stand tall with your feet shoulder-width apart.","Interlace your fingers behind your head with your elbows pointing outwards.","Slowly squeeze your shoulder blades together and push your chest forward.","Hold the stretch for 15-30 seconds.","Release the stretch and repeat as desired."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/1259-QoHIhPl.jpg","gif_url":"videos/1259-QoHIhPl.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0129","name":"bench dip (knees bent)","category":"upper arms","equipment":"body weight","instruction_steps":{"en":["Sit on the edge of a bench or chair with your hands gripping the edge next to your hips.","Slide your butt off the bench and straighten your legs in front of you, keeping your heels on the ground.","Bend your elbows and lower your body towards the ground, keeping your back close to the bench.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0129-RrLske5.jpg","gif_url":"videos/0129-RrLske5.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1399","name":"bench dip on floor","category":"upper arms","equipment":"body weight","instruction_steps":{"en":["Sit on the edge of a bench or chair with your hands gripping the edge, fingers pointing forward.","Slide your butt off the bench, supporting your weight with your hands.","Lower your body by bending your elbows until your upper arms are parallel to the floor.","Push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/1399-9RT8oQW.jpg","gif_url":"videos/1399-9RT8oQW.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0130","name":"bench hip extension","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Sit on a bench with your back against the bench and your feet flat on the ground.","Place your hands on the bench for support.","Engage your glutes and hamstrings, then lift your hips off the bench until your body forms a straight line from your knees to your shoulders.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"target":"glutes","image":"images/0130-u27Kcdz.jpg","gif_url":"videos/0130-u27Kcdz.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3019","name":"bench pull-ups","category":"back","equipment":"body weight","instruction_steps":{"en":["Position yourself under a bar or a sturdy horizontal surface that is at chest height.","Grab the bar or surface with an overhand grip, slightly wider than shoulder-width apart.","Hang with your arms fully extended and your body straight.","Pull your chest towards the bar or surface by squeezing your shoulder blades together and bending your elbows.","Continue pulling until your chin is above the bar or surface.","Lower yourself back down to the starting position with control.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/3019-mExgrF9.jpg","gif_url":"videos/3019-mExgrF9.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3639","name":"bent knee lying twist (male)","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Extend your arms out to the sides, perpendicular to your body.","Keeping your knees together, slowly lower them to one side, aiming to touch the ground with your knees.","Pause for a moment, then engage your core and slowly lift your knees back to the starting position.","Repeat the movement to the other side.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques","hip flexors"],"target":"glutes","image":"images/3639-6sYyrRX.jpg","gif_url":"videos/3639-6sYyrRX.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1770","name":"biceps leg concentration curl","category":"upper arms","equipment":"body weight","instruction_steps":{"en":["Sit on a bench with your legs spread apart and your feet flat on the ground.","Hold a dumbbell in one hand and place your elbow on the inside of your thigh, just above the knee.","With your palm facing up, curl the dumbbell towards your shoulder while keeping your upper arm stationary.","Squeeze your biceps at the top of the movement, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1770-sJFIDIp.jpg","gif_url":"videos/1770-sJFIDIp.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0139","name":"biceps narrow pull-ups","category":"upper arms","equipment":"body weight","instruction_steps":{"en":["Hang from a pull-up bar with your palms facing towards you and your hands shoulder-width apart.","Engage your core and pull yourself up towards the bar, focusing on using your biceps to lift your body.","Pause for a moment at the top, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms","shoulders"],"target":"biceps","image":"images/0139-50BETrz.jpg","gif_url":"videos/0139-50BETrz.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0140","name":"biceps pull-up","category":"upper arms","equipment":"body weight","instruction_steps":{"en":["Hang from a pull-up bar with your palms facing away from you and your hands shoulder-width apart.","Engage your core and pull yourself up by bending your elbows, bringing your chest towards the bar.","Pause at the top of the movement, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms","shoulders"],"target":"biceps","image":"images/0140-guT8YnS.jpg","gif_url":"videos/0140-guT8YnS.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0137","name":"body-up","category":"upper arms","equipment":"body weight","instruction_steps":{"en":["Start by placing your hands on a raised surface, such as a bench or parallel bars, with your palms facing down and fingers pointing forward.","Extend your legs out in front of you, keeping your heels on the ground and your body straight.","Lower your body by bending your elbows, keeping them close to your sides, until your upper arms are parallel to the ground.","Pause for a moment, then push through your palms to straighten your arms and lift your body back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0137-U6G2gk9.jpg","gif_url":"videos/0137-U6G2gk9.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3543","name":"bodyweight drop jump squat","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart.","Lower your body into a squat position by bending your knees and pushing your hips back.","Jump up explosively, extending your hips, knees, and ankles.","While in mid-air, quickly bring your feet together.","Land softly on the balls of your feet and immediately drop back into a squat position.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/3543-wfotm7S.jpg","gif_url":"videos/3543-wfotm7S.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3544","name":"bodyweight incline side plank","category":"waist","equipment":"body weight","instruction_steps":{"en":["Start by lying on your side with your legs extended and stacked on top of each other.","Place your forearm on the ground directly below your shoulder, with your elbow bent at a 90-degree angle.","Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.","Hold this position for the desired amount of time.","Lower your hips back down to the ground and repeat on the other side."]},"muscle_group":"obliques","secondary_muscles":["obliques","shoulders"],"target":"abs","image":"images/3544-5VXmnV5.jpg","gif_url":"videos/3544-5VXmnV5.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1771","name":"bodyweight kneeling triceps extension","category":"upper arms","equipment":"body weight","instruction_steps":{"en":["Kneel down on the ground with your knees hip-width apart.","Place your hands on the ground in front of you, shoulder-width apart, fingers pointing forward.","Extend your legs straight behind you, balancing on your toes and hands, forming a straight line from head to heels.","Bend your elbows and lower your upper body towards the ground, keeping your elbows close to your sides.","Pause for a moment at the bottom, then push through your hands to straighten your arms and return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","chest"],"target":"triceps","image":"images/1771-s0HKO2I.jpg","gif_url":"videos/1771-s0HKO2I.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1769","name":"bodyweight side lying biceps curl","category":"upper arms","equipment":"body weight","instruction_steps":{"en":["Lie on your side with your legs extended and your head supported by your arm.","Hold your upper arm against your side and bend your elbow to curl your forearm towards your shoulder.","Pause for a moment at the top, then slowly lower your forearm back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1769-gscGLOU.jpg","gif_url":"videos/1769-gscGLOU.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3168","name":"bodyweight squatting row","category":"back","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding onto a sturdy object or suspension trainer with your arms extended.","Lower your body into a squat position, keeping your back straight and your knees behind your toes.","From the squat position, pull your body up towards the object or suspension trainer, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"target":"upper back","image":"images/3168-3xK09Sk.jpg","gif_url":"videos/3168-3xK09Sk.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3167","name":"bodyweight squatting row (with towel)","category":"back","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a towel in front of you with your palms facing down.","Bend your knees and lower your body into a squat position, keeping your back straight and your chest up.","As you lower into the squat, simultaneously pull the towel towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the squat, then slowly return to the starting position while extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"target":"upper back","image":"images/3167-BReCuOn.jpg","gif_url":"videos/3167-BReCuOn.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1373","name":"bodyweight standing calf raise","category":"lower legs","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart, toes pointing forward.","Place your hands on a wall or stable surface for balance.","Slowly raise your heels off the ground, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"ankles","secondary_muscles":["ankles","feet"],"target":"calves","image":"images/1373-bJYHBIN.jpg","gif_url":"videos/1373-bJYHBIN.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3156","name":"bodyweight standing close-grip one arm row","category":"back","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in one hand with a neutral grip.","Bend forward at the hips, keeping your back straight and your core engaged.","Pull the dumbbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/3156-v2DfH14.jpg","gif_url":"videos/3156-v2DfH14.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3158","name":"bodyweight standing close-grip row","category":"back","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart and knees slightly bent.","Bend forward at the waist, keeping your back straight and your core engaged.","Extend your arms straight in front of you, gripping the bar or handles with a close grip.","Pull the bar or handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release and return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/3158-tig3PXb.jpg","gif_url":"videos/3158-tig3PXb.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3162","name":"bodyweight standing one arm row","category":"back","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in one hand.","Bend forward at the hips, keeping your back straight and your core engaged.","Let the dumbbell hang straight down in front of you, with your arm fully extended.","Pull the dumbbell up towards your chest, keeping your elbow close to your body.","Squeeze your shoulder blades together at the top of the movement.","Lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/3162-xbkPfaw.jpg","gif_url":"videos/3162-xbkPfaw.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3161","name":"bodyweight standing one arm row (with towel)","category":"back","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart, knees slightly bent, and hold a towel with one hand.","Bend forward at the hips, keeping your back straight and your core engaged.","Pull the towel towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the towel back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/3161-O4oIqQD.jpg","gif_url":"videos/3161-O4oIqQD.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3166","name":"bodyweight standing row","category":"back","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart and knees slightly bent.","Grasp a bar or handles with an overhand grip, palms facing down.","Keep your back straight and core engaged.","Pull the bar or handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the top of the movement.","Slowly release and extend your arms back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"target":"upper back","image":"images/3166-wd4ds3s.jpg","gif_url":"videos/3166-wd4ds3s.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3165","name":"bodyweight standing row (with towel)","category":"back","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold a towel in front of you with both hands.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Pull the towel towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"target":"upper back","image":"images/3165-uTv34oq.jpg","gif_url":"videos/3165-uTv34oq.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0138","name":"bottoms-up","category":"waist","equipment":"body weight","instruction_steps":{"en":["Lie flat on your back with your legs extended and your arms by your sides.","Bend your knees and bring them towards your chest, keeping your feet off the ground.","Engaging your abs, lift your hips off the ground, bringing your knees towards your head.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques","hip flexors"],"target":"abs","image":"images/0138-CI6baTY.jpg","gif_url":"videos/0138-CI6baTY.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1374","name":"box jump down with one leg stabilization","category":"lower legs","equipment":"body weight","instruction_steps":{"en":["Stand in front of a box or platform with your feet shoulder-width apart.","Bend your knees and jump onto the box, landing softly with one foot on the box and the other foot hanging off the edge.","Stabilize yourself on the box with the foot that is on it, while keeping the other foot off the ground.","Hold this position for a few seconds, engaging your calf muscles to maintain balance.","Slowly step down with the foot that is on the box, returning to the starting position.","Repeat the exercise with the other leg."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","glutes"],"target":"calves","image":"images/1374-iPm26QU.jpg","gif_url":"videos/1374-iPm26QU.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2466","name":"bridge - mountain climber (cross body)","category":"waist","equipment":"body weight","instruction_steps":{"en":["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.","Engage your core and lift your right foot off the ground, bringing your right knee towards your left elbow.","Return your right foot to the starting position and repeat the movement with your left foot towards your right elbow.","Continue alternating sides, moving at a controlled pace.","Keep your hips level and avoid lifting your hips too high or sagging them too low.","Maintain a steady breathing pattern throughout the exercise.","Repeat for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","quadriceps","hamstrings","shoulders","triceps"],"target":"abs","image":"images/2466-9c6T1YX.jpg","gif_url":"videos/2466-9c6T1YX.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1160","name":"burpee","category":"cardio","equipment":"body weight","instruction_steps":{"en":["Start in a standing position with your feet shoulder-width apart.","Lower your body into a squat position by bending your knees and placing your hands on the floor in front of you.","Kick your feet back into a push-up position.","Perform a push-up, keeping your body in a straight line.","Jump your feet back into the squat position.","Jump up explosively, reaching your arms overhead.","Land softly and immediately lower back into a squat position to begin the next repetition."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves","shoulders","chest"],"target":"cardiovascular system","image":"images/1160-dK9394r.jpg","gif_url":"videos/1160-dK9394r.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0870","name":"butt-ups","category":"waist","equipment":"body weight","instruction_steps":{"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands by your sides, palms facing down.","Engaging your abs, lift your legs off the ground, bringing your knees towards your chest.","At the top of the movement, squeeze your abs and pause for a moment.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors","lower back"],"target":"abs","image":"images/0870-qcNN2FN.jpg","gif_url":"videos/0870-qcNN2FN.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1494","name":"butterfly yoga pose","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Sit on the floor with your legs extended in front of you.","Bend your knees and bring the soles of your feet together, allowing your knees to fall out to the sides.","Hold onto your ankles or feet with your hands.","Sit up tall and lengthen your spine.","Gently press your knees down towards the floor, feeling a stretch in your inner thighs.","Hold this position for a few breaths.","To release, slowly bring your knees back up and extend your legs."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","groin"],"target":"adductors","image":"images/1494-bWlZvXh.jpg","gif_url":"videos/1494-bWlZvXh.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0148","name":"cable alternate shoulder press","category":"shoulders","equipment":"cable","instruction_steps":{"en":["Stand with your feet shoulder-width apart and grasp the handles of the cable machine with an overhand grip.","Position your hands at shoulder height, with your palms facing forward.","Keep your core engaged and your back straight.","Press one handle up and forward until your arm is fully extended.","Pause for a moment at the top, then slowly lower the handle back to the starting position.","Repeat with the other arm.","Alternate between arms for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0148-KHPZL0b.jpg","gif_url":"videos/0148-KHPZL0b.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0149","name":"cable alternate triceps extension","category":"upper arms","equipment":"cable","instruction_steps":{"en":["Stand facing the cable machine with your feet shoulder-width apart.","Hold the cable handle with your right hand and bring your arm up so that your upper arm is parallel to the ground and your elbow is bent at a 90-degree angle.","Keep your upper arm stationary and extend your forearm backward, fully straightening your arm.","Pause for a moment, then slowly return to the starting position.","Repeat with your left arm.","Continue alternating arms for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0149-Gchi5Tr.jpg","gif_url":"videos/0149-Gchi5Tr.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3235","name":"cable assisted inverse leg curl","category":"upper legs","equipment":"cable","instruction_steps":{"en":["Adjust the cable machine so that the ankle attachment is at the lowest setting.","Lie face down on the bench with your legs straight and the ankle attachment secured to your ankles.","Hold onto the handles of the bench for stability.","Keeping your upper body stationary, exhale and curl your legs up towards your glutes by flexing your knees.","Pause for a moment at the top of the movement, squeezing your hamstrings.","Inhale and slowly lower your legs back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","calves"],"target":"hamstrings","image":"images/3235-zHEpuuc.jpg","gif_url":"videos/3235-zHEpuuc.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0150","name":"cable bar lateral pulldown","category":"back","equipment":"cable","instruction_steps":{"en":["Adjust the cable pulley to a high position and attach a straight bar.","Sit facing the cable machine with your feet flat on the ground and your knees slightly bent.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Lean back slightly and keep your chest up, maintaining a slight arch in your lower back.","Pull the bar down towards your chest, leading with your elbows and squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly return the bar to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","rhomboids","rear deltoids"],"target":"lats","image":"images/0150-eYnzaCm.jpg","gif_url":"videos/0150-eYnzaCm.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0151","name":"cable bench press","category":"chest","equipment":"cable","instruction_steps":{"en":["Adjust the cable machine to chest height and attach the handles.","Stand facing away from the machine with your feet shoulder-width apart.","Grasp the handles with an overhand grip and step forward to create tension in the cables.","Position your feet firmly on the ground and engage your core.","Bend your elbows and bring your hands to shoulder level, keeping your elbows at a 90-degree angle.","Push the handles forward, extending your arms fully in front of you.","Pause for a moment, then slowly reverse the movement, bringing your hands back to shoulder level.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/0151-7xI5MXA.jpg","gif_url":"videos/0151-7xI5MXA.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1630","name":"cable close grip curl","category":"upper arms","equipment":"cable","instruction_steps":{"en":["Attach a straight bar to a low pulley cable machine.","Stand facing the machine with your feet shoulder-width apart and your knees slightly bent.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Exhale and curl the bar up towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the bar back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1630-BCGQ6J5.jpg","gif_url":"videos/1630-BCGQ6J5.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1631","name":"cable concentration curl","category":"upper arms","equipment":"cable","instruction_steps":{"en":["Sit on a bench or chair with your feet flat on the floor and your knees slightly bent.","Hold the cable handle with an underhand grip and rest your elbow against the inside of your thigh.","Keeping your upper arm stationary, exhale and curl the cable handle towards your shoulder while contracting your biceps.","Pause for a moment at the top of the movement, then inhale and slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1631-NvfE43H.jpg","gif_url":"videos/1631-NvfE43H.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0152","name":"cable concentration extension (on knee)","category":"upper arms","equipment":"cable","instruction_steps":{"en":["Sit on a bench or chair with your knees bent and feet flat on the ground.","Hold the cable handle with your right hand and place your elbow on the inside of your right knee.","Extend your arm fully, keeping your elbow stationary and close to your knee.","Pause for a moment at the top, then slowly lower your arm back to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"triceps","image":"images/0152-Db7eEgw.jpg","gif_url":"videos/0152-Db7eEgw.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0153","name":"cable cross-over lateral pulldown","category":"back","equipment":"cable","instruction_steps":{"en":["Attach a cable handle to each side of a cable machine at shoulder height.","Stand in the middle of the machine with your feet shoulder-width apart.","Grasp the handles with an overhand grip and step back to create tension in the cables.","Lean forward slightly from the hips, keeping your back straight and your chest up.","Pull the handles down and across your body, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","rhomboids","rear deltoids"],"target":"lats","image":"images/0153-OQ1otBN.jpg","gif_url":"videos/0153-OQ1otBN.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0154","name":"cable cross-over revers fly","category":"shoulders","equipment":"cable","instruction_steps":{"en":["Attach a D-handle to each low pulley cable and stand in the middle of the cable crossover machine.","Grasp the handles with a pronated grip (palms facing down) and take a step forward, positioning your feet shoulder-width apart.","Bend your knees slightly and lean forward at the waist, keeping your back straight and your abs engaged.","With your arms extended out to the sides and slightly bent at the elbows, exhale and squeeze your shoulder blades together as you pull the cables back and upward in a reverse fly motion.","Pause for a moment at the peak contraction, then inhale and slowly return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"rhomboids","secondary_muscles":["rhomboids","trapezius"],"target":"delts","image":"images/0154-aqvSOQE.jpg","gif_url":"videos/0154-aqvSOQE.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0155","name":"cable cross-over variation","category":"chest","equipment":"cable","instruction_steps":{"en":["Adjust the cable pulleys to chest height.","Stand in the center of the cable machine with one foot in front of the other.","Grasp the handles with your palms facing down and your arms extended out to the sides.","Take a step forward, keeping your arms slightly bent.","With a slight bend in your elbows, bring your hands together in front of your chest.","Pause for a moment, then slowly return your arms back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"deltoids","secondary_muscles":["deltoids","triceps"],"target":"pectorals","image":"images/0155-0CXGHya.jpg","gif_url":"videos/0155-0CXGHya.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0868","name":"cable curl","category":"upper arms","equipment":"cable","instruction_steps":{"en":["Stand facing the cable machine with your feet shoulder-width apart.","Grasp the cable attachment with an underhand grip, palms facing up.","Keep your elbows close to your sides and your upper arms stationary.","Exhale and curl the cable attachment towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the cable attachment back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0868-G08RZcQ.jpg","gif_url":"videos/0868-G08RZcQ.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0157","name":"cable deadlift","category":"upper legs","equipment":"cable","instruction_steps":{"en":["Stand facing the cable machine with your feet shoulder-width apart.","Bend at the hips and knees, lowering your torso until your back is parallel to the ground.","Grasp the cable handles with an overhand grip, keeping your arms straight and your shoulders back.","Engage your glutes and hamstrings to lift the cable handles, extending your hips and standing up straight.","Pause for a moment at the top, then slowly lower the cable handles back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps","lower back"],"target":"glutes","image":"images/0157-eGDudUV.jpg","gif_url":"videos/0157-eGDudUV.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0158","name":"cable decline fly","category":"chest","equipment":"cable","instruction_steps":{"en":["Adjust the cable machine to a decline position.","Stand facing away from the machine with your feet shoulder-width apart.","Hold the handles with your palms facing forward and your arms extended straight out in front of you.","Keeping a slight bend in your elbows, open your arms out to the sides in a controlled motion.","Pause for a moment at the fully extended position, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/0158-7saC5zz.jpg","gif_url":"videos/0158-7saC5zz.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1260","name":"cable decline one arm press","category":"chest","equipment":"cable","instruction_steps":{"en":["Adjust the cable machine to a decline position.","Stand facing away from the machine and grab the handle with one hand.","Position yourself with your back against the decline bench and your arm extended straight in front of you.","Bend your elbow and lower the handle towards your chest while keeping your upper arm stationary.","Pause for a moment at the bottom, then push the handle back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1260-KHGNa16.jpg","gif_url":"videos/1260-KHGNa16.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1261","name":"cable decline press","category":"chest","equipment":"cable","instruction_steps":{"en":["Adjust the cable machine to a decline position.","Sit on the decline bench facing the cable machine.","Grasp the handles with an overhand grip and position them at chest level.","Keep your feet flat on the ground and your back firmly against the bench.","Exhale and push the handles away from your body, extending your arms fully.","Pause for a moment at the end of the movement, squeezing your chest muscles.","Inhale and slowly return the handles back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1261-2Pya1cP.jpg","gif_url":"videos/1261-2Pya1cP.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0159","name":"cable decline seated wide-grip row","category":"back","equipment":"cable","instruction_steps":{"en":["Sit on the decline bench facing the cable machine with your feet securely placed on the footrests.","Grasp the cable attachment with a wide overhand grip, palms facing down.","Lean back slightly, keeping your back straight and your core engaged.","Pull the cable towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the peak of the contraction, then slowly release the cable back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0159-kesXOpB.jpg","gif_url":"videos/0159-kesXOpB.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1632","name":"cable drag curl","category":"upper arms","equipment":"cable","instruction_steps":{"en":["Stand facing a cable machine with your feet shoulder-width apart.","Grasp the cable attachment with an underhand grip, palms facing up, and arms fully extended.","Keeping your upper arms stationary, exhale and curl the cable attachment towards your shoulders by contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the cable attachment back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1632-dXz8zjF.jpg","gif_url":"videos/1632-dXz8zjF.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0160","name":"cable floor seated wide-grip row","category":"back","equipment":"cable","instruction_steps":{"en":["Sit on the floor with your legs extended and your back straight.","Attach a cable handle to a low pulley and position the cable machine behind you.","Grasp the handle with a wide overhand grip, palms facing down.","Lean back slightly, keeping your back straight and your chest lifted.","Pull the handle towards your waist, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release the handle back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0160-veXwo0D.jpg","gif_url":"videos/0160-veXwo0D.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0161","name":"cable forward raise","category":"shoulders","equipment":"cable","instruction_steps":{"en":["Stand with your feet shoulder-width apart and your knees slightly bent.","Hold the cable handle with an overhand grip, palms facing down, and your arms fully extended in front of you.","Keeping your arms straight, raise the cable handle up to shoulder level.","Pause for a moment at the top, then slowly lower the cable handle back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","forearms"],"target":"delts","image":"images/0161-hvHhCv8.jpg","gif_url":"videos/0161-hvHhCv8.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0162","name":"cable front raise","category":"shoulders","equipment":"cable","instruction_steps":{"en":["Stand with your feet shoulder-width apart and grasp the cable handle with an overhand grip.","Keep your back straight and your core engaged.","Raise the cable handle in front of you, keeping your arms straight and your palms facing down.","Continue lifting until your arms are parallel to the floor.","Pause for a moment at the top, then slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","forearms"],"target":"delts","image":"images/0162-u2X71Np.jpg","gif_url":"videos/0162-u2X71Np.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0164","name":"cable front shoulder raise","category":"shoulders","equipment":"cable","instruction_steps":{"en":["Stand with your feet shoulder-width apart and grasp the cable handle with an overhand grip.","Keep your back straight and your core engaged.","Raise the cable handle in front of you, keeping your arms straight and your palms facing down.","Continue lifting until your arms are parallel to the floor.","Pause for a moment at the top, then slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"trapezius","secondary_muscles":["trapezius","biceps"],"target":"delts","image":"images/0164-mTT3KLn.jpg","gif_url":"videos/0164-mTT3KLn.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0165","name":"cable hammer curl (with rope)","category":"upper arms","equipment":"cable","instruction_steps":{"en":["Stand upright with your feet shoulder-width apart and a slight bend in your knees.","Hold the cable rope attachment with an underhand grip, palms facing each other, and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the cable rope attachment until your biceps are fully contracted and the rope is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the cable rope attachment back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0165-HPlPoQA.jpg","gif_url":"videos/0165-HPlPoQA.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1722","name":"cable high pulley overhead tricep extension","category":"upper arms","equipment":"cable","instruction_steps":{"en":["Attach a rope to a high pulley and stand facing away from the machine.","Grasp the rope with both hands and extend your arms overhead.","Keep your elbows close to your head and your upper arms stationary.","Slowly lower the rope behind your head by bending your elbows.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/1722-1xHyxys.jpg","gif_url":"videos/1722-1xHyxys.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0167","name":"cable high row (kneeling)","category":"back","equipment":"cable","instruction_steps":{"en":["Attach a straight bar to a cable machine at chest height.","Kneel down in front of the cable machine and grab the bar with an overhand grip, hands shoulder-width apart.","Sit back on your heels, keeping your back straight and your core engaged.","Pull the bar towards your upper abdomen, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release the bar back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"target":"upper back","image":"images/0167-ZSJNetl.jpg","gif_url":"videos/0167-ZSJNetl.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0168","name":"cable hip adduction","category":"upper legs","equipment":"cable","instruction_steps":{"en":["Attach the ankle cuff to your ankle and stand facing the cable machine.","Position yourself far enough away from the machine so that there is tension on the cable.","Place your hands on the machine for support.","Keeping your leg straight, slowly move your leg across your body towards the midline.","Pause for a moment at the end of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","quadriceps"],"target":"adductors","image":"images/0168-hBGWILP.jpg","gif_url":"videos/0168-hBGWILP.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0169","name":"cable incline bench press","category":"chest","equipment":"cable","instruction_steps":{"en":["Adjust the bench to a 45-degree incline.","Attach the cable handles to the high pulleys.","Sit on the bench facing the cable machine with your feet flat on the ground.","Grasp the handles with an overhand grip and bring them to shoulder height.","Push the handles forward and upward until your arms are fully extended.","Pause for a moment, then slowly lower the handles back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"deltoids","secondary_muscles":["deltoids","triceps"],"target":"pectorals","image":"images/0169-Vh0GsK4.jpg","gif_url":"videos/0169-Vh0GsK4.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1318","name":"cable incline bench row","category":"back","equipment":"cable","instruction_steps":{"en":["Set up an incline bench at a 45-degree angle and attach a cable handle to the low pulley.","Sit on the bench facing the cable machine with your feet flat on the floor and your knees slightly bent.","Grasp the cable handle with an overhand grip and extend your arms fully in front of you.","Lean forward from your hips while keeping your back straight and your core engaged.","Pull the cable handle towards your chest by retracting your shoulder blades and bending your elbows.","Squeeze your back muscles at the top of the movement, then slowly extend your arms back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","rear deltoids"],"target":"upper back","image":"images/1318-yaMIo4D.jpg","gif_url":"videos/1318-yaMIo4D.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0171","name":"cable incline fly","category":"chest","equipment":"cable","instruction_steps":{"en":["Adjust the cable machine to a low position and attach the handles.","Sit on an incline bench with your back against the pad and feet flat on the floor.","Grasp the handles with an overhand grip and extend your arms straight out in front of you.","Keeping a slight bend in your elbows, open your arms out to the sides in a controlled motion.","Pause for a moment at the fully extended position, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"deltoids","secondary_muscles":["deltoids","triceps"],"target":"pectorals","image":"images/0171-tBWXbIT.jpg","gif_url":"videos/0171-tBWXbIT.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0170","name":"cable incline fly (on stability ball)","category":"chest","equipment":"cable","instruction_steps":{"en":["Set up a stability ball at an incline angle.","Attach the cable handles to the high pulleys of a cable machine.","Sit on the stability ball facing away from the machine, with your feet firmly planted on the ground.","Grasp the cable handles with an overhand grip, palms facing forward.","Lean forward slightly, keeping your back straight and core engaged.","With a controlled motion, bring your arms out to the sides, keeping a slight bend in your elbows.","Continue the motion until your arms are parallel to the ground.","Pause for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"deltoids","secondary_muscles":["deltoids","triceps"],"target":"pectorals","image":"images/0170-27NNGFr.jpg","gif_url":"videos/0170-27NNGFr.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0172","name":"cable incline pushdown","category":"back","equipment":"cable","instruction_steps":{"en":["Attach a straight bar to a high pulley cable machine.","Stand facing away from the machine with your feet shoulder-width apart.","Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.","Lean forward slightly and keep your back straight.","Pull the bar down towards your thighs by extending your elbows.","Pause for a moment at the bottom, then slowly return the bar to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"lats","image":"images/0172-1PK5Uo3.jpg","gif_url":"videos/0172-1PK5Uo3.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0173","name":"cable incline triceps extension","category":"upper arms","equipment":"cable","instruction_steps":{"en":["Adjust the cable machine to a low pulley position.","Attach a straight bar to the cable.","Stand facing away from the machine with your feet shoulder-width apart.","Grasp the bar with an overhand grip and extend your arms straight overhead.","Lean forward slightly, keeping your back straight and core engaged.","Bend your elbows and lower the bar behind your head, keeping your upper arms close to your ears.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0173-Hx1WC8I.jpg","gif_url":"videos/0173-Hx1WC8I.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0174","name":"cable judo flip","category":"waist","equipment":"cable","instruction_steps":{"en":["Stand facing the cable machine with your feet shoulder-width apart.","Hold the cable handle with both hands at chest level, palms facing down.","Engage your core and rotate your torso to the right, pulling the cable across your body.","As you rotate, pivot your back foot and allow your hips to rotate naturally.","Extend your arms fully and finish the movement by flipping the cable handle over your shoulder.","Return to the starting position by reversing the movement, rotating your torso back to the center.","Repeat the movement on the opposite side.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques","shoulders"],"target":"abs","image":"images/0174-MvQPqVW.jpg","gif_url":"videos/0174-MvQPqVW.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0860","name":"cable kickback","category":"upper arms","equipment":"cable","instruction_steps":{"en":["Stand facing a cable machine with your feet shoulder-width apart.","Hold the cable handle with your right hand and step back to create tension in the cable.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Keep your upper arm close to your body and your elbow bent at a 90-degree angle.","Extend your forearm backward, straightening your arm fully.","Pause for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0860-HEJ6DIX.jpg","gif_url":"videos/0860-HEJ6DIX.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0175","name":"cable kneeling crunch","category":"waist","equipment":"cable","instruction_steps":{"en":["Attach a rope handle to a high pulley and kneel down facing away from the machine.","Hold the rope handle with both hands and place it behind your head, keeping your elbows out to the sides.","Keeping your hips stationary, flex your waist and crunch your torso down towards your thighs.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/0175-WW95auq.jpg","gif_url":"videos/0175-WW95auq.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3697","name":"cable kneeling rear delt row (with rope) (male)","category":"shoulders","equipment":"cable","instruction_steps":{"en":["Attach a rope handle to a low cable pulley and kneel down facing the machine.","Grasp the rope with a neutral grip (palms facing each other) and extend your arms fully in front of you.","Keeping your back straight and core engaged, pull the rope towards your body by retracting your shoulder blades.","Squeeze your shoulder blades together at the end of the movement and hold for a brief pause.","Slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids","biceps"],"target":"delts","image":"images/3697-G61cXLk.jpg","gif_url":"videos/3697-G61cXLk.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0176","name":"cable kneeling triceps extension","category":"upper arms","equipment":"cable","instruction_steps":{"en":["Attach a rope handle to a high pulley and kneel down facing the cable machine.","Grasp the rope with a neutral grip (palms facing each other) and bring your hands to the sides of your head.","Keep your elbows close to your head and your upper arms stationary throughout the exercise.","Extend your forearms by contracting your triceps until your arms are fully extended.","Pause for a moment, then slowly return to the starting position by bending your elbows.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0176-KWdF2JI.jpg","gif_url":"videos/0176-KWdF2JI.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2330","name":"cable lat pulldown full range of motion","category":"back","equipment":"cable","instruction_steps":{"en":["Sit on the lat pulldown machine with your knees positioned under the pads.","Grasp the cable bar with an overhand grip, slightly wider than shoulder-width apart.","Lean back slightly and keep your chest up, maintaining a slight arch in your lower back.","Pull the bar down towards your upper chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the bar back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","rhomboids","rear deltoids"],"target":"lats","image":"images/2330-LEprlgG.jpg","gif_url":"videos/2330-LEprlgG.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0177","name":"cable lateral pulldown (with rope attachment)","category":"back","equipment":"cable","instruction_steps":{"en":["Attach a rope attachment to the cable machine at a high position.","Stand facing the machine with your feet shoulder-width apart.","Grasp the rope with an overhand grip, palms facing each other.","Keep your back straight and lean slightly back.","Pull the rope down towards your sides, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement.","Slowly release the tension and allow the rope to return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/0177-CuaWCmC.jpg","gif_url":"videos/0177-CuaWCmC.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2616","name":"cable lateral pulldown with v-bar","category":"back","equipment":"cable","instruction_steps":{"en":["Sit down on the cable pulldown machine and grab the v-bar attachment with an overhand grip.","Adjust the knee pad so that your thighs are secured under it.","Keep your back straight and lean back slightly.","Pull the v-bar down towards your upper chest while keeping your elbows close to your body.","Squeeze your back muscles at the bottom of the movement.","Slowly return the v-bar to the starting position and repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/2616-4c9BhzB.jpg","gif_url":"videos/2616-4c9BhzB.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0178","name":"cable lateral raise","category":"shoulders","equipment":"cable","instruction_steps":{"en":["Stand with your feet shoulder-width apart and grasp the cable handles with an overhand grip.","Keep your arms straight and your core engaged.","Raise your arms out to the sides until they are parallel to the floor.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"traps","secondary_muscles":["traps","triceps"],"target":"delts","image":"images/0178-goJ6ezq.jpg","gif_url":"videos/0178-goJ6ezq.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0179","name":"cable low fly","category":"chest","equipment":"cable","instruction_steps":{"en":["Attach the handles to the low pulleys of a cable machine and select an appropriate weight.","Stand in the middle of the machine with your feet shoulder-width apart and a slight bend in your knees.","Grasp the handles with an overhand grip and extend your arms out to the sides, keeping a slight bend in your elbows.","Maintaining control, slowly bring your arms forward in a sweeping motion, crossing them in front of your body.","Pause for a moment at the peak of the movement, feeling the stretch in your chest muscles.","Reverse the motion and slowly return your arms to the starting position, keeping tension on your chest muscles throughout.","Repeat for the desired number of repetitions."]},"muscle_group":"deltoids","secondary_muscles":["deltoids","triceps"],"target":"pectorals","image":"images/0179-FVmZVhk.jpg","gif_url":"videos/0179-FVmZVhk.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0180","name":"cable low seated row","category":"back","equipment":"cable","instruction_steps":{"en":["Sit on the machine with your feet flat on the footrests and your knees slightly bent.","Grasp the handles with an overhand grip, palms facing down.","Keep your back straight and lean slightly forward, maintaining a slight bend in your elbows.","Pull the handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0180-hvV79Si.jpg","gif_url":"videos/0180-hvV79Si.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1634","name":"cable lying bicep curl","category":"upper arms","equipment":"cable","instruction_steps":{"en":["Attach a straight bar to a low pulley cable machine.","Lie face up on a flat bench with your feet flat on the ground.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Extend your arms fully, keeping your elbows close to your sides.","Keeping your upper arms stationary, exhale and curl the bar up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the bar back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1634-otqIxU4.jpg","gif_url":"videos/1634-otqIxU4.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0182","name":"cable lying close-grip curl","category":"upper arms","equipment":"cable","instruction_steps":{"en":["Attach a straight bar to a low pulley cable machine.","Lie face up on a flat bench with your feet flat on the ground.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Extend your arms fully, keeping your elbows close to your sides.","Keeping your upper arms stationary, curl the bar towards your chest by contracting your biceps.","Pause for a moment at the top, squeezing your biceps.","Slowly lower the bar back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0182-61GrD55.jpg","gif_url":"videos/0182-61GrD55.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0184","name":"cable lying extension pullover (with rope attachment)","category":"back","equipment":"cable","instruction_steps":{"en":["Attach a rope to a cable machine and set the pulley at the highest position.","Lie down on a bench with your head towards the cable machine.","Hold the rope with both hands and extend your arms straight up above your chest.","Keeping your arms straight, slowly lower the rope behind your head while maintaining control.","Pause for a moment at the bottom, then slowly raise the rope back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"lats","image":"images/0184-Q2Eu1Ax.jpg","gif_url":"videos/0184-Q2Eu1Ax.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0185","name":"cable lying fly","category":"chest","equipment":"cable","instruction_steps":{"en":["Attach the handles to the cables and lie flat on a bench with your feet flat on the ground.","Hold the handles with your palms facing each other and your arms extended straight above your chest.","Keeping a slight bend in your elbows, lower your arms out to the sides in a wide arc until you feel a stretch in your chest.","Pause for a moment, then squeeze your chest muscles to bring your arms back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"deltoids","secondary_muscles":["deltoids","triceps"],"target":"pectorals","image":"images/0185-lJJ7Yq8.jpg","gif_url":"videos/0185-lJJ7Yq8.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0186","name":"cable lying triceps extension v. 2","category":"upper arms","equipment":"cable","instruction_steps":{"en":["Attach a rope handle to a low pulley cable machine.","Lie down on a flat bench facing up, with your head towards the cable machine.","Grasp the rope handle with both hands, palms facing each other, and extend your arms straight up over your chest.","Keeping your upper arms stationary, slowly lower the rope handle towards your forehead by bending your elbows.","Pause for a moment at the bottom, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0186-uxJcFUU.jpg","gif_url":"videos/0186-uxJcFUU.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0188","name":"cable middle fly","category":"chest","equipment":"cable","instruction_steps":{"en":["Attach cables to both sides of a cable machine at chest height.","Stand in the center of the machine with one foot slightly in front of the other.","Grasp the handles with an overhand grip and extend your arms out to the sides.","Keep a slight bend in your elbows and maintain a slight forward lean.","Engage your chest muscles and bring your arms forward in a sweeping motion.","Pause for a moment at the center, then slowly return your arms back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"deltoids","secondary_muscles":["deltoids","triceps"],"target":"pectorals","image":"images/0188-xLYSdtg.jpg","gif_url":"videos/0188-xLYSdtg.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0189","name":"cable one arm bent over row","category":"back","equipment":"cable","instruction_steps":{"en":["Stand facing a cable machine with your feet shoulder-width apart.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Grasp the cable handle with one hand, palm facing inward, and extend your arm fully.","Pull the cable handle towards your body, keeping your elbow close to your side, until your hand reaches your lower chest.","Pause for a moment, then slowly extend your arm back to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0189-EIsE3u8.jpg","gif_url":"videos/0189-EIsE3u8.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0190","name":"cable one arm curl","category":"upper arms","equipment":"cable","instruction_steps":{"en":["Stand facing the cable machine with your feet shoulder-width apart.","Grasp the cable handle with an underhand grip, palm facing up.","Keep your elbow close to your side and slowly curl your forearm up towards your shoulder.","Pause for a moment at the top, then slowly lower your forearm back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0190-YTur5nR.jpg","gif_url":"videos/0190-YTur5nR.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1262","name":"cable one arm decline chest fly","category":"chest","equipment":"cable","instruction_steps":{"en":["Attach a D-handle to a low pulley cable machine and set the bench to a decline angle.","Lie down on the bench with your head towards the machine and grab the handle with your right hand.","Extend your arm straight up above your chest, keeping a slight bend in your elbow.","With a controlled motion, lower your arm out to the side until your hand is in line with your shoulder.","Pause for a moment, then reverse the motion and bring your arm back to the starting position.","Repeat for the desired number of repetitions, then switch to your left arm and repeat the exercise."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/1262-w4dLzSx.jpg","gif_url":"videos/1262-w4dLzSx.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1263","name":"cable one arm fly on exercise ball","category":"chest","equipment":"cable","instruction_steps":{"en":["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a cable handle in one hand and extend your arm out to the side, parallel to the ground.","Keep your elbow slightly bent and your palm facing forward.","Slowly bring your arm across your body, squeezing your chest muscles.","Pause for a moment at the end of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},"muscle_group":"deltoids","secondary_muscles":["deltoids","triceps"],"target":"pectorals","image":"images/1263-hHy8tQG.jpg","gif_url":"videos/1263-hHy8tQG.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1264","name":"cable one arm incline fly on exercise ball","category":"chest","equipment":"cable","instruction_steps":{"en":["Sit on an exercise ball with your feet flat on the ground and your back against an incline bench.","Hold a cable handle in one hand with your arm extended and palm facing inward.","Keeping a slight bend in your elbow, slowly lower your arm out to the side until your hand is in line with your shoulder.","Pause for a moment, then squeeze your chest muscles to bring your arm back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"deltoids","secondary_muscles":["deltoids","triceps"],"target":"pectorals","image":"images/1264-P14Dz9D.jpg","gif_url":"videos/1264-P14Dz9D.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1265","name":"cable one arm incline press","category":"chest","equipment":"cable","instruction_steps":{"en":["Adjust the cable machine to a low pulley position.","Sit on an incline bench facing away from the cable machine.","Grasp the handle with one hand and bring it up to shoulder height.","Position your feet firmly on the ground and maintain a stable position.","Press the handle forward and upward, extending your arm fully.","Pause for a moment at the top, then slowly lower the handle back to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},"muscle_group":"deltoids","secondary_muscles":["deltoids","triceps"],"target":"pectorals","image":"images/1265-GKEH6jj.jpg","gif_url":"videos/1265-GKEH6jj.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1266","name":"cable one arm incline press on exercise ball","category":"chest","equipment":"cable","instruction_steps":{"en":["Sit on an exercise ball with your feet flat on the ground and your back resting against an incline bench.","Hold a cable handle in one hand and position your arm at a 90-degree angle with your elbow bent.","Press the cable handle forward and upward, extending your arm fully.","Pause for a moment at the top, then slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/1266-6t00BsF.jpg","gif_url":"videos/1266-6t00BsF.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0191","name":"cable one arm lateral bent-over","category":"chest","equipment":"cable","instruction_steps":{"en":["Stand with your feet shoulder-width apart, facing a cable machine.","Grasp the handle with one hand and step back to create tension on the cable.","Bend forward at the waist, keeping your back straight and your core engaged.","Extend your arm out to the side, parallel to the ground, with a slight bend in your elbow.","Slowly bring your arm back to the starting position, maintaining control throughout the movement.","Repeat for the desired number of repetitions, then switch sides."]},"muscle_group":"deltoids","secondary_muscles":["deltoids","trapezius"],"target":"pectorals","image":"images/0191-dB07vDu.jpg","gif_url":"videos/0191-dB07vDu.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0192","name":"cable one arm lateral raise","category":"shoulders","equipment":"cable","instruction_steps":{"en":["Stand with your feet shoulder-width apart, facing the cable machine.","Hold the cable handle with one hand, palm facing down, and stand far enough away from the machine so that there is tension on the cable.","Keep your arm straight and slowly raise it out to the side until it is parallel to the ground.","Pause for a moment at the top, then slowly lower your arm back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},"muscle_group":"traps","secondary_muscles":["traps","triceps"],"target":"delts","image":"images/0192-wEulIzp.jpg","gif_url":"videos/0192-wEulIzp.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1633","name":"cable one arm preacher curl","category":"upper arms","equipment":"cable","instruction_steps":{"en":["Adjust the cable machine so that the preacher curl pad is at chest height.","Stand facing the cable machine with your feet shoulder-width apart.","Grasp the cable handle with an underhand grip and position your upper arm against the preacher curl pad.","Keep your back straight and your core engaged.","Slowly curl the cable handle towards your shoulder, keeping your upper arm against the pad.","Pause for a moment at the top of the movement, squeezing your biceps.","Slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions.","Switch arms and repeat the exercise."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1633-eHBlPsa.jpg","gif_url":"videos/1633-eHBlPsa.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1267","name":"cable one arm press on exercise ball","category":"chest","equipment":"cable","instruction_steps":{"en":["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a cable handle in one hand and position your arm at chest height, elbow bent.","Place your other hand on your hip for stability.","Press the cable handle forward, extending your arm fully.","Pause for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/1267-MKIelrR.jpg","gif_url":"videos/1267-MKIelrR.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3563","name":"cable one arm pulldown","category":"back","equipment":"cable","instruction_steps":{"en":["Attach a single handle to a high pulley cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the handle with an overhand grip and extend your arm fully.","Keep your back straight and your core engaged.","Pull the handle down towards your side while keeping your elbow close to your body.","Pause for a moment at the bottom of the movement, squeezing your lat muscle.","Slowly release the handle back to the starting position.","Repeat for the desired number of repetitions.","Switch sides and repeat the exercise with the other arm."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/3563-U5INZY6.jpg","gif_url":"videos/3563-U5INZY6.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1635","name":"cable one arm reverse preacher curl","category":"upper arms","equipment":"cable","instruction_steps":{"en":["Adjust the cable machine so that the pulley is at the lowest position.","Stand facing the cable machine with your feet shoulder-width apart.","Grasp the cable handle with an underhand grip and position your upper arm against the preacher bench pad.","Keep your back straight and your core engaged throughout the exercise.","Slowly curl your forearm towards your bicep, keeping your upper arm stationary against the pad.","Pause for a moment at the top of the movement, squeezing your bicep.","Slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions.","Switch arms and repeat the exercise."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1635-ZXnjcOQ.jpg","gif_url":"videos/1635-ZXnjcOQ.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0193","name":"cable one arm straight back high row (kneeling)","category":"back","equipment":"cable","instruction_steps":{"en":["Attach a handle to a cable machine at waist height.","Kneel down facing the cable machine and grab the handle with one hand.","Keep your back straight and your core engaged.","Pull the handle towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top of the movement.","Slowly release the handle back to the starting position.","Repeat for the desired number of repetitions.","Switch sides and repeat the exercise with the other arm."]},"muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"target":"upper back","image":"images/0193-WrYPP2g.jpg","gif_url":"videos/0193-WrYPP2g.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1723","name":"cable one arm tricep pushdown","category":"upper arms","equipment":"cable","instruction_steps":{"en":["Stand facing a cable machine with a straight bar attachment at chest height.","Grasp the bar with an overhand grip and step back to create tension in the cable.","Position your feet shoulder-width apart and slightly bend your knees.","Keep your back straight and core engaged throughout the exercise.","Start with your arm fully extended and perpendicular to the floor.","Keeping your upper arm stationary, exhale and push the bar down until your arm is fully extended.","Pause for a moment, then inhale and slowly return to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"triceps","image":"images/1723-qRZ5S1N.jpg","gif_url":"videos/1723-qRZ5S1N.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1636","name":"cable overhead curl","category":"upper arms","equipment":"cable","instruction_steps":{"en":["Attach a straight bar to a high pulley cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary.","Exhale and curl the bar down towards your forehead, keeping your upper arms stationary.","Pause for a moment at the bottom of the movement, squeezing your biceps.","Inhale and slowly return the bar to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms","shoulders"],"target":"biceps","image":"images/1636-wDUqY2u.jpg","gif_url":"videos/1636-wDUqY2u.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1637","name":"cable overhead curl on exercise ball","category":"upper arms","equipment":"cable","instruction_steps":{"en":["Sit on an exercise ball and hold the cable handle with an underhand grip.","Extend your arms fully overhead, keeping your elbows close to your ears.","Slowly curl the cable down towards your forehead, keeping your upper arms stationary.","Pause for a moment at the bottom of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms","shoulders"],"target":"biceps","image":"images/1637-ioTf098.jpg","gif_url":"videos/1637-ioTf098.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0194","name":"cable overhead triceps extension (rope attachment)","category":"upper arms","equipment":"cable","instruction_steps":{"en":["Attach a rope to a cable machine at a high position.","Stand facing away from the machine with your feet shoulder-width apart.","Grasp the rope with both hands, palms facing each other, and bring your hands above your head.","Keep your upper arms close to your head and your elbows pointing forward.","Slowly lower the rope behind your head by bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0194-2IxROQ1.jpg","gif_url":"videos/0194-2IxROQ1.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1319","name":"cable palm rotational row","category":"back","equipment":"cable","instruction_steps":{"en":["Attach a handle to a cable machine at waist height.","Stand facing the machine with your feet shoulder-width apart.","Grasp the handle with an overhand grip, palms facing down.","Step back to create tension on the cable, keeping your back straight and knees slightly bent.","Pull the handle towards your body, rotating your palms to face upwards as you do so.","Squeeze your shoulder blades together at the end of the movement.","Slowly release the handle back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/1319-OmQ8w0p.jpg","gif_url":"videos/1319-OmQ8w0p.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0195","name":"cable preacher curl","category":"upper arms","equipment":"cable","instruction_steps":{"en":["Adjust the cable machine so that the preacher curl pad is at chest height.","Sit on the preacher curl bench and place your upper arms on the pad, gripping the cable attachment with an underhand grip.","Keep your back straight and your elbows tucked in at your sides.","Slowly curl the cable attachment up towards your shoulders, squeezing your biceps at the top of the movement.","Pause for a moment, then slowly lower the cable attachment back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0195-P2lNrGL.jpg","gif_url":"videos/0195-P2lNrGL.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1268","name":"cable press on exercise ball","category":"chest","equipment":"cable","instruction_steps":{"en":["Sit on an exercise ball with your feet flat on the ground and your knees at a 90-degree angle.","Hold the cable handles at chest height with your palms facing down and your elbows bent.","Engage your core and press the cable handles forward until your arms are fully extended.","Pause for a moment, then slowly release the tension and bring the cable handles back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/1268-vAwm6rK.jpg","gif_url":"videos/1268-vAwm6rK.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0196","name":"cable pull through (with rope)","category":"upper legs","equipment":"cable","instruction_steps":{"en":["Stand facing away from the cable machine with your feet shoulder-width apart.","Grab the rope attachment with both hands and step forward, creating tension in the cable.","Bend at the hips and lower your upper body until it is parallel to the ground, keeping your back straight.","Engage your glutes and hamstrings to pull your body back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"target":"glutes","image":"images/0196-OM46QHm.jpg","gif_url":"videos/0196-OM46QHm.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0198","name":"cable pulldown","category":"back","equipment":"cable","instruction_steps":{"en":["Adjust the cable pulldown machine so that the seat is at a comfortable height and the knee pad is secured.","Sit on the seat with your back straight and your feet flat on the ground.","Grasp the cable bar with an overhand grip, slightly wider than shoulder-width apart.","Lean back slightly and engage your core.","Pull the cable bar down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the bar back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/0198-RVwzP10.jpg","gif_url":"videos/0198-RVwzP10.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0197","name":"cable pulldown (pro lat bar)","category":"back","equipment":"cable","instruction_steps":{"en":["Adjust the seat height so that your thighs are parallel to the ground and your feet are flat on the floor.","Grasp the lat bar with an overhand grip, slightly wider than shoulder-width apart.","Sit down and lean back slightly, keeping your chest up and your back straight.","Pull the bar down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the bar back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/0197-qdRxqCj.jpg","gif_url":"videos/0197-qdRxqCj.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1638","name":"cable pulldown bicep curl","category":"upper arms","equipment":"cable","instruction_steps":{"en":["Attach a straight bar to the cable machine at the highest setting.","Stand facing the machine with your feet shoulder-width apart.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary.","Exhale and slowly curl the bar down towards your thighs, keeping your wrists straight.","Pause for a moment at the bottom of the movement, squeezing your biceps.","Inhale and slowly return the bar to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1638-QTXKWPh.jpg","gif_url":"videos/1638-QTXKWPh.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0201","name":"cable pushdown","category":"upper arms","equipment":"cable","instruction_steps":{"en":["Attach a straight bar to a high pulley cable machine.","Stand facing the machine with your feet shoulder-width apart and a slight bend in your knees.","Grasp the bar with an overhand grip, hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary.","Exhale and push the bar down until your elbows are fully extended.","Pause for a moment, then inhale and slowly return the bar to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"triceps","image":"images/0201-3ZflifB.jpg","gif_url":"videos/0201-3ZflifB.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0199","name":"cable pushdown (straight arm) v. 2","category":"back","equipment":"cable","instruction_steps":{"en":["Attach a straight bar to a high pulley cable machine.","Stand facing the machine with your feet shoulder-width apart and a slight bend in your knees.","Grasp the bar with an overhand grip, keeping your arms straight and your palms facing down.","Engage your core and keep your back straight as you exhale and push the bar down towards your thighs.","Pause for a moment at the bottom, then slowly return the bar to the starting position while inhaling.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"lats","image":"images/0199-PskORrA.jpg","gif_url":"videos/0199-PskORrA.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0200","name":"cable pushdown (with rope attachment)","category":"upper arms","equipment":"cable","instruction_steps":{"en":["Attach a rope attachment to a high pulley on a cable machine.","Stand facing the machine with your feet shoulder-width apart and a slight bend in your knees.","Grasp the rope with an overhand grip, palms facing each other.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Exhale and push the rope downward by extending your elbows until your arms are fully extended.","Pause for a moment, then inhale and slowly return to the starting position by allowing your elbows to flex.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"triceps","image":"images/0200-dU605di.jpg","gif_url":"videos/0200-dU605di.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0202","name":"cable rear delt row (stirrups)","category":"shoulders","equipment":"cable","instruction_steps":{"en":["Attach a stirrup handle to a low cable pulley and stand facing the machine.","Grasp the handle with your left hand and take a step back with your right foot, positioning your body at a slight angle.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and your core engaged.","With your left arm extended and your palm facing down, pull the handle towards your chest by retracting your shoulder blade.","Pause for a moment at the top of the movement, squeezing your shoulder blade.","Slowly release the handle back to the starting position and repeat for the desired number of repetitions.","Switch sides and repeat the exercise with your right arm."]},"muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids","biceps"],"target":"delts","image":"images/0202-yUdIGNs.jpg","gif_url":"videos/0202-yUdIGNs.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0203","name":"cable rear delt row (with rope)","category":"shoulders","equipment":"cable","instruction_steps":{"en":["Attach a rope handle to a low pulley cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the rope handle with an overhand grip, palms facing each other.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Keep your elbows slightly bent and pull the rope towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids","biceps"],"target":"delts","image":"images/0203-wqNPGCg.jpg","gif_url":"videos/0203-wqNPGCg.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0204","name":"cable rear drive","category":"upper arms","equipment":"cable","instruction_steps":{"en":["Attach a handle to a low pulley cable machine and stand facing away from the machine.","Grasp the handle with an overhand grip and extend your arms straight out in front of you.","Keeping your elbows stationary, pull the handle back towards your body, squeezing your triceps at the end of the movement.","Slowly return the handle to the starting position and repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","back"],"target":"triceps","image":"images/0204-c3QQLPi.jpg","gif_url":"videos/0204-c3QQLPi.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0205","name":"cable rear pulldown","category":"back","equipment":"cable","instruction_steps":{"en":["Adjust the cable machine so that the pulley is at the highest position.","Sit facing the machine with your feet flat on the ground and your knees slightly bent.","Grasp the cable attachment with an overhand grip, hands slightly wider than shoulder-width apart.","Lean back slightly, keeping your back straight and your chest up.","Pull the cable attachment down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the cable back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","rhomboids","rear deltoids"],"target":"lats","image":"images/0205-SpsOSXk.jpg","gif_url":"videos/0205-SpsOSXk.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0873","name":"cable reverse crunch","category":"waist","equipment":"cable","instruction_steps":{"en":["Attach a cable to a low pulley and lie down facing up on a mat.","Hold the cable with both hands and extend your arms straight up towards the ceiling.","Bend your knees and lift your legs up, bringing your thighs towards your chest.","While keeping your upper body stable, curl your pelvis up towards your chest, lifting your hips off the mat.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0873-RqOtqD7.jpg","gif_url":"videos/0873-RqOtqD7.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0206","name":"cable reverse curl","category":"upper arms","equipment":"cable","instruction_steps":{"en":["Attach a straight bar to a low pulley cable machine.","Stand facing the machine with your feet shoulder-width apart and your knees slightly bent.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Exhale and curl the bar up towards your shoulders, contracting your biceps.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the bar back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0206-eOG0r6v.jpg","gif_url":"videos/0206-eOG0r6v.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2406","name":"cable reverse grip triceps pushdown (sz-bar) (with arm blaster)","category":"upper arms","equipment":"cable","instruction_steps":{"en":["Attach a straight bar to the cable machine at the highest setting.","Stand facing the cable machine with your feet shoulder-width apart.","Grasp the bar with an underhand grip, palms facing up, and your hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Engage your triceps and slowly push the bar down until your arms are fully extended.","Pause for a moment at the bottom, then slowly return the bar to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"triceps","image":"images/2406-ThKP69G.jpg","gif_url":"videos/2406-ThKP69G.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1413","name":"cable reverse one arm curl","category":"upper arms","equipment":"cable","instruction_steps":{"en":["Stand facing a cable machine with your feet shoulder-width apart.","Grasp the cable handle with an underhand grip, palm facing down.","Keep your elbow close to your side and slowly curl your forearm up towards your shoulder.","Pause for a moment at the top, then slowly lower your forearm back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1413-gVlnLIJ.jpg","gif_url":"videos/1413-gVlnLIJ.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0209","name":"cable reverse preacher curl","category":"upper arms","equipment":"cable","instruction_steps":{"en":["Adjust the cable machine so that the preacher curl pad is at chest height.","Sit on the preacher curl bench and place your upper arms on the pad, with your palms facing down and your elbows fully extended.","Grab the cable handles with an underhand grip, shoulder-width apart.","Keeping your upper arms stationary, exhale and curl the handles towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the handles back to the starting position, fully extending your elbows.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0209-IwX5NqK.jpg","gif_url":"videos/0209-IwX5NqK.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0210","name":"cable reverse wrist curl","category":"lower arms","equipment":"cable","instruction_steps":{"en":["Attach a cable to a low pulley and sit on a bench facing the cable machine.","Grasp the cable handle with an overhand grip, palms facing down.","Rest your forearms on your thighs, with your wrists hanging off the edge.","Keeping your forearms stationary, exhale and curl your wrists upward as far as possible.","Pause for a moment at the top, then inhale and slowly lower your wrists back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms","wrists"],"target":"forearms","image":"images/0210-eYmsEPR.jpg","gif_url":"videos/0210-eYmsEPR.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0207","name":"cable reverse-grip pushdown","category":"upper arms","equipment":"cable","instruction_steps":{"en":["Attach a straight bar to a high pulley cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the bar with an underhand grip, palms facing up, and your hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Using your triceps, push the bar down until your arms are fully extended and your triceps are contracted.","Pause for a moment, then slowly return the bar to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"triceps","image":"images/0207-VjYliFZ.jpg","gif_url":"videos/0207-VjYliFZ.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0208","name":"cable reverse-grip straight back seated high row","category":"back","equipment":"cable","instruction_steps":{"en":["Sit on the seat facing the cable machine with your feet flat on the floor.","Grasp the cable attachment with an underhand grip, palms facing up, and your hands shoulder-width apart.","Keep your back straight and lean slightly forward from your hips.","Pull the cable towards your torso by retracting your shoulder blades and squeezing your back muscles.","Pause for a moment at the peak of the contraction, then slowly release the cable back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0208-PNtsX17.jpg","gif_url":"videos/0208-PNtsX17.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1320","name":"cable rope crossover seated row","category":"back","equipment":"cable","instruction_steps":{"en":["Sit on the rowing machine with your feet flat on the footrests and your knees slightly bent.","Grasp the cable ropes with an overhand grip, palms facing each other.","Lean back slightly, keeping your back straight and your core engaged.","Pull the cable ropes towards your chest, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/1320-UFGF6gk.jpg","gif_url":"videos/1320-UFGF6gk.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1321","name":"cable rope elevated seated row","category":"back","equipment":"cable","instruction_steps":{"en":["Sit on the elevated seat facing the cable machine.","Grab the cable rope handles with an overhand grip, palms facing each other.","Keep your back straight and lean slightly back, maintaining a slight bend in your knees.","Pull the cable towards your body by retracting your shoulder blades and squeezing your back muscles.","Pause for a moment at the fully contracted position.","Slowly release the tension and extend your arms back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/1321-c8oybX6.jpg","gif_url":"videos/1321-c8oybX6.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1322","name":"cable rope extension incline bench row","category":"back","equipment":"cable","instruction_steps":{"en":["Set up an incline bench at a 45-degree angle and attach a cable machine to the low pulley.","Attach a rope handle to the cable machine and sit on the incline bench facing the machine.","Grab the rope handle with an overhand grip and lean forward, keeping your back straight.","Extend your arms fully, pulling the rope towards your upper chest while keeping your elbows close to your body.","Squeeze your shoulder blades together at the end of the movement.","Slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"target":"upper back","image":"images/1322-MgKwAAo.jpg","gif_url":"videos/1322-MgKwAAo.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1639","name":"cable rope hammer preacher curl","category":"upper arms","equipment":"cable","instruction_steps":{"en":["Attach a rope attachment to a low pulley cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the rope with a neutral grip (palms facing each other).","Position your upper arms against the preacher bench pad, keeping your elbows slightly bent.","Keeping your upper arms stationary, exhale and curl the rope towards your shoulders by contracting your biceps.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the rope back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1639-PcPe0P5.jpg","gif_url":"videos/1639-PcPe0P5.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1724","name":"cable rope high pulley overhead tricep extension","category":"upper arms","equipment":"cable","instruction_steps":{"en":["Attach a rope to a high pulley and adjust the weight accordingly.","Stand facing away from the pulley machine with your feet shoulder-width apart.","Grasp the rope with both hands, palms facing down, and bring your hands above your head.","Keep your upper arms close to your head and perpendicular to the floor.","Slowly lower the rope behind your head by bending your elbows.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/1724-NN8nSNT.jpg","gif_url":"videos/1724-NN8nSNT.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1725","name":"cable rope incline tricep extension","category":"upper arms","equipment":"cable","instruction_steps":{"en":["Attach a rope to a high pulley and adjust the incline bench to a comfortable angle.","Stand facing away from the pulley with your feet shoulder-width apart.","Grasp the rope with an overhand grip and extend your arms straight overhead.","Keep your elbows close to your head and your upper arms stationary throughout the exercise.","Lower the rope behind your head by bending your elbows until your forearms touch your biceps.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/1725-ZujAdR9.jpg","gif_url":"videos/1725-ZujAdR9.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1726","name":"cable rope lying on floor tricep extension","category":"upper arms","equipment":"cable","instruction_steps":{"en":["Attach a rope to a cable machine and set it to the lowest position.","Lie on the floor facing up, with your head towards the cable machine.","Hold the rope with both hands, palms facing each other, and extend your arms straight up towards the ceiling.","Keep your upper arms stationary and slowly lower the rope towards your forehead, bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/1726-U3ffHlY.jpg","gif_url":"videos/1726-U3ffHlY.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1640","name":"cable rope one arm hammer preacher curl","category":"upper arms","equipment":"cable","instruction_steps":{"en":["Attach a rope handle to a low pulley cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the rope handle with an underhand grip, palms facing up.","Position your upper arm against the preacher bench pad, keeping your elbow slightly bent.","Keep your back straight and your core engaged throughout the exercise.","Slowly curl the rope handle towards your shoulder, keeping your upper arm stationary.","Squeeze your biceps at the top of the movement, then slowly lower the rope handle back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1640-4hATdoB.jpg","gif_url":"videos/1640-4hATdoB.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1323","name":"cable rope seated row","category":"back","equipment":"cable","instruction_steps":{"en":["Sit on the rowing machine with your feet flat on the footrests and knees slightly bent.","Grasp the cable ropes with an overhand grip, palms facing each other.","Keep your back straight and lean slightly forward, maintaining a slight bend in your elbows.","Pull the cable ropes towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/1323-SJqRxOt.jpg","gif_url":"videos/1323-SJqRxOt.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0211","name":"cable russian twists (on stability ball)","category":"waist","equipment":"cable","instruction_steps":{"en":["Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold the cable handle with both hands and extend your arms straight out in front of you.","Lean back slightly while keeping your back straight and your core engaged.","Twist your torso to the right, bringing the cable handle towards your right hip.","Pause for a moment, then twist your torso to the left, bringing the cable handle towards your left hip.","Continue alternating twists for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques","lower back"],"target":"abs","image":"images/0211-d9Xaxq6.jpg","gif_url":"videos/0211-d9Xaxq6.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2144","name":"cable seated chest press","category":"chest","equipment":"cable","instruction_steps":{"en":["Adjust the seat height and cable handles to a comfortable position.","Sit on the bench with your back straight and feet flat on the floor.","Grasp the cable handles with an overhand grip at shoulder height.","Push the handles forward and away from your body, extending your arms fully.","Pause for a moment, then slowly bring the handles back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/2144-nIR4Rwl.jpg","gif_url":"videos/2144-nIR4Rwl.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0212","name":"cable seated crunch","category":"waist","equipment":"cable","instruction_steps":{"en":["Sit on a cable machine with your feet flat on the ground and your knees bent.","Hold the cable handle with both hands and position it behind your head.","Engage your abs and slowly curl your upper body forward, bringing your chest towards your knees.","Pause for a moment at the top, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/0212-8xUv4J7.jpg","gif_url":"videos/0212-8xUv4J7.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1641","name":"cable seated curl","category":"upper arms","equipment":"cable","instruction_steps":{"en":["Sit on a cable machine with your feet flat on the ground and your back straight.","Grasp the cable attachment with an underhand grip, palms facing up, and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the cable attachment towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the cable attachment back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1641-8oYqOt9.jpg","gif_url":"videos/1641-8oYqOt9.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0213","name":"cable seated high row (v-bar)","category":"back","equipment":"cable","instruction_steps":{"en":["Sit on the cable machine with your feet flat on the floor and your knees slightly bent.","Grasp the v-bar attachment with an overhand grip, palms facing each other, and your hands shoulder-width apart.","Keep your back straight and lean slightly forward from the hips.","Pull the v-bar towards your torso by retracting your shoulder blades and squeezing your back muscles.","Pause for a moment at the peak of the contraction, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","rhomboids","rear deltoids"],"target":"lats","image":"images/0213-pwt0pnM.jpg","gif_url":"videos/0213-pwt0pnM.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0214","name":"cable seated one arm alternate row","category":"back","equipment":"cable","instruction_steps":{"en":["Sit on a bench facing a cable machine with your feet flat on the ground and knees slightly bent.","Grasp the handle with one hand and keep your arm fully extended in front of you.","Pull the handle towards your body, retracting your shoulder blade and keeping your elbow close to your side.","Pause for a moment at the top of the movement, squeezing your back muscles.","Slowly release the handle back to the starting position.","Repeat with the other arm.","Alternate between arms for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0214-vpp9Ku2.jpg","gif_url":"videos/0214-vpp9Ku2.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1642","name":"cable seated one arm concentration curl","category":"upper arms","equipment":"cable","instruction_steps":{"en":["Sit on a bench with your feet flat on the floor and your back straight.","Hold a cable handle with one hand and place your elbow on the inside of your thigh, just above the knee.","Keep your upper arm stationary and curl the cable handle towards your shoulder while exhaling.","Pause for a moment at the top of the movement, squeezing your biceps.","Slowly lower the cable handle back to the starting position while inhaling.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1642-rZ80Gbp.jpg","gif_url":"videos/1642-rZ80Gbp.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1643","name":"cable seated overhead curl","category":"upper arms","equipment":"cable","instruction_steps":{"en":["Sit on a bench facing the cable machine with your feet flat on the ground.","Grasp the cable attachment with an underhand grip, palms facing up, and your hands shoulder-width apart.","Keep your upper arms stationary and your elbows close to your sides.","Exhale and curl the cable attachment towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the cable attachment back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms","shoulders"],"target":"biceps","image":"images/1643-DpWMFP5.jpg","gif_url":"videos/1643-DpWMFP5.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0215","name":"cable seated rear lateral raise","category":"shoulders","equipment":"cable","instruction_steps":{"en":["Sit on a bench facing the cable machine with your feet flat on the ground.","Grasp the cable handles with an overhand grip and extend your arms straight in front of you.","Keeping your arms straight, slowly raise them out to the sides until they are parallel to the floor.","Pause for a moment at the top, then slowly lower your arms back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"traps","secondary_muscles":["traps","rhomboids"],"target":"delts","image":"images/0215-x825CZm.jpg","gif_url":"videos/0215-x825CZm.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0861","name":"cable seated row","category":"back","equipment":"cable","instruction_steps":{"en":["Sit on the cable row machine with your feet flat on the footrests and your knees slightly bent.","Grasp the handles with an overhand grip, keeping your back straight and your shoulders relaxed.","Pull the handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0861-fUBheHs.jpg","gif_url":"videos/0861-fUBheHs.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0216","name":"cable seated shoulder internal rotation","category":"shoulders","equipment":"cable","instruction_steps":{"en":["Sit on a bench or chair facing the cable machine with your feet flat on the ground.","Hold the cable handle with your arm extended straight out in front of you, parallel to the ground.","Keep your elbow slightly bent and your shoulder blades pulled back and down.","Slowly rotate your arm inward, bringing the cable handle towards the center of your body.","Pause for a moment at the end of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"rotator cuff","secondary_muscles":["rotator cuff","triceps"],"target":"delts","image":"images/0216-YPoVrBi.jpg","gif_url":"videos/0216-YPoVrBi.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2399","name":"cable seated twist","category":"waist","equipment":"cable","instruction_steps":{"en":["Sit on a cable machine with your feet flat on the ground and your knees slightly bent.","Hold the cable handle with both hands and extend your arms straight in front of you.","Keeping your core engaged, slowly rotate your torso to one side, pulling the cable across your body.","Pause for a moment at the end of the range of motion, then slowly rotate back to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/2399-UEjSrKI.jpg","gif_url":"videos/2399-UEjSrKI.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0218","name":"cable seated wide-grip row","category":"back","equipment":"cable","instruction_steps":{"en":["Sit on the cable row machine with your feet flat on the footrests and your knees slightly bent.","Grasp the handle with a wide overhand grip, palms facing down.","Keep your back straight and lean slightly forward from the hips.","Pull the handle towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the peak of the contraction.","Slowly release the handle back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0218-qcY50ZD.jpg","gif_url":"videos/0218-qcY50ZD.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0219","name":"cable shoulder press","category":"shoulders","equipment":"cable","instruction_steps":{"en":["Adjust the cable machine so that the handles are at shoulder height.","Stand facing away from the machine with your feet shoulder-width apart.","Grasp the handles with an overhand grip and bring them up to shoulder level, with your elbows bent and pointing outwards.","Press the handles upwards until your arms are fully extended overhead.","Pause for a moment at the top, then slowly lower the handles back down to shoulder level.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0219-PzQanLE.jpg","gif_url":"videos/0219-PzQanLE.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0220","name":"cable shrug","category":"back","equipment":"cable","instruction_steps":{"en":["Stand facing the cable machine with your feet shoulder-width apart.","Grasp the cable handles with an overhand grip and let your arms hang down in front of you.","Keeping your arms straight, shrug your shoulders up towards your ears.","Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"traps","image":"images/0220-Eg98Ft9.jpg","gif_url":"videos/0220-Eg98Ft9.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0222","name":"cable side bend","category":"waist","equipment":"cable","instruction_steps":{"en":["Stand with your feet shoulder-width apart and grasp the cable handle with one hand.","Keep your back straight and your core engaged.","Slowly bend sideways at the waist, lowering the cable handle towards your knee.","Pause for a moment, then return to the starting position.","Repeat on the other side.","Alternate sides for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/0222-wPypxFY.jpg","gif_url":"videos/0222-wPypxFY.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0221","name":"cable side bend crunch (bosu ball)","category":"waist","equipment":"cable","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a cable handle in one hand.","Place the other hand on your hip.","Engage your core and slowly bend sideways towards the hand holding the cable, keeping your back straight.","Pause for a moment at the bottom of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},"muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/0221-qatbkEd.jpg","gif_url":"videos/0221-qatbkEd.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0223","name":"cable side crunch","category":"waist","equipment":"cable","instruction_steps":{"en":["Attach a cable handle to a low pulley and stand sideways to the machine.","Grasp the handle with the hand furthest from the machine and place your other hand on your hip.","Keep your feet shoulder-width apart and your knees slightly bent.","With your abs engaged, bend sideways at the waist, bringing your elbow down towards your hip.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},"muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/0223-q2ADGqV.jpg","gif_url":"videos/0223-q2ADGqV.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1717","name":"cable squat row (with rope attachment)","category":"back","equipment":"cable","instruction_steps":{"en":["Attach a rope to a cable machine at waist height.","Stand facing the cable machine with your feet shoulder-width apart.","Bend your knees and lower your body into a squat position, keeping your back straight and chest up.","Grasp the rope with an overhand grip, with your hands shoulder-width apart.","Engage your core and pull the rope towards your body, squeezing your shoulder blades together.","Keep your elbows close to your body and continue pulling until your hands reach your chest.","Pause for a moment at the top of the movement, then slowly release the rope and extend your arms back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","rhomboids","rear deltoids"],"target":"lats","image":"images/1717-f7fnAIB.jpg","gif_url":"videos/1717-f7fnAIB.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1644","name":"cable squatting curl","category":"upper arms","equipment":"cable","instruction_steps":{"en":["Attach a cable handle to the lowest setting on a cable machine.","Stand facing the machine with your feet shoulder-width apart.","Hold the cable handle with an underhand grip, palms facing up, and arms fully extended.","Lower your body into a squat position, keeping your back straight and knees behind your toes.","As you squat down, curl the cable handle towards your shoulders, keeping your elbows close to your sides.","Pause for a moment at the top of the curl, squeezing your biceps.","Slowly lower the cable handle back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1644-3XFdb1Z.jpg","gif_url":"videos/1644-3XFdb1Z.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0224","name":"cable standing back wrist curl","category":"lower arms","equipment":"cable","instruction_steps":{"en":["Stand facing a cable machine with your feet shoulder-width apart.","Hold the cable handle with an overhand grip, palms facing down.","Keep your arms straight and your elbows close to your sides.","Slowly curl your wrists upward, bringing the cable handle towards your body.","Pause for a moment at the top, then slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","brachialis"],"target":"forearms","image":"images/0224-VhX2JdE.jpg","gif_url":"videos/0224-VhX2JdE.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1375","name":"cable standing calf raise","category":"lower legs","equipment":"cable","instruction_steps":{"en":["Stand facing a cable machine with your feet shoulder-width apart.","Hold onto the cable machine handles or attach a cable ankle strap to your ankles.","Raise your heels off the ground by extending your ankles as high as possible.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"calves","image":"images/1375-yl2IYyy.jpg","gif_url":"videos/1375-yl2IYyy.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0225","name":"cable standing cross-over high reverse fly","category":"shoulders","equipment":"cable","instruction_steps":{"en":["Attach a D-handle to each side of a cable machine at shoulder height.","Stand in the middle of the cable machine with your feet shoulder-width apart.","Grasp the handles with an overhand grip and extend your arms out to the sides, palms facing forward.","Keep a slight bend in your elbows and maintain a straight back throughout the exercise.","Engage your shoulder muscles and squeeze your shoulder blades together as you pull the handles towards the front of your body.","Pause for a moment at the peak of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids","rear deltoids"],"target":"delts","image":"images/0225-P5p0j8B.jpg","gif_url":"videos/0225-P5p0j8B.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0226","name":"cable standing crunch","category":"waist","equipment":"cable","instruction_steps":{"en":["Attach a cable handle to a high pulley and stand facing away from the machine.","Hold the handle with both hands and place it behind your head, keeping your elbows bent.","Stand with your feet shoulder-width apart and your knees slightly bent.","Keeping your abs engaged, exhale and crunch your torso down towards your knees, bringing your elbows towards your thighs.","Pause for a moment at the bottom of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/0226-jpgqxiS.jpg","gif_url":"videos/0226-jpgqxiS.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0874","name":"cable standing crunch (with rope attachment)","category":"waist","equipment":"cable","instruction_steps":{"en":["Attach a rope to a cable machine at chest height.","Stand facing away from the machine with your feet shoulder-width apart.","Hold the rope with both hands and bring it behind your head, keeping your elbows bent.","Engage your abs and slowly crunch your torso forward, bringing your elbows towards your knees.","Pause for a moment at the top of the crunch, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/0874-XU3ePuv.jpg","gif_url":"videos/0874-XU3ePuv.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0227","name":"cable standing fly","category":"chest","equipment":"cable","instruction_steps":{"en":["Attach the handles to the cables at chest height.","Stand with your feet shoulder-width apart, facing away from the cable machine.","Grasp the handles with an overhand grip, palms facing forward.","Step forward slightly to create tension in the cables.","Keep your core engaged and your back straight throughout the exercise.","With a slight bend in your elbows, slowly bring your arms forward and together in front of your chest.","Squeeze your chest muscles at the peak of the movement.","Slowly reverse the movement, returning your arms to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"deltoids","secondary_muscles":["deltoids","triceps"],"target":"pectorals","image":"images/0227-Pr9Rhf4.jpg","gif_url":"videos/0227-Pr9Rhf4.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0228","name":"cable standing hip extension","category":"upper legs","equipment":"cable","instruction_steps":{"en":["Attach a cable to a low pulley and stand facing away from the machine.","Place the cable around your ankle and stand with your feet shoulder-width apart.","Keep your core engaged and your back straight throughout the exercise.","Slowly extend your leg straight back, squeezing your glutes at the top of the movement.","Pause for a moment, then return to the starting position.","Repeat for the desired number of repetitions.","Switch sides and repeat with the other leg."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps"],"target":"glutes","image":"images/0228-Kpajagk.jpg","gif_url":"videos/0228-Kpajagk.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0229","name":"cable standing inner curl","category":"upper arms","equipment":"cable","instruction_steps":{"en":["Stand facing a cable machine with your feet shoulder-width apart.","Grasp the cable handle with an underhand grip, palms facing up.","Keep your elbows close to your sides and your upper arms stationary.","Exhale and curl the cable handle towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0229-YwnI4ja.jpg","gif_url":"videos/0229-YwnI4ja.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0230","name":"cable standing lift","category":"waist","equipment":"cable","instruction_steps":{"en":["Stand facing the cable machine with your feet shoulder-width apart.","Hold the cable handle with both hands and position it at waist height.","Engage your core and maintain a straight back throughout the exercise.","Keeping your arms straight, exhale and lift the cable handle up towards your opposite shoulder, rotating your torso.","Pause for a moment at the top, then inhale and slowly lower the cable handle back to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},"muscle_group":"obliques","secondary_muscles":["obliques","lower back"],"target":"abs","image":"images/0230-qFpAkpP.jpg","gif_url":"videos/0230-qFpAkpP.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0231","name":"cable standing one arm triceps extension","category":"upper arms","equipment":"cable","instruction_steps":{"en":["Stand with your feet shoulder-width apart, facing the cable machine.","Hold the cable handle with your right hand, palm facing down, and position your arm so that it is fully extended and parallel to the ground.","Keep your elbow stationary and close to your body.","Slowly bend your elbow, lowering the cable handle towards the back of your head.","Pause for a moment at the bottom of the movement, then extend your arm back to the starting position.","Repeat for the desired number of repetitions, then switch sides and perform the exercise with your left arm."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0231-sYCcnon.jpg","gif_url":"videos/0231-sYCcnon.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1376","name":"cable standing one leg calf raise","category":"lower legs","equipment":"cable","instruction_steps":{"en":["Stand facing a cable machine with your feet shoulder-width apart.","Hold onto the cable machine for support.","Lift one leg off the ground and balance on the other leg.","Slowly raise your heel off the ground, lifting your body up onto your toes.","Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Repeat for the desired number of repetitions, then switch legs."]},"muscle_group":"ankles","secondary_muscles":["ankles","feet"],"target":"calves","image":"images/1376-fgc9Xdl.jpg","gif_url":"videos/1376-fgc9Xdl.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0232","name":"cable standing pulldown (with rope)","category":"upper arms","equipment":"cable","instruction_steps":{"en":["Attach a rope to the cable machine at the highest setting.","Stand facing the machine with your feet shoulder-width apart.","Grasp the rope with an overhand grip, palms facing down.","Keep your back straight and core engaged throughout the exercise.","Pull the rope down towards your thighs, squeezing your biceps.","Pause for a moment at the bottom, then slowly release the rope back up.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms","shoulders"],"target":"biceps","image":"images/0232-CvPn9WV.jpg","gif_url":"videos/0232-CvPn9WV.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0233","name":"cable standing rear delt row (with rope)","category":"shoulders","equipment":"cable","instruction_steps":{"en":["Stand facing a cable machine with your feet shoulder-width apart.","Hold the cable attachment with both hands, palms facing each other, and step back to create tension in the cable.","Keep your back straight and your core engaged.","Pull the cable towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the cable back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids","biceps"],"target":"delts","image":"images/0233-ZfyAGhK.jpg","gif_url":"videos/0233-ZfyAGhK.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1727","name":"cable standing reverse grip one arm overhead tricep extension","category":"upper arms","equipment":"cable","instruction_steps":{"en":["Stand facing away from the cable machine with your feet shoulder-width apart.","Hold the cable handle with an underhand grip and extend your arm overhead, keeping your elbow close to your head.","Keep your upper arm stationary and slowly lower the cable handle behind your head by bending your elbow.","Pause for a moment at the bottom, then extend your arm back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/1727-i11JWU7.jpg","gif_url":"videos/1727-i11JWU7.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0234","name":"cable standing row (v-bar)","category":"back","equipment":"cable","instruction_steps":{"en":["Stand facing the cable machine with your feet shoulder-width apart.","Grasp the v-bar attachment with an overhand grip, palms facing down.","Keep your back straight and your core engaged.","Pull the v-bar towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"target":"upper back","image":"images/0234-4f8RXP8.jpg","gif_url":"videos/0234-4f8RXP8.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0235","name":"cable standing shoulder external rotation","category":"shoulders","equipment":"cable","instruction_steps":{"en":["Stand with your feet shoulder-width apart and your knees slightly bent.","Hold the cable handle with your arm extended in front of you, parallel to the ground.","Keep your elbow slightly bent and your shoulder blades pulled back.","Slowly rotate your arm outward, away from your body, while keeping your elbow in the same position.","Pause for a moment at the end of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"rotator cuff","secondary_muscles":["rotator cuff","trapezius"],"target":"delts","image":"images/0235-FWdVhcW.jpg","gif_url":"videos/0235-FWdVhcW.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0236","name":"cable standing twist row (v-bar)","category":"back","equipment":"cable","instruction_steps":{"en":["Attach a v-bar attachment to a cable machine at chest height.","Stand facing the cable machine with your feet shoulder-width apart.","Grasp the v-bar with an overhand grip, palms facing down.","Take a step back to create tension in the cable.","Keep your back straight and core engaged throughout the exercise.","Pull the v-bar towards your torso by retracting your shoulder blades and bending your elbows.","As you pull, twist your torso to one side, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, feeling the contraction in your upper back.","Slowly release the tension and return to the starting position, untwisting your torso.","Repeat the movement for the desired number of repetitions, alternating the twisting direction with each rep."]},"muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"target":"upper back","image":"images/0236-JOZhu2h.jpg","gif_url":"videos/0236-JOZhu2h.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1269","name":"cable standing up straight crossovers","category":"chest","equipment":"cable","instruction_steps":{"en":["Stand in the middle of a cable machine with your feet shoulder-width apart.","Hold the handles of the cables with your palms facing down and your arms extended straight out to the sides.","Keeping your arms straight, bring your hands together in front of your body, crossing them over each other.","Pause for a moment, then slowly return to the starting position, keeping your arms extended.","Repeat for the desired number of repetitions."]},"muscle_group":"deltoids","secondary_muscles":["deltoids","triceps"],"target":"pectorals","image":"images/1269-UKWTJWR.jpg","gif_url":"videos/1269-UKWTJWR.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0238","name":"cable straight arm pulldown","category":"back","equipment":"cable","instruction_steps":{"en":["Attach a straight bar to the high pulley of a cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the bar with an overhand grip, keeping your arms straight and your palms facing down.","Engage your lats and pull the bar down towards your thighs, keeping your arms straight throughout the movement.","Pause for a moment at the bottom, then slowly return the bar to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","biceps"],"target":"lats","image":"images/0238-x69MAlq.jpg","gif_url":"videos/0238-x69MAlq.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0237","name":"cable straight arm pulldown (with rope)","category":"back","equipment":"cable","instruction_steps":{"en":["Attach a rope to the cable machine at the highest setting.","Stand facing the machine with your feet shoulder-width apart.","Grasp the rope with both hands, palms facing down.","Extend your arms fully in front of you, keeping your elbows slightly bent.","Engage your lats and slowly pull the rope down towards your thighs, keeping your arms straight.","Pause for a moment at the bottom, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/0237-DT14T9T.jpg","gif_url":"videos/0237-DT14T9T.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0239","name":"cable straight back seated row","category":"back","equipment":"cable","instruction_steps":{"en":["Sit on the cable row machine with your feet flat on the footrests and your knees slightly bent.","Grasp the cable handles with an overhand grip, palms facing down.","Keep your back straight and lean slightly forward from the hips.","Pull the cable handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms","shoulders"],"target":"upper back","image":"images/0239-Tq6gbK6.jpg","gif_url":"videos/0239-Tq6gbK6.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0240","name":"cable supine reverse fly","category":"shoulders","equipment":"cable","instruction_steps":{"en":["Attach a D-handle to a low pulley cable machine and lie face down on a flat bench.","Grasp the D-handle with each hand, palms facing down, and extend your arms straight out in front of you.","Keeping your arms straight, raise them out to the sides until they are parallel to the floor.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids"],"target":"delts","image":"images/0240-PQcUlDi.jpg","gif_url":"videos/0240-PQcUlDi.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2464","name":"cable thibaudeau kayak row","category":"back","equipment":"cable","instruction_steps":{"en":["Attach a cable handle to a low pulley and sit facing the machine with your feet flat on the floor.","Grasp the handle with your right hand and extend your arm fully, keeping a slight bend in your elbow.","Lean forward from your hips, keeping your back straight and your abs engaged.","Pull the handle towards your torso by retracting your shoulder blade and bending your elbow, keeping your arm close to your body.","Squeeze your back muscles at the top of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides and perform with your left arm."]},"muscle_group":"biceps","secondary_muscles":["biceps","rhomboids","rear deltoids"],"target":"lats","image":"images/2464-ZgwWBoC.jpg","gif_url":"videos/2464-ZgwWBoC.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0241","name":"cable triceps pushdown (v-bar)","category":"upper arms","equipment":"cable","instruction_steps":{"en":["Attach a v-bar attachment to the cable machine at the highest setting.","Stand facing the cable machine with your feet shoulder-width apart.","Grasp the v-bar with an overhand grip, palms facing down, and your hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Engage your triceps and exhale as you push the v-bar down until your arms are fully extended.","Pause for a moment at the bottom of the movement, squeezing your triceps.","Inhale as you slowly return the v-bar to the starting position, maintaining control.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"triceps","image":"images/0241-gAwDzB3.jpg","gif_url":"videos/0241-gAwDzB3.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2405","name":"cable triceps pushdown (v-bar) (with arm blaster)","category":"upper arms","equipment":"cable","instruction_steps":{"en":["Attach a v-bar attachment to the cable machine at the highest setting.","Stand facing the cable machine with your feet shoulder-width apart.","Grasp the v-bar with an overhand grip, palms facing down, and your hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Engage your triceps and exhale as you push the v-bar down until your arms are fully extended.","Pause for a moment at the bottom of the movement, squeezing your triceps.","Inhale as you slowly return the v-bar to the starting position, maintaining control.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"triceps","image":"images/2405-OxJk1fg.jpg","gif_url":"videos/2405-OxJk1fg.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0242","name":"cable tuck reverse crunch","category":"waist","equipment":"cable","instruction_steps":{"en":["Attach a cable to a low pulley and lie down on a mat facing up.","Hold the cable with both hands and extend your arms straight up above your chest.","Bend your knees and lift your legs up, bringing your knees towards your chest.","At the same time, curl your pelvis up towards your chest, lifting your hips off the ground.","Pause for a moment at the top, then slowly lower your legs and hips back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0242-TXtXc84.jpg","gif_url":"videos/0242-TXtXc84.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0243","name":"cable twist","category":"waist","equipment":"cable","instruction_steps":{"en":["Stand with your feet shoulder-width apart, facing the cable machine.","Hold the cable handle with both hands in front of your chest, keeping your arms slightly bent.","Engage your core and twist your torso to the right, pulling the cable across your body.","Pause for a moment at the end of the movement, feeling the contraction in your abs and obliques.","Slowly return to the starting position, resisting the cable's pull.","Repeat the movement to the left side.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/0243-aVs3BR3.jpg","gif_url":"videos/0243-aVs3BR3.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0862","name":"cable twist (up-down)","category":"waist","equipment":"cable","instruction_steps":{"en":["Stand with your feet shoulder-width apart, facing the cable machine.","Hold the cable handle with both hands in front of your chest, keeping your arms slightly bent.","Engage your core and slowly rotate your torso to one side, keeping your hips and legs stable.","Pause for a moment at the end of the rotation, then slowly return to the starting position.","Repeat the rotation to the opposite side.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques","lower back"],"target":"abs","image":"images/0862-fhZQPlV.jpg","gif_url":"videos/0862-fhZQPlV.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0244","name":"cable twisting pull","category":"back","equipment":"cable","instruction_steps":{"en":["Attach a cable handle to a low pulley and stand facing the machine.","Grasp the handle with your left hand and step away from the machine, extending your arm fully.","Position your feet shoulder-width apart, with your knees slightly bent.","Keep your back straight and your core engaged throughout the exercise.","Pull the handle towards your body, rotating your torso to the right as you do so.","Squeeze your back muscles at the end of the movement.","Slowly return to the starting position, keeping tension on the cable.","Repeat for the desired number of repetitions, then switch sides and perform with your right hand."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","biceps"],"target":"lats","image":"images/0244-zCgxPbV.jpg","gif_url":"videos/0244-zCgxPbV.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1645","name":"cable two arm curl on incline bench","category":"upper arms","equipment":"cable","instruction_steps":{"en":["Sit on an incline bench with your back against the pad and your feet flat on the ground.","Grasp the cable handles with an underhand grip, palms facing up, and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the handles towards your shoulders while contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the handles back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1645-H9y3Dkr.jpg","gif_url":"videos/1645-H9y3Dkr.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1728","name":"cable two arm tricep kickback","category":"upper arms","equipment":"cable","instruction_steps":{"en":["Stand with your feet shoulder-width apart and knees slightly bent.","Hold the cable handle in each hand with your palms facing inwards and your arms bent at a 90-degree angle.","Keeping your upper arms stationary, extend your forearms backwards until your arms are fully extended.","Pause for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/1728-vvNjDJS.jpg","gif_url":"videos/1728-vvNjDJS.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0245","name":"cable underhand pulldown","category":"back","equipment":"cable","instruction_steps":{"en":["Adjust the cable machine so that the pulldown bar is at a height above your head.","Sit down on the seat and grab the pulldown bar with an underhand grip, hands slightly wider than shoulder-width apart.","Keep your back straight and lean back slightly.","Pull the bar down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the bar back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/0245-xBYcQHj.jpg","gif_url":"videos/0245-xBYcQHj.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1270","name":"cable upper chest crossovers","category":"chest","equipment":"cable","instruction_steps":{"en":["Attach the handles to the cables at chest height.","Stand in the center of the cable machine with one foot slightly in front of the other.","Grasp the handles with your palms facing down and your arms extended out to the sides.","Keep a slight bend in your elbows and engage your core.","Pull the cables together in front of your chest, crossing them over each other.","Squeeze your chest muscles at the peak of the movement.","Slowly release the cables back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"deltoids","secondary_muscles":["deltoids","triceps"],"target":"pectorals","image":"images/1270-j7XMAyn.jpg","gif_url":"videos/1270-j7XMAyn.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1324","name":"cable upper row","category":"back","equipment":"cable","instruction_steps":{"en":["Attach a straight bar to a cable machine at chest height.","Stand facing the machine with your feet shoulder-width apart.","Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.","Keep your back straight and your core engaged.","Pull the bar towards your upper chest, squeezing your shoulder blades together.","Pause for a moment at the top of the movement.","Slowly release the bar back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"target":"upper back","image":"images/1324-PQStVXH.jpg","gif_url":"videos/1324-PQStVXH.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0246","name":"cable upright row","category":"shoulders","equipment":"cable","instruction_steps":{"en":["Stand with your feet shoulder-width apart, knees slightly bent, and hold the cable attachment with an overhand grip.","Keep your back straight and your core engaged throughout the exercise.","Pull the cable attachment straight up towards your chin, leading with your elbows.","Pause for a moment at the top, squeezing your shoulder blades together.","Slowly lower the cable attachment back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"traps","secondary_muscles":["traps","biceps"],"target":"delts","image":"images/0246-cALKspW.jpg","gif_url":"videos/0246-cALKspW.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1325","name":"cable wide grip rear pulldown behind neck","category":"back","equipment":"cable","instruction_steps":{"en":["Adjust the cable machine so that the pulldown bar is at a height above your head.","Sit down on the seat and grab the pulldown bar with a wide overhand grip.","Keep your back straight and your chest up as you lean back slightly.","Pull the bar down towards your upper chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the bar back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","rhomboids","rear deltoids"],"target":"lats","image":"images/1325-CmEr4pM.jpg","gif_url":"videos/1325-CmEr4pM.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0247","name":"cable wrist curl","category":"lower arms","equipment":"cable","instruction_steps":{"en":["Attach a straight bar to a low pulley cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the bar with an underhand grip, palms facing up, and your hands shoulder-width apart.","Rest your forearms on a bench or pad, with your wrists hanging off the edge.","Keeping your forearms stationary, exhale and curl your wrists upward as far as possible.","Pause for a moment at the top, then inhale and slowly lower the bar back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","brachialis"],"target":"forearms","image":"images/0247-LrV4s90.jpg","gif_url":"videos/0247-LrV4s90.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1407","name":"calf push stretch with hands against wall","category":"lower legs","equipment":"body weight","instruction_steps":{"en":["Stand facing a wall with your feet hip-width apart.","Place your hands against the wall at shoulder height.","Step back with one foot, keeping your heel on the ground and your leg straight.","Bend your front knee slightly and lean forward, feeling a stretch in your calf.","Hold the stretch for 20-30 seconds.","Switch legs and repeat the stretch."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"target":"calves","image":"images/1407-PzNxakt.jpg","gif_url":"videos/1407-PzNxakt.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1377","name":"calf stretch with hands against wall","category":"lower legs","equipment":"body weight","instruction_steps":{"en":["Stand facing a wall with your feet hip-width apart.","Place your hands against the wall at shoulder height.","Step your right foot back, keeping your heel on the ground and your leg straight.","Bend your left knee and lean forward, keeping your back leg straight and your heel on the ground.","Hold the stretch for 20-30 seconds.","Switch legs and repeat the stretch."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"target":"calves","image":"images/1377-m0tCHqc.jpg","gif_url":"videos/1377-m0tCHqc.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1378","name":"calf stretch with rope","category":"lower legs","equipment":"rope","instruction_steps":{"en":["Stand facing a wall or sturdy object with your feet hip-width apart.","Hold the ends of the rope in each hand and place the middle of the rope around the ball of your right foot.","Step back with your left foot, keeping your heel on the ground and your leg straight.","Lean forward, keeping your back straight, and gently pull on the rope to stretch your calf.","Hold the stretch for 20-30 seconds, then release.","Repeat on the other leg."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"target":"calves","image":"images/1378-1LVFcEn.jpg","gif_url":"videos/1378-1LVFcEn.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0248","name":"cambered bar lying row","category":"back","equipment":"barbell","instruction_steps":{"en":["Set up a barbell on the floor and lie face down on a bench with your chest just off the edge.","Reach down and grab the barbell with an overhand grip, slightly wider than shoulder-width apart.","With your legs straight and feet on the ground, lift the barbell off the floor by extending your arms.","Pull the barbell towards your chest, squeezing your shoulder blades together.","Lower the barbell back down to the starting position and repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0248-R5swFnc.jpg","gif_url":"videos/0248-R5swFnc.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2963","name":"captains chair straight leg raise","category":"waist","equipment":"body weight","instruction_steps":{"en":["Sit on the captain's chair with your back against the backrest and your forearms resting on the arm pads.","Keep your upper body stable and your back straight.","Engage your abs and lift your legs up in front of you, keeping them straight.","Continue lifting until your legs are parallel to the ground or as high as you can comfortably go.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/2963-weoDEpH.jpg","gif_url":"videos/2963-weoDEpH.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1548","name":"chair leg extended stretch","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Sit on the edge of a chair with your back straight and feet flat on the ground.","Extend one leg straight out in front of you, keeping your heel on the ground.","Lean forward slightly, feeling a stretch in your quadriceps.","Hold this position for 20-30 seconds.","Switch legs and repeat the stretch."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","calves"],"target":"quads","image":"images/1548-xGgAGPm.jpg","gif_url":"videos/1548-xGgAGPm.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1271","name":"chest and front of shoulder stretch","category":"chest","equipment":"body weight","instruction_steps":{"en":["Stand tall with your feet shoulder-width apart.","Extend your arms straight out in front of you at shoulder height.","Cross your arms in front of your body, with your right arm on top of your left arm.","Interlace your fingers and press your palms together.","Gently squeeze your shoulder blades together and push your hands forward, feeling a stretch in your chest and front of your shoulders.","Hold the stretch for 20-30 seconds, then release.","Repeat for the desired number of repetitions."]},"muscle_group":"deltoids","secondary_muscles":["deltoids"],"target":"pectorals","image":"images/1271-Uto7l43.jpg","gif_url":"videos/1271-Uto7l43.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0251","name":"chest dip","category":"chest","equipment":"body weight","instruction_steps":{"en":["Position yourself on parallel bars with your arms fully extended and your body straight.","Lower your body by bending your elbows until your shoulders are below your elbows.","Push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/0251-9WTm7dq.jpg","gif_url":"videos/0251-9WTm7dq.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1430","name":"chest dip (on dip-pull-up cage)","category":"chest","equipment":"body weight","instruction_steps":{"en":["Adjust the dip bars to a height that allows you to comfortably grip them.","Stand between the bars and place your hands on each bar, slightly wider than shoulder-width apart.","Jump up and straighten your arms, supporting your body weight on the bars.","Bend your knees and cross your ankles behind you.","Lower your body by bending your elbows, keeping your chest up and your shoulders down.","Continue lowering until your shoulders are below your elbows or until you feel a stretch in your chest.","Push through your palms and extend your elbows to raise your body back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1430-XgWyAiA.jpg","gif_url":"videos/1430-XgWyAiA.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2462","name":"chest dip on straight bar","category":"chest","equipment":"body weight","instruction_steps":{"en":["Grab the parallel bars with your palms facing down and your arms fully extended.","Bend your knees and cross your ankles.","Lower your body by bending your arms until your shoulders are below your elbows.","Push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/2462-LQFOrMn.jpg","gif_url":"videos/2462-LQFOrMn.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1272","name":"chest stretch with exercise ball","category":"chest","equipment":"stability ball","instruction_steps":{"en":["Sit on the stability ball with your feet flat on the ground and your back straight.","Hold the exercise ball with both hands and extend your arms straight out in front of you.","Slowly bring the exercise ball towards your chest, feeling a stretch in your chest muscles.","Hold the stretch for a few seconds, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/1272-ykA5tU7.jpg","gif_url":"videos/1272-ykA5tU7.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3216","name":"chest tap push-up (male)","category":"chest","equipment":"body weight","instruction_steps":{"en":["Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line.","Lower your body towards the ground by bending your elbows, keeping them close to your sides.","As you lower yourself, tap your chest with your right hand.","Push yourself back up to the starting position.","Repeat the movement, this time tapping your chest with your left hand.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/3216-7E06s6d.jpg","gif_url":"videos/3216-7E06s6d.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1326","name":"chin-up","category":"back","equipment":"body weight","instruction_steps":{"en":["Hang from a pull-up bar with your palms facing towards you and your hands shoulder-width apart.","Engage your core and pull your body up towards the bar, leading with your chest.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/1326-T2mxWqc.jpg","gif_url":"videos/1326-T2mxWqc.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0253","name":"chin-ups (narrow parallel grip)","category":"back","equipment":"body weight","instruction_steps":{"en":["Hang from a pull-up bar with a narrow parallel grip, palms facing towards you.","Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0253-G70mEAJ.jpg","gif_url":"videos/0253-G70mEAJ.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0257","name":"circles knee stretch","category":"lower legs","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart and your hands on your hips.","Bend your knees slightly and lift your heels off the ground, balancing on the balls of your feet.","Keeping your knees bent, rotate your knees in a circular motion, first clockwise and then counterclockwise.","Perform the movement for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps"],"target":"calves","image":"images/0257-X7jbxra.jpg","gif_url":"videos/0257-X7jbxra.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1273","name":"clap push up","category":"chest","equipment":"body weight","instruction_steps":{"en":["Start in a high plank position with your hands slightly wider than shoulder-width apart.","Lower your body towards the ground by bending your elbows, keeping your core engaged.","Push through your palms explosively to propel your body off the ground.","While in mid-air, clap your hands together before landing back in the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1273-wigSg76.jpg","gif_url":"videos/1273-wigSg76.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0258","name":"clock push-up","category":"chest","equipment":"body weight","instruction_steps":{"en":["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.","Lower your body towards the ground by bending your elbows, keeping them close to your sides.","As you lower, rotate your body to the left, extending your left arm straight out to the side.","Push back up to the starting position, while rotating your body to the center.","Repeat the push-up, this time rotating your body to the right and extending your right arm out to the side.","Continue alternating sides with each repetition."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders","core"],"target":"pectorals","image":"images/0258-CMAxnsG.jpg","gif_url":"videos/0258-CMAxnsG.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1327","name":"close grip chin-up","category":"back","equipment":"body weight","instruction_steps":{"en":["Grab the pull-up bar with your palms facing towards you and your hands shoulder-width apart.","Hang from the bar with your arms fully extended and your feet off the ground.","Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/1327-VnfUNW7.jpg","gif_url":"videos/1327-VnfUNW7.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0259","name":"close-grip push-up","category":"upper arms","equipment":"body weight","instruction_steps":{"en":["Start in a high plank position with your hands placed close together, directly under your shoulders.","Engage your core and lower your body towards the ground, keeping your elbows close to your sides.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0259-x6KpKpq.jpg","gif_url":"videos/0259-x6KpKpq.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2398","name":"close-grip push-up (on knees)","category":"upper arms","equipment":"body weight","instruction_steps":{"en":["Start by getting on your hands and knees, with your hands shoulder-width apart and your knees hip-width apart.","Lower your upper body towards the ground by bending your elbows, keeping them close to your sides.","Pause for a moment when your chest is just above the ground.","Push through your palms to straighten your arms and return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/2398-v3vLFW0.jpg","gif_url":"videos/2398-v3vLFW0.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0260","name":"cocoons","category":"waist","equipment":"body weight","instruction_steps":{"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors","lower back"],"target":"abs","image":"images/0260-SLKj2pX.jpg","gif_url":"videos/0260-SLKj2pX.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1468","name":"crab twist toe touch","category":"waist","equipment":"body weight","instruction_steps":{"en":["Start by sitting on the ground with your knees bent and feet flat on the floor.","Place your hands behind you, fingers pointing towards your feet, and lift your hips off the ground.","Extend one leg straight out in front of you while simultaneously reaching your opposite hand towards your toes.","Return to the starting position and repeat on the other side.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques","hip flexors"],"target":"abs","image":"images/1468-xgsGFVM.jpg","gif_url":"videos/1468-xgsGFVM.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0262","name":"cross body crunch","category":"waist","equipment":"body weight","instruction_steps":{"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, lift your upper body off the ground and twist to bring your right elbow towards your left knee.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat on the other side, bringing your left elbow towards your right knee.","Repeat for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/0262-rbu5UUb.jpg","gif_url":"videos/0262-rbu5UUb.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0267","name":"crunch (hands overhead)","category":"waist","equipment":"body weight","instruction_steps":{"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Extend your arms straight above your head.","Engaging your abs, lift your upper body off the ground, curling forward towards your knees.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0267-kjJ3VoQ.jpg","gif_url":"videos/0267-kjJ3VoQ.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0271","name":"crunch (on stability ball)","category":"waist","equipment":"stability ball","instruction_steps":{"en":["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Lie back on the ball until your lower back is supported and your upper body is parallel to the floor.","Place your hands behind your head or across your chest.","Engage your abs and lift your upper body towards your knees, curling your torso forward.","Pause for a moment at the top of the movement, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0271-MCUhf1F.jpg","gif_url":"videos/0271-MCUhf1F.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0272","name":"crunch (on stability ball, arms straight)","category":"waist","equipment":"stability ball","instruction_steps":{"en":["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Lie back on the ball until your lower back is supported and your upper body is parallel to the floor.","Place your hands behind your head or cross them over your chest.","Engage your abs and lift your upper body off the ball, curling your shoulders towards your hips.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0272-Sn8wxAI.jpg","gif_url":"videos/0272-Sn8wxAI.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0274","name":"crunch floor","category":"waist","equipment":"body weight","instruction_steps":{"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engage your abs and lift your shoulders off the ground, curling forward towards your knees.","Pause for a moment at the top, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0274-TFqbd8t.jpg","gif_url":"videos/0274-TFqbd8t.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3016","name":"curl-up","category":"waist","equipment":"body weight","instruction_steps":{"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/3016-g2oKspu.jpg","gif_url":"videos/3016-g2oKspu.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3769","name":"curtsey squat","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart.","Take a step diagonally behind and across your body with your right foot, crossing it behind your left leg.","Bend both knees as if you were curtsying, lowering your body towards the ground.","Keep your torso upright and your weight on your front foot.","Push through your front foot to return to the starting position.","Repeat on the other side, stepping diagonally behind and across your body with your left foot."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/3769-gUjqdei.jpg","gif_url":"videos/3769-gUjqdei.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2331","name":"cycle cross trainer","category":"cardio","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height and position yourself on the cycle cross trainer.","Place your feet on the pedals and grip the handlebars.","Start pedaling in a smooth and controlled motion.","Maintain a steady pace and increase the resistance if desired.","Continue pedaling for the desired duration of your cardio workout."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","glutes"],"target":"cardiovascular system","image":"images/2331-XSCHmiI.jpg","gif_url":"videos/2331-XSCHmiI.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0276","name":"dead bug","category":"waist","equipment":"body weight","instruction_steps":{"en":["Lie flat on your back with your arms extended towards the ceiling.","Bend your knees and lift your legs off the ground, creating a 90-degree angle at your hips and knees.","Engage your core and lower back to press your lower back into the ground.","Slowly lower your right arm and left leg towards the ground, keeping them straight and hovering just above the floor.","Pause for a moment, then return to the starting position.","Repeat the movement with your left arm and right leg.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors","lower back"],"target":"abs","image":"images/0276-iny3m5y.jpg","gif_url":"videos/0276-iny3m5y.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0277","name":"decline crunch","category":"waist","equipment":"body weight","instruction_steps":{"en":["Lie on a decline bench with your feet secured and your knees bent at a 90-degree angle.","Place your hands behind your head or across your chest.","Engage your abs and lift your upper body towards your knees, curling your torso.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0277-9Ap7miY.jpg","gif_url":"videos/0277-9Ap7miY.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0279","name":"decline push-up","category":"chest","equipment":"body weight","instruction_steps":{"en":["Place your hands on the ground slightly wider than shoulder-width apart, with your feet elevated on a stable surface.","Keep your body in a straight line from head to toe, engaging your core muscles.","Lower your chest towards the ground by bending your elbows, keeping them close to your body.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/0279-i5cEhka.jpg","gif_url":"videos/0279-i5cEhka.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0282","name":"decline sit-up","category":"waist","equipment":"body weight","instruction_steps":{"en":["Lie on a decline bench with your feet secured and your knees bent.","Place your hands behind your head or across your chest.","Engage your abs and lift your upper body off the bench, curling forward towards your knees.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors","lower back"],"target":"abs","image":"images/0282-QLL2gdc.jpg","gif_url":"videos/0282-QLL2gdc.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1274","name":"deep push up","category":"chest","equipment":"dumbbell","instruction_steps":{"en":["Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line.","Lower your chest towards the ground by bending your elbows, keeping them close to your body.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1274-vptOQ4N.jpg","gif_url":"videos/1274-vptOQ4N.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0283","name":"diamond push-up","category":"upper arms","equipment":"body weight","instruction_steps":{"en":["Start in a high plank position with your hands close together, forming a diamond shape with your thumbs and index fingers.","Keep your body in a straight line from head to toe, engaging your core and glutes.","Lower your chest towards the diamond shape formed by your hands, keeping your elbows close to your body.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0283-soIB2rj.jpg","gif_url":"videos/0283-soIB2rj.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0284","name":"donkey calf raise","category":"lower legs","equipment":"body weight","instruction_steps":{"en":["Stand with your toes on an elevated surface, such as a step or block.","Place your hands on a stable support, such as a wall or railing, for balance.","Raise your heels as high as possible, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"calves","image":"images/0284-u5ESqzH.jpg","gif_url":"videos/0284-u5ESqzH.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1275","name":"drop push up","category":"chest","equipment":"body weight","instruction_steps":{"en":["Start in a high plank position with your hands slightly wider than shoulder-width apart.","Lower your chest towards the ground, keeping your elbows close to your body.","Once your chest is just above the ground, quickly drop your knees to the ground.","Push yourself back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1275-Q497lAE.jpg","gif_url":"videos/1275-Q497lAE.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0285","name":"dumbbell alternate biceps curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Stand up straight with a dumbbell in each hand, palms facing forward and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions, alternating arms."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0285-BU15nH4.jpg","gif_url":"videos/0285-BU15nH4.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2403","name":"dumbbell alternate biceps curl (with arm blaster)","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Stand up straight with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.","Place the arm blaster on your upper arms, ensuring a secure fit.","Keeping your upper arms stationary, exhale and curl one dumbbell up towards your shoulder while contracting your biceps.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat the movement with the opposite arm.","Continue alternating arms for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/2403-CfKsRbG.jpg","gif_url":"videos/2403-CfKsRbG.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1646","name":"dumbbell alternate hammer preacher curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on a preacher bench with a dumbbell in each hand, palms facing your torso and arms fully extended.","Keep your upper arms stationary and exhale as you curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the recommended amount of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1646-fy7Tgy4.jpg","gif_url":"videos/1646-fy7Tgy4.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1647","name":"dumbbell alternate preacher curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on a preacher bench with a dumbbell in each hand, palms facing up.","Rest your upper arms on the pad of the preacher bench, allowing your arms to fully extend.","Keeping your upper arms stationary, exhale and curl the dumbbell in your right hand as you contract your biceps.","Continue to curl the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Pause for a moment, then inhale and slowly lower the dumbbell back to the starting position.","Repeat the movement with your left arm.","Continue alternating arms for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1647-NlfIbzq.jpg","gif_url":"videos/1647-NlfIbzq.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1648","name":"dumbbell alternate seated hammer curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench with a dumbbell in each hand, palms facing your torso and arms extended down.","Keep your back straight and your elbows close to your torso.","Exhale and curl the dumbbell in your right hand towards your shoulder, keeping your upper arm stationary.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Pause for a brief moment, then inhale and slowly lower the dumbbell back to the starting position.","Repeat the movement with your left arm.","Continue alternating arms for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1648-6em2Dxj.jpg","gif_url":"videos/1648-6em2Dxj.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0286","name":"dumbbell alternate side press","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height.","Press one dumbbell overhead while keeping the other dumbbell at shoulder height.","Lower the pressed dumbbell back to shoulder height while pressing the other dumbbell overhead.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","core"],"target":"delts","image":"images/0286-izMnLqz.jpg","gif_url":"videos/0286-izMnLqz.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1649","name":"dumbbell alternating bicep curl with leg raised on exercise ball","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.","Place an exercise ball behind you and position one foot on top of it, keeping your balance.","With your arms fully extended and elbows close to your sides, curl one dumbbell towards your shoulder while keeping your upper arm stationary.","Lower the dumbbell back down to the starting position and repeat with the other arm.","Continue alternating arms for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms","shoulders"],"target":"biceps","image":"images/1649-Zwiw7XR.jpg","gif_url":"videos/1649-Zwiw7XR.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1650","name":"dumbbell alternating seated bicep curl on exercise ball","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in each hand with your palms facing forward and your arms fully extended.","Keeping your upper arms stationary, exhale and curl one dumbbell while rotating your forearm until your palm is facing your shoulder.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat the curl with the other arm.","Continue alternating curls for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1650-J74XlNf.jpg","gif_url":"videos/1650-J74XlNf.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2137","name":"dumbbell arnold press","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench with back support and hold a dumbbell in each hand at shoulder level, palms facing your body and elbows bent.","Press the dumbbells upward until your arms are fully extended and your palms are facing forward.","Rotate your wrists as you lift, so that your palms are facing forward at the top of the movement.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","upper chest"],"target":"delts","image":"images/2137-Xy4jlWA.jpg","gif_url":"videos/2137-Xy4jlWA.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0287","name":"dumbbell arnold press v. 2","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench with back support and hold a dumbbell in each hand at shoulder level, palms facing your body and elbows bent.","Press the dumbbells upward until your arms are fully extended and your palms are facing forward.","Rotate your wrists as you lift, so that your palms end up facing forward at the top of the movement.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","upper chest"],"target":"delts","image":"images/0287-eOrFCnx.jpg","gif_url":"videos/0287-eOrFCnx.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0288","name":"dumbbell around pullover","category":"chest","equipment":"dumbbell","instruction_steps":{"en":["Lie flat on a bench with your head at one end and your feet firmly on the ground.","Hold a dumbbell with both hands and extend your arms straight above your chest.","Keeping your arms straight, slowly lower the dumbbell behind your head in an arc motion.","Pause for a moment at the bottom, then raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","latissimus dorsi"],"target":"pectorals","image":"images/0288-vi8EhoE.jpg","gif_url":"videos/0288-vi8EhoE.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0289","name":"dumbbell bench press","category":"chest","equipment":"dumbbell","instruction_steps":{"en":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Hold a dumbbell in each hand, with your palms facing forward and your arms extended above your chest.","Lower the dumbbells slowly to the sides of your chest, keeping your elbows at a 90-degree angle.","Pause for a moment, then push the dumbbells back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/0289-SpYC0Kp.jpg","gif_url":"videos/0289-SpYC0Kp.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0290","name":"dumbbell bench seated press","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench with a dumbbell in each hand, resting on your thighs.","Lean back and position the dumbbells to the sides of your chest, palms facing forward.","Press the dumbbells upward until your arms are fully extended.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","chest"],"target":"delts","image":"images/0290-3d7wHyd.jpg","gif_url":"videos/0290-3d7wHyd.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0291","name":"dumbbell bench squat","category":"upper legs","equipment":"dumbbell","instruction_steps":{"en":["Place a dumbbell on the ground in front of a bench.","Stand facing away from the bench with your feet shoulder-width apart.","Bend at the knees and hips to lower yourself down towards the bench, keeping your chest up and back straight.","Once your glutes touch the bench, push through your heels to stand back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0291-mnzcrIB.jpg","gif_url":"videos/0291-mnzcrIB.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0293","name":"dumbbell bent over row","category":"back","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in each hand with your palms facing your body.","Bend forward at the hips, keeping your back straight and your core engaged.","Let your arms hang straight down towards the floor, with your elbows slightly bent.","Pull the dumbbells up towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0293-BJ0Hz5L.jpg","gif_url":"videos/0293-BJ0Hz5L.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1651","name":"dumbbell bicep curl lunge with bowling motion","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing forward.","Take a step forward with your right foot, bending your right knee and lowering your body into a lunge position.","As you lunge forward, curl the dumbbells up towards your shoulders, keeping your elbows close to your body.","At the bottom of the lunge, rotate your torso to the right, as if you were bowling a ball.","Reverse the motion, stepping back with your right foot and returning to the starting position while lowering the dumbbells back down.","Repeat the lunge and curl motion, this time rotating your torso to the left.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms","shoulders"],"target":"biceps","image":"images/1651-1VpF8db.jpg","gif_url":"videos/1651-1VpF8db.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1652","name":"dumbbell bicep curl on exercise ball with leg raised","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in each hand with your palms facing forward and your arms fully extended.","Slowly curl the dumbbells towards your shoulders, keeping your elbows close to your sides.","Pause for a moment at the top of the movement, then slowly lower the dumbbells back to the starting position.","While performing the bicep curl, raise one leg off the ground and hold it in the air for the duration of the exercise.","Repeat for the desired number of repetitions, then switch legs and repeat."]},"muscle_group":"forearms","secondary_muscles":["forearms","shoulders"],"target":"biceps","image":"images/1652-2NImIAG.jpg","gif_url":"videos/1652-2NImIAG.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1653","name":"dumbbell bicep curl with stork stance","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.","Extend one leg behind you, balancing on the toes of that foot.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1653-uSkDMYl.jpg","gif_url":"videos/1653-uSkDMYl.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0294","name":"dumbbell biceps curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Stand up straight with a dumbbell in each hand, palms facing forward and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0294-NbVPDMW.jpg","gif_url":"videos/0294-NbVPDMW.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2401","name":"dumbbell biceps curl (with arm blaster)","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Stand up straight with a dumbbell in each hand, palms facing forward.","Keep your elbows close to your torso and your upper arms stationary.","Exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/2401-nlJsbkW.jpg","gif_url":"videos/2401-nlJsbkW.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1654","name":"dumbbell biceps curl reverse","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Stand up straight with a dumbbell in each hand, palms facing down and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1654-nFc4FyV.jpg","gif_url":"videos/1654-nFc4FyV.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1655","name":"dumbbell biceps curl squat","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing forward.","Keeping your back straight and your elbows close to your sides, exhale and curl the dumbbells up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1655-niXESDw.jpg","gif_url":"videos/1655-niXESDw.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1656","name":"dumbbell biceps curl v sit on bosu ball","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bosu ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold a dumbbell in each hand with your palms facing forward and your arms fully extended down by your sides.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms","shoulders"],"target":"biceps","image":"images/1656-H1XAdpk.jpg","gif_url":"videos/1656-H1XAdpk.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1201","name":"dumbbell burpee","category":"cardio","equipment":"dumbbell","instruction_steps":{"en":["Start in a standing position with your feet shoulder-width apart and a dumbbell in each hand.","Lower your body into a squat position, placing the dumbbells on the ground in front of you.","Kick your feet back into a push-up position, keeping your body in a straight line.","Perform a push-up, bending your elbows and lowering your chest towards the ground.","Jump your feet back towards your hands, landing in a squat position.","Stand up explosively, lifting the dumbbells off the ground and bringing them to your shoulders.","Press the dumbbells overhead, fully extending your arms.","Lower the dumbbells back to your shoulders and repeat the entire sequence for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves","shoulders","triceps","core"],"target":"cardiovascular system","image":"images/1201-0JtKWum.jpg","gif_url":"videos/1201-0JtKWum.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0295","name":"dumbbell clean","category":"upper legs","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Bend your knees and lower your hips into a squat position, keeping your back straight and chest up.","Explosively extend your hips and knees, driving through your heels to jump off the ground.","As you jump, shrug your shoulders and pull the dumbbells up towards your shoulders, keeping them close to your body.","Catch the dumbbells at shoulder height, with your elbows pointing forward and your palms facing up.","Lower the dumbbells back down to the starting position by reversing the movement.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps","calves"],"target":"glutes","image":"images/0295-7Hg55JG.jpg","gif_url":"videos/0295-7Hg55JG.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1731","name":"dumbbell close grip press","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on a flat bench with a dumbbell in each hand, resting on your thighs.","Using your thighs to help raise the dumbbells, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.","Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.","As you breathe in, slowly lower the dumbbells to your side until they are about level with your chest.","As you exhale, use your triceps to lift the dumbbells back to the starting position. Make sure to use only your triceps and do not use your forearms or biceps to help lift the dumbbells.","After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/1731-7jGOBF3.jpg","gif_url":"videos/1731-7jGOBF3.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0296","name":"dumbbell close-grip press","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on a flat bench with a dumbbell in each hand, resting on your thighs.","Using your thighs to help raise the dumbbells, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.","Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.","As you breathe in, slowly lower the dumbbells to your side until they are about level with your chest.","As you exhale, use your triceps to lift the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0296-RxayqAZ.jpg","gif_url":"videos/0296-RxayqAZ.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0297","name":"dumbbell concentration curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench with your legs spread apart and a dumbbell in one hand, resting your elbow on the inside of your thigh.","Fully extend your arm and hold the dumbbell with an underhand grip.","Keeping your upper arm stationary, exhale and curl the weight up towards your shoulder while contracting your biceps.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0297-gvsWLQw.jpg","gif_url":"videos/0297-gvsWLQw.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3635","name":"dumbbell contralateral forward lunge","category":"upper legs","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Take a step forward with your right foot, keeping your back straight and core engaged.","Lower your body by bending both knees until your right thigh is parallel to the ground.","Push through your right heel to return to the starting position.","Repeat with your left leg.","Alternate legs for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/3635-ecl28tP.jpg","gif_url":"videos/3635-ecl28tP.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0298","name":"dumbbell cross body hammer curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Stand up straight with a dumbbell in each hand, palms facing your body.","Keep your elbows close to your torso and your upper arms stationary.","Exhale and curl the weights while contracting your biceps, bringing the dumbbells across your body towards your opposite shoulder.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0298-Qyk5J3p.jpg","gif_url":"videos/0298-Qyk5J3p.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1657","name":"dumbbell cross body hammer curl v. 2","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Stand up straight with a dumbbell in each hand, palms facing your body.","Keep your elbows close to your torso and your upper arms stationary.","Exhale and curl the weights while contracting your biceps, bringing the dumbbells as close to your opposite shoulder as possible.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1657-HDYiZcY.jpg","gif_url":"videos/1657-HDYiZcY.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0299","name":"dumbbell cuban press","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height with your palms facing down.","Keeping your core engaged and your elbows slightly bent, press the dumbbells up and overhead until your arms are fully extended.","Rotate your wrists so that your palms are facing forward.","Slowly lower the dumbbells back to the starting position, rotating your wrists back to the starting position as you do so.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0299-QfAKy1G.jpg","gif_url":"videos/0299-QfAKy1G.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2136","name":"dumbbell cuban press v. 2","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height with your palms facing down.","Keeping your core engaged and your back straight, press the dumbbells straight up overhead until your arms are fully extended.","Rotate your wrists so that your palms are facing forward.","Lower the dumbbells back down to shoulder height, rotating your wrists back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/2136-BqgCRif.jpg","gif_url":"videos/2136-BqgCRif.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0300","name":"dumbbell deadlift","category":"upper legs","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, toes pointing forward.","Hold a dumbbell in each hand, palms facing your body, arms extended downwards.","Bend at your hips and knees, lowering the dumbbells towards the ground while keeping your back straight.","Push through your heels and extend your hips and knees, lifting the dumbbells back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"target":"glutes","image":"images/0300-nUwVh7b.jpg","gif_url":"videos/0300-nUwVh7b.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0301","name":"dumbbell decline bench press","category":"chest","equipment":"dumbbell","instruction_steps":{"en":["Lie down on a decline bench with your feet secured and your head lower than your hips.","Hold a dumbbell in each hand and extend your arms straight up above your chest, palms facing forward.","Lower the dumbbells slowly to the sides of your chest, keeping your elbows at a 90-degree angle.","Push the dumbbells back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/0301-DwhEmmE.jpg","gif_url":"videos/0301-DwhEmmE.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0302","name":"dumbbell decline fly","category":"chest","equipment":"dumbbell","instruction_steps":{"en":["Lie on a decline bench with your feet secured and your head lower than your hips.","Hold a dumbbell in each hand with your palms facing each other and your arms extended above your chest.","Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.","Pause for a moment, then squeeze your chest muscles to bring the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"pectorals","image":"images/0302-xXm4nYq.jpg","gif_url":"videos/0302-xXm4nYq.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0303","name":"dumbbell decline hammer press","category":"chest","equipment":"dumbbell","instruction_steps":{"en":["Lie on a decline bench with your feet secured and your head lower than your hips.","Hold a dumbbell in each hand with your palms facing each other and your arms extended above your chest.","Lower the dumbbells to the sides of your chest, keeping your elbows slightly bent.","Press the dumbbells back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/0303-1qrWgZ2.jpg","gif_url":"videos/0303-1qrWgZ2.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1276","name":"dumbbell decline one arm fly","category":"chest","equipment":"dumbbell","instruction_steps":{"en":["Lie down on a decline bench with a dumbbell in one hand, resting it on your thigh.","Using your thigh to help raise the dumbbell, lift it up to shoulder width with your palm facing your torso.","Rotate your wrist so that the palm of your hand is facing forward.","As you breathe in, lower the dumbbell slowly to the side until you feel a stretch in your chest.","Exhale and use your chest muscles to bring the dumbbell back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"pectorals","image":"images/1276-NL6YBwN.jpg","gif_url":"videos/1276-NL6YBwN.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1617","name":"dumbbell decline one arm hammer press","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Lie on a decline bench with a dumbbell in one hand, resting on your chest.","Extend your arm straight up, keeping your elbow slightly bent.","Lower the dumbbell down towards your shoulder, keeping your elbow close to your body.","Press the dumbbell back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/1617-SHUMp5H.jpg","gif_url":"videos/1617-SHUMp5H.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0305","name":"dumbbell decline shrug","category":"back","equipment":"dumbbell","instruction_steps":{"en":["Set up a decline bench at a 45-degree angle.","Lie face down on the bench with your chest and stomach resting against it.","Hold a dumbbell in each hand with your arms fully extended towards the floor.","Keeping your arms straight, raise your shoulders towards your ears as high as possible.","Hold the contraction for a moment, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","rhomboids"],"target":"traps","image":"images/0305-cwsAI4G.jpg","gif_url":"videos/0305-cwsAI4G.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0304","name":"dumbbell decline shrug v. 2","category":"back","equipment":"dumbbell","instruction_steps":{"en":["Set up a decline bench at a 45-degree angle.","Lie face down on the bench with your chest and stomach resting on it.","Hold a dumbbell in each hand with your palms facing each other and your arms fully extended.","Keeping your arms straight, raise your shoulders as high as possible while squeezing your shoulder blades together.","Hold the contraction for a brief pause, then lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","rhomboids"],"target":"traps","image":"images/0304-bRlbdjK.jpg","gif_url":"videos/0304-bRlbdjK.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0306","name":"dumbbell decline triceps extension","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Lie on a decline bench with your head lower than your feet and hold a dumbbell in each hand, palms facing each other.","Extend your arms fully, keeping your elbows close to your head.","Lower the dumbbells slowly behind your head, bending your elbows.","Pause for a moment, then raise the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0306-OTgkHwR.jpg","gif_url":"videos/0306-OTgkHwR.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0307","name":"dumbbell decline twist fly","category":"chest","equipment":"dumbbell","instruction_steps":{"en":["Lie down on a decline bench with your head lower than your hips.","Hold a dumbbell in each hand with your palms facing each other and your arms extended straight up over your chest.","Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.","As you lower the dumbbells, twist your wrists so that your palms face forward at the bottom of the movement.","Reverse the motion and bring the dumbbells back up to the starting position, squeezing your chest muscles at the top.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/0307-reFHapa.jpg","gif_url":"videos/0307-reFHapa.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1437","name":"dumbbell finger curls","category":"lower arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench or chair with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand with an underhand grip, resting your forearm on your thigh, palm facing up.","Allow the dumbbell to roll down to your fingertips, then curl it back up by flexing your fingers.","Repeat for the desired number of repetitions, then switch to the other hand."]},"muscle_group":"wrist flexors","secondary_muscles":["wrist flexors","wrist extensors"],"target":"forearms","image":"images/1437-mtXengz.jpg","gif_url":"videos/1437-mtXengz.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0308","name":"dumbbell fly","category":"chest","equipment":"dumbbell","instruction_steps":{"en":["Lie flat on a bench with a dumbbell in each hand, palms facing each other.","Extend your arms straight up over your chest, with a slight bend in your elbows.","Keeping a slight bend in your elbows, lower your arms out to the sides in a wide arc until you feel a stretch in your chest.","Pause for a moment, then reverse the movement and bring the dumbbells back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"pectorals","image":"images/0308-yz9nUhF.jpg","gif_url":"videos/0308-yz9nUhF.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1277","name":"dumbbell fly on exercise ball","category":"chest","equipment":"dumbbell","instruction_steps":{"en":["Sit on an exercise ball and hold a dumbbell in each hand.","Walk your feet forward and roll your body down until your head, neck, and upper back are supported by the ball.","Extend your arms straight up above your chest, palms facing each other.","Bend your elbows slightly and lower your arms out to the sides in a wide arc until you feel a stretch in your chest.","Pause for a moment, then reverse the movement and squeeze your chest muscles as you bring the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/1277-Lt3iWnf.jpg","gif_url":"videos/1277-Lt3iWnf.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1732","name":"dumbbell forward lunge triceps extension","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Take a step forward with your right foot, lowering your body into a lunge position.","Keep your back straight and your chest up.","Extend your arms straight overhead, keeping your elbows close to your ears.","Lower the dumbbells behind your head by bending your elbows.","Pause for a moment, then straighten your arms to return to the starting position.","Repeat the movement for the desired number of repetitions, then switch legs and repeat."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","core"],"target":"triceps","image":"images/1732-XalXcvM.jpg","gif_url":"videos/1732-XalXcvM.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0310","name":"dumbbell front raise","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your thighs.","Keeping your arms straight, exhale and lift the dumbbells in front of you until they are at shoulder level.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","trapezius"],"target":"delts","image":"images/0310-3eGE2JC.jpg","gif_url":"videos/0310-3eGE2JC.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0309","name":"dumbbell front raise v. 2","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your thighs.","Keep your back straight and engage your core.","Slowly lift the dumbbells in front of you, with your arms straight, until they are at shoulder level.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"trapezius","secondary_muscles":["trapezius","biceps"],"target":"delts","image":"images/0309-Rr7S3yg.jpg","gif_url":"videos/0309-Rr7S3yg.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0311","name":"dumbbell full can lateral raise","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body.","Keep your back straight and engage your core.","Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"traps","secondary_muscles":["traps","rotator cuff"],"target":"delts","image":"images/0311-AQ0mC4Y.jpg","gif_url":"videos/0311-AQ0mC4Y.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1760","name":"dumbbell goblet squat","category":"upper legs","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a dumbbell vertically against your chest with both hands.","Keeping your chest up and core engaged, lower your body down into a squat position by pushing your hips back and bending your knees.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves"],"target":"quads","image":"images/1760-yn8yg1r.jpg","gif_url":"videos/1760-yn8yg1r.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0313","name":"dumbbell hammer curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Stand up straight with a dumbbell in each hand, palms facing your torso.","Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.","This will be your starting position.","Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Then, inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the recommended amount of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0313-slDvUAU.jpg","gif_url":"videos/0313-slDvUAU.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1659","name":"dumbbell hammer curl on exercise ball","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in each hand with your palms facing your body and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the dumbbells while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1659-fY68AyX.jpg","gif_url":"videos/1659-fY68AyX.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0312","name":"dumbbell hammer curl v. 2","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Stand up straight with a dumbbell in each hand, palms facing your torso.","Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.","This will be your starting position.","Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Then, inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the recommended amount of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0312-2NpxjC1.jpg","gif_url":"videos/0312-2NpxjC1.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2402","name":"dumbbell hammer curls (with arm blaster)","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Stand up straight with a dumbbell in each hand, palms facing your torso.","Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.","This will be your starting position.","Now, while holding your upper arm stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Then, inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the recommended amount of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/2402-GNhAeJ0.jpg","gif_url":"videos/2402-GNhAeJ0.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1664","name":"dumbbell high curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Stand up straight with a dumbbell in each hand, palms facing forward.","Keep your upper arms stationary and curl the dumbbells as high as possible while contracting your biceps.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1664-qAmNMJY.jpg","gif_url":"videos/1664-qAmNMJY.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3545","name":"dumbbell incline alternate press","category":"chest","equipment":"dumbbell","instruction_steps":{"en":["Sit on an incline bench with a dumbbell in each hand, resting on your thighs.","Lean back on the bench and use your thighs to help raise the dumbbells to shoulder height, palms facing forward.","Once at shoulder height, rotate your wrists so that the palms of your hands are facing forward.","Push the dumbbells up with your chest and shoulders, extending your arms fully.","Lower the dumbbells back down to the starting position, keeping your elbows slightly bent.","Repeat for the desired number of repetitions, alternating arms."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/3545-TVdivgY.jpg","gif_url":"videos/3545-TVdivgY.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0314","name":"dumbbell incline bench press","category":"chest","equipment":"dumbbell","instruction_steps":{"en":["Set up an incline bench at a 45-degree angle.","Sit on the bench with your feet flat on the ground and your back pressed firmly against the bench.","Hold a dumbbell in each hand, palms facing forward, and lift them to shoulder height.","Slowly lower the dumbbells to the sides of your chest, keeping your elbows at a 90-degree angle.","Push the dumbbells back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/0314-ns0SIbU.jpg","gif_url":"videos/0314-ns0SIbU.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0315","name":"dumbbell incline biceps curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on an incline bench with a dumbbell in each hand, palms facing forward, and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0315-F3xgbjF.jpg","gif_url":"videos/0315-F3xgbjF.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0316","name":"dumbbell incline breeding","category":"chest","equipment":"dumbbell","instruction_steps":{"en":["Set up an incline bench at a 45-degree angle.","Sit on the bench with your back against the pad and feet flat on the ground.","Hold a dumbbell in each hand with an overhand grip, palms facing forward.","Start with your arms fully extended, perpendicular to the ground.","Lower the dumbbells slowly to the sides of your chest, keeping your elbows at a 90-degree angle.","Pause for a moment at the bottom, then push the dumbbells back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/0316-B3Rxp6L.jpg","gif_url":"videos/0316-B3Rxp6L.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0318","name":"dumbbell incline curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing forward.","Rest your upper arms on the incline bench and let your elbows hang down, fully extending your arms.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0318-ae9UoXQ.jpg","gif_url":"videos/0318-ae9UoXQ.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0317","name":"dumbbell incline curl v. 2","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on an incline bench with a dumbbell in each hand, palms facing forward and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0317-RaflbWD.jpg","gif_url":"videos/0317-RaflbWD.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0319","name":"dumbbell incline fly","category":"chest","equipment":"dumbbell","instruction_steps":{"en":["Set an incline bench to a 45-degree angle.","Sit on the bench with a dumbbell in each hand, palms facing each other.","Lie back on the bench and press the dumbbells up to the starting position, directly above your chest.","Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.","Pause for a moment, then squeeze your chest muscles to bring the dumbbells back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"pectorals","image":"images/0319-ESOd5Pl.jpg","gif_url":"videos/0319-ESOd5Pl.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1278","name":"dumbbell incline fly on exercise ball","category":"chest","equipment":"dumbbell","instruction_steps":{"en":["Set up an incline bench at a 45-degree angle.","Sit on an exercise ball and roll forward until your upper back is resting on the incline bench.","Hold a dumbbell in each hand with your palms facing each other and your arms extended above your chest.","Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.","Pause for a moment, then squeeze your chest muscles to bring the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"pectorals","image":"images/1278-HYe1ZqR.jpg","gif_url":"videos/1278-HYe1ZqR.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0320","name":"dumbbell incline hammer curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on an incline bench with a dumbbell in each hand, palms facing your torso and arms fully extended.","Keep your back against the bench and your feet flat on the floor.","While keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0320-ByX0WxV.jpg","gif_url":"videos/0320-ByX0WxV.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0321","name":"dumbbell incline hammer press","category":"chest","equipment":"dumbbell","instruction_steps":{"en":["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, resting on your thighs.","Lie back on the bench and position the dumbbells at shoulder level with your palms facing each other.","Press the dumbbells up and away from your body until your arms are fully extended.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/0321-PG1kcIb.jpg","gif_url":"videos/0321-PG1kcIb.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1618","name":"dumbbell incline hammer press on exercise ball","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on an exercise ball with a dumbbell in each hand, palms facing each other.","Walk your feet forward and roll your body down the ball until your head, neck, and upper back are supported on the ball.","Hold the dumbbells at shoulder level, elbows bent and pointing out to the sides.","Press the dumbbells up and slightly inward, keeping your palms facing each other.","Extend your arms fully, squeezing your triceps at the top of the movement.","Slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/1618-wkgnGfb.jpg","gif_url":"videos/1618-wkgnGfb.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0322","name":"dumbbell incline inner biceps curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on an incline bench with a dumbbell in each hand, palms facing each other.","Rest your upper arms on the bench, allowing your elbows to hang down and your palms to face forward.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0322-LCtQPn8.jpg","gif_url":"videos/0322-LCtQPn8.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1279","name":"dumbbell incline one arm fly","category":"chest","equipment":"dumbbell","instruction_steps":{"en":["Adjust the incline bench to a 30-45 degree angle.","Sit on the bench with a dumbbell in one hand, resting it on your thigh.","Lie back on the bench, keeping your feet flat on the ground.","Hold the dumbbell with your arm extended straight up over your chest.","Lower the dumbbell out to the side in a wide arc, keeping a slight bend in your elbow.","Pause when your arm is parallel to the ground, then reverse the motion to bring the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"deltoids","secondary_muscles":["deltoids","triceps"],"target":"pectorals","image":"images/1279-Gw2HFvW.jpg","gif_url":"videos/1279-Gw2HFvW.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1280","name":"dumbbell incline one arm fly on exercise ball","category":"chest","equipment":"dumbbell","instruction_steps":{"en":["Sit on an exercise ball with a dumbbell in one hand.","Walk your feet forward and roll your body down until your head, neck, and upper back are supported on the ball.","Hold the dumbbell with your arm extended straight up over your chest, palm facing inwards.","Slowly lower the dumbbell out to the side, keeping a slight bend in your elbow.","Pause for a moment when your arm is parallel to the ground.","Engage your chest muscles to bring the dumbbell back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"pectorals","image":"images/1280-LLNh6q5.jpg","gif_url":"videos/1280-LLNh6q5.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1619","name":"dumbbell incline one arm hammer press","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on an incline bench with a dumbbell in one hand, resting on your thigh.","Lean back on the bench and use your thigh to help raise the dumbbell to shoulder height.","Rotate your wrist so that your palm is facing inward, towards your body.","Press the dumbbell up and away from your body, extending your arm fully.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","chest"],"target":"triceps","image":"images/1619-LL1UiTX.jpg","gif_url":"videos/1619-LL1UiTX.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1620","name":"dumbbell incline one arm hammer press on exercise ball","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on an exercise ball with a dumbbell in one hand.","Walk your feet forward and roll your body down until your head, neck, and upper back are supported on the ball.","Hold the dumbbell with your palm facing inward and your elbow bent at a 90-degree angle.","Press the dumbbell up towards the ceiling, straightening your arm.","Lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","chest"],"target":"triceps","image":"images/1620-jDnrkar.jpg","gif_url":"videos/1620-jDnrkar.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0323","name":"dumbbell incline one arm lateral raise","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Sit on an incline bench with a dumbbell in one hand, resting it on your thigh.","Lean forward and position your upper arm against the inside of your thigh.","Raise the dumbbell to the side, keeping your arm slightly bent and your palm facing down.","Continue lifting until your arm is parallel to the floor.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]},"muscle_group":"trapezius","secondary_muscles":["trapezius","triceps"],"target":"delts","image":"images/0323-aTNKZiC.jpg","gif_url":"videos/0323-aTNKZiC.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1281","name":"dumbbell incline one arm press","category":"chest","equipment":"dumbbell","instruction_steps":{"en":["Sit on an incline bench with a dumbbell in one hand, resting on your thigh.","Lie back on the bench and position the dumbbell at shoulder level, palm facing forward.","Press the dumbbell upward and slightly inward, extending your arm fully.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/1281-rDAiRf9.jpg","gif_url":"videos/1281-rDAiRf9.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1282","name":"dumbbell incline one arm press on exercise ball","category":"chest","equipment":"dumbbell","instruction_steps":{"en":["Sit on an exercise ball with a dumbbell in one hand, feet flat on the ground.","Slowly walk your feet forward, rolling the ball until your head, neck, and upper back are supported on the ball.","Hold the dumbbell at shoulder height with your palm facing forward.","Press the dumbbell upward until your arm is fully extended.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/1282-Bg5JKSH.jpg","gif_url":"videos/1282-Bg5JKSH.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0324","name":"dumbbell incline palm-in press","category":"chest","equipment":"dumbbell","instruction_steps":{"en":["Set up an incline bench at a 45-degree angle.","Sit on the bench with a dumbbell in each hand, palms facing each other.","Plant your feet firmly on the ground and keep your back straight against the bench.","Start with the dumbbells at shoulder level, elbows bent and palms facing each other.","Press the dumbbells up and away from your body, extending your arms fully.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/0324-OVLmUuL.jpg","gif_url":"videos/0324-OVLmUuL.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1283","name":"dumbbell incline press on exercise ball","category":"chest","equipment":"dumbbell","instruction_steps":{"en":["Sit on an exercise ball with a dumbbell in each hand, palms facing forward.","Slowly walk your feet forward, rolling your body down the ball until your head, neck, and upper back are supported on the ball.","Hold the dumbbells at shoulder level, elbows bent and pointing out to the sides.","Press the dumbbells upward, extending your arms fully.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/1283-bfiHMpI.jpg","gif_url":"videos/1283-bfiHMpI.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0325","name":"dumbbell incline raise","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Sit on an incline bench with a dumbbell in each hand, resting on your thighs.","Lean back on the bench and raise the dumbbells to shoulder height, palms facing forward.","Keeping your back against the bench, exhale and raise the dumbbells above your head, fully extending your arms.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back to shoulder height.","Repeat for the desired number of repetitions."]},"muscle_group":"trapezius","secondary_muscles":["trapezius","triceps"],"target":"delts","image":"images/0325-nxW6BkN.jpg","gif_url":"videos/0325-nxW6BkN.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0326","name":"dumbbell incline rear lateral raise","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Set up an incline bench at a 45-degree angle.","Sit on the bench with your chest against the backrest and hold a dumbbell in each hand.","Extend your arms straight down with your palms facing each other.","Keeping a slight bend in your elbows, raise your arms out to the sides until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"traps","secondary_muscles":["traps","rhomboids"],"target":"delts","image":"images/0326-vYk8lqw.jpg","gif_url":"videos/0326-vYk8lqw.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0327","name":"dumbbell incline row","category":"back","equipment":"dumbbell","instruction_steps":{"en":["Set up an incline bench at a 45-degree angle.","Grab a dumbbell in each hand and sit on the bench with your chest against the incline.","Extend your arms fully, allowing the dumbbells to hang straight down from your shoulders.","Pull the dumbbells up towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"target":"upper back","image":"images/0327-7vG5o25.jpg","gif_url":"videos/0327-7vG5o25.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0328","name":"dumbbell incline shoulder raise","category":"chest","equipment":"dumbbell","instruction_steps":{"en":["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing down.","Rest the dumbbells on your thighs and lean back onto the bench.","Use your thighs to help raise the dumbbells to shoulder height, then rotate your wrists so that your palms are facing forward.","Exhale and slowly raise the dumbbells above your head, keeping a slight bend in your elbows.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back to shoulder height.","Repeat for the desired number of repetitions."]},"muscle_group":"deltoids","secondary_muscles":["deltoids","trapezius"],"target":"serratus anterior","image":"images/0328-6e2DcYX.jpg","gif_url":"videos/0328-6e2DcYX.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0329","name":"dumbbell incline shrug","category":"back","equipment":"dumbbell","instruction_steps":{"en":["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand.","Place your feet flat on the ground and let your arms hang straight down with your palms facing your body.","Keeping your arms straight, shrug your shoulders up towards your ears as high as possible.","Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"traps","image":"images/0329-JymLInS.jpg","gif_url":"videos/0329-JymLInS.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3542","name":"dumbbell incline t-raise","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing inwards.","Lean forward and let your arms hang straight down, perpendicular to the floor.","Keeping your arms straight, raise them out to the sides until they are parallel to the floor, forming a 'T' shape with your body.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"traps","secondary_muscles":["traps","rhomboids"],"target":"delts","image":"images/3542-jgbvVJ0.jpg","gif_url":"videos/3542-jgbvVJ0.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0330","name":"dumbbell incline triceps extension","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on an incline bench with a dumbbell in each hand, palms facing inwards.","Extend your arms fully overhead, keeping your elbows close to your head.","Lower the dumbbells behind your head by bending your elbows, keeping your upper arms stationary.","Pause for a moment, then raise the dumbbells back to the starting position by extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0330-OVIKwsd.jpg","gif_url":"videos/0330-OVIKwsd.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0331","name":"dumbbell incline twisted flyes","category":"chest","equipment":"dumbbell","instruction_steps":{"en":["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing each other.","Lie back on the bench and press the dumbbells up to the starting position, directly above your chest, with your arms extended.","Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.","As you lower the dumbbells, rotate your wrists so that your palms face forward at the bottom of the movement.","Reverse the motion and bring the dumbbells back up to the starting position, squeezing your chest muscles together at the top.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/0331-1PLE8e9.jpg","gif_url":"videos/0331-1PLE8e9.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1733","name":"dumbbell incline two arm extension","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on an incline bench with a dumbbell in each hand, resting on your thighs.","Slowly lie back on the bench, keeping the dumbbells close to your chest.","Once you are fully lying down, extend your arms straight up towards the ceiling, keeping your elbows slightly bent.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/1733-U7D9Fx3.jpg","gif_url":"videos/1733-U7D9Fx3.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3541","name":"dumbbell incline y-raise","category":"back","equipment":"dumbbell","instruction_steps":{"en":["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing inwards.","Lean forward slightly and let your arms hang straight down, keeping a slight bend in your elbows.","Raise your arms out to the sides and up in a Y shape until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","rear deltoids"],"target":"upper back","image":"images/3541-PbzNu7c.jpg","gif_url":"videos/3541-PbzNu7c.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0332","name":"dumbbell iron cross","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.","Raise your arms out to the sides until they are parallel to the ground, forming a T shape with your body.","Pause for a moment, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","chest"],"target":"delts","image":"images/0332-cALkHHX.jpg","gif_url":"videos/0332-cALkHHX.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0333","name":"dumbbell kickback","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Bring your upper arms close to your sides, with your elbows bent at a 90-degree angle.","Extend your arms straight back, squeezing your triceps at the top of the movement.","Pause for a moment, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0333-W6PxUkg.jpg","gif_url":"videos/0333-W6PxUkg.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1734","name":"dumbbell kickbacks on exercise ball","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in each hand with your palms facing inwards and your arms bent at a 90-degree angle.","Extend your arms straight back, squeezing your triceps at the top of the movement.","Pause for a moment, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","back"],"target":"triceps","image":"images/1734-cAvTaSg.jpg","gif_url":"videos/1734-cAvTaSg.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1660","name":"dumbbell kneeling bicep curl exercise ball","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Kneel on the floor with an exercise ball in front of you.","Place your elbows on top of the exercise ball, holding a dumbbell in each hand with your palms facing up.","Keeping your upper arms stationary, exhale and curl the dumbbells while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1660-2JCuFTU.jpg","gif_url":"videos/1660-2JCuFTU.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0334","name":"dumbbell lateral raise","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.","Keep your back straight and engage your core.","Raise your arms out to the sides until they are parallel to the floor, keeping a slight bend in your elbows.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"traps","secondary_muscles":["traps"],"target":"delts","image":"images/0334-DsgkuIt.jpg","gif_url":"videos/0334-DsgkuIt.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0335","name":"dumbbell lateral to front raise","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body.","Keep your back straight and engage your core.","Raise your arms out to the sides until they are parallel to the ground, keeping a slight bend in your elbows.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Next, raise your arms in front of you until they are parallel to the ground, again keeping a slight bend in your elbows.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"trapezius","secondary_muscles":["trapezius","biceps"],"target":"delts","image":"images/0335-xMjBKwn.jpg","gif_url":"videos/0335-xMjBKwn.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0336","name":"dumbbell lunge","category":"upper legs","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Take a step forward with your right foot, lowering your body into a lunge position.","Keep your back straight and your chest up as you lower your body.","Push through your right heel to return to the starting position.","Repeat with your left leg.","Alternate legs for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0336-RRWFUcw.jpg","gif_url":"videos/0336-RRWFUcw.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1658","name":"dumbbell lunge with bicep curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing forward.","Take a step forward with your right foot, lowering your body into a lunge position. Your right knee should be bent at a 90-degree angle and your left knee should be hovering just above the ground.","As you lunge forward, simultaneously curl the dumbbells towards your shoulders, keeping your elbows close to your body.","Pause for a moment at the bottom of the lunge, then push through your right heel to return to the starting position, lowering the dumbbells back down to your sides.","Repeat the lunge and bicep curl on the opposite side, stepping forward with your left foot.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings"],"target":"biceps","image":"images/1658-Mz6lLcW.jpg","gif_url":"videos/1658-Mz6lLcW.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0337","name":"dumbbell lying extension (across face)","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold a dumbbell with both hands and extend your arms straight up above your chest, palms facing each other.","Keeping your upper arms stationary, slowly lower the dumbbell in an arc behind your head until your forearms are parallel to the ground.","Pause for a moment, then contract your triceps to bring the dumbbell back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0337-L2V5Nan.jpg","gif_url":"videos/0337-L2V5Nan.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1729","name":"dumbbell lying alternate extension","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Lie flat on a bench with a dumbbell in each hand, palms facing each other.","Extend your arms straight up over your chest, keeping a slight bend in your elbows.","Lower one dumbbell down towards your head, bending at the elbow, while keeping the other arm extended.","Pause for a moment at the bottom, then raise the dumbbell back up to the starting position.","Repeat with the other arm, alternating sides for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/1729-NfP83rA.jpg","gif_url":"videos/1729-NfP83rA.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0338","name":"dumbbell lying elbow press","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Lie flat on a bench with a dumbbell in each hand, palms facing each other and arms extended straight up over your chest.","Lower the dumbbells towards your shoulders by bending your elbows, keeping your upper arms stationary.","Pause for a moment at the bottom, then press the dumbbells back up to the starting position by extending your elbows.","Repeat for the desired number of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0338-eOCOwIR.jpg","gif_url":"videos/0338-eOCOwIR.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0863","name":"dumbbell lying external shoulder rotation","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Lie on your side on a flat bench with your upper arm against your side and your elbow bent 90 degrees.","Hold a dumbbell in your hand with your palm facing down.","Keeping your upper arm against your side, slowly rotate your forearm upward as far as possible.","Pause for a moment at the top, then slowly lower your forearm back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},"muscle_group":"rotator cuff","secondary_muscles":["rotator cuff","triceps"],"target":"delts","image":"images/0863-bmBf7LN.jpg","gif_url":"videos/0863-bmBf7LN.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0339","name":"dumbbell lying femoral","category":"upper legs","equipment":"dumbbell","instruction_steps":{"en":["Lie flat on your back with your legs extended and a dumbbell resting on your lower abdomen.","Bend your knees and bring the dumbbell towards your glutes, keeping your feet flat on the ground.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes"],"target":"hamstrings","image":"images/0339-FkBIE6a.jpg","gif_url":"videos/0339-FkBIE6a.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0340","name":"dumbbell lying hammer press","category":"chest","equipment":"dumbbell","instruction_steps":{"en":["Lie flat on a bench with a dumbbell in each hand, palms facing each other and arms extended straight up.","Lower the dumbbells to the sides of your chest, keeping your elbows at a 90-degree angle.","Press the dumbbells back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/0340-7gdLIXa.jpg","gif_url":"videos/0340-7gdLIXa.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2470","name":"dumbbell lying on floor rear delt raise","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Lie face down on the floor with a dumbbell in each hand, palms facing each other.","Extend your arms straight out in front of you, keeping a slight bend in your elbows.","Engaging your shoulder muscles, lift your arms up and out to the sides, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids"],"target":"delts","image":"images/2470-Ion0XWz.jpg","gif_url":"videos/2470-Ion0XWz.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0341","name":"dumbbell lying one arm deltoid rear","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Lie face down on a flat bench with a dumbbell in one hand, palm facing inwards.","Extend your arm straight down towards the floor, keeping it close to your body.","Raise your arm up and back, squeezing your shoulder blade towards your spine.","Pause for a moment at the top, then slowly lower your arm back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids"],"target":"delts","image":"images/0341-gSw59a4.jpg","gif_url":"videos/0341-gSw59a4.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0343","name":"dumbbell lying one arm press","category":"chest","equipment":"dumbbell","instruction_steps":{"en":["Lie flat on a bench with a dumbbell in one hand and your feet flat on the ground.","Hold the dumbbell at shoulder level with your palm facing forward.","Press the dumbbell upward until your arm is fully extended.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/0343-zGSIWQi.jpg","gif_url":"videos/0343-zGSIWQi.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0342","name":"dumbbell lying one arm press v. 2","category":"chest","equipment":"dumbbell","instruction_steps":{"en":["Lie flat on a bench with your back supported and feet flat on the ground.","Hold a dumbbell in one hand with your palm facing towards your feet.","Extend your arm straight up towards the ceiling, keeping your elbow slightly bent.","Slowly lower the dumbbell down towards your chest, keeping your elbow close to your body.","Pause for a moment at the bottom, then push the dumbbell back up to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/0342-K3dIO25.jpg","gif_url":"videos/0342-K3dIO25.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0344","name":"dumbbell lying one arm pronated triceps extension","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Lie flat on a bench with your back and head supported, and your feet flat on the ground.","Hold a dumbbell in one hand with your palm facing down, and extend your arm straight up above your shoulder.","Keeping your upper arm stationary, slowly lower the dumbbell behind your head by bending your elbow.","Pause for a moment at the bottom, then extend your arm back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0344-wyaqzOS.jpg","gif_url":"videos/0344-wyaqzOS.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0345","name":"dumbbell lying one arm rear lateral raise","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Lie face down on a flat bench with a dumbbell in one hand, hanging towards the floor.","Keep your arm straight and lift the dumbbell out to the side, away from your body.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]},"muscle_group":"traps","secondary_muscles":["traps","rhomboids"],"target":"delts","image":"images/0345-KwFGiEP.jpg","gif_url":"videos/0345-KwFGiEP.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0346","name":"dumbbell lying one arm supinated triceps extension","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Lie flat on a bench with your back and head supported, and your feet flat on the ground.","Hold a dumbbell in one hand with an underhand grip, and extend your arm straight up above your shoulder.","Keeping your upper arm stationary, slowly lower the dumbbell behind your head by bending your elbow.","Pause for a moment at the bottom, then extend your arm back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"triceps","image":"images/0346-zZlORz6.jpg","gif_url":"videos/0346-zZlORz6.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0347","name":"dumbbell lying pronation","category":"lower arms","equipment":"dumbbell","instruction_steps":{"en":["Lie flat on a bench with your chest facing down and your arms extended straight down, holding a dumbbell in each hand.","Rotate your palms so they are facing up.","Keeping your upper arms stationary, exhale and curl the dumbbells as you rotate your palms to face down.","Inhale and slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"target":"forearms","image":"images/0347-mym4hJo.jpg","gif_url":"videos/0347-mym4hJo.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2705","name":"dumbbell lying pronation on floor","category":"lower arms","equipment":"dumbbell","instruction_steps":{"en":["Lie flat on the floor with your face down and your arms extended straight out in front of you, holding a dumbbell in each hand.","Rotate your palms so they are facing down towards the floor.","Keeping your arms straight, lift the dumbbells off the floor by contracting your forearms.","Continue lifting until your forearms are fully contracted and the dumbbells are at shoulder level.","Hold for a moment, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","triceps"],"target":"forearms","image":"images/2705-7RWNjiB.jpg","gif_url":"videos/2705-7RWNjiB.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1284","name":"dumbbell lying pullover on exercise ball","category":"chest","equipment":"dumbbell","instruction_steps":{"en":["Sit on an exercise ball and roll forward until your upper back is resting on the ball.","Hold a dumbbell with both hands and extend your arms straight up over your chest.","Slowly lower the dumbbell behind your head while keeping your arms straight.","Pause for a moment, then raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders","back"],"target":"pectorals","image":"images/1284-iK59oEA.jpg","gif_url":"videos/1284-iK59oEA.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1328","name":"dumbbell lying rear delt row","category":"back","equipment":"dumbbell","instruction_steps":{"en":["Lie face down on a flat bench with a dumbbell in each hand, palms facing inwards.","Extend your arms straight down towards the floor, keeping a slight bend in your elbows.","Engaging your back muscles, lift the dumbbells up towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","biceps"],"target":"upper back","image":"images/1328-XUUD0Fs.jpg","gif_url":"videos/1328-XUUD0Fs.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0348","name":"dumbbell lying rear lateral raise","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Lie face down on a flat bench with a dumbbell in each hand, palms facing each other.","Extend your arms straight down towards the floor, keeping a slight bend in your elbows.","Engaging your shoulder muscles, lift your arms out to the sides until they are parallel to the floor.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"traps","secondary_muscles":["traps","rhomboids"],"target":"delts","image":"images/0348-53Ttlck.jpg","gif_url":"videos/0348-53Ttlck.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1735","name":"dumbbell lying single extension","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Lie flat on a bench with a dumbbell in one hand and your arm fully extended above your chest.","Lower the dumbbell in a controlled manner towards your forehead, keeping your upper arm stationary.","Pause briefly at the bottom of the movement, then extend your arm back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/1735-6MfS53i.jpg","gif_url":"videos/1735-6MfS53i.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0349","name":"dumbbell lying supination","category":"lower arms","equipment":"dumbbell","instruction_steps":{"en":["Lie flat on a bench with your feet flat on the ground.","Hold a dumbbell in each hand with your palms facing up and your arms fully extended.","Keeping your upper arms stationary, curl the dumbbells towards your shoulders by contracting your forearms.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"target":"forearms","image":"images/0349-M2Pm3zj.jpg","gif_url":"videos/0349-M2Pm3zj.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2706","name":"dumbbell lying supination on floor","category":"lower arms","equipment":"dumbbell","instruction_steps":{"en":["Lie flat on your back on the floor with your legs extended and your arms by your sides, holding a dumbbell in each hand.","Rotate your palms to face up, keeping your elbows close to your sides.","Slowly curl the dumbbells towards your shoulders, squeezing your forearms.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"target":"forearms","image":"images/2706-rEhi2o5.jpg","gif_url":"videos/2706-rEhi2o5.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1661","name":"dumbbell lying supine biceps curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Lie flat on a bench with your back and head supported, and your feet flat on the ground.","Hold a dumbbell in each hand with your palms facing up and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1661-XVzF3iZ.jpg","gif_url":"videos/1661-XVzF3iZ.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0350","name":"dumbbell lying supine curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Lie flat on a bench with a dumbbell in each hand, palms facing up and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0350-KUaZst7.jpg","gif_url":"videos/0350-KUaZst7.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0351","name":"dumbbell lying triceps extension","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Lie flat on a bench with a dumbbell in each hand, palms facing each other.","Extend your arms straight up over your chest, keeping your elbows close to your body.","Lower the dumbbells down towards your forehead, bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0351-mpKZGWz.jpg","gif_url":"videos/0351-mpKZGWz.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1662","name":"dumbbell lying wide curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Lie flat on a bench with a dumbbell in each hand, palms facing up and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1662-qm9veZw.jpg","gif_url":"videos/1662-qm9veZw.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0352","name":"dumbbell neutral grip bench press","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Hold a dumbbell in each hand with a neutral grip (palms facing each other) and your arms extended straight up over your chest.","Slowly lower the dumbbells down towards your chest, keeping your elbows close to your body.","Pause for a moment at the bottom, then push the dumbbells back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0352-pP8wP2P.jpg","gif_url":"videos/0352-pP8wP2P.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1285","name":"dumbbell one arm bench fly","category":"chest","equipment":"dumbbell","instruction_steps":{"en":["Sit on a flat bench with a dumbbell in one hand, resting it on top of your thigh.","Lie back on the bench, keeping the dumbbell pressed against your thigh.","Using your free hand, help lift the dumbbell up to the starting position.","Hold the dumbbell directly above your shoulder with your arm extended and palm facing inward.","Lower the dumbbell out to the side in a wide arc, keeping a slight bend in your elbow.","Pause when your arm is parallel to the ground, then reverse the movement and bring the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms and repeat."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"pectorals","image":"images/1285-o5Jsk92.jpg","gif_url":"videos/1285-o5Jsk92.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0292","name":"dumbbell one arm bent-over row","category":"back","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a dumbbell in one hand with your palm facing your body.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and your core engaged.","Let the dumbbell hang straight down towards the floor, with your arm fully extended.","Pull the dumbbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0292-C0MA9bC.jpg","gif_url":"videos/0292-C0MA9bC.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1286","name":"dumbbell one arm chest fly on exercise ball","category":"chest","equipment":"dumbbell","instruction_steps":{"en":["Sit on an exercise ball with a dumbbell in one hand and your feet flat on the ground.","Walk your feet forward, rolling the ball until your upper back is supported on the ball and your head, neck, and shoulders are off the ball.","Extend your arm with the dumbbell straight up above your chest, palm facing inward.","Slowly lower the dumbbell out to the side, keeping a slight bend in your elbow.","Pause for a moment when your arm is parallel to the ground.","Engage your chest muscles to bring the dumbbell back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/1286-Bpkf41o.jpg","gif_url":"videos/1286-Bpkf41o.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0353","name":"dumbbell one arm concentration curl (on stability ball)","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold a dumbbell in one hand with your palm facing up and your arm extended down towards the floor.","Rest your elbow on the inside of your thigh, just above the knee.","Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder while contracting your biceps.","Pause for a moment at the top of the movement, then inhale and slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch arms and repeat."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0353-k5IpyHg.jpg","gif_url":"videos/0353-k5IpyHg.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1287","name":"dumbbell one arm decline chest press","category":"chest","equipment":"dumbbell","instruction_steps":{"en":["Lie on a decline bench with a dumbbell in one hand, resting on your chest.","Place your feet flat on the ground and keep your back pressed against the bench.","Extend your arm and push the dumbbell up towards the ceiling, fully extending your elbow.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1287-REGM1dE.jpg","gif_url":"videos/1287-REGM1dE.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1288","name":"dumbbell one arm fly on exercise ball","category":"chest","equipment":"dumbbell","instruction_steps":{"en":["Sit on an exercise ball with a dumbbell in one hand and your feet flat on the ground.","Walk your feet forward and roll your body down until your upper back is resting on the exercise ball.","Extend your arm with the dumbbell straight up above your chest, palm facing inwards.","Slowly lower the dumbbell out to the side, keeping a slight bend in your elbow.","Pause for a moment, then squeeze your chest muscles to bring the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/1288-Am02iPd.jpg","gif_url":"videos/1288-Am02iPd.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1736","name":"dumbbell one arm french press on exercise ball","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand with your palm facing up and your elbow bent at a 90-degree angle.","Extend your arm straight up towards the ceiling, keeping your elbow stationary.","Slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/1736-ziFKQXP.jpg","gif_url":"videos/1736-ziFKQXP.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1663","name":"dumbbell one arm hammer preacher curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on a preacher bench with a dumbbell in one hand and your upper arm resting on the pad.","Hold the dumbbell with a neutral grip (palms facing your body).","Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1663-4dF3maG.jpg","gif_url":"videos/1663-4dF3maG.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1621","name":"dumbbell one arm hammer press on exercise ball","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand with your palm facing inwards and your elbow bent at a 90-degree angle.","Place your other hand on your hip for stability.","Press the dumbbell upwards, extending your arm fully.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","chest"],"target":"triceps","image":"images/1621-VYmYxK5.jpg","gif_url":"videos/1621-VYmYxK5.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1289","name":"dumbbell one arm incline chest press","category":"chest","equipment":"dumbbell","instruction_steps":{"en":["Adjust the incline bench to a 45-degree angle.","Sit on the bench with your back against the pad and feet flat on the ground.","Hold a dumbbell in one hand with an overhand grip, resting it on your shoulder.","Push the dumbbell up and away from your body, extending your arm fully.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/1289-PDaMuyV.jpg","gif_url":"videos/1289-PDaMuyV.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0354","name":"dumbbell one arm kickback","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold a dumbbell in your right hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Bring your right elbow up to your side, keeping it bent at a 90-degree angle.","Extend your right arm straight back, squeezing your triceps at the top of the movement.","Slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0354-bQy2Eni.jpg","gif_url":"videos/0354-bQy2Eni.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0355","name":"dumbbell one arm lateral raise","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a dumbbell in one hand with your palm facing your body.","Keep your back straight and your core engaged throughout the exercise.","Raise the dumbbell to the side, keeping your arm straight and your palm facing down.","Continue lifting until your arm is parallel to the ground.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]},"muscle_group":"trapezius","secondary_muscles":["trapezius","triceps"],"target":"delts","image":"images/0355-n5cWCsI.jpg","gif_url":"videos/0355-n5cWCsI.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0356","name":"dumbbell one arm lateral raise with support","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold a dumbbell in one hand, with your palm facing your body.","Place your other hand on a stable surface, such as a bench or wall, for support.","Keep your back straight and engage your core.","Raise the dumbbell out to the side, keeping your arm straight and your palm facing down.","Continue lifting until your arm is parallel to the ground.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},"muscle_group":"trapezius","secondary_muscles":["trapezius","rotator cuff"],"target":"delts","image":"images/0356-Yg7MJAT.jpg","gif_url":"videos/0356-Yg7MJAT.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1290","name":"dumbbell one arm press on exercise ball","category":"chest","equipment":"dumbbell","instruction_steps":{"en":["Sit on an exercise ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold a dumbbell in one hand and position it at shoulder height, with your elbow bent and palm facing forward.","Slowly press the dumbbell upward until your arm is fully extended, while keeping your core engaged and maintaining balance on the exercise ball.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps","core"],"target":"pectorals","image":"images/1290-QZFv5ui.jpg","gif_url":"videos/1290-QZFv5ui.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1665","name":"dumbbell one arm prone curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Lie face down on a flat bench with a dumbbell in one hand, palm facing down.","Extend your arm fully, letting it hang straight down towards the floor.","Keeping your upper arm stationary, curl the dumbbell up towards your shoulder by contracting your biceps.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1665-JWjujiY.jpg","gif_url":"videos/1665-JWjujiY.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1666","name":"dumbbell one arm prone hammer curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Lie face down on a flat bench with a dumbbell in one hand, palm facing your body and arm fully extended.","Keep your upper arm stationary and curl the dumbbell towards your shoulder, contracting your biceps.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1666-LIGZSTA.jpg","gif_url":"videos/1666-LIGZSTA.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1291","name":"dumbbell one arm pullover on exercise ball","category":"chest","equipment":"dumbbell","instruction_steps":{"en":["Sit on an exercise ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold a dumbbell with one hand and extend your arm straight up above your chest.","Slowly lower the dumbbell behind your head while keeping your arm straight.","Pause for a moment, then raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"triceps","secondary_muscles":["triceps","latissimus dorsi","rhomboids"],"target":"pectorals","image":"images/1291-bQHPBU3.jpg","gif_url":"videos/1291-bQHPBU3.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0358","name":"dumbbell one arm reverse wrist curl","category":"lower arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench or chair with your feet flat on the ground.","Hold a dumbbell in one hand with an overhand grip, palm facing down.","Rest your forearm on your thigh, with your wrist hanging off the edge.","Slowly lower the dumbbell towards the ground by flexing your wrist.","Pause for a moment at the bottom, then slowly curl your wrist back up towards your body.","Repeat for the desired number of repetitions, then switch to the other arm."]},"muscle_group":"wrist extensors","secondary_muscles":["wrist extensors"],"target":"forearms","image":"images/0358-BwSNDGt.jpg","gif_url":"videos/0358-BwSNDGt.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0359","name":"dumbbell one arm reverse fly (with support)","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand with your palm facing inwards.","Lean forward and place your free hand on the bench for support.","Keep your arm slightly bent and raise it out to the side until it is parallel to the ground.","Pause for a moment at the top, then slowly lower your arm back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids"],"target":"delts","image":"images/0359-e25F58f.jpg","gif_url":"videos/0359-e25F58f.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1622","name":"dumbbell one arm reverse grip press","category":"chest","equipment":"dumbbell","instruction_steps":{"en":["Sit on a flat bench with a dumbbell in one hand, palm facing towards your body.","Place your feet flat on the ground and keep your back straight.","Raise the dumbbell to shoulder height, keeping your elbow close to your body.","Press the dumbbell upwards until your arm is fully extended.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1622-Ze7MoIb.jpg","gif_url":"videos/1622-Ze7MoIb.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1414","name":"dumbbell one arm reverse preacher curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on a preacher bench with your chest against the pad and your arm extended over the edge of the bench, holding a dumbbell with an underhand grip.","Lower the dumbbell slowly until your arm is fully extended.","Curl the dumbbell back up towards your shoulder, keeping your upper arm stationary.","Squeeze your biceps at the top of the movement, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1414-bWxq4op.jpg","gif_url":"videos/1414-bWxq4op.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1667","name":"dumbbell one arm reverse spider curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Stand up straight with a dumbbell in one hand, palm facing down and arm fully extended.","Keeping your upper arm stationary, curl the dumbbell towards your shoulder by flexing your elbow.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1667-VdLZ3nB.jpg","gif_url":"videos/1667-VdLZ3nB.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1668","name":"dumbbell one arm seated bicep curl on exercise ball","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand with your palm facing up and your arm fully extended.","Keeping your upper arm stationary, curl the dumbbell towards your shoulder by contracting your biceps.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1668-s999Hdo.jpg","gif_url":"videos/1668-s999Hdo.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1669","name":"dumbbell one arm seated hammer curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell in one hand with a neutral grip (palms facing each other).","Rest your elbow on the inside of your thigh, just above the knee.","Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1669-jK2hZ6n.jpg","gif_url":"videos/1669-jK2hZ6n.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1415","name":"dumbbell one arm seated neutral wrist curl","category":"lower arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing up.","Rest your forearm on your thigh, allowing your wrist to hang off the edge.","Keeping your forearm stationary, curl your wrist upward as far as possible.","Pause for a moment at the top, then slowly lower your wrist back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other hand."]},"muscle_group":"biceps","secondary_muscles":["biceps","brachialis"],"target":"forearms","image":"images/1415-YtaCTYl.jpg","gif_url":"videos/1415-YtaCTYl.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0361","name":"dumbbell one arm shoulder press","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold a dumbbell in one hand at shoulder level, palm facing forward.","Press the dumbbell upward until your arm is fully extended overhead.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]},"muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0361-84RyJf8.jpg","gif_url":"videos/0361-84RyJf8.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0360","name":"dumbbell one arm shoulder press v. 2","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold a dumbbell in one hand at shoulder level, palm facing forward.","Engage your core and press the dumbbell straight up overhead, fully extending your arm.","Pause for a moment at the top, then slowly lower the dumbbell back to shoulder level.","Repeat for the desired number of repetitions, then switch to the other arm."]},"muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0360-1TkiAFK.jpg","gif_url":"videos/0360-1TkiAFK.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3888","name":"dumbbell one arm snatch","category":"upper legs","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a dumbbell in one hand with an overhand grip.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.","Lower the dumbbell towards the ground, keeping it close to your body.","Explosively extend your hips, knees, and ankles, driving the dumbbell upwards in a straight line.","As the dumbbell reaches shoulder height, quickly rotate your hand and punch it overhead, fully extending your arm.","Catch the dumbbell overhead with a slight bend in your knees and hips.","Lower the dumbbell back down to the starting position in a controlled manner.","Repeat for the desired number of repetitions, then switch to the other arm."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps","core"],"target":"glutes","image":"images/3888-6pTkI99.jpg","gif_url":"videos/3888-6pTkI99.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1670","name":"dumbbell one arm standing curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Stand up straight with a dumbbell in one hand, palm facing forward and arm fully extended.","Keeping your upper arm stationary, exhale and curl the weight upward while contracting your biceps.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1670-ffQsyBj.jpg","gif_url":"videos/1670-ffQsyBj.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1671","name":"dumbbell one arm standing hammer curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Stand up straight with a dumbbell in each hand, palms facing your torso.","Keep your elbows close to your torso and your upper arms stationary.","Exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1671-2sQGZ5b.jpg","gif_url":"videos/1671-2sQGZ5b.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0362","name":"dumbbell one arm triceps extension (on bench)","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell in one hand and place your other hand on the bench for support.","Raise the dumbbell overhead, keeping your upper arm close to your head and your elbow pointing forward.","Lower the dumbbell behind your head by bending your elbow, keeping your upper arm stationary.","Extend your arm back up to the starting position, fully straightening your elbow.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0362-nAuHPcD.jpg","gif_url":"videos/0362-nAuHPcD.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0363","name":"dumbbell one arm upright row","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a dumbbell in one hand with an overhand grip.","Let the dumbbell hang at arm's length in front of your thighs, with your palm facing your body.","Keeping your back straight and your core engaged, exhale and lift the dumbbell straight up towards your chin, leading with your elbow.","Pause for a moment at the top, then inhale and slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]},"muscle_group":"traps","secondary_muscles":["traps","biceps"],"target":"delts","image":"images/0363-6cKQC5E.jpg","gif_url":"videos/0363-6cKQC5E.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0364","name":"dumbbell one arm wrist curl","category":"lower arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench or chair with your feet flat on the ground.","Hold a dumbbell in one hand with an underhand grip, resting your forearm on your thigh.","Allow your wrist to extend, letting the dumbbell roll down towards your fingers.","Slowly curl your wrist back up, bringing the dumbbell towards your forearm.","Repeat for the desired number of repetitions, then switch to the other hand."]},"muscle_group":"biceps","secondary_muscles":["biceps","brachialis"],"target":"forearms","image":"images/0364-q8aHNoF.jpg","gif_url":"videos/0364-q8aHNoF.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1672","name":"dumbbell one arm zottman preacher curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on a preacher curl bench and hold a dumbbell in one hand with an underhand grip.","Rest your upper arm on the preacher bench pad, allowing your arm to fully extend.","Curl the dumbbell up towards your shoulder, keeping your upper arm stationary.","At the top of the curl, rotate your wrist so that your palm faces up.","Slowly lower the dumbbell back down to the starting position, rotating your wrist back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1672-sxY5Biu.jpg","gif_url":"videos/1672-sxY5Biu.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1292","name":"dumbbell one leg fly on exercise ball","category":"chest","equipment":"dumbbell","instruction_steps":{"en":["Sit on an exercise ball with a dumbbell in each hand, palms facing each other.","Place one foot on the ground and extend the other leg straight out in front of you.","Lean forward slightly and bring your arms out to the sides, keeping a slight bend in your elbows.","Slowly lower the dumbbells down and out to the sides, feeling a stretch in your chest.","Pause for a moment at the bottom, then squeeze your chest muscles to bring the dumbbells back up to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/1292-pH2x2jj.jpg","gif_url":"videos/1292-pH2x2jj.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0365","name":"dumbbell over bench neutral wrist curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.","Rest your forearms on the bench, allowing your wrists to hang off the edge.","Keeping your upper arms stationary, exhale and curl the dumbbells up towards your shoulders.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0365-BKa8dmT.jpg","gif_url":"videos/0365-BKa8dmT.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0366","name":"dumbbell over bench one arm neutral wrist curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench with a dumbbell in one hand and your arm extended over the bench, palm facing up.","Keep your upper arm stationary and curl the dumbbell towards your shoulder, keeping your wrist in a neutral position.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0366-IvV6C9M.jpg","gif_url":"videos/0366-IvV6C9M.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1441","name":"dumbbell over bench one arm reverse wrist curl","category":"lower arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing down.","Rest your forearm on the bench with your wrist hanging off the edge.","Slowly curl your wrist upwards, bringing the dumbbell towards your forearm.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]},"muscle_group":"biceps","secondary_muscles":["biceps","brachialis"],"target":"forearms","image":"images/1441-4Jc36XM.jpg","gif_url":"videos/1441-4Jc36XM.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0367","name":"dumbbell over bench one arm wrist curl","category":"lower arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing down.","Rest your forearm on the bench with your wrist hanging off the edge.","Slowly curl your wrist upwards, bringing the dumbbell towards your forearm.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]},"muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"target":"forearms","image":"images/0367-KI1DjNN.jpg","gif_url":"videos/0367-KI1DjNN.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0368","name":"dumbbell over bench revers wrist curl","category":"lower arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing down.","Rest your forearms on the bench, allowing your wrists to hang off the edge.","Slowly curl your wrists upward, bringing the dumbbells towards your body.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","brachialis"],"target":"forearms","image":"images/0368-3tAXPQ6.jpg","gif_url":"videos/0368-3tAXPQ6.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0369","name":"dumbbell over bench wrist curl","category":"lower arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench with your forearms resting on the bench and your palms facing up, holding a dumbbell in each hand.","Allow your wrists to hang over the edge of the bench.","Slowly curl your wrists upward, squeezing your forearms at the top of the movement.","Pause for a moment, then slowly lower your wrists back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","brachialis"],"target":"forearms","image":"images/0369-D1xYJAU.jpg","gif_url":"videos/0369-D1xYJAU.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1329","name":"dumbbell palm rotational bent over row","category":"back","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Bend forward at the hips, keeping your back straight and your knees slightly bent.","Let your arms hang straight down, palms facing your body.","Engage your core and pull the dumbbells up towards your chest, keeping your elbows close to your body.","As you pull the dumbbells up, rotate your palms so they face away from your body.","Squeeze your shoulder blades together at the top of the movement.","Slowly lower the dumbbells back down to the starting position, rotating your palms back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/1329-wt6rwjk.jpg","gif_url":"videos/1329-wt6rwjk.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1623","name":"dumbbell palms in incline bench press","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Set up an incline bench at a 45-degree angle.","Sit on the bench with your back against the backrest and feet flat on the ground.","Hold a dumbbell in each hand with an overhand grip, palms facing inwards.","Extend your arms straight up above your chest, keeping a slight bend in your elbows.","Lower the dumbbells slowly towards your shoulders, keeping your elbows close to your body.","Pause for a moment at the bottom, then press the dumbbells back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/1623-8eqjhOl.jpg","gif_url":"videos/1623-8eqjhOl.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0370","name":"dumbbell peacher hammer curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Stand up straight with a dumbbell in each hand, palms facing your torso.","Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.","This will be your starting position.","Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Then, inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the recommended amount of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0370-F1KxjBa.jpg","gif_url":"videos/0370-F1KxjBa.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0371","name":"dumbbell plyo squat","category":"upper legs","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.","Lower your body into a squat position by bending your knees and pushing your hips back.","As you reach the bottom of the squat, explode upward, jumping off the ground.","While in the air, quickly switch the position of your feet, landing with your opposite foot forward.","Immediately lower your body back into a squat position and repeat the jump, switching your feet again.","Continue alternating the position of your feet with each jump for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0371-S4pwGlc.jpg","gif_url":"videos/0371-S4pwGlc.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0372","name":"dumbbell preacher curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on a preacher curl bench with your upper arms resting on the pad and your chest against it.","Hold a dumbbell in each hand with your palms facing up and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0372-jivWf8n.jpg","gif_url":"videos/0372-jivWf8n.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1673","name":"dumbbell preacher curl over exercise ball","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand with an underhand grip, resting your elbow on the exercise ball.","Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.","Pause for a moment at the top, then inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1673-hwygydB.jpg","gif_url":"videos/1673-hwygydB.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1293","name":"dumbbell press on exercise ball","category":"chest","equipment":"dumbbell","instruction_steps":{"en":["Sit on an exercise ball with your feet flat on the ground and dumbbells in each hand, resting on your thighs.","Slowly walk your feet forward, rolling the exercise ball until your lower back is supported on the ball and your knees are at a 90-degree angle.","Raise the dumbbells to shoulder height, palms facing forward.","Press the dumbbells upward until your arms are fully extended.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/1293-O8o7q4d.jpg","gif_url":"videos/1293-O8o7q4d.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0373","name":"dumbbell pronate-grip triceps extension","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench or chair with your back straight and feet flat on the ground.","Hold a dumbbell with both hands, palms facing down, and extend your arms straight up overhead.","Keeping your upper arms close to your head and elbows pointing forward, slowly lower the dumbbell behind your head by bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"triceps","image":"images/0373-bpJL2Qs.jpg","gif_url":"videos/0373-bpJL2Qs.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0374","name":"dumbbell prone incline curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Adjust the bench to a 45-degree incline.","Lie face down on the bench with your chest and stomach resting against it.","Hold a dumbbell in each hand with your palms facing down and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0374-mwpPcr1.jpg","gif_url":"videos/0374-mwpPcr1.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1674","name":"dumbbell prone incline hammer curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Adjust the bench to a 45-degree incline.","Lie face down on the bench with a dumbbell in each hand, palms facing each other.","Allow your arms to hang straight down towards the floor, keeping your elbows slightly bent.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1674-cWemPG8.jpg","gif_url":"videos/1674-cWemPG8.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0375","name":"dumbbell pullover","category":"chest","equipment":"dumbbell","instruction_steps":{"en":["Lie flat on a bench with your head at one end and your feet on the floor.","Hold a dumbbell with both hands and extend your arms straight above your chest.","Keeping a slight bend in your elbows, slowly lower the dumbbell behind your head until you feel a stretch in your chest and shoulders.","Pause for a moment, then raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"latissimus dorsi","secondary_muscles":["latissimus dorsi","triceps"],"target":"pectorals","image":"images/0375-9XjtHvS.jpg","gif_url":"videos/0375-9XjtHvS.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1294","name":"dumbbell pullover hip extension on exercise ball","category":"chest","equipment":"dumbbell","instruction_steps":{"en":["Sit on an exercise ball with your feet flat on the ground and the dumbbell resting on your thighs.","Slowly walk your feet forward, rolling the exercise ball down your back until your head, neck, and upper back are supported on the ball.","Hold the dumbbell with both hands and extend your arms straight up over your chest, keeping a slight bend in your elbows.","Lower the dumbbell behind your head, keeping your arms straight and maintaining control.","Pause for a moment, then raise the dumbbell back to the starting position.","While keeping your arms extended, lift your hips off the ground, squeezing your glutes and engaging your core.","Lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders","core"],"target":"pectorals","image":"images/1294-lI7easp.jpg","gif_url":"videos/1294-lI7easp.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1295","name":"dumbbell pullover on exercise ball","category":"chest","equipment":"dumbbell","instruction_steps":{"en":["Sit on an exercise ball and hold a dumbbell with both hands above your chest, arms extended.","Slowly lower the dumbbell behind your head while keeping your arms straight.","Pause for a moment, then raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","latissimus dorsi"],"target":"pectorals","image":"images/1295-FSD6PGL.jpg","gif_url":"videos/1295-FSD6PGL.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1700","name":"dumbbell push press","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level.","Bend your knees slightly and dip your body down, then explosively extend your legs and press the dumbbells overhead.","Lock out your arms at the top of the movement, then lower the dumbbells back to shoulder level.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","core"],"target":"delts","image":"images/1700-FS63wTN.jpg","gif_url":"videos/1700-FS63wTN.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0376","name":"dumbbell raise","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.","Keep your back straight and engage your core.","Raise your arms out to the sides until they are parallel to the floor, keeping a slight bend in your elbows.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"traps","secondary_muscles":["traps","rhomboids"],"target":"delts","image":"images/0376-c9MnDRp.jpg","gif_url":"videos/0376-c9MnDRp.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2292","name":"dumbbell rear delt raise","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the floor.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids"],"target":"delts","image":"images/2292-mu5Guxt.jpg","gif_url":"videos/2292-mu5Guxt.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0377","name":"dumbbell rear delt row_shoulder","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and knees slightly bent.","Hold a dumbbell in each hand with your palms facing your body.","Bend forward at the waist, keeping your back straight and your core engaged.","Extend your arms straight down towards the floor, with a slight bend in your elbows.","Raise the dumbbells out to the sides, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids"],"target":"delts","image":"images/0377-EKXOMEh.jpg","gif_url":"videos/0377-EKXOMEh.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0378","name":"dumbbell rear fly","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Extend your arms straight down towards the ground, palms facing each other.","Keeping a slight bend in your elbows, lift your arms out to the sides and squeeze your shoulder blades together.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids"],"target":"delts","image":"images/0378-8DiFDVA.jpg","gif_url":"videos/0378-8DiFDVA.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0380","name":"dumbbell rear lateral raise","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and core engaged.","Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the floor.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"traps","secondary_muscles":["traps","rhomboids"],"target":"delts","image":"images/0380-v1qBec9.jpg","gif_url":"videos/0380-v1qBec9.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0379","name":"dumbbell rear lateral raise (support head)","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"traps","secondary_muscles":["traps","rhomboids"],"target":"delts","image":"images/0379-UzkLrem.jpg","gif_url":"videos/0379-UzkLrem.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0381","name":"dumbbell rear lunge","category":"upper legs","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Take a step backward with your right foot, lowering your body into a lunge position.","Bend your left knee and lower your body until your left thigh is parallel to the ground.","Pause for a moment, then push through your left heel to return to the starting position.","Repeat on the other side, stepping back with your left foot."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0381-SSsBDwB.jpg","gif_url":"videos/0381-SSsBDwB.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0382","name":"dumbbell revers grip biceps curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Stand up straight with a dumbbell in each hand, palms facing down and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0382-e4ojVhP.jpg","gif_url":"videos/0382-e4ojVhP.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1624","name":"dumbbell reverse bench press","category":"chest","equipment":"dumbbell","instruction_steps":{"en":["Lie flat on a bench with your feet flat on the ground and your knees bent.","Hold a dumbbell in each hand with an overhand grip, palms facing towards your feet.","Extend your arms straight up towards the ceiling, keeping a slight bend in your elbows.","Slowly lower the dumbbells towards your chest, allowing your elbows to flare out to the sides.","Pause for a moment at the bottom, then push the dumbbells back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1624-UIbGx6H.jpg","gif_url":"videos/1624-UIbGx6H.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0383","name":"dumbbell reverse fly","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Extend your arms straight down in front of you, palms facing each other.","Keeping a slight bend in your elbows, raise your arms out to the sides until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids"],"target":"delts","image":"images/0383-EAs3xL9.jpg","gif_url":"videos/0383-EAs3xL9.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1330","name":"dumbbell reverse grip incline bench one arm row","category":"back","equipment":"dumbbell","instruction_steps":{"en":["Set up an incline bench at a 45-degree angle.","Place a dumbbell on the floor next to the bench.","Stand facing the bench with your feet shoulder-width apart.","Bend at the waist and place your left knee and left hand on the bench for support.","Pick up the dumbbell with your right hand using a reverse grip (palm facing down).","Keep your back straight and your core engaged.","Pull the dumbbell up towards your chest, keeping your elbow close to your body.","Squeeze your back muscles at the top of the movement.","Lower the dumbbell back down to the starting position in a controlled manner.","Repeat for the desired number of repetitions.","Switch sides and repeat the exercise with your left arm."]},"muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"target":"upper back","image":"images/1330-ZIViNh1.jpg","gif_url":"videos/1330-ZIViNh1.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1331","name":"dumbbell reverse grip incline bench two arm row","category":"back","equipment":"dumbbell","instruction_steps":{"en":["Set up an incline bench at a 45-degree angle.","Sit on the bench with your chest against the backrest and your feet flat on the ground.","Hold a dumbbell in each hand with an underhand grip.","Lean forward and let your arms hang straight down, fully extended.","Pull the dumbbells up towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/1331-9pQSkH8.jpg","gif_url":"videos/1331-9pQSkH8.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2327","name":"dumbbell reverse grip row (female)","category":"back","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and knees slightly bent.","Hold a dumbbell in each hand with an overhand grip, palms facing your body.","Bend forward at the waist, keeping your back straight and your core engaged.","Let your arms hang straight down, fully extended, with a slight bend in your elbows.","Pull the dumbbells up towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/2327-Nh3mvOO.jpg","gif_url":"videos/2327-Nh3mvOO.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0384","name":"dumbbell reverse preacher curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on a preacher bench with your upper arms resting on the pad and your chest against the support.","Hold a dumbbell in each hand with an underhand grip, palms facing up.","Keeping your upper arms stationary, exhale and curl the dumbbells as you contract your biceps.","Continue to curl the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0384-O8Aq69u.jpg","gif_url":"videos/0384-O8Aq69u.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1675","name":"dumbbell reverse spider curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Stand up straight with a dumbbell in each hand, palms facing your body and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1675-6sMAmNv.jpg","gif_url":"videos/1675-6sMAmNv.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0385","name":"dumbbell reverse wrist curl","category":"lower arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench or chair with your feet flat on the ground.","Hold a dumbbell in each hand with an overhand grip, palms facing down.","Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Slowly curl your wrists upward, bringing the dumbbells towards your body.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","brachialis"],"target":"forearms","image":"images/0385-BLCvwr2.jpg","gif_url":"videos/0385-BLCvwr2.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1459","name":"dumbbell romanian deadlift","category":"upper legs","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Keeping your back straight and your core engaged, hinge at the hips and lower the dumbbells towards the ground, allowing your knees to bend slightly.","Lower the dumbbells until you feel a stretch in your hamstrings, then push through your heels and engage your glutes to return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"target":"glutes","image":"images/1459-rR0LJzx.jpg","gif_url":"videos/1459-rR0LJzx.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0386","name":"dumbbell rotation reverse fly","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing inwards.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.","Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the floor.","Rotate your arms so that your palms are facing downwards.","Slowly lower your arms back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids"],"target":"delts","image":"images/0386-prbWx1D.jpg","gif_url":"videos/0386-prbWx1D.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2397","name":"dumbbell scott press","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench with a dumbbell in each hand, palms facing forward.","Raise the dumbbells to shoulder height, with your elbows bent and palms facing forward.","Press the dumbbells upward until your arms are fully extended.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","chest"],"target":"delts","image":"images/2397-5vfAI0I.jpg","gif_url":"videos/2397-5vfAI0I.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0387","name":"dumbbell seated alternate front raise","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell in each hand with your palms facing your body and arms extended down by your sides.","Keeping your arms straight, raise one dumbbell in front of you until it is parallel to the ground.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat with the other arm.","Alternate between arms for the desired number of repetitions."]},"muscle_group":"trapezius","secondary_muscles":["trapezius","biceps"],"target":"delts","image":"images/0387-gH5fRsC.jpg","gif_url":"videos/0387-gH5fRsC.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1676","name":"dumbbell seated alternate hammer curl on exercise ball","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in each hand with your palms facing your body and your arms fully extended.","Keeping your upper arms stationary, exhale and curl one dumbbell up towards your shoulder while keeping your palm facing your body.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat the movement with the opposite arm.","Continue alternating arms for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1676-QLRmNeT.jpg","gif_url":"videos/1676-QLRmNeT.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0388","name":"dumbbell seated alternate press","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench with a dumbbell in each hand, palms facing forward.","Raise the dumbbells to shoulder height, with your elbows bent and palms facing forward.","Press one dumbbell up overhead, fully extending your arm.","Lower the dumbbell back down to shoulder height.","Repeat with the other arm.","Continue alternating arms for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","chest"],"target":"delts","image":"images/0388-QT5Q0nK.jpg","gif_url":"videos/0388-QT5Q0nK.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3546","name":"dumbbell seated alternate shoulder","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell in each hand, palms facing inwards, and raise them to shoulder height.","Press one dumbbell up overhead while keeping the other dumbbell at shoulder height.","Lower the raised dumbbell back to shoulder height while simultaneously pressing the other dumbbell up overhead.","Continue alternating between arms for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/3546-q7qkONO.jpg","gif_url":"videos/3546-q7qkONO.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0389","name":"dumbbell seated bench extension","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell with both hands and extend your arms straight up above your head.","Slowly lower the dumbbell behind your head, keeping your elbows close to your ears.","Pause for a moment, then raise the dumbbell back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0389-JhYSVwT.jpg","gif_url":"videos/0389-JhYSVwT.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2317","name":"dumbbell seated bent arm lateral raise","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell in each hand with your palms facing your body and your arms bent at a 90-degree angle.","Keeping your elbows bent, raise your arms out to the sides until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids"],"target":"delts","image":"images/2317-JzQbv7J.jpg","gif_url":"videos/2317-JzQbv7J.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1730","name":"dumbbell seated bent over alternate kickback","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench with a dumbbell in each hand, palms facing inwards.","Bend forward at the waist, keeping your back straight and parallel to the ground.","Extend one arm straight back, keeping it close to your body, until your arm is fully extended.","Pause for a moment, then slowly lower the dumbbell back to the starting position.","Repeat with the other arm.","Continue alternating arms for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","back"],"target":"triceps","image":"images/1730-x0lwvfq.jpg","gif_url":"videos/1730-x0lwvfq.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1737","name":"dumbbell seated bent over triceps extension","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand.","Bend forward at the waist, keeping your back straight and your head up.","Extend your arms straight back, keeping your elbows close to your head.","Pause for a moment, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","back"],"target":"triceps","image":"images/1737-4ievMJ9.jpg","gif_url":"videos/1737-4ievMJ9.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1677","name":"dumbbell seated bicep curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.","Keep your back straight and your elbows close to your torso.","Exhale and curl the dumbbells up towards your shoulders, contracting your biceps.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1677-xiA6lRr.jpg","gif_url":"videos/1677-xiA6lRr.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0390","name":"dumbbell seated biceps curl (on stability ball)","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on a stability ball with your feet flat on the ground and your back straight.","Hold a dumbbell in each hand with your palms facing forward and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the dumbbells while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0390-WgJnBH5.jpg","gif_url":"videos/0390-WgJnBH5.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3547","name":"dumbbell seated biceps curl to shoulder press","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell in each hand with your palms facing forward and arms fully extended.","Keeping your elbows close to your sides, curl the dumbbells up towards your shoulders.","Once your forearms are vertical, rotate your wrists so that your palms are facing forward.","Press the dumbbells overhead until your arms are fully extended.","Lower the dumbbells back down to the starting position by reversing the movement.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"biceps","image":"images/3547-OeL23VY.jpg","gif_url":"videos/3547-OeL23VY.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1379","name":"dumbbell seated calf raise","category":"lower legs","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench or chair with your feet flat on the ground and a dumbbell resting on your thighs.","Place the balls of your feet on a raised surface such as a step or block, with your heels hanging off the edge.","Hold onto the dumbbell for stability.","Raise your heels as high as possible, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"target":"calves","image":"images/1379-r29jP7S.jpg","gif_url":"videos/1379-r29jP7S.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0391","name":"dumbbell seated curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench with your feet flat on the ground and a dumbbell in each hand, palms facing forward.","Keep your back straight and your elbows close to your torso.","Exhale and curl the dumbbells up towards your shoulders, contracting your biceps.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0391-TiaZTxx.jpg","gif_url":"videos/0391-TiaZTxx.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0392","name":"dumbbell seated front raise","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench with your feet flat on the ground and a dumbbell in each hand, resting on your thighs.","Keep your back straight and core engaged.","Raise the dumbbells in front of you, with your palms facing down, until they are at shoulder level.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"trapezius","secondary_muscles":["trapezius","biceps"],"target":"delts","image":"images/0392-Ys97II0.jpg","gif_url":"videos/0392-Ys97II0.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1678","name":"dumbbell seated hammer curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench with a dumbbell in each hand, palms facing your torso and arms extended straight down.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1678-IGtBdNT.jpg","gif_url":"videos/1678-IGtBdNT.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0393","name":"dumbbell seated inner biceps curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.","Rest your upper arms on your thighs, allowing the dumbbells to hang down.","Keeping your upper arms stationary, curl the dumbbells up towards your shoulders by contracting your biceps.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0393-KXyoEtA.jpg","gif_url":"videos/0393-KXyoEtA.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0394","name":"dumbbell seated kickback","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand.","Bend your knees slightly and lean forward from your hips, keeping your back straight.","Bring your upper arms close to your sides and keep your elbows bent at a 90-degree angle.","Extend your arms straight back, squeezing your triceps at the top of the movement.","Pause for a moment, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0394-en550rk.jpg","gif_url":"videos/0394-en550rk.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0396","name":"dumbbell seated lateral raise","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench with your feet flat on the ground and a dumbbell in each hand, resting on your thighs.","Keep your back straight and core engaged.","Raise the dumbbells to your sides with a slight bend in your elbows, until your arms are parallel to the ground.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"traps","secondary_muscles":["traps","upper back"],"target":"delts","image":"images/0396-hxyTtWj.jpg","gif_url":"videos/0396-hxyTtWj.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0395","name":"dumbbell seated lateral raise v. 2","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench with your feet flat on the ground and a dumbbell in each hand, resting on your thighs.","Keep your back straight and core engaged.","Raise the dumbbells to your sides with a slight bend in your elbows, until your arms are parallel to the ground.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"traps","secondary_muscles":["traps","triceps"],"target":"delts","image":"images/0395-hrrS0Ed.jpg","gif_url":"videos/0395-hrrS0Ed.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0397","name":"dumbbell seated neutral wrist curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing each other.","Rest your forearms on your thighs, allowing the dumbbells to hang down.","Keeping your wrists in a neutral position, curl the dumbbells up towards your shoulders.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0397-uJmK7Z1.jpg","gif_url":"videos/0397-uJmK7Z1.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1679","name":"dumbbell seated one arm bicep curl on exercise ball with leg raised","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand with your palm facing up and your arm fully extended.","Place your other hand on your hip for stability.","Slowly curl the dumbbell towards your shoulder, keeping your upper arm stationary.","Pause for a moment at the top of the movement, squeezing your bicep.","Slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions.","Switch arms and repeat the exercise."]},"muscle_group":"forearms","secondary_muscles":["forearms","shoulders"],"target":"biceps","image":"images/1679-84sESNy.jpg","gif_url":"videos/1679-84sESNy.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0398","name":"dumbbell seated one arm kickback","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand.","Bend your torso forward at the waist, keeping your back straight and parallel to the ground.","Extend your arm straight back, keeping your elbow close to your body.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0398-VQ3sNCn.jpg","gif_url":"videos/0398-VQ3sNCn.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0399","name":"dumbbell seated one arm rotate","category":"lower arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench with your back straight and hold a dumbbell in one hand, resting it on your thigh.","Raise the dumbbell up to shoulder height, keeping your elbow close to your body.","Rotate your forearm outward, away from your body, while keeping your upper arm stationary.","Pause for a moment at the top, then slowly rotate your forearm back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","biceps"],"target":"forearms","image":"images/0399-7f2jsqP.jpg","gif_url":"videos/0399-7f2jsqP.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0400","name":"dumbbell seated one leg calf raise","category":"lower legs","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench or chair with your feet flat on the ground and a dumbbell resting on your right thigh.","Extend your left leg straight out in front of you, keeping your foot flexed.","Place the ball of your right foot on an elevated surface, such as a step or weight plate.","Using your calf muscles, raise your right heel as high as possible.","Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Repeat for the desired number of repetitions, then switch legs."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"calves","image":"images/0400-Ia7tumC.jpg","gif_url":"videos/0400-Ia7tumC.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1380","name":"dumbbell seated one leg calf raise - hammer grip","category":"lower legs","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench or chair with your feet flat on the ground and a dumbbell resting on your thighs.","Place one foot on a raised surface, such as a step or block, with your heel hanging off the edge.","Hold the dumbbell with a hammer grip, meaning your palms are facing each other and your fingers are wrapped around the handle.","Keeping your core engaged and your back straight, slowly raise your heel as high as possible by pushing through the ball of your foot.","Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other leg."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"calves","image":"images/1380-FxhcxUW.jpg","gif_url":"videos/1380-FxhcxUW.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1381","name":"dumbbell seated one leg calf raise - palm up","category":"lower legs","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench or chair with your back straight and your feet flat on the ground.","Hold a dumbbell in one hand and place it on top of your thigh, palm facing up.","Lift one leg off the ground and extend it in front of you, keeping your knee slightly bent.","Raise your heel as high as possible by pushing through the ball of your foot.","Pause for a moment at the top, then slowly lower your heel back down.","Repeat for the desired number of repetitions, then switch legs and repeat."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"calves","image":"images/1381-VW88JNd.jpg","gif_url":"videos/1381-VW88JNd.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0401","name":"dumbbell seated palms up wrist curl","category":"lower arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.","Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Slowly curl your wrists upward, squeezing your forearms at the top of the movement.","Pause for a moment, then lower your wrists back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"target":"forearms","image":"images/0401-2dImyQ8.jpg","gif_url":"videos/0401-2dImyQ8.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0402","name":"dumbbell seated preacher curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on a preacher curl bench with your feet flat on the floor.","Hold a dumbbell in one hand with an underhand grip, resting your upper arm against the preacher pad.","Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.","Pause for a moment at the top, then inhale and slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0402-7D5bgLT.jpg","gif_url":"videos/0402-7D5bgLT.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0403","name":"dumbbell seated revers grip concentration curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing up.","Rest your elbow on the inside of your thigh, just above the knee.","Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0403-lyKCLmK.jpg","gif_url":"videos/0403-lyKCLmK.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1738","name":"dumbbell seated reverse grip one arm overhead tricep extension","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell with an underhand grip and extend your arm straight up overhead.","Lower the dumbbell behind your head by bending your elbow, keeping your upper arm stationary.","Pause for a moment, then extend your arm back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/1738-5fKX7wi.jpg","gif_url":"videos/1738-5fKX7wi.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0405","name":"dumbbell seated shoulder press","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench with a dumbbell in each hand, resting on your thighs.","Raise the dumbbells to shoulder height, palms facing forward.","Press the dumbbells upward until your arms are fully extended overhead.","Pause for a moment at the top, then slowly lower the dumbbells back to shoulder height.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0405-znQUdHY.jpg","gif_url":"videos/0405-znQUdHY.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0404","name":"dumbbell seated shoulder press (parallel grip)","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench with a dumbbell in each hand, palms facing inward.","Raise the dumbbells to shoulder height, elbows bent and palms facing forward.","Press the dumbbells upward until your arms are fully extended overhead.","Pause for a moment at the top, then slowly lower the dumbbells back to shoulder height.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0404-f1jf47L.jpg","gif_url":"videos/0404-f1jf47L.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2188","name":"dumbbell seated triceps extension","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell with both hands and extend your arms straight up overhead.","Bend your elbows and lower the dumbbell behind your head, keeping your upper arms close to your ears.","Pause for a moment, then straighten your arms and return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/2188-kont8Ut.jpg","gif_url":"videos/2188-kont8Ut.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0406","name":"dumbbell shrug","category":"back","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand with your palms facing your body.","Keep your arms straight and let the dumbbells hang by your sides.","Raise your shoulders as high as possible, as if you are trying to touch your ears with your shoulders.","Hold the contraction for a second, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"traps","image":"images/0406-NJzBsGJ.jpg","gif_url":"videos/0406-NJzBsGJ.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0407","name":"dumbbell side bend","category":"waist","equipment":"dumbbell","instruction_steps":{"en":["Stand up straight with your feet shoulder-width apart and hold a dumbbell in one hand, letting it hang down by your side.","Keeping your back straight and your core engaged, slowly bend sideways at the waist towards the opposite side of the dumbbell, lowering the weight as far as you comfortably can.","Pause for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides and repeat."]},"muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/0407-IpONWYv.jpg","gif_url":"videos/0407-IpONWYv.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0408","name":"dumbbell side lying one hand raise","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Lie on your side with your legs extended and your head supported by your arm.","Hold a dumbbell in your top hand with your palm facing down.","Keeping your arm straight, raise the dumbbell up to shoulder height.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},"muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids"],"target":"delts","image":"images/0408-fTlkJop.jpg","gif_url":"videos/0408-fTlkJop.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3664","name":"dumbbell side plank with rear fly","category":"back","equipment":"dumbbell","instruction_steps":{"en":["Start by lying on your side with your legs extended and stacked on top of each other.","Place your forearm on the ground directly below your shoulder, keeping your elbow bent at a 90-degree angle.","Hold a dumbbell in your top hand, with your arm extended straight down towards the ground.","Engage your core and lift your hips off the ground, creating a straight line from your head to your heels.","While maintaining the side plank position, lift the dumbbell up towards the ceiling, squeezing your shoulder blades together.","Lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","core"],"target":"upper back","image":"images/3664-X6ytgYZ.jpg","gif_url":"videos/3664-X6ytgYZ.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3548","name":"dumbbell single arm overhead carry","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Stand tall with your feet shoulder-width apart, holding a dumbbell in one hand.","Raise the dumbbell overhead, fully extending your arm.","Engage your core and keep your back straight as you walk forward, maintaining the dumbbell overhead.","Continue walking for the desired distance or time.","Switch hands and repeat the exercise."]},"muscle_group":"traps","secondary_muscles":["traps","core"],"target":"delts","image":"images/3548-mWBtgmb.jpg","gif_url":"videos/3548-mWBtgmb.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0409","name":"dumbbell single leg calf raise","category":"lower legs","equipment":"dumbbell","instruction_steps":{"en":["Stand on the edge of a step or platform with your heels hanging off and your toes on the step.","Hold a dumbbell in one hand and place your other hand on a wall or railing for support.","Raise your heel as high as possible, lifting your body up onto your toes.","Pause for a moment at the top, then slowly lower your heel back down below the step.","Repeat for the desired number of repetitions, then switch to the other leg."]},"muscle_group":"ankles","secondary_muscles":["ankles"],"target":"calves","image":"images/0409-1kB3Wmk.jpg","gif_url":"videos/0409-1kB3Wmk.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1757","name":"dumbbell single leg deadlift","category":"upper legs","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet hip-width apart, holding a dumbbell in your right hand.","Shift your weight onto your left leg and lift your right foot slightly off the ground.","Keeping your back straight, hinge forward at the hips and lower the dumbbell towards the ground.","At the same time, extend your right leg straight behind you, maintaining a slight bend in your left knee.","Lower the dumbbell until your torso and right leg are parallel to the ground.","Pause for a moment, then engage your glutes and hamstrings to return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"target":"glutes","image":"images/1757-gKozT8X.jpg","gif_url":"videos/1757-gKozT8X.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2805","name":"dumbbell single leg deadlift with stepbox support","category":"upper legs","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet hip-width apart, holding a dumbbell in your right hand.","Place your left foot on a stepbox or elevated surface behind you.","Keeping your back straight and core engaged, hinge forward at the hips, lowering the dumbbell towards the ground.","As you lower the dumbbell, simultaneously lift your left leg behind you, maintaining a straight line from head to heel.","Lower the dumbbell until you feel a stretch in your right hamstring, then return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"target":"glutes","image":"images/2805-daBmy1Y.jpg","gif_url":"videos/2805-daBmy1Y.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0410","name":"dumbbell single leg split squat","category":"upper legs","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Take a step forward with one foot and position your feet so that your front foot is flat on the ground and your back foot is elevated on a bench or step.","Lower your body by bending your front knee and hip, keeping your back knee slightly bent and your back heel off the ground.","Continue lowering until your front thigh is parallel to the ground, then push through your front heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."]},"muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves"],"target":"quads","image":"images/0410-qx4fgX7.jpg","gif_url":"videos/0410-qx4fgX7.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0411","name":"dumbbell single leg squat","category":"upper legs","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Extend one leg forward and keep it off the ground throughout the exercise.","Bend your standing leg and lower your body down as if sitting back into a chair.","Keep your chest up and your back straight.","Pause for a moment at the bottom, then push through your heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0411-H6ybluc.jpg","gif_url":"videos/0411-H6ybluc.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0413","name":"dumbbell squat","category":"upper legs","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.","Keeping your chest up and core engaged, lower your body down by bending at the knees and hips, as if sitting back into a chair.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0413-HsvHqgf.jpg","gif_url":"videos/0413-HsvHqgf.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3560","name":"dumbbell standing alternate hammer curl and press","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Stand up straight with a dumbbell in each hand, palms facing your body.","Keep your elbows close to your torso and your back straight.","Exhale and curl the dumbbell in your right hand towards your shoulder, keeping your upper arm stationary.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat the curl with your left hand.","After completing the curl with your left hand, exhale and press the dumbbell in your right hand overhead.","Extend your arm fully and hold for a moment at the top.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat the press with your left hand.","Continue alternating between curls and presses for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms","shoulders"],"target":"biceps","image":"images/3560-LeaZOIz.jpg","gif_url":"videos/3560-LeaZOIz.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0414","name":"dumbbell standing alternate overhead press","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level with your palms facing forward.","Press one dumbbell overhead, fully extending your arm.","Lower the dumbbell back to shoulder level.","Repeat with the other arm.","Continue alternating arms for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","core"],"target":"delts","image":"images/0414-bBi35y3.jpg","gif_url":"videos/0414-bBi35y3.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0415","name":"dumbbell standing alternate raise","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body.","Keep your back straight and your core engaged.","Raise one dumbbell to the side, keeping your arm straight and your palm facing down.","Continue lifting until your arm is parallel to the ground.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat with the other arm.","Alternate between arms for the desired number of repetitions."]},"muscle_group":"traps","secondary_muscles":["traps","forearms"],"target":"delts","image":"images/0415-SxHteRW.jpg","gif_url":"videos/0415-SxHteRW.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1739","name":"dumbbell standing alternating tricep kickback","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Extend your arms straight back, keeping your elbows close to your body.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat with the other arm, alternating sides with each repetition."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/1739-Gi2BXfK.jpg","gif_url":"videos/1739-Gi2BXfK.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2143","name":"dumbbell standing around world","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Extend your arms straight out to the sides at shoulder height, palms facing down.","Keeping your arms straight, slowly rotate your arms in a circular motion, bringing the dumbbells in front of your body and then overhead.","Continue the circular motion, bringing the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","forearms"],"target":"delts","image":"images/2143-RSOsp5d.jpg","gif_url":"videos/2143-RSOsp5d.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1740","name":"dumbbell standing bent over one arm triceps extension","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold a dumbbell in one hand.","Bend forward at the waist, keeping your back straight and parallel to the ground.","Extend your arm straight back, keeping your elbow close to your body.","Slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","back"],"target":"triceps","image":"images/1740-CJwa0vD.jpg","gif_url":"videos/1740-CJwa0vD.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1741","name":"dumbbell standing bent over two arm triceps extension","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Bend forward at the waist, keeping your back straight and your knees slightly bent.","Extend your arms straight back, keeping your elbows close to your body.","Slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","back"],"target":"triceps","image":"images/1741-3T12T87.jpg","gif_url":"videos/1741-3T12T87.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0416","name":"dumbbell standing biceps curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Stand up straight with a dumbbell in each hand, palms facing forward and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0416-3s4NnTh.jpg","gif_url":"videos/0416-3s4NnTh.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0417","name":"dumbbell standing calf raise","category":"lower legs","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Raise your heels off the ground as high as possible, using your calves.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"ankles","secondary_muscles":["ankles"],"target":"calves","image":"images/0417-dPmaUaU.jpg","gif_url":"videos/0417-dPmaUaU.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0418","name":"dumbbell standing concentration curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold a dumbbell in one hand, with your arm fully extended and palm facing inwards.","Place your opposite hand on your thigh for support.","Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder by contracting your biceps.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0418-7inpWch.jpg","gif_url":"videos/0418-7inpWch.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0419","name":"dumbbell standing front raise above head","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Keep your arms straight and lift the dumbbells in front of you, raising them above your head.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"trapezius","secondary_muscles":["trapezius","biceps"],"target":"delts","image":"images/0419-laVRfDf.jpg","gif_url":"videos/0419-laVRfDf.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2321","name":"dumbbell standing inner biceps curl v. 2","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Stand up straight with a dumbbell in each hand, palms facing your torso.","Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.","While holding your upper arms stationary, curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Slowly begin to bring the dumbbells back to the starting position as your breathe in.","Repeat for the recommended amount of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/2321-vKilzz3.jpg","gif_url":"videos/2321-vKilzz3.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0420","name":"dumbbell standing kickback","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Extend your arms straight back, squeezing your triceps at the top of the movement.","Pause for a moment, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0420-UmpPAAe.jpg","gif_url":"videos/0420-UmpPAAe.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0421","name":"dumbbell standing one arm concentration curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Stand up straight with your feet shoulder-width apart and hold a dumbbell in one hand, palm facing up.","Place your free hand on your thigh for support.","Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder by contracting your biceps.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0421-8fgqP5a.jpg","gif_url":"videos/0421-8fgqP5a.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0422","name":"dumbbell standing one arm curl (over incline bench)","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a dumbbell in one hand with your palm facing forward.","Place your other hand on an incline bench for support.","Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder by contracting your biceps.","Pause for a moment at the top, then inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0422-BIb1tGo.jpg","gif_url":"videos/0422-BIb1tGo.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1680","name":"dumbbell standing one arm curl over incline bench","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a dumbbell in one hand.","Place your other hand on an incline bench for support.","Keeping your upper arm stationary, curl the dumbbell towards your shoulder by contracting your biceps.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1680-EmlJR2y.jpg","gif_url":"videos/1680-EmlJR2y.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0423","name":"dumbbell standing one arm extension","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a dumbbell in one hand.","Raise the dumbbell overhead, fully extending your arm.","Keep your upper arm close to your head and perpendicular to the ground.","Slowly lower the dumbbell behind your head, bending your elbow.","Pause for a moment, then raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0423-BCUR88E.jpg","gif_url":"videos/0423-BCUR88E.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0424","name":"dumbbell standing one arm palm in press","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a dumbbell in one hand at shoulder height with your palm facing inwards.","Engage your core and keep your back straight.","Press the dumbbell upwards until your arm is fully extended.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]},"muscle_group":"triceps","secondary_muscles":["triceps","core"],"target":"delts","image":"images/0424-ocYc6Db.jpg","gif_url":"videos/0424-ocYc6Db.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0425","name":"dumbbell standing one arm reverse curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Stand up straight with your feet shoulder-width apart and hold a dumbbell in one hand with an overhand grip.","Keep your arm fully extended and close to your body, with your palm facing down.","Slowly curl the dumbbell up towards your shoulder, keeping your upper arm stationary.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0425-DU5Kkj2.jpg","gif_url":"videos/0425-DU5Kkj2.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0426","name":"dumbbell standing overhead press","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level with your palms facing forward.","Press the dumbbells upward until your arms are fully extended overhead.","Pause for a moment at the top, then slowly lower the dumbbells back down to shoulder level.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0426-A6wtbuL.jpg","gif_url":"videos/0426-A6wtbuL.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0427","name":"dumbbell standing palms in press","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level with your palms facing inwards.","Keeping your core engaged and your back straight, press the dumbbells upwards until your arms are fully extended overhead.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","chest"],"target":"delts","image":"images/0427-UilDHSs.jpg","gif_url":"videos/0427-UilDHSs.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0428","name":"dumbbell standing preacher curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Stand upright with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.","Rest the back of your upper arms against the preacher bench or an incline bench, with your elbows slightly bent.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0428-hq2hyDH.jpg","gif_url":"videos/0428-hq2hyDH.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0429","name":"dumbbell standing reverse curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Stand up straight with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0429-0IgNjSM.jpg","gif_url":"videos/0429-0IgNjSM.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0430","name":"dumbbell standing triceps extension","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold a dumbbell in one hand.","Raise the dumbbell overhead, keeping your arm straight.","Bend your elbow and lower the dumbbell behind your head, keeping your upper arm stationary.","Extend your arm back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0430-PdmaD0N.jpg","gif_url":"videos/0430-PdmaD0N.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2293","name":"dumbbell standing zottman preacher curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Stand up straight with a dumbbell in each hand, palms facing forward.","Place your upper arms against the preacher bench and keep your elbows slightly bent.","Curl the dumbbells up towards your shoulders while keeping your upper arms stationary.","At the top of the movement, rotate your wrists so that your palms are facing downward.","Slowly lower the dumbbells back to the starting position, rotating your wrists back to the starting position as well.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/2293-P2nRiUa.jpg","gif_url":"videos/2293-P2nRiUa.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1684","name":"dumbbell step up single leg balance with bicep curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Stand in front of a step or platform with a dumbbell in each hand, palms facing your body.","Place your right foot on the step, ensuring your entire foot is in contact with the surface.","Engage your core and push through your right heel to lift your body up onto the step, bringing your left knee up towards your chest.","At the top of the movement, perform a bicep curl by bending your elbows and bringing the dumbbells towards your shoulders.","Lower the dumbbells back down and simultaneously lower your left foot back to the ground.","Repeat the movement on the opposite side, stepping up with your left foot and curling the dumbbells.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","glutes","hamstrings"],"target":"biceps","image":"images/1684-76vfTdU.jpg","gif_url":"videos/1684-76vfTdU.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0431","name":"dumbbell step-up","category":"upper legs","equipment":"dumbbell","instruction_steps":{"en":["Stand in front of a bench or step with a dumbbell in each hand, palms facing your body.","Place your right foot on the bench or step, ensuring your entire foot is in contact with the surface.","Push through your right heel and lift your body up onto the bench or step, straightening your right leg.","Bring your left foot up onto the bench or step, standing fully upright.","Step back down with your left foot, followed by your right foot, returning to the starting position.","Repeat for the desired number of repetitions, then switch legs."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0431-aXtJhlg.jpg","gif_url":"videos/0431-aXtJhlg.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2796","name":"dumbbell step-up lunge","category":"upper legs","equipment":"dumbbell","instruction_steps":{"en":["Stand in front of a step or platform with a dumbbell in each hand, palms facing your sides.","Place your right foot on the step, ensuring your entire foot is on the surface.","Push through your right heel and lift your body up onto the step, bringing your left foot up as well.","Once both feet are on the step, lower your left foot back down to the starting position, keeping your right foot on the step.","Repeat the movement, alternating which foot you step up with each time.","Continue for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves"],"target":"quads","image":"images/2796-gFyFj9z.jpg","gif_url":"videos/2796-gFyFj9z.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2812","name":"dumbbell step-up split squat","category":"upper legs","equipment":"dumbbell","instruction_steps":{"en":["Stand in front of a bench or step with a dumbbell in each hand, palms facing your body.","Place your right foot on the bench or step, ensuring your entire foot is in contact with the surface.","Step up onto the bench or step with your right foot, pushing through your heel to lift your body up.","As you step up, simultaneously lift your left knee towards your chest.","Pause at the top of the movement, then slowly lower your left foot back to the ground while keeping your right foot on the bench or step.","Repeat the movement with your left foot on the bench or step.","Continue alternating between your right and left foot for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves"],"target":"quads","image":"images/2812-QjE2DcA.jpg","gif_url":"videos/2812-QjE2DcA.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0432","name":"dumbbell stiff leg deadlift","category":"upper legs","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Keeping your back straight and your core engaged, hinge at the hips and lower the dumbbells towards the ground, allowing a slight bend in your knees.","Lower the dumbbells until you feel a stretch in your hamstrings, then squeeze your glutes and push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"target":"glutes","image":"images/0432-5eLRITT.jpg","gif_url":"videos/0432-5eLRITT.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0433","name":"dumbbell straight arm pullover","category":"chest","equipment":"dumbbell","instruction_steps":{"en":["Lie flat on a bench with your head at one end and your feet planted firmly on the ground.","Hold a dumbbell with both hands and extend your arms straight above your chest.","Keeping your arms straight, slowly lower the dumbbell behind your head in an arc-like motion.","Pause for a moment, then raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"latissimus dorsi","secondary_muscles":["latissimus dorsi","triceps"],"target":"pectorals","image":"images/0433-i8BdLTK.jpg","gif_url":"videos/0433-i8BdLTK.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0434","name":"dumbbell straight leg deadlift","category":"upper legs","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Keeping your back straight and your core engaged, hinge at the hips and lower the dumbbells towards the ground, allowing your torso to lean forward.","Continue lowering the dumbbells until you feel a stretch in your hamstrings, keeping your knees slightly bent.","Pause for a moment at the bottom, then engage your glutes and hamstrings to lift your torso back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"target":"glutes","image":"images/0434-oom75KC.jpg","gif_url":"videos/0434-oom75KC.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2808","name":"dumbbell sumo pull through","category":"upper legs","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet wider than shoulder-width apart, toes pointed outwards.","Hold a dumbbell with both hands in front of your body, arms extended.","Bend your knees and lower your hips down into a squat position, keeping your back straight.","Lower the dumbbell down between your legs, keeping your arms straight.","Drive through your heels and extend your hips forward, pulling the dumbbell up and in front of your body.","Squeeze your glutes at the top of the movement, then lower the dumbbell back down between your legs.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps","core"],"target":"glutes","image":"images/2808-BmrwWzo.jpg","gif_url":"videos/2808-BmrwWzo.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2803","name":"dumbbell supported squat","category":"upper legs","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.","Keeping your chest up and core engaged, slowly lower your body down by bending your knees and pushing your hips back.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves"],"target":"quads","image":"images/2803-r5DgrW9.jpg","gif_url":"videos/2803-r5DgrW9.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0436","name":"dumbbell tate press","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on a flat bench with a dumbbell in each hand, palms facing each other.","Raise the dumbbells to shoulder height, then rotate your wrists so that your palms are facing away from you.","Press the dumbbells up until your arms are fully extended, then lower them back down to shoulder height.","Rotate your wrists back to the starting position and repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0436-s5PdDyY.jpg","gif_url":"videos/0436-s5PdDyY.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1742","name":"dumbbell tricep kickback with stork stance","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold a dumbbell in your right hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Bring your right elbow up to your side, keeping it bent at a 90-degree angle.","Extend your right arm straight back, squeezing your triceps.","Pause for a moment, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/1742-wOLmCXc.jpg","gif_url":"videos/1742-wOLmCXc.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1743","name":"dumbbell twisting bench press","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Hold a dumbbell in each hand with an overhand grip, palms facing away from you.","Extend your arms straight up over your chest, keeping a slight bend in your elbows.","Lower the dumbbells down towards your chest, keeping your elbows close to your body.","As you lower the dumbbells, twist your wrists so that your palms face towards you at the bottom of the movement.","Pause for a moment at the bottom, then reverse the movement by pressing the dumbbells back up to the starting position.","As you press the dumbbells up, twist your wrists back to the starting position with palms facing away from you.","Repeat for the desired number of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/1743-z6TAHoT.jpg","gif_url":"videos/1743-z6TAHoT.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0437","name":"dumbbell upright row","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Let the dumbbells hang in front of your thighs, with your arms fully extended.","Keeping your back straight and your core engaged, exhale and lift the dumbbells straight up towards your chin, leading with your elbows.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"traps","secondary_muscles":["traps","biceps"],"target":"delts","image":"images/0437-ainizkb.jpg","gif_url":"videos/0437-ainizkb.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1765","name":"dumbbell upright row (back pov)","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Let the dumbbells hang in front of your thighs, with your arms fully extended and your palms facing your body.","Keeping your back straight and your core engaged, exhale and lift the dumbbells straight up towards your chin, leading with your elbows.","Continue lifting until the dumbbells are at shoulder height, with your elbows pointing out to the sides.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"traps","secondary_muscles":["traps","biceps"],"target":"delts","image":"images/1765-Iptlv6x.jpg","gif_url":"videos/1765-Iptlv6x.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0864","name":"dumbbell upright shoulder external rotation","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand with your palms facing your body.","Raise your arms out to the sides until they are parallel to the ground, keeping your elbows slightly bent.","Rotate your arms externally, bringing the dumbbells up towards your head while keeping your elbows in the same position.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"rotator cuff","secondary_muscles":["rotator cuff","trapezius"],"target":"delts","image":"images/0864-x306lCW.jpg","gif_url":"videos/0864-x306lCW.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"5201","name":"dumbbell waiter biceps curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Stand up straight with a dumbbell in each hand, palms facing forward.","Keep your upper arms close to your body and your elbows tucked in.","Slowly curl the dumbbells up towards your shoulders, keeping your wrists straight.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms","shoulders"],"target":"biceps","image":"images/5201-KOpzGBL.jpg","gif_url":"videos/5201-KOpzGBL.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0438","name":"dumbbell w-press","category":"shoulders","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench with a dumbbell in each hand, palms facing forward.","Raise the dumbbells to shoulder height, elbows bent and palms facing forward.","Press the dumbbells upward until your arms are fully extended overhead.","Lower the dumbbells back to shoulder height.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","chest"],"target":"delts","image":"images/0438-vmwLyCg.jpg","gif_url":"videos/0438-vmwLyCg.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0439","name":"dumbbell zottman curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Stand up straight with a dumbbell in each hand, palms facing your body.","Keep your elbows close to your torso and rotate your palms to face forward.","Curl the dumbbells up to your shoulders while keeping your upper arms stationary.","At the top of the movement, rotate your wrists so that your palms are facing away from your body.","Slowly lower the dumbbells back to the starting position, rotating your palms back to facing your body.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0439-kXaIn5A.jpg","gif_url":"videos/0439-kXaIn5A.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2294","name":"dumbbell zottman preacher curl","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on a preacher bench with a dumbbell in each hand, palms facing up and elbows resting on the pad.","Curl the dumbbells up towards your shoulders, keeping your upper arms stationary and your palms facing up.","At the top of the curl, rotate your wrists so that your palms are facing down.","Slowly lower the dumbbells back down to the starting position, rotating your wrists back to the starting position as you do so.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/2294-y5U5B9Y.jpg","gif_url":"videos/2294-y5U5B9Y.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2189","name":"dumbbells seated triceps extension","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell in both hands with an overhand grip, and raise it above your head.","Bend your elbows and lower the dumbbell behind your head, keeping your upper arms close to your ears.","Extend your arms and raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/2189-FQXdXzY.jpg","gif_url":"videos/2189-FQXdXzY.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1167","name":"dynamic chest stretch (male)","category":"chest","equipment":"body weight","instruction_steps":{"en":["Stand tall with your feet shoulder-width apart.","Extend your arms straight out to the sides, parallel to the ground.","Slowly bring your arms forward, crossing them in front of your body.","Feel the stretch in your chest muscles.","Hold the stretch for 10-30 seconds.","Return to the starting position and repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/1167-3uj0Ozg.jpg","gif_url":"videos/1167-3uj0Ozg.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3287","name":"elbow dips","category":"upper arms","equipment":"body weight","instruction_steps":{"en":["Sit on the edge of a bench or chair with your hands gripping the edge next to your hips.","Slide your hips forward off the bench and straighten your legs, keeping your heels on the ground.","Bend your elbows and lower your body towards the ground, keeping your back close to the bench.","Pause for a moment at the bottom, then push through your hands to straighten your arms and lift your body back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/3287-LkoAWAE.jpg","gif_url":"videos/3287-LkoAWAE.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1772","name":"elbow lift - reverse push-up","category":"back","equipment":"body weight","instruction_steps":{"en":["Start by lying face down on the ground with your legs extended and your hands placed directly under your shoulders.","Engage your core and press through your palms to lift your upper body off the ground, keeping your elbows close to your sides.","Pause at the top for a moment, squeezing your upper back muscles.","Slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"upper back","image":"images/1772-wbUYILZ.jpg","gif_url":"videos/1772-wbUYILZ.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0443","name":"elbow-to-knee","category":"waist","equipment":"body weight","instruction_steps":{"en":["Start by lying flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engage your abs and lift your upper body off the ground, bringing your right elbow towards your left knee.","At the same time, bring your left knee towards your right elbow, creating a twisting motion.","Pause for a moment at the top, then slowly lower your upper body and extend your legs back to the starting position.","Repeat the movement, this time bringing your left elbow towards your right knee and your right knee towards your left elbow.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/0443-jvp6DiD.jpg","gif_url":"videos/0443-jvp6DiD.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3292","name":"elevator","category":"back","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart and your knees slightly bent.","Place your hands on your hips or cross them in front of your chest.","Keeping your back straight, slowly bend forward at the waist, lowering your upper body towards the ground.","Pause for a moment at the bottom, then slowly raise your upper body back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","trapezius"],"target":"upper back","image":"images/3292-zYmNaoY.jpg","gif_url":"videos/3292-zYmNaoY.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1332","name":"exercise ball alternating arm ups","category":"back","equipment":"stability ball","instruction_steps":{"en":["Sit on the stability ball with your feet flat on the ground and your back straight.","Hold a dumbbell in each hand with your palms facing inwards and your arms extended down by your sides.","Engage your core and slowly lift one arm up towards your shoulder, keeping your elbow slightly bent.","Pause for a moment at the top, then slowly lower your arm back down to the starting position.","Repeat the movement with the other arm.","Continue alternating arms for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","core"],"target":"lats","image":"images/1332-EyLrNC2.jpg","gif_url":"videos/1332-EyLrNC2.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1333","name":"exercise ball back extension with arms extended","category":"back","equipment":"stability ball","instruction_steps":{"en":["Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall for stability.","Extend your arms straight out in front of you, with your palms facing down.","Engage your core and slowly lift your upper body off the ball, keeping your back straight and your neck in line with your spine.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","hamstrings"],"target":"spine","image":"images/1333-PERjVm8.jpg","gif_url":"videos/1333-PERjVm8.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1334","name":"exercise ball back extension with hands behind head","category":"back","equipment":"stability ball","instruction_steps":{"en":["Place the stability ball on the ground and lie face down on top of it with your hips resting on the ball.","Position your feet against a wall or other stable surface for support.","Cross your arms behind your head, with your hands touching the back of your head.","Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your hips.","Pause for a moment at the top of the movement, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","hamstrings"],"target":"spine","image":"images/1334-o1HGDSq.jpg","gif_url":"videos/1334-o1HGDSq.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1335","name":"exercise ball back extension with knees off ground","category":"back","equipment":"stability ball","instruction_steps":{"en":["Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall for stability.","Position your hands behind your head or crossed over your chest.","Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your heels.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","hamstrings"],"target":"spine","image":"images/1335-WME869U.jpg","gif_url":"videos/1335-WME869U.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1336","name":"exercise ball back extension with rotation","category":"back","equipment":"stability ball","instruction_steps":{"en":["Start by lying face down on the stability ball with your hips resting on the ball and your feet firmly planted on the ground.","Place your hands behind your head or cross them over your chest.","Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your heels.","Pause for a moment at the top, then slowly rotate your torso to one side, keeping your hips and legs stable.","Return to the center and repeat the rotation to the other side.","Lower your upper body back down to the starting position and repeat for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","hamstrings"],"target":"spine","image":"images/1336-WVD66ff.jpg","gif_url":"videos/1336-WVD66ff.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1744","name":"exercise ball dip","category":"upper arms","equipment":"stability ball","instruction_steps":{"en":["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Place your hands on the ball beside your hips, fingers pointing forward.","Engage your triceps and push through your hands to lift your body off the ball, straightening your arms.","Lower your body back down by bending your elbows, keeping them close to your sides.","Repeat for the desired number of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/1744-kprile3.jpg","gif_url":"videos/1744-kprile3.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1559","name":"exercise ball hip flexor stretch","category":"upper legs","equipment":"stability ball","instruction_steps":{"en":["Place the stability ball on the ground and kneel in front of it.","Place your right foot on top of the stability ball, with your knee bent at a 90-degree angle.","Extend your left leg behind you, keeping it straight.","Lean forward, pushing your hips towards the stability ball, until you feel a stretch in your right hip flexor.","Hold the stretch for 20-30 seconds, then switch sides and repeat."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings"],"target":"glutes","image":"images/1559-2LQkNPW.jpg","gif_url":"videos/1559-2LQkNPW.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1338","name":"exercise ball hug","category":"back","equipment":"stability ball","instruction_steps":{"en":["Sit on the stability ball with your feet flat on the ground and your back straight.","Hold the stability ball with both hands, hugging it close to your chest.","Engage your core muscles and slowly lean back, keeping your back straight and your feet planted on the ground.","Continue leaning back until you feel a stretch in your back muscles.","Hold the position for a few seconds, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","chest"],"target":"spine","image":"images/1338-d7z1Y7V.jpg","gif_url":"videos/1338-d7z1Y7V.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1339","name":"exercise ball lat stretch","category":"back","equipment":"stability ball","instruction_steps":{"en":["Sit on a stability ball with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand and extend your arm straight up overhead.","Slowly lean to the opposite side, feeling a stretch in your lat muscle.","Hold the stretch for 20-30 seconds, then return to the starting position.","Repeat on the other side."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"lats","image":"images/1339-sM84pE4.jpg","gif_url":"videos/1339-sM84pE4.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1341","name":"exercise ball lower back stretch (pyramid)","category":"back","equipment":"stability ball","instruction_steps":{"en":["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Slowly walk your feet forward, rolling the ball down your back until your lower back is resting on the ball.","Place your hands behind your head or cross them over your chest.","Engage your core and slowly lower your upper body towards the ground, allowing your lower back to stretch over the ball.","Hold the stretch for a few seconds, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","hamstrings"],"target":"lats","image":"images/1341-yU7w7CA.jpg","gif_url":"videos/1341-yU7w7CA.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1342","name":"exercise ball lying side lat stretch","category":"back","equipment":"stability ball","instruction_steps":{"en":["Lie on your side with your legs extended and your head supported by the stability ball.","Place your top arm on the ball for stability.","Reach your top arm overhead and allow your torso to rotate slightly.","Feel the stretch in your lat muscles on the side of your body.","Hold the stretch for 20-30 seconds, then switch sides and repeat."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"lats","image":"images/1342-rTbyBYV.jpg","gif_url":"videos/1342-rTbyBYV.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1382","name":"exercise ball on the wall calf raise","category":"lower legs","equipment":"dumbbell","instruction_steps":{"en":["Stand with your back against a wall and place an exercise ball between your lower back and the wall.","Position your feet shoulder-width apart, with your toes pointing forward.","Hold a dumbbell in each hand, with your arms extended by your sides.","Raise your heels off the ground, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps"],"target":"calves","image":"images/1382-xo6sENf.jpg","gif_url":"videos/1382-xo6sENf.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3241","name":"exercise ball on the wall calf raise (tennis ball between ankles)","category":"lower legs","equipment":"dumbbell","instruction_steps":{"en":["Stand facing a wall with your feet shoulder-width apart.","Place an exercise ball between the wall and your lower back.","Hold a dumbbell in each hand, with your arms extended by your sides.","Place a tennis ball between your ankles.","Raise your heels off the ground, lifting your body up onto your toes.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps"],"target":"calves","image":"images/3241-FY3UdNT.jpg","gif_url":"videos/3241-FY3UdNT.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3240","name":"exercise ball on the wall calf raise (tennis ball between knees)","category":"lower legs","equipment":"dumbbell","instruction_steps":{"en":["Stand with your back against a wall and place an exercise ball between your lower back and the wall.","Position your feet shoulder-width apart and slightly in front of you.","Hold a dumbbell in each hand, with your arms extended by your sides.","Place a tennis ball between your knees.","Raise your heels off the ground, lifting your body up onto your toes.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings"],"target":"calves","image":"images/3240-j74M6Zn.jpg","gif_url":"videos/3240-j74M6Zn.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1416","name":"exercise ball one leg prone lower body rotation","category":"upper legs","equipment":"stability ball","instruction_steps":{"en":["Lie face down on the stability ball with your hips resting on the ball and your legs extended straight behind you.","Place your hands on the ground in front of you for support.","Engage your glutes and core muscles to stabilize your body.","Slowly lift one leg off the ground, keeping it straight and parallel to the floor.","Rotate your leg outward, away from your body, while keeping your hips and upper body stable.","Pause for a moment at the end of the rotation, then slowly return your leg to the starting position.","Repeat the rotation with the other leg.","Continue alternating legs for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps","core"],"target":"glutes","image":"images/1416-M72BExt.jpg","gif_url":"videos/1416-M72BExt.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1417","name":"exercise ball one legged diagonal kick hamstring curl","category":"upper legs","equipment":"stability ball","instruction_steps":{"en":["Start by lying on your back with your legs extended and your heels resting on top of the stability ball.","Place your arms by your sides for stability.","Engage your glutes and core muscles to lift your hips off the ground, creating a straight line from your shoulders to your heels.","Bend your right knee and bring it towards your chest, keeping your left leg extended and your foot flexed.","Kick your right leg diagonally across your body, extending it fully and engaging your hamstrings.","Slowly return your right leg to the starting position, maintaining control and stability.","Repeat the movement with your left leg, alternating sides for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","calves"],"target":"glutes","image":"images/1417-GOJKFfO.jpg","gif_url":"videos/1417-GOJKFfO.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1296","name":"exercise ball pike push up","category":"chest","equipment":"stability ball","instruction_steps":{"en":["Start in a push-up position with your hands on the floor and your shins resting on the stability ball.","Engage your core and lift your hips up towards the ceiling, rolling the ball towards your hands.","Keep your legs straight and your body in a pike position, forming an inverted V shape.","Bend your elbows and lower your upper body towards the floor, keeping your head in line with your hands.","Push through your hands and extend your arms to return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps","core"],"target":"pectorals","image":"images/1296-sVvXT5J.jpg","gif_url":"videos/1296-sVvXT5J.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1343","name":"exercise ball prone leg raise","category":"back","equipment":"stability ball","instruction_steps":{"en":["Lie face down on a mat with your legs extended and your toes resting on top of the stability ball.","Place your hands on the ground, shoulder-width apart, and engage your core muscles.","Keeping your legs straight, slowly lift them off the ground, using your lower back and glutes to raise them as high as possible.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"abdominals","secondary_muscles":["abdominals","glutes"],"target":"spine","image":"images/1343-lCKm4Rs.jpg","gif_url":"videos/1343-lCKm4Rs.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1560","name":"exercise ball seated hamstring stretch","category":"upper legs","equipment":"stability ball","instruction_steps":{"en":["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Slowly roll the ball forward, walking your feet out until your upper back is resting on the ball and your legs are extended straight in front of you.","Place your hands on your hips for support.","Engage your core and slowly lower your upper body towards the ground, keeping your back straight and your chest lifted.","Stop when you feel a stretch in your hamstrings, and hold the position for 20-30 seconds.","Slowly return to the starting position by pushing through your heels and using your hamstrings to pull yourself back up.","Repeat for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","lower back"],"target":"hamstrings","image":"images/1560-yRYyfdA.jpg","gif_url":"videos/1560-yRYyfdA.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1745","name":"exercise ball seated triceps stretch","category":"upper arms","equipment":"stability ball","instruction_steps":{"en":["Sit on a stability ball with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand and extend your arm straight up above your head.","Bend your elbow and lower the dumbbell behind your head, keeping your upper arm close to your ear.","Hold the stretch for a few seconds, then return to the starting position.","Repeat with the other arm."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/1745-7ePTw4B.jpg","gif_url":"videos/1745-7ePTw4B.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1746","name":"exercise ball supine triceps extension","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Sit on an exercise ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold a dumbbell with both hands and extend your arms straight up towards the ceiling.","Slowly lower the dumbbell behind your head, keeping your elbows close to your ears.","Pause for a moment, then raise the dumbbell back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/1746-Gm2Uv1z.jpg","gif_url":"videos/1746-Gm2Uv1z.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1747","name":"ez bar french press on exercise ball","category":"upper arms","equipment":"ez barbell","instruction_steps":{"en":["Sit on an exercise ball and hold an EZ barbell with an overhand grip.","Extend your arms straight up, keeping your elbows close to your head.","Slowly lower the barbell behind your head by bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/1747-CFN9P8G.jpg","gif_url":"videos/1747-CFN9P8G.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3010","name":"ez bar lying bent arms pullover","category":"back","equipment":"ez barbell","instruction_steps":{"en":["Lie flat on a bench with your head at one end and your feet on the floor.","Hold the EZ barbell with a pronated grip (palms facing away from you) and your hands shoulder-width apart.","Extend your arms straight above your chest, keeping a slight bend in your elbows.","Lower the barbell in an arc motion behind your head, maintaining the slight bend in your elbows.","Pause for a moment, then return the barbell to the starting position by reversing the arc motion.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","chest"],"target":"lats","image":"images/3010-nDK1HJ0.jpg","gif_url":"videos/3010-nDK1HJ0.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1748","name":"ez bar lying close grip triceps extension behind head","category":"upper arms","equipment":"ez barbell","instruction_steps":{"en":["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold the ez barbell with a close grip, palms facing up, and extend your arms straight up over your chest.","Keeping your upper arms stationary, slowly lower the barbell behind your head by bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/1748-6CKUx7o.jpg","gif_url":"videos/1748-6CKUx7o.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1344","name":"ez bar reverse grip bent over row","category":"back","equipment":"ez barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and knees slightly bent.","Hold the ez barbell with an underhand grip, palms facing up, and hands shoulder-width apart.","Bend forward at the hips, keeping your back straight and chest up, until your torso is almost parallel to the floor.","Pull the ez barbell towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the ez barbell back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/1344-G8dXpNG.jpg","gif_url":"videos/1344-G8dXpNG.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1682","name":"ez bar seated close grip concentration curl","category":"upper arms","equipment":"ez barbell","instruction_steps":{"en":["Sit on a bench with your feet flat on the ground and hold an EZ barbell with an underhand grip.","Rest your elbow on the inside of your thigh, just above the knee.","Curl the barbell up towards your shoulder while keeping your upper arm stationary.","Squeeze your biceps at the top of the movement, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1682-Dsfz0Id.jpg","gif_url":"videos/1682-Dsfz0Id.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1749","name":"ez bar standing french press","category":"upper arms","equipment":"ez barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold the ez barbell with an overhand grip.","Raise the barbell above your head, fully extending your arms.","Keeping your upper arms close to your head, slowly lower the barbell behind your head by bending your elbows.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/1749-1cTf2Ux.jpg","gif_url":"videos/1749-1cTf2Ux.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0445","name":"ez barbell anti gravity press","category":"shoulders","equipment":"ez barbell","instruction_steps":{"en":["Start by standing with your feet shoulder-width apart and holding the ez barbell with an overhand grip.","Raise the barbell to shoulder height, keeping your elbows slightly bent and your palms facing forward.","Press the barbell overhead, extending your arms fully.","Lower the barbell back to shoulder height and repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","chest"],"target":"delts","image":"images/0445-fprd84i.jpg","gif_url":"videos/0445-fprd84i.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1627","name":"ez barbell close grip preacher curl","category":"upper arms","equipment":"ez barbell","instruction_steps":{"en":["Sit on a preacher curl bench and place your upper arms on the pad, gripping the ez barbell with an underhand grip.","Rest your triceps on the pad and fully extend your arms, keeping your back straight.","Slowly curl the barbell towards your shoulders, contracting your biceps.","Pause for a moment at the top, squeezing your biceps.","Lower the barbell back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1627-hacCyUv.jpg","gif_url":"videos/1627-hacCyUv.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0446","name":"ez barbell close-grip curl","category":"upper arms","equipment":"ez barbell","instruction_steps":{"en":["Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, hands shoulder-width apart.","Keep your elbows close to your torso and your upper arms stationary throughout the movement.","Curl the barbell up towards your shoulders, contracting your biceps.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0446-V4ryaZa.jpg","gif_url":"videos/0446-V4ryaZa.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0447","name":"ez barbell curl","category":"upper arms","equipment":"ez barbell","instruction_steps":{"en":["Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up.","Keep your elbows close to your torso and your upper arms stationary throughout the movement.","Exhale as you curl the barbell up towards your shoulders, contracting your biceps.","Pause for a moment at the top, then inhale as you slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0447-6TG6x2w.jpg","gif_url":"videos/0447-6TG6x2w.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0448","name":"ez barbell decline close grip face press","category":"upper arms","equipment":"ez barbell","instruction_steps":{"en":["Lie on a decline bench with your head lower than your feet.","Grasp the ez barbell with a close grip, palms facing each other.","Extend your arms straight up above your chest, keeping your elbows close to your body.","Lower the barbell towards your forehead by bending your elbows.","Pause for a moment, then press the barbell back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0448-DgZQ11d.jpg","gif_url":"videos/0448-DgZQ11d.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2186","name":"ez barbell decline triceps extension","category":"upper arms","equipment":"ez barbell","instruction_steps":{"en":["Lie on a decline bench with your head lower than your feet and your feet secured.","Hold the ez barbell with an overhand grip, hands shoulder-width apart.","Extend your arms fully, keeping your elbows close to your head.","Lower the barbell slowly towards your forehead, bending your elbows.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/2186-CQHoDm0.jpg","gif_url":"videos/2186-CQHoDm0.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0449","name":"ez barbell incline triceps extension","category":"upper arms","equipment":"ez barbell","instruction_steps":{"en":["Set up an incline bench at a 45-degree angle.","Sit on the bench with your back against the pad and hold the ez barbell with an overhand grip.","Extend your arms fully overhead, keeping your elbows close to your head.","Lower the barbell behind your head by bending your elbows, keeping your upper arms stationary.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0449-KyLtiLT.jpg","gif_url":"videos/0449-KyLtiLT.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0450","name":"ez barbell jm bench press","category":"upper arms","equipment":"ez barbell","instruction_steps":{"en":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the ez barbell with an overhand grip, slightly wider than shoulder-width apart.","Lower the barbell to your chest, keeping your elbows tucked in close to your body.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0450-hnOYgH3.jpg","gif_url":"videos/0450-hnOYgH3.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0451","name":"ez barbell reverse grip curl","category":"upper arms","equipment":"ez barbell","instruction_steps":{"en":["Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip.","Keep your elbows close to your torso and your upper arms stationary throughout the exercise.","Curl the barbell upwards by contracting your biceps, while exhaling.","Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Slowly begin to bring the barbell back to the starting position as you inhale.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0451-Y5X65IB.jpg","gif_url":"videos/0451-Y5X65IB.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0452","name":"ez barbell reverse grip preacher curl","category":"upper arms","equipment":"ez barbell","instruction_steps":{"en":["Sit on a preacher bench with your chest against the pad and your feet flat on the floor.","Grasp the ez barbell with an underhand grip, hands shoulder-width apart.","Rest your upper arms on the pad, allowing your forearms to hang down.","Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders.","Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0452-vBNyir7.jpg","gif_url":"videos/0452-vBNyir7.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1458","name":"ez barbell seated curls","category":"upper arms","equipment":"ez barbell","instruction_steps":{"en":["Sit on a bench with your feet flat on the ground and your back straight.","Hold the ez barbell with an underhand grip, palms facing up, and your hands shoulder-width apart.","Rest your upper arms on your thighs, allowing the ez barbell to hang down in front of you.","Keeping your upper arms stationary, exhale and curl the ez barbell upwards towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the ez barbell back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1458-jtFKbt5.jpg","gif_url":"videos/1458-jtFKbt5.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0453","name":"ez barbell seated triceps extension","category":"upper arms","equipment":"ez barbell","instruction_steps":{"en":["Sit on a bench with your back straight and feet flat on the ground.","Hold the ez barbell with an overhand grip, hands shoulder-width apart.","Raise the barbell overhead, fully extending your arms.","Keeping your upper arms stationary, lower the barbell behind your head by bending your elbows.","Pause for a moment, then raise the barbell back to the starting position by extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0453-iaapw0g.jpg","gif_url":"videos/0453-iaapw0g.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0454","name":"ez barbell spider curl","category":"upper arms","equipment":"ez barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up.","Rest your upper arms on a preacher bench or stability ball, allowing your elbows to hang down.","Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0454-Ye5Qxb0.jpg","gif_url":"videos/0454-Ye5Qxb0.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1628","name":"ez barbell spider curl","category":"upper arms","equipment":"ez barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up.","Rest your upper arms on a preacher bench or stability ball, allowing your elbows to hang down.","Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1628-2kattbR.jpg","gif_url":"videos/1628-2kattbR.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2404","name":"ez-bar biceps curl (with arm blaster)","category":"upper arms","equipment":"ez barbell","instruction_steps":{"en":["Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up.","Place your upper arms against the arm blaster, keeping them stationary throughout the exercise.","Keeping your elbows close to your body, exhale and curl the barbell up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the barbell back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/2404-tJ5nYqo.jpg","gif_url":"videos/2404-tJ5nYqo.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2432","name":"ez-bar close-grip bench press","category":"upper arms","equipment":"ez barbell","instruction_steps":{"en":["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Grasp the ez barbell with a close grip, hands shoulder-width apart, palms facing forward.","Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Slowly lower the barbell towards your chest, keeping your elbows close to your body.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/2432-da4cXST.jpg","gif_url":"videos/2432-da4cXST.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2741","name":"ez-barbell standing wide grip biceps curl","category":"upper arms","equipment":"ez barbell","instruction_steps":{"en":["Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, hands wider than shoulder-width apart.","Keep your elbows close to your torso and your upper arms stationary throughout the movement.","Curl the barbell up towards your shoulders by contracting your biceps.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/2741-OVTZ65k.jpg","gif_url":"videos/2741-OVTZ65k.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2133","name":"farmers walk","category":"upper legs","equipment":"dumbbell","instruction_steps":{"en":["Stand up straight with a dumbbell in each hand, palms facing your sides.","Keep your back straight and your shoulders back.","Take small, controlled steps forward, maintaining an upright posture.","Continue walking for the desired distance or time.","To finish, stop walking and carefully lower the dumbbells to your sides."]},"muscle_group":"calves","secondary_muscles":["calves","forearms","core"],"target":"quads","image":"images/2133-qPEzJjA.jpg","gif_url":"videos/2133-qPEzJjA.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0455","name":"finger curls","category":"lower arms","equipment":"barbell","instruction_steps":{"en":["Sit on a bench with your feet flat on the ground and hold a barbell with an underhand grip, palms facing up.","Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Slowly curl your fingers towards your palms, squeezing the barbell tightly.","Hold the contraction for a moment, then slowly release your fingers back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"wrist flexors","secondary_muscles":["wrist flexors","grip muscles"],"target":"forearms","image":"images/0455-awG04cF.jpg","gif_url":"videos/0455-awG04cF.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3303","name":"flag","category":"waist","equipment":"body weight","instruction_steps":{"en":["Start by gripping a vertical pole with both hands, palms facing each other, and arms fully extended.","Engage your core and lift your legs off the ground, keeping them straight.","Using your core and upper body strength, raise your legs until they are parallel to the ground.","Hold this position for as long as you can, maintaining a straight body line.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques","shoulders"],"target":"abs","image":"images/3303-pQ0Mx1Z.jpg","gif_url":"videos/3303-pQ0Mx1Z.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0456","name":"flexion leg sit up (bent knee)","category":"waist","equipment":"body weight","instruction_steps":{"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","At the same time, lift your legs off the ground, bending your knees and bringing them towards your chest.","Pause for a moment at the top, then slowly lower your upper body and legs back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0456-AR0ig3o.jpg","gif_url":"videos/0456-AR0ig3o.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0457","name":"flexion leg sit up (straight arm)","category":"waist","equipment":"body weight","instruction_steps":{"en":["Lie flat on your back with your legs extended and arms straight above your head.","Engaging your abs, lift your upper body off the ground while simultaneously lifting your legs towards your chest.","Reach your hands towards your toes as you lift your upper body and legs.","Pause for a moment at the top, then slowly lower your upper body and legs back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors","quadriceps"],"target":"abs","image":"images/0457-KZn52RC.jpg","gif_url":"videos/0457-KZn52RC.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0458","name":"floor fly (with barbell)","category":"chest","equipment":"barbell","instruction_steps":{"en":["Lie flat on your back on the floor with your knees bent and feet flat on the ground.","Hold a barbell with an overhand grip, arms extended straight up over your chest.","Slowly lower the barbell out to the sides, keeping a slight bend in your elbows.","Lower the barbell until your arms are parallel to the floor, feeling a stretch in your chest.","Pause for a moment, then squeeze your chest muscles to bring the barbell back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"deltoids","secondary_muscles":["deltoids","triceps"],"target":"pectorals","image":"images/0458-neonEDL.jpg","gif_url":"videos/0458-neonEDL.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0459","name":"flutter kicks","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Lie flat on your back with your legs extended and your hands by your sides.","Engage your core and lift your legs off the ground about 6 inches.","Keeping your legs straight, alternate lifting one leg slightly higher than the other.","Continue this fluttering motion for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors","lower abs"],"target":"glutes","image":"images/0459-UVo2Qs2.jpg","gif_url":"videos/0459-UVo2Qs2.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1472","name":"forward jump","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart.","Bend your knees and lower your body into a squat position.","Swing your arms back for momentum.","Jump forward explosively, extending your hips, knees, and ankles.","Land softly on the balls of your feet and immediately go into the next jump.","Repeat for the desired number of repetitions."]},"muscle_group":"calves","secondary_muscles":["calves","hamstrings","glutes"],"target":"quads","image":"images/1472-uZKq7lo.jpg","gif_url":"videos/1472-uZKq7lo.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3470","name":"forward lunge (male)","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Stand with your feet hip-width apart and hands on your hips.","Take a big step forward with your right foot, lowering your body into a lunge position.","Bend your right knee to about 90 degrees, keeping your knee aligned with your ankle.","Push off with your right foot and return to the starting position.","Repeat with your left leg, alternating sides for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/3470-kMzUs9Y.jpg","gif_url":"videos/3470-kMzUs9Y.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3194","name":"frankenstein squat","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold the barbell in front of your body with straight arms.","Keeping your back straight, lower your body by bending at the knees and hips, as if sitting back into a chair.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/3194-bdWcbaU.jpg","gif_url":"videos/3194-bdWcbaU.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2429","name":"frog crunch","category":"waist","equipment":"body weight","instruction_steps":{"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/2429-FFRP97T.jpg","gif_url":"videos/2429-FFRP97T.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3301","name":"frog planche","category":"waist","equipment":"body weight","instruction_steps":{"en":["Start in a push-up position with your hands shoulder-width apart and your feet together.","Bend your elbows and lower your body towards the ground, keeping your back straight.","As you lower your body, lift your feet off the ground and bring your knees towards your chest.","Hold this position for a few seconds, then extend your legs back out and push yourself back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","chest","triceps"],"target":"abs","image":"images/3301-rQhGcin.jpg","gif_url":"videos/3301-rQhGcin.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3296","name":"front lever","category":"waist","equipment":"body weight","instruction_steps":{"en":["Start by hanging from a pull-up bar with an overhand grip, hands shoulder-width apart.","Engage your core and pull your shoulder blades down and back.","Bend your knees and tuck them towards your chest.","Simultaneously, lift your legs up and extend them straight out in front of you, keeping your body parallel to the ground.","Hold this position for as long as you can, aiming for a full front lever position.","To release, slowly lower your legs back down and return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"lats","secondary_muscles":["lats","shoulders","forearms"],"target":"abs","image":"images/3296-PkCN2lv.jpg","gif_url":"videos/3296-PkCN2lv.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3295","name":"front lever reps","category":"back","equipment":"body weight","instruction_steps":{"en":["Hang from a pull-up bar with an overhand grip, palms facing away from you.","Engage your core and pull your shoulder blades down and back.","Keeping your body straight, lift your legs up until they are parallel to the ground.","Hold this position for as long as you can, aiming for 10-20 seconds.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"core","secondary_muscles":["core","shoulders"],"target":"upper back","image":"images/3295-hbY9wqG.jpg","gif_url":"videos/3295-hbY9wqG.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0464","name":"front plank with twist","category":"waist","equipment":"body weight","instruction_steps":{"en":["Start in a high plank position with your hands directly under your shoulders and your body in a straight line from head to toe.","Engage your core and glutes to maintain a stable position.","Rotate your torso to the right, lifting your right arm and extending it towards the ceiling.","Keep your hips and legs stable as you twist.","Hold for a moment, then return to the starting position.","Repeat the twist on the left side.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques","shoulders"],"target":"abs","image":"images/0464-CosupLu.jpg","gif_url":"videos/0464-CosupLu.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3315","name":"full maltese","category":"waist","equipment":"body weight","instruction_steps":{"en":["Start by standing with your feet shoulder-width apart and your arms extended straight out to the sides.","Slowly lean forward, keeping your arms straight, until your upper body is parallel to the ground.","Engage your core and hold this position for a few seconds.","Return to the starting position by pushing through your feet and standing back up.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","chest"],"target":"abs","image":"images/3315-YRaCa5Y.jpg","gif_url":"videos/3315-YRaCa5Y.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3299","name":"full planche","category":"waist","equipment":"body weight","instruction_steps":{"en":["Start in a push-up position with your hands shoulder-width apart and your fingers pointing forward.","Engage your core and slowly shift your weight forward, lifting your feet off the ground.","Continue shifting your weight forward until your body is parallel to the ground, balancing on your hands.","Hold this position for as long as you can, maintaining a straight body line.","Slowly lower your feet back to the ground and return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","chest","triceps"],"target":"abs","image":"images/3299-YZ4961r.jpg","gif_url":"videos/3299-YZ4961r.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3327","name":"full planche push-up","category":"chest","equipment":"body weight","instruction_steps":{"en":["Start in a push-up position with your hands placed slightly wider than shoulder-width apart.","Engage your core and lower your body down towards the ground, keeping your elbows close to your sides.","As you lower yourself, lean your body forward and lift your feet off the ground, balancing on your hands.","Continue to lower your body until your chest is just above the ground.","Push through your hands and extend your arms to lift your body back up to the starting position.","Maintain a straight line from your head to your heels throughout the movement.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps","core"],"target":"pectorals","image":"images/3327-gw9PqGk.jpg","gif_url":"videos/3327-gw9PqGk.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0466","name":"gironda sternum chin","category":"back","equipment":"body weight","instruction_steps":{"en":["Stand facing a high bar with your feet shoulder-width apart.","Reach up and grab the bar with an overhand grip, slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your body straight.","Engage your lats and biceps to pull your chest up towards the bar, leading with your sternum.","Pause for a moment at the top, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","rhomboids","rear deltoids"],"target":"lats","image":"images/0466-IL0JUxR.jpg","gif_url":"videos/0466-IL0JUxR.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3561","name":"glute bridge march","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Engage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders.","While keeping your hips lifted, lift one foot off the ground and bring your knee towards your chest.","Lower your foot back to the ground and repeat the movement with the other leg.","Continue alternating legs in a marching motion while maintaining the bridge position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps"],"target":"glutes","image":"images/3561-GibBPPg.jpg","gif_url":"videos/3561-GibBPPg.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3523","name":"glute bridge two legs on bench (male)","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Sit on the edge of a bench with your back against it and your feet flat on the ground.","Place your hands on the bench beside your hips for support.","Engage your glutes and hamstrings, then lift your hips off the bench until your body forms a straight line from your knees to your shoulders.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","core"],"target":"glutes","image":"images/3523-aWedzZX.jpg","gif_url":"videos/3523-aWedzZX.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3193","name":"glute-ham raise","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Adjust the glute-ham raise machine to fit your body.","Position yourself face down on the machine with your ankles secured.","Place your hands on your chest or cross them over your chest.","Engage your hamstrings and glutes to lift your upper body up towards the ceiling.","Continue lifting until your body is in a straight line from your head to your heels.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","lower back"],"target":"hamstrings","image":"images/3193-Vvwjz6N.jpg","gif_url":"videos/3193-Vvwjz6N.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0467","name":"gorilla chin","category":"waist","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp a pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your palms facing away from you.","Engage your core and pull your body up towards the bar, bringing your chin above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms","biceps"],"target":"abs","image":"images/0467-bmwlYvD.jpg","gif_url":"videos/0467-bmwlYvD.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0469","name":"groin crunch","category":"waist","equipment":"body weight","instruction_steps":{"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, lift your legs off the ground, bringing your knees towards your chest.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors","inner thighs"],"target":"abs","image":"images/0469-mWppALS.jpg","gif_url":"videos/0469-mWppALS.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1383","name":"hack calf raise","category":"lower legs","equipment":"sled machine","instruction_steps":{"en":["Adjust the sled machine to a comfortable weight.","Stand on the sled machine with your toes on the platform and your heels hanging off.","Hold onto the handles for stability.","Raise your heels as high as possible by pushing through the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"calves","image":"images/1383-2ORFMoR.jpg","gif_url":"videos/1383-2ORFMoR.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1384","name":"hack one leg calf raise","category":"lower legs","equipment":"sled machine","instruction_steps":{"en":["Adjust the sled machine to an appropriate weight.","Stand on the sled machine with one foot, keeping the other foot off the ground.","Hold onto the handles for stability.","Raise your heel as high as possible, lifting your body up on the ball of your foot.","Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Repeat for the desired number of repetitions.","Switch legs and repeat the exercise."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"calves","image":"images/1384-AxFoqAD.jpg","gif_url":"videos/1384-AxFoqAD.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3221","name":"half knee bends (male)","category":"cardio","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart.","Bend your knees and lower your body down as if you were sitting back into a chair.","Keep your chest up and your weight in your heels.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","glutes"],"target":"cardiovascular system","image":"images/3221-ia6kIIl.jpg","gif_url":"videos/3221-ia6kIIl.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3202","name":"half sit-up (male)","category":"waist","equipment":"body weight","instruction_steps":{"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/3202-iQ241UP.jpg","gif_url":"videos/3202-iQ241UP.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1511","name":"hamstring stretch","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart.","Step forward with your right foot and shift your weight onto your right leg.","Keeping your back straight, slowly bend forward at the hips, reaching towards your right foot with both hands.","Hold the stretch for 20-30 seconds, then return to the starting position.","Repeat on the other side."]},"muscle_group":"glutes","secondary_muscles":["glutes"],"target":"hamstrings","image":"images/1511-99rWm7w.jpg","gif_url":"videos/1511-99rWm7w.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2139","name":"hands bike","category":"chest","equipment":"upper body ergometer","instruction_steps":{"en":["Adjust the seat height and handlebar position to a comfortable level.","Sit on the ergometer with your back straight and feet on the pedals.","Grasp the handles with your hands and position your arms at a 90-degree angle.","Start pedaling with your hands, pushing and pulling the handles in a controlled motion.","Continue pedaling for the desired duration or number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/2139-pAIWRGu.jpg","gif_url":"videos/2139-pAIWRGu.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3218","name":"hands clasped circular toe touch (male)","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart and your hands clasped together in front of your chest.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Lower your hands towards your toes in a circular motion, reaching as far as you can without straining.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps","calves"],"target":"glutes","image":"images/3218-B5xca8s.jpg","gif_url":"videos/3218-B5xca8s.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3215","name":"hands reversed clasped circular toe touch (male)","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart and your arms extended to the sides.","Bend forward at the waist, keeping your back straight and your knees slightly bent.","Reach down with your hands and clasp them together behind your legs.","Slowly raise your hands up and over your head in a circular motion, keeping your legs straight.","Continue the circular motion until your hands touch your toes.","Reverse the motion and bring your hands back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps","calves"],"target":"glutes","image":"images/3215-yq3GAJX.jpg","gif_url":"videos/3215-yq3GAJX.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3302","name":"handstand","category":"upper arms","equipment":"body weight","instruction_steps":{"en":["Find an open space with enough room to perform a handstand.","Place your hands on the ground shoulder-width apart, fingers pointing forward.","Kick your legs up towards the wall, using your core and shoulders to maintain balance.","Once in a handstand position, engage your triceps to support your body weight.","Hold the handstand for as long as you can maintain balance.","To come down, slowly lower your legs back to the ground.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","core"],"target":"triceps","image":"images/3302-XooAdhl.jpg","gif_url":"videos/3302-XooAdhl.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0471","name":"handstand push-up","category":"upper arms","equipment":"body weight","instruction_steps":{"en":["Find a wall and face away from it, standing a few feet away.","Place your hands on the ground shoulder-width apart and kick your feet up against the wall, coming into a handstand position.","Bend your elbows and lower your head towards the ground, keeping your body in a straight line.","Push through your hands and extend your arms to return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","chest","core"],"target":"triceps","image":"images/0471-rQxwMxO.jpg","gif_url":"videos/0471-rQxwMxO.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1764","name":"hanging leg hip raise","category":"waist","equipment":"body weight","instruction_steps":{"en":["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your legs up by flexing your hips and knees until your thighs are parallel to the ground.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors","lower back"],"target":"abs","image":"images/1764-VEcJRo2.jpg","gif_url":"videos/1764-VEcJRo2.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0472","name":"hanging leg raise","category":"waist","equipment":"body weight","instruction_steps":{"en":["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your legs up in front of you, keeping them straight.","Continue lifting until your legs are parallel to the ground or as high as you can comfortably go.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0472-I3tsCnC.jpg","gif_url":"videos/0472-I3tsCnC.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1761","name":"hanging oblique knee raise","category":"waist","equipment":"body weight","instruction_steps":{"en":["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your knees towards your chest, twisting your torso to the side as you do so.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat on the other side, twisting your torso in the opposite direction.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/1761-BaE7O6U.jpg","gif_url":"videos/1761-BaE7O6U.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0473","name":"hanging pike","category":"waist","equipment":"body weight","instruction_steps":{"en":["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your legs up towards the bar, keeping them straight.","Continue lifting until your body forms a 'V' shape, with your legs parallel to the ground.","Hold the position for a moment, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors","shoulders"],"target":"abs","image":"images/0473-nuBF9MO.jpg","gif_url":"videos/0473-nuBF9MO.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0474","name":"hanging straight leg hip raise","category":"waist","equipment":"body weight","instruction_steps":{"en":["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your legs up in front of you until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0474-pj0X0tF.jpg","gif_url":"videos/0474-pj0X0tF.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0475","name":"hanging straight leg raise","category":"waist","equipment":"body weight","instruction_steps":{"en":["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your legs up in front of you, keeping them straight.","Continue lifting until your legs are parallel to the ground or as high as you can comfortably go.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0475-4Ml7QFO.jpg","gif_url":"videos/0475-4Ml7QFO.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0476","name":"hanging straight twisting leg hip raise","category":"waist","equipment":"body weight","instruction_steps":{"en":["Hang from a pull-up bar with your arms fully extended and your legs straight.","Engage your core and lift your legs up towards your chest, keeping them straight.","Once your legs are parallel to the ground, twist your hips to one side, bringing your legs towards that side.","Pause for a moment, then return to the starting position.","Repeat the movement, but this time twist your hips to the opposite side.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques","hip flexors"],"target":"abs","image":"images/0476-Q6bvyen.jpg","gif_url":"videos/0476-Q6bvyen.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3636","name":"high knee against wall","category":"cardio","equipment":"body weight","instruction_steps":{"en":["Stand facing a wall with your feet hip-width apart.","Place your hands on the wall for support.","Engage your core and lift your right knee up towards your chest, while keeping your left foot on the ground.","Quickly switch legs, bringing your left knee up towards your chest and lowering your right foot back down.","Continue alternating legs in a running motion, bringing your knees up as high as possible.","Maintain a fast pace and keep your upper body stable throughout the exercise.","Repeat for the desired duration or number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","glutes","calves"],"target":"cardiovascular system","image":"images/3636-ealLwvX.jpg","gif_url":"videos/3636-ealLwvX.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0484","name":"hip raise (bent knee)","category":"waist","equipment":"body weight","instruction_steps":{"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands by your sides, palms facing down.","Engage your core and glutes, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","hamstrings"],"target":"abs","image":"images/0484-196HJGw.jpg","gif_url":"videos/0484-196HJGw.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1418","name":"hug keens to chest","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Start by standing with your feet shoulder-width apart.","Bend your knees and lower your body down into a squat position.","As you squat down, bring your knees up towards your chest and hug them with your arms.","Hold this position for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps"],"target":"glutes","image":"images/1418-znP9SIh.jpg","gif_url":"videos/1418-znP9SIh.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3234","name":"hyght dumbbell fly","category":"chest","equipment":"dumbbell","instruction_steps":{"en":["Lie flat on a bench with a dumbbell in each hand, palms facing each other.","Extend your arms straight up over your chest, with a slight bend in your elbows.","Keeping a slight bend in your elbows, lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.","Pause for a moment, then reverse the movement and bring the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"pectorals","image":"images/3234-P9ZRyLT.jpg","gif_url":"videos/3234-P9ZRyLT.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0489","name":"hyperextension","category":"back","equipment":"body weight","instruction_steps":{"en":["Adjust the hyperextension bench so that your upper thighs are resting on the pad and your feet are secured.","Cross your arms over your chest or place your hands behind your head.","Lower your upper body towards the ground while keeping your back straight.","Pause for a moment at the bottom, then raise your upper body back up until it is in line with your legs.","Repeat for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","hamstrings"],"target":"spine","image":"images/0489-zhMwOwE.jpg","gif_url":"videos/0489-zhMwOwE.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0488","name":"hyperextension (on bench)","category":"back","equipment":"body weight","instruction_steps":{"en":["Adjust the hyperextension bench so that your hips are resting comfortably on the pad and your feet are secured.","Cross your arms over your chest or place your hands behind your head.","Slowly lower your upper body towards the ground while keeping your back straight.","Pause for a moment at the bottom, then raise your upper body back up until it is in line with your legs.","Repeat for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","hamstrings"],"target":"spine","image":"images/0488-zkgRrbK.jpg","gif_url":"videos/0488-zkgRrbK.gif","attribution":"© Gym visual ��� https://gymvisual.com/"},{"id":"3289","name":"impossible dips","category":"upper arms","equipment":"body weight","instruction_steps":{"en":["Position yourself between two parallel bars with your arms fully extended and your body suspended in the air.","Bend your knees and cross your ankles.","Lower your body by bending your elbows until your upper arms are parallel to the ground.","Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/3289-05Cf2v8.jpg","gif_url":"videos/3289-05Cf2v8.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1471","name":"inchworm","category":"waist","equipment":"body weight","instruction_steps":{"en":["Start in a standing position with your feet hip-width apart.","Bend forward at the waist and place your hands on the ground in front of you.","Walk your hands forward until you are in a high plank position, with your body in a straight line from head to toe.","Pause for a moment, then walk your hands back towards your feet, keeping your legs as straight as possible.","Once your hands reach your feet, stand back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","hamstrings"],"target":"abs","image":"images/1471-ZgsNQ6d.jpg","gif_url":"videos/1471-ZgsNQ6d.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3698","name":"inchworm v. 2","category":"waist","equipment":"body weight","instruction_steps":{"en":["Start in a standing position with your feet hip-width apart.","Bend forward at the waist and place your hands on the ground in front of you.","Walk your hands forward until you are in a high plank position, with your body in a straight line from head to toe.","Keeping your legs straight, walk your feet towards your hands, bringing your hips up towards the ceiling.","Continue walking your hands forward, repeating the movement for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","hamstrings"],"target":"abs","image":"images/3698-TV87DNB.jpg","gif_url":"videos/3698-TV87DNB.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0490","name":"incline close-grip push-up","category":"upper arms","equipment":"body weight","instruction_steps":{"en":["Place your hands on an elevated surface, such as a bench or step, slightly wider than shoulder-width apart.","Extend your legs behind you, resting on the balls of your feet, with your body forming a straight line from head to heels.","Lower your chest towards the elevated surface by bending your elbows, keeping them close to your sides.","Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0490-1YB40kg.jpg","gif_url":"videos/0490-1YB40kg.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0491","name":"incline leg hip raise (leg straight)","category":"waist","equipment":"body weight","instruction_steps":{"en":["Lie on an incline bench with your back flat against the bench and your legs extended straight out in front of you.","Place your hands on the sides of the bench for support.","Engaging your abs, lift your legs off the bench, raising them as high as you can while keeping them straight.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0491-eVxAzgz.jpg","gif_url":"videos/0491-eVxAzgz.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0492","name":"incline push up depth jump","category":"chest","equipment":"body weight","instruction_steps":{"en":["Find an elevated surface, such as a bench or step, and place your hands shoulder-width apart on the edge.","Step your feet back, keeping your body in a straight line from head to heels.","Lower your chest towards the edge of the surface, bending your elbows and keeping your body aligned.","Push through your palms to extend your arms and return to the starting position.","Jump off the edge of the surface, landing softly with your knees slightly bent.","Repeat the push-up and depth jump for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders","core"],"target":"pectorals","image":"images/0492-CB8WET1.jpg","gif_url":"videos/0492-CB8WET1.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0493","name":"incline push-up","category":"chest","equipment":"body weight","instruction_steps":{"en":["Place your hands on an elevated surface, such as a bench or step, slightly wider than shoulder-width apart.","Extend your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels.","Lower your chest towards the elevated surface by bending your elbows, keeping your body in a straight line.","Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/0493-B1EVP9F.jpg","gif_url":"videos/0493-B1EVP9F.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3785","name":"incline push-up (on box)","category":"chest","equipment":"body weight","instruction_steps":{"en":["Place your hands on the edge of a box or elevated surface, slightly wider than shoulder-width apart.","Extend your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels.","Lower your chest towards the box by bending your elbows, keeping your body in a straight line.","Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/3785-F7vjXqT.jpg","gif_url":"videos/3785-F7vjXqT.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0494","name":"incline reverse grip push-up","category":"chest","equipment":"body weight","instruction_steps":{"en":["Place your hands on the edge of a bench or elevated surface, slightly wider than shoulder-width apart.","Extend your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels.","Lower your chest towards the bench by bending your elbows, keeping them close to your sides.","Pause for a moment at the bottom, then push yourself back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/0494-XaaRnRn.jpg","gif_url":"videos/0494-XaaRnRn.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3011","name":"incline scapula push up","category":"chest","equipment":"body weight","instruction_steps":{"en":["Set up an incline bench at a 45-degree angle.","Place your hands on the bench slightly wider than shoulder-width apart.","Position your feet on the ground, hip-width apart.","Lower your chest towards the bench, keeping your elbows tucked in.","As you lower, retract your shoulder blades, squeezing your scapulae together.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"serratus anterior","image":"images/3011-GdMa1ET.jpg","gif_url":"videos/3011-GdMa1ET.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0495","name":"incline twisting sit-up","category":"waist","equipment":"body weight","instruction_steps":{"en":["Set up an incline bench at a 45-degree angle.","Lie down on the bench with your feet secured under the foot pads.","Place your hands behind your head or across your chest.","Engage your abs and lift your upper body off the bench, curling forward.","As you curl up, twist your torso to one side, bringing your elbow towards the opposite knee.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat the movement, this time twisting your torso to the other side.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/0495-9ZGZuOD.jpg","gif_url":"videos/0495-9ZGZuOD.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1564","name":"intermediate hip flexor and quad stretch","category":"upper legs","equipment":"rope","instruction_steps":{"en":["Stand upright with your feet shoulder-width apart.","Hold onto a stable object for support.","Bend your right knee and bring your right foot towards your glutes, grabbing the rope with your right hand.","Slowly pull your right foot towards your glutes, feeling a stretch in your right quad.","Hold the stretch for 20-30 seconds.","Release the stretch and repeat on the left side."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"quads","image":"images/1564-tFGKm99.jpg","gif_url":"videos/1564-tFGKm99.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0496","name":"inverse leg curl (bench support)","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Lie face down on a bench with your hips at the edge and your legs extended straight behind you.","Hold onto the bench for support.","Keeping your upper body still, bend your knees and curl your legs towards your glutes.","Pause for a moment at the top, then slowly extend your legs back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","calves"],"target":"hamstrings","image":"images/0496-ms7tjSG.jpg","gif_url":"videos/0496-ms7tjSG.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2400","name":"inverse leg curl (on pull-up cable machine)","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Adjust the cable machine so that the ankle straps are at the lowest setting.","Lie face down on the bench with your legs extended and the ankle straps attached to your feet.","Hold onto the handles of the bench for stability.","Bend your knees and curl your legs towards your glutes, squeezing your hamstrings.","Pause for a moment at the top of the movement, then slowly lower your legs back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","calves"],"target":"hamstrings","image":"images/2400-0rHfvy9.jpg","gif_url":"videos/2400-0rHfvy9.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0499","name":"inverted row","category":"back","equipment":"body weight","instruction_steps":{"en":["Set up a bar at waist height or use a suspension trainer.","Stand facing the bar or suspension trainer, with your feet shoulder-width apart.","Grab the bar or handles with an overhand grip, slightly wider than shoulder-width apart.","Lean back, keeping your body straight and your heels on the ground.","Pull your chest towards the bar or handles, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower yourself back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0499-bZGHsAZ.jpg","gif_url":"videos/0499-bZGHsAZ.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2300","name":"inverted row bent knees","category":"back","equipment":"body weight","instruction_steps":{"en":["Set up a bar at waist height and lie underneath it.","Grab the bar with an overhand grip, slightly wider than shoulder-width apart.","Position your body so that your heels are on the ground and your body is straight.","Pull your chest up towards the bar by squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/2300-VPPtusI.jpg","gif_url":"videos/2300-VPPtusI.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2298","name":"inverted row on bench","category":"back","equipment":"body weight","instruction_steps":{"en":["Set up a bench at a height that allows your body to hang freely underneath it.","Lie face up on the ground with your head towards the bench.","Reach up and grab the bench with an overhand grip, slightly wider than shoulder-width apart.","Position your body so that your heels are on the ground and your arms are fully extended.","Engage your core and squeeze your shoulder blades together as you pull your chest up towards the bench.","Pause for a moment at the top of the movement, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/2298-Mxa7Cr8.jpg","gif_url":"videos/2298-Mxa7Cr8.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0497","name":"inverted row v. 2","category":"back","equipment":"body weight","instruction_steps":{"en":["Set up a bar at waist height on a Smith machine or use a suspension trainer.","Stand facing the bar or suspension trainer and grab it with an overhand grip, hands shoulder-width apart.","Walk your feet forward, leaning back until your body is at a slight angle.","Keep your body straight and pull your chest up towards the bar or handles, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0497-uX3sUBz.jpg","gif_url":"videos/0497-uX3sUBz.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0498","name":"inverted row with straps","category":"back","equipment":"body weight","instruction_steps":{"en":["Set up a suspension trainer or straps at chest height.","Stand facing the anchor point and grab the handles with an overhand grip.","Walk your feet forward, leaning back until your body is at an angle.","Keep your body straight and engage your core.","Pull your chest towards the handles, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower yourself back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0498-jdiExfW.jpg","gif_url":"videos/0498-jdiExfW.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1419","name":"iron cross stretch","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Lie flat on your back with your arms extended out to the sides.","Raise your legs up towards the ceiling, keeping them straight.","Slowly lower your legs to one side, aiming to touch the floor with your feet.","Hold the stretch for a few seconds, then return your legs to the starting position.","Repeat the stretch on the other side.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps"],"target":"glutes","image":"images/1419-pZwUsKB.jpg","gif_url":"videos/1419-pZwUsKB.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1297","name":"isometric chest squeeze","category":"chest","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart and your knees slightly bent.","Extend your arms straight out in front of you, parallel to the ground, with your palms facing each other.","Squeeze your chest muscles together as hard as you can, while keeping your arms straight.","Hold this position for a few seconds, focusing on contracting your chest muscles.","Release the squeeze and relax your chest muscles.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1297-HbSG1Pw.jpg","gif_url":"videos/1297-HbSG1Pw.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0500","name":"isometric wipers","category":"chest","equipment":"body weight","instruction_steps":{"en":["Start by lying flat on your back on a mat or bench.","Extend your arms straight out to the sides, perpendicular to your body.","Engage your core and lift both legs off the ground, keeping them together and straight.","Slowly lower your legs to one side, aiming to touch the ground with your feet while maintaining control.","Pause for a moment, then use your core to lift your legs back to the starting position.","Repeat the movement, this time lowering your legs to the opposite side.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps","core"],"target":"pectorals","image":"images/0500-11wrviz.jpg","gif_url":"videos/0500-11wrviz.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0501","name":"jack burpee","category":"cardio","equipment":"body weight","instruction_steps":{"en":["Start in a standing position with your feet shoulder-width apart.","Lower your body into a squat position, placing your hands on the ground in front of you.","Kick your feet back, landing in a push-up position.","Perform a push-up, lowering your chest to the ground and then pushing back up.","Jump your feet forward, landing in a squat position.","Jump up explosively, reaching your arms overhead.","Land softly and immediately lower back into the squat position to begin the next repetition."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves","shoulders","triceps","core"],"target":"cardiovascular system","image":"images/0501-mr7pkqP.jpg","gif_url":"videos/0501-mr7pkqP.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3224","name":"jack jump (male)","category":"cardio","equipment":"body weight","instruction_steps":{"en":["Stand with your feet together and your arms by your sides.","Jump up, spreading your feet apart and raising your arms above your head.","As you land, quickly jump back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","calves"],"target":"cardiovascular system","image":"images/3224-1g5bPpA.jpg","gif_url":"videos/3224-1g5bPpA.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0507","name":"jackknife sit-up","category":"waist","equipment":"body weight","instruction_steps":{"en":["Lie flat on your back with your legs extended and your arms overhead.","Engage your core and lift your legs and upper body simultaneously, reaching your hands towards your toes.","Pause for a moment at the top, then slowly lower your legs and upper body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0507-mbkgB44.jpg","gif_url":"videos/0507-mbkgB44.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0508","name":"janda sit-up","category":"waist","equipment":"body weight","instruction_steps":{"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors","lower back"],"target":"abs","image":"images/0508-1GPHRyK.jpg","gif_url":"videos/0508-1GPHRyK.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2612","name":"jump rope","category":"cardio","equipment":"rope","instruction_steps":{"en":["Hold the handles of the jump rope with your hands, palms facing inward.","Stand with your feet shoulder-width apart and knees slightly bent.","Swing the rope over your head and jump over it as it comes towards your feet.","Land softly on the balls of your feet and repeat the jump as the rope comes around again.","Continue jumping for the desired duration or number of repetitions."]},"muscle_group":"calves","secondary_muscles":["calves","quadriceps","hamstrings","glutes"],"target":"cardiovascular system","image":"images/2612-e1e76I2.jpg","gif_url":"videos/2612-e1e76I2.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0514","name":"jump squat","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart.","Lower your body into a squat position by bending your knees and pushing your hips back.","Jump explosively off the ground, extending your hips, knees, and ankles.","While in mid-air, quickly bring your arms forward for balance.","Land softly on the balls of your feet and immediately go into the next repetition.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0514-LIlE5Tn.jpg","gif_url":"videos/0514-LIlE5Tn.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0513","name":"jump squat v. 2","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart.","Lower your body into a squat position by bending your knees and pushing your hips back.","Jump explosively, extending your hips and knees fully.","Land softly on the balls of your feet and immediately lower your body back into a squat position.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0513-TDYiji6.jpg","gif_url":"videos/0513-TDYiji6.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0517","name":"kettlebell advanced windmill","category":"waist","equipment":"kettlebell","instruction_steps":{"en":["Stand with your feet wider than shoulder-width apart, toes pointing slightly outward.","Hold a kettlebell in your right hand, with your arm extended overhead and your palm facing forward.","Rotate your left foot slightly to the right, and shift your weight onto your left leg.","Bend your left knee and hinge at the hip, lowering your torso towards the left side.","Keep your right arm extended overhead and your eyes on the kettlebell.","As you lower your torso, allow your right leg to straighten and your right foot to pivot slightly.","Lower your torso until you feel a stretch in your left hamstring and your right arm is pointing towards the ground.","Pause for a moment, then engage your core and push through your left heel to return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},"muscle_group":"obliques","secondary_muscles":["obliques","shoulders"],"target":"abs","image":"images/0517-Kal9cQQ.jpg","gif_url":"videos/0517-Kal9cQQ.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0518","name":"kettlebell alternating hang clean","category":"lower arms","equipment":"kettlebell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a kettlebell in each hand with an overhand grip.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.","Allow the kettlebells to hang in front of your body with your arms fully extended.","In one fluid motion, explosively extend your hips, shrug your shoulders, and pull the kettlebells up towards your shoulders.","As the kettlebells reach shoulder height, rotate your wrists and catch the kettlebells in the rack position, with your palms facing inward and the kettlebells resting on the outside of your forearms.","Lower the kettlebells back down to the starting position and repeat the movement with the opposite arm.","Continue alternating arms for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","traps","core"],"target":"forearms","image":"images/0518-I4tibZG.jpg","gif_url":"videos/0518-I4tibZG.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0520","name":"kettlebell alternating press","category":"shoulders","equipment":"kettlebell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.","Press one kettlebell overhead, fully extending your arm.","Lower the kettlebell back to shoulder height.","Repeat with the other arm.","Continue alternating arms for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","core"],"target":"delts","image":"images/0520-5KLbZWx.jpg","gif_url":"videos/0520-5KLbZWx.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0519","name":"kettlebell alternating press on floor","category":"chest","equipment":"kettlebell","instruction_steps":{"en":["Start by lying on your back on the floor with your knees bent and feet flat on the ground.","Hold a kettlebell in each hand, with your palms facing towards your feet and your arms extended straight up towards the ceiling.","Lower one kettlebell down towards your shoulder while keeping the other kettlebell extended straight up.","Press the lowered kettlebell back up to the starting position while simultaneously lowering the other kettlebell down towards your shoulder.","Continue alternating the press motion with each kettlebell for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/0519-7w6i0vE.jpg","gif_url":"videos/0519-7w6i0vE.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0521","name":"kettlebell alternating renegade row","category":"back","equipment":"kettlebell","instruction_steps":{"en":["Start in a high plank position with your hands gripping the kettlebells and your feet hip-width apart.","Engage your core and keep your body in a straight line from head to heels.","Pull one kettlebell up towards your chest, keeping your elbow close to your body.","Lower the kettlebell back down to the starting position and repeat with the other arm.","Continue alternating arms for the desired number of repetitions."]},"muscle_group":"core","secondary_muscles":["core","shoulders"],"target":"upper back","image":"images/0521-b9kqlBy.jpg","gif_url":"videos/0521-b9kqlBy.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0522","name":"kettlebell alternating row","category":"back","equipment":"kettlebell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, knees slightly bent, and hold a kettlebell in each hand with your palms facing your body.","Bend forward at the hips, keeping your back straight and your core engaged.","Pull one kettlebell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.","Lower the kettlebell back down to the starting position and repeat with the other arm.","Continue alternating arms for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0522-Ca76jUE.jpg","gif_url":"videos/0522-Ca76jUE.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0523","name":"kettlebell arnold press","category":"shoulders","equipment":"kettlebell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height with your palms facing towards you.","Engage your core and press the kettlebells overhead, rotating your palms to face forward as you extend your arms.","Pause at the top of the movement, then slowly lower the kettlebells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0523-UM8mgyG.jpg","gif_url":"videos/0523-UM8mgyG.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0524","name":"kettlebell bent press","category":"waist","equipment":"kettlebell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a kettlebell in your right hand.","Bend your knees slightly and press the kettlebell overhead with your right arm, keeping your elbow locked.","Rotate your torso to the left, shifting your weight onto your left foot.","Bend your left knee and lower your torso towards the ground, keeping your right arm extended overhead.","As you lower, keep your eyes on the kettlebell and your chest lifted.","Once your left hand touches the ground, push through your left foot and straighten your left leg, driving your hips forward.","As you drive your hips forward, use your core and right arm to press the kettlebell back up to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps","obliques"],"target":"abs","image":"images/0524-kjE55n5.jpg","gif_url":"videos/0524-kjE55n5.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0525","name":"kettlebell bottoms up clean from the hang position","category":"upper arms","equipment":"kettlebell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.","Allow the kettlebell to hang down between your legs, with your arm fully extended.","In one fluid motion, explosively extend your hips and knees while pulling the kettlebell up towards your shoulder.","As the kettlebell reaches shoulder height, rotate your wrist so that the bottom of the kettlebell is facing up.","Catch the kettlebell at shoulder height with your elbow bent and your palm facing up.","Lower the kettlebell back down to the starting position by reversing the movement.","Repeat for the desired number of repetitions, then switch sides."]},"muscle_group":"forearms","secondary_muscles":["forearms","shoulders"],"target":"biceps","image":"images/0525-4KJEpzb.jpg","gif_url":"videos/0525-4KJEpzb.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0526","name":"kettlebell double alternating hang clean","category":"upper arms","equipment":"kettlebell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a kettlebell in each hand with an overhand grip.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.","Allow the kettlebells to hang straight down in front of your body.","In one fluid motion, explosively extend your hips and knees while shrugging your shoulders.","As the kettlebells rise, pull them up towards your shoulders, keeping your elbows high and out to the sides.","Catch the kettlebells at shoulder height, with your palms facing inward and your elbows pointing forward.","Lower the kettlebells back down to the starting position and repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms","shoulders"],"target":"biceps","image":"images/0526-a4F9Oyc.jpg","gif_url":"videos/0526-a4F9Oyc.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0527","name":"kettlebell double jerk","category":"shoulders","equipment":"kettlebell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.","Bend your knees slightly and engage your core.","Press the kettlebells overhead, fully extending your arms.","Bend your knees and quickly drop into a partial squat.","Explosively extend your hips and knees, driving the kettlebells overhead.","Lock out your arms and catch the kettlebells overhead with your knees slightly bent.","Stand up straight and return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","core"],"target":"delts","image":"images/0527-tznL2Ad.jpg","gif_url":"videos/0527-tznL2Ad.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0528","name":"kettlebell double push press","category":"shoulders","equipment":"kettlebell","instruction_steps":{"en":["Start by standing with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.","Bend your knees slightly and engage your core.","Initiate the movement by explosively extending your hips, knees, and ankles, driving the kettlebells overhead.","As the kettlebells reach the top, press them fully overhead, locking out your arms.","Lower the kettlebells back to the starting position by bending your elbows and bringing them back down to shoulder height.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","core"],"target":"delts","image":"images/0528-I4KkPdl.jpg","gif_url":"videos/0528-I4KkPdl.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0529","name":"kettlebell double snatch","category":"shoulders","equipment":"kettlebell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at arm's length in front of your thighs.","Bend your knees slightly and hinge forward at the hips, keeping your back flat and chest up.","In one explosive motion, extend your hips, knees, and ankles, and simultaneously pull the kettlebells up towards your shoulders.","As the kettlebells reach shoulder level, rotate your wrists and punch the kettlebells overhead, fully extending your arms.","Lower the kettlebells back down to the starting position and repeat for the desired number of repetitions."]},"muscle_group":"trapezius","secondary_muscles":["trapezius","forearms","core"],"target":"delts","image":"images/0529-M74kdvm.jpg","gif_url":"videos/0529-M74kdvm.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0530","name":"kettlebell double windmill","category":"waist","equipment":"kettlebell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a kettlebell in your right hand.","Extend your right arm overhead, keeping your eyes on the kettlebell.","Rotate your left foot 45 degrees to the left and your right foot 90 degrees to the right.","Bend at the waist to the left, keeping your right arm extended overhead.","Lower the kettlebell towards the ground, reaching towards your left foot.","Pause for a moment, then engage your core and push through your right foot to return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","hamstrings"],"target":"abs","image":"images/0530-OaE7CpD.jpg","gif_url":"videos/0530-OaE7CpD.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0531","name":"kettlebell extended range one arm press on floor","category":"chest","equipment":"kettlebell","instruction_steps":{"en":["Start by lying on your back on the floor with your knees bent and feet flat on the ground.","Hold a kettlebell in one hand, with your palm facing towards your feet.","Extend your arm straight up towards the ceiling, keeping your elbow locked and your wrist straight.","Slowly lower the kettlebell back down to the starting position, maintaining control throughout the movement.","Repeat for the desired number of repetitions, then switch to the other arm."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/0531-rseLfH3.jpg","gif_url":"videos/0531-rseLfH3.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0532","name":"kettlebell figure 8","category":"waist","equipment":"kettlebell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a kettlebell in one hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Pass the kettlebell between your legs, switching hands as it reaches the back of your legs.","As the kettlebell comes forward, pass it to the other hand between your legs.","Continue passing the kettlebell between your legs in a figure 8 motion.","Maintain a steady pace and engage your core throughout the exercise.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","forearms"],"target":"abs","image":"images/0532-L4ay0PW.jpg","gif_url":"videos/0532-L4ay0PW.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0533","name":"kettlebell front squat","category":"upper legs","equipment":"kettlebell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, toes slightly turned out.","Hold the kettlebell with both hands in front of your chest, close to your body.","Engage your core and keep your chest up as you lower your hips down and back, as if sitting into a chair.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Drive through your heels to stand back up, squeezing your glutes at the top.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0533-DB0n8AG.jpg","gif_url":"videos/0533-DB0n8AG.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0534","name":"kettlebell goblet squat","category":"upper legs","equipment":"kettlebell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a kettlebell close to your chest with both hands.","Keeping your chest up and core engaged, lower your body down into a squat position by bending at the knees and hips.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0534-ZA8b5hc.jpg","gif_url":"videos/0534-ZA8b5hc.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0535","name":"kettlebell hang clean","category":"upper legs","equipment":"kettlebell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a kettlebell in front of your thighs.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Lower the kettlebell towards the ground, allowing it to swing between your legs.","Quickly extend your hips and knees, using the momentum to swing the kettlebell up to shoulder height.","As the kettlebell reaches shoulder height, rotate your wrists and catch the kettlebell in the rack position, with your elbow tucked in and the kettlebell resting on your forearm.","Lower the kettlebell back down to the starting position between your legs, and repeat for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","quadriceps","calves"],"target":"hamstrings","image":"images/0535-LHWF7us.jpg","gif_url":"videos/0535-LHWF7us.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0536","name":"kettlebell lunge pass through","category":"upper legs","equipment":"kettlebell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a kettlebell in front of your chest with both hands.","Take a step forward with your right foot, lowering your body into a lunge position.","As you lunge forward, pass the kettlebell under your right thigh and transfer it to your left hand.","Push off with your right foot to return to the starting position, while simultaneously passing the kettlebell back to your right hand.","Repeat the lunge on the opposite side, passing the kettlebell under your left thigh.","Continue alternating lunges and passing the kettlebell between hands for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0536-WKMQzCD.jpg","gif_url":"videos/0536-WKMQzCD.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0537","name":"kettlebell one arm clean and jerk","category":"shoulders","equipment":"kettlebell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip.","Bend your knees slightly and hinge at the hips, lowering the kettlebell between your legs.","Explosively extend your hips, knees, and ankles, using the momentum to swing the kettlebell up to shoulder height.","As the kettlebell reaches shoulder height, rotate your wrist and punch your hand straight up, locking out your arm overhead.","Lower the kettlebell back down to the starting position and repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","core"],"target":"delts","image":"images/0537-vzAxBtt.jpg","gif_url":"videos/0537-vzAxBtt.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1298","name":"kettlebell one arm floor press","category":"chest","equipment":"kettlebell","instruction_steps":{"en":["Lie flat on your back on the floor with your knees bent and feet flat on the ground.","Hold the kettlebell in one hand with your palm facing towards your feet and your arm extended straight up towards the ceiling.","Slowly lower the kettlebell towards your chest by bending your elbow, keeping your upper arm close to your body.","Pause for a moment when the kettlebell is just above your chest, then push it back up to the starting position by extending your elbow.","Repeat for the desired number of repetitions, then switch to the other arm."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1298-rg59QCH.jpg","gif_url":"videos/1298-rg59QCH.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0538","name":"kettlebell one arm jerk","category":"shoulders","equipment":"kettlebell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a kettlebell in one hand at shoulder height.","Bend your knees slightly and engage your core.","Press the kettlebell overhead in a straight line, fully extending your arm.","As you press the kettlebell overhead, simultaneously dip your knees and quickly straighten them to generate momentum.","As the kettlebell reaches its highest point, quickly drop underneath it by bending your knees and hips.","Catch the kettlebell with a slight bend in your knees and hips, and your arm fully extended overhead.","Stand up straight, fully extending your knees and hips, and stabilize the kettlebell overhead.","Lower the kettlebell back to the starting position by bending your knees and hips, and repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","core"],"target":"delts","image":"images/0538-S37C94C.jpg","gif_url":"videos/0538-S37C94C.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0539","name":"kettlebell one arm military press to the side","category":"shoulders","equipment":"kettlebell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a kettlebell in one hand at shoulder height.","Engage your core and keep your back straight.","Press the kettlebell overhead, extending your arm fully.","Pause for a moment at the top, then slowly lower the kettlebell back to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},"muscle_group":"triceps","secondary_muscles":["triceps","core"],"target":"delts","image":"images/0539-yCvYdi7.jpg","gif_url":"videos/0539-yCvYdi7.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0540","name":"kettlebell one arm push press","category":"shoulders","equipment":"kettlebell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a kettlebell in one hand at shoulder level.","Bend your knees slightly and engage your core.","Press the kettlebell overhead by extending your arm and fully extending your legs.","Lower the kettlebell back to the starting position by bending your knees and bringing the kettlebell back to your shoulder.","Repeat for the desired number of repetitions, then switch sides."]},"muscle_group":"triceps","secondary_muscles":["triceps","core"],"target":"delts","image":"images/0540-osdXT3K.jpg","gif_url":"videos/0540-osdXT3K.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0541","name":"kettlebell one arm row","category":"back","equipment":"kettlebell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and your core engaged.","Pull the kettlebell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the kettlebell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides and repeat with the other arm."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0541-g9AsZ8P.jpg","gif_url":"videos/0541-g9AsZ8P.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0542","name":"kettlebell one arm snatch","category":"shoulders","equipment":"kettlebell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a kettlebell in one hand between your legs.","Bend your knees slightly and hinge at the hips, lowering the kettlebell towards the ground.","Explosively extend your hips and knees, using the momentum to swing the kettlebell up towards your shoulder.","As the kettlebell reaches shoulder height, rotate your hand and punch it straight up overhead, fully extending your arm.","Lower the kettlebell back down between your legs and repeat for the desired number of repetitions."]},"muscle_group":"trapezius","secondary_muscles":["trapezius","forearms","core"],"target":"delts","image":"images/0542-aXcUyKb.jpg","gif_url":"videos/0542-aXcUyKb.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0543","name":"kettlebell pirate supper legs","category":"shoulders","equipment":"kettlebell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a kettlebell in one hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Raise the kettlebell up to shoulder height, keeping your elbow close to your body.","Extend your arm fully overhead, straightening your elbow.","Lower the kettlebell back down to shoulder height, then return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},"muscle_group":"triceps","secondary_muscles":["triceps","forearms"],"target":"delts","image":"images/0543-kuXhl0o.jpg","gif_url":"videos/0543-kuXhl0o.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0544","name":"kettlebell pistol squat","category":"upper legs","equipment":"kettlebell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a kettlebell in front of your chest with both hands.","Lift your left foot off the ground and extend it forward, keeping it parallel to the ground.","Slowly lower your body down into a squat position, keeping your right foot flat on the ground and your left leg extended.","Pause for a moment at the bottom of the squat, then push through your right heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0544-5bpPTHv.jpg","gif_url":"videos/0544-5bpPTHv.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0545","name":"kettlebell plyo push-up","category":"chest","equipment":"kettlebell","instruction_steps":{"en":["Start in a high plank position with your hands on the kettlebells, shoulder-width apart.","Lower your chest towards the ground, keeping your elbows close to your body.","Push through your hands explosively, lifting your hands off the kettlebells and extending your arms fully.","Land softly back on the kettlebells and immediately lower your chest back down for the next repetition.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders","core"],"target":"pectorals","image":"images/0545-ktf3nvW.jpg","gif_url":"videos/0545-ktf3nvW.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0546","name":"kettlebell seated press","category":"shoulders","equipment":"kettlebell","instruction_steps":{"en":["Sit on a bench with your back straight and feet flat on the ground.","Hold a kettlebell in each hand at shoulder height, palms facing forward.","Press the kettlebells overhead, fully extending your arms.","Lower the kettlebells back to shoulder height.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","core"],"target":"delts","image":"images/0546-BkxB8LW.jpg","gif_url":"videos/0546-BkxB8LW.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1438","name":"kettlebell seated two arm military press","category":"shoulders","equipment":"kettlebell","instruction_steps":{"en":["Sit on a bench with your back straight and feet flat on the ground.","Hold a kettlebell in each hand at shoulder level with your palms facing forward.","Press the kettlebells overhead by extending your arms fully.","Pause for a moment at the top, then slowly lower the kettlebells back to shoulder level.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/1438-ZEkjZDi.jpg","gif_url":"videos/1438-ZEkjZDi.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0547","name":"kettlebell seesaw press","category":"shoulders","equipment":"kettlebell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.","Press one kettlebell overhead while keeping the other kettlebell at shoulder height.","Lower the pressed kettlebell back to shoulder height while simultaneously pressing the other kettlebell overhead.","Continue alternating the pressing motion, creating a seesaw-like movement.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","core"],"target":"delts","image":"images/0547-UDm6cGl.jpg","gif_url":"videos/0547-UDm6cGl.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0548","name":"kettlebell sumo high pull","category":"back","equipment":"kettlebell","instruction_steps":{"en":["Stand with your feet wider than shoulder-width apart, toes pointing outwards.","Hold a kettlebell with both hands in front of your body, arms extended downwards.","Bend your knees and lower your hips into a squat position, keeping your back straight.","Drive through your heels and explosively extend your hips and knees, pulling the kettlebell up towards your chin.","As you pull the kettlebell up, keep your elbows high and wide, and squeeze your shoulder blades together.","Lower the kettlebell back down to the starting position and repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","glutes","hamstrings"],"target":"traps","image":"images/0548-8ARQ9Hw.jpg","gif_url":"videos/0548-8ARQ9Hw.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0549","name":"kettlebell swing","category":"upper legs","equipment":"kettlebell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, toes pointed slightly outward.","Hold the kettlebell with both hands in front of your body, arms extended.","Bend your knees slightly and hinge at the hips, pushing your butt back.","Swing the kettlebell back between your legs, keeping your arms straight and maintaining a flat back.","Drive your hips forward and swing the kettlebell up to shoulder height, using the momentum generated by your hips.","Allow the kettlebell to swing back down between your legs and repeat the movement for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","core"],"target":"glutes","image":"images/0549-UHJlbu3.jpg","gif_url":"videos/0549-UHJlbu3.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0550","name":"kettlebell thruster","category":"shoulders","equipment":"kettlebell","instruction_steps":{"en":["Start by standing with your feet shoulder-width apart, holding a kettlebell in front of your chest with both hands, palms facing each other.","Lower into a squat position by bending your knees and pushing your hips back, keeping your chest up and your back straight.","As you reach the bottom of the squat, explosively drive through your heels to stand up, simultaneously pressing the kettlebell overhead.","Lock out your arms at the top of the movement, fully extending your elbows.","Lower the kettlebell back to the starting position by reversing the movement, bending your elbows and lowering the weight back to your chest.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","glutes","core"],"target":"delts","image":"images/0550-yWxMvB5.jpg","gif_url":"videos/0550-yWxMvB5.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0551","name":"kettlebell turkish get up (squat style)","category":"upper legs","equipment":"kettlebell","instruction_steps":{"en":["Start by lying on your back with your legs extended and the kettlebell held in your right hand, arm fully extended above your shoulder.","Bend your right knee and place your right foot flat on the ground, keeping your left leg extended.","Pressing through your right foot, lift your hips off the ground, coming into a bridge position.","Slide your left leg underneath your body, bending your left knee and placing your left foot flat on the ground.","Rotate your torso to the left, bringing your left hand to the ground for support.","Pressing through your right foot and left hand, lift your torso off the ground, coming into a kneeling position.","From the kneeling position, stand up, keeping the kettlebell extended overhead.","Reverse the movement to return to the starting position.","Repeat the exercise on the other side, starting with the kettlebell in your left hand."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","core"],"target":"glutes","image":"images/0551-Ha7SZ3y.jpg","gif_url":"videos/0551-Ha7SZ3y.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0552","name":"kettlebell two arm clean","category":"shoulders","equipment":"kettlebell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a kettlebell in front of your thighs with both hands, palms facing towards you.","Bend your knees slightly and hinge at the hips, lowering the kettlebell towards the ground.","Explosively extend your hips and knees, using the momentum to pull the kettlebell up towards your shoulders.","As the kettlebell reaches shoulder height, rotate your wrists and catch the kettlebell in the rack position, with your elbows tucked in and the kettlebell resting on the back of your forearm.","Lower the kettlebell back down to the starting position and repeat for the desired number of repetitions."]},"muscle_group":"traps","secondary_muscles":["traps","forearms"],"target":"delts","image":"images/0552-7Ba7bQ2.jpg","gif_url":"videos/0552-7Ba7bQ2.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0553","name":"kettlebell two arm military press","category":"shoulders","equipment":"kettlebell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder level with your palms facing forward.","Engage your core and press the kettlebells overhead, fully extending your arms.","Pause for a moment at the top, then slowly lower the kettlebells back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0553-blBXysN.jpg","gif_url":"videos/0553-blBXysN.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1345","name":"kettlebell two arm row","category":"back","equipment":"kettlebell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, knees slightly bent, and hold a kettlebell in each hand with your palms facing your body.","Bend forward at the hips, keeping your back straight and your core engaged.","Pull the kettlebells up towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the kettlebells back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/1345-wf24o8S.jpg","gif_url":"videos/1345-wf24o8S.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0554","name":"kettlebell windmill","category":"waist","equipment":"kettlebell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a kettlebell in your right hand overhead.","Rotate your left foot outwards about 45 degrees and keep your right foot pointing forward.","Bend your torso to the left side, keeping your right arm extended overhead and your eyes on the kettlebell.","Lower your torso as far as you can while keeping your right arm straight and your left arm extended to the side.","Pause for a moment, then return to the starting position by pushing through your right foot and engaging your obliques.","Repeat for the desired number of repetitions, then switch sides."]},"muscle_group":"obliques","secondary_muscles":["obliques","shoulders"],"target":"abs","image":"images/0554-9Tkqa9O.jpg","gif_url":"videos/0554-9Tkqa9O.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0555","name":"kick out sit","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Sit on the edge of a bench or chair with your feet flat on the ground and your knees bent at a 90-degree angle.","Lean back slightly and place your hands on the edge of the bench or chair for support.","Engaging your hamstrings, lift your feet off the ground and extend your legs straight out in front of you.","Pause for a moment at the top, then slowly bend your knees and bring your feet back towards your body.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","glutes"],"target":"hamstrings","image":"images/0555-v7p5bYl.jpg","gif_url":"videos/0555-v7p5bYl.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0558","name":"kipping muscle up","category":"back","equipment":"body weight","instruction_steps":{"en":["Start by hanging from a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart.","Engage your core and use a swinging motion to generate momentum.","As you swing forward, pull your chest towards the bar, using your lats and biceps to initiate the movement.","Continue the upward motion until your chest reaches the bar, then transition into a dip position by pushing down on the bar and extending your arms.","Lower yourself back down to the starting position by bending your arms and controlling the descent.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","triceps","shoulders","core"],"target":"lats","image":"images/0558-pM07UxU.jpg","gif_url":"videos/0558-pM07UxU.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3640","name":"knee touch crunch","category":"waist","equipment":"body weight","instruction_steps":{"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, lift your shoulder blades off the ground and reach your right hand towards your left knee.","Return to the starting position and repeat, this time reaching your left hand towards your right knee.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/3640-dTg95eZ.jpg","gif_url":"videos/3640-dTg95eZ.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1420","name":"kneeling jump squat","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Start by kneeling on the ground with your feet hip-width apart and your toes pointing forward.","Hold a barbell across your upper back, resting it on your shoulders.","Engage your core and glutes, then explosively jump up into the air, extending your hips and knees.","As you jump, push through your toes and fully extend your ankles, knees, and hips.","Land softly back on the ground, bending your knees to absorb the impact.","Immediately go into the next repetition, repeating the jump squat motion."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/1420-UgDm3oy.jpg","gif_url":"videos/1420-UgDm3oy.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1346","name":"kneeling lat stretch","category":"back","equipment":"body weight","instruction_steps":{"en":["Kneel on the ground with your knees hip-width apart and your toes pointing back.","Extend your arms overhead and interlace your fingers.","Keeping your back straight, slowly lean to the right side, feeling a stretch in your left lat muscle.","Hold the stretch for 20-30 seconds, then return to the starting position.","Repeat the stretch on the left side, leaning to the left and feeling a stretch in your right lat muscle.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"lats","image":"images/1346-f38OEuO.jpg","gif_url":"videos/1346-f38OEuO.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3239","name":"kneeling plank tap shoulder (male)","category":"waist","equipment":"body weight","instruction_steps":{"en":["Start in a kneeling position with your hands on the ground, shoulder-width apart.","Extend your legs behind you, resting on your toes, and lift your body into a plank position.","Keeping your core engaged and your hips stable, lift one hand off the ground and tap the opposite shoulder.","Return the hand to the ground and repeat with the other hand.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"abs","image":"images/3239-h1ezqSu.jpg","gif_url":"videos/3239-h1ezqSu.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3211","name":"kneeling push-up (male)","category":"chest","equipment":"body weight","instruction_steps":{"en":["Start by kneeling on the ground with your hands shoulder-width apart, fingers pointing forward.","Extend your legs behind you, resting on the balls of your feet, so that your body forms a straight line from head to heels.","Engage your core and lower your body towards the ground by bending your elbows, keeping them close to your sides.","Continue lowering until your chest is just above the ground, then push back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/3211-ZOuKWir.jpg","gif_url":"videos/3211-ZOuKWir.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3288","name":"korean dips","category":"chest","equipment":"body weight","instruction_steps":{"en":["Position yourself between two parallel bars with your arms extended and supporting your body weight.","Lower your body by bending your elbows until your upper arms are parallel to the ground.","Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/3288-rWoBmi5.jpg","gif_url":"videos/3288-rWoBmi5.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3418","name":"l-pull-up","category":"back","equipment":"body weight","instruction_steps":{"en":["Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Hang with your arms fully extended and your body straight.","Engage your lats and biceps to pull your body up towards the bar, keeping your elbows close to your body.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/3418-d1GgzTU.jpg","gif_url":"videos/3418-d1GgzTU.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3419","name":"l-sit on floor","category":"waist","equipment":"body weight","instruction_steps":{"en":["Sit on the floor with your legs extended in front of you.","Place your hands on the floor beside your hips, fingers pointing forward.","Engage your core and lift your legs off the ground, keeping them straight.","Try to bring your legs parallel to the floor, forming an 'L' shape with your body.","Hold this position for as long as you can.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/3419-UpWmA5E.jpg","gif_url":"videos/3419-UpWmA5E.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0562","name":"landmine 180","category":"waist","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold the barbell with both hands in front of your chest.","Bend your knees slightly and rotate your torso to the right, swinging the barbell down towards your right hip.","As you reach the bottom of the movement, quickly reverse the motion and rotate your torso to the left, swinging the barbell up and across your body towards your left shoulder.","Continue this twisting motion, alternating sides, for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques","quadriceps"],"target":"abs","image":"images/0562-QYysSLV.jpg","gif_url":"videos/0562-QYysSLV.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3237","name":"landmine lateral raise","category":"shoulders","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and knees slightly bent.","Hold the barbell with an overhand grip, resting it on the front of your shoulders.","Keeping your core engaged and back straight, lift the barbell up and away from your body, raising it to shoulder height.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"traps","secondary_muscles":["traps","upper back"],"target":"delts","image":"images/3237-eXMFHww.jpg","gif_url":"videos/3237-eXMFHww.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3300","name":"lean planche","category":"waist","equipment":"body weight","instruction_steps":{"en":["Start in a push-up position with your hands shoulder-width apart and your body straight.","Engage your core and slowly shift your weight forward, bringing your shoulders past your hands.","Keep your elbows slightly bent and your body straight as you lean forward.","Hold this position for a few seconds, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","chest","triceps"],"target":"abs","image":"images/3300-LYJodFS.jpg","gif_url":"videos/3300-LYJodFS.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2271","name":"left hook. boxing","category":"shoulders","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart and your knees slightly bent.","Keep your left hand up to protect your face and your right hand by your chin.","Rotate your hips and pivot on your left foot as you extend your left arm forward in a punching motion.","Twist your torso and engage your core muscles to generate power in the punch.","Snap your arm back to the starting position and repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","triceps","forearms"],"target":"delts","image":"images/2271-hoXt6wv.jpg","gif_url":"videos/2271-hoXt6wv.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0570","name":"leg pull in flat bench","category":"waist","equipment":"body weight","instruction_steps":{"en":["Sit on a flat bench with your legs extended straight out in front of you.","Place your hands on the bench beside your hips for support.","Engage your abs and lift your legs off the ground, bringing your knees towards your chest.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors","lower back"],"target":"abs","image":"images/0570-OyoZ3Pu.jpg","gif_url":"videos/0570-OyoZ3Pu.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1576","name":"leg up hamstring stretch","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Lie flat on your back with your legs extended.","Bend one knee and bring it towards your chest, holding onto your thigh or shin.","Straighten your leg as much as possible while keeping it elevated.","Hold the stretch for 20-30 seconds.","Repeat with the other leg."]},"muscle_group":"glutes","secondary_muscles":["glutes"],"target":"hamstrings","image":"images/1576-sU5BrfP.jpg","gif_url":"videos/1576-sU5BrfP.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2287","name":"lever alternate leg press","category":"upper legs","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat and foot platform of the leverage machine to your desired position.","Sit on the machine with your back against the backrest and your feet on the foot platform.","Place your hands on the handles or sides of the machine for stability.","Push one foot against the foot platform, extending your leg until it is almost fully straight.","Pause for a moment, then slowly bend your leg and return to the starting position.","Repeat with the other leg.","Continue alternating legs for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"quads","image":"images/2287-V07qpXy.jpg","gif_url":"videos/2287-V07qpXy.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0571","name":"lever alternating narrow grip seated row","category":"back","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height and footplate position to ensure proper alignment.","Sit on the machine with your back straight and feet flat on the footplate.","Grasp the handles with a narrow grip, palms facing each other.","Keep your chest up and shoulders back throughout the exercise.","Pull one handle towards your torso while keeping the other handle stationary.","Squeeze your shoulder blades together at the end of the movement.","Slowly return the handle to the starting position and repeat with the other side.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0571-w2oRpuH.jpg","gif_url":"videos/0571-w2oRpuH.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0572","name":"lever assisted chin-up","category":"back","equipment":"leverage machine","instruction_steps":{"en":["Adjust the leverage machine to your desired resistance level.","Stand on the foot platform and grip the handles with an overhand grip, slightly wider than shoulder-width apart.","Hang with your arms fully extended, keeping your body straight.","Engage your back muscles and pull your body up towards the handles, leading with your chest.","Continue pulling until your chin is above the handles.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/0572-MaMuGH6.jpg","gif_url":"videos/0572-MaMuGH6.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0573","name":"lever back extension","category":"back","equipment":"leverage machine","instruction_steps":{"en":["Adjust the machine to fit your body size and range of motion.","Sit on the machine with your back against the pad and your feet secured.","Place your hands on the handles or grip bars.","Engage your core and slowly lean forward, allowing your back to round slightly.","Pause for a moment at the bottom position, feeling a stretch in your lower back.","Using your back muscles, slowly raise your torso back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","hamstrings"],"target":"spine","image":"images/0573-rUXfn3R.jpg","gif_url":"videos/0573-rUXfn3R.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0574","name":"lever bent over row","category":"back","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and knees slightly bent.","Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Bend forward at the hips, keeping your back straight and chest up.","Pull the barbell towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0574-X3cqyXz.jpg","gif_url":"videos/0574-X3cqyXz.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3200","name":"lever bent-over row with v-bar","category":"back","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height and position yourself facing the machine.","Grasp the v-bar with an overhand grip, keeping your back straight and your knees slightly bent.","Pull the v-bar towards your abdomen, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release the weight back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/3200-LuBEORI.jpg","gif_url":"videos/3200-LuBEORI.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0575","name":"lever bicep curl","category":"upper arms","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height and position yourself on the machine with your back against the pad.","Grasp the handles with an underhand grip, palms facing up, and keep your elbows close to your sides.","Exhale and curl the handles upward, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the handles back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0575-q6y3OhV.jpg","gif_url":"videos/0575-q6y3OhV.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2289","name":"lever calf press","category":"lower legs","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat of the leverage machine so that your shoulders are aligned with the lever pad.","Place your toes on the lever pad, with your heels hanging off the edge.","Grasp the handles or side supports for stability.","Push the lever pad down by extending your ankles, contracting your calf muscles.","Pause for a moment at the bottom of the movement.","Slowly return to the starting position by allowing your heels to rise back up.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"target":"calves","image":"images/2289-7B4F5nZ.jpg","gif_url":"videos/2289-7B4F5nZ.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0577","name":"lever chest press","category":"chest","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height and position yourself on the machine with your back flat against the pad.","Grasp the handles with an overhand grip and position your elbows at a 90-degree angle.","Push the handles forward until your arms are fully extended, exhaling during the movement.","Pause briefly at the end of the movement, then slowly return to the starting position, inhaling as you do so.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/0577-T0yTjgW.jpg","gif_url":"videos/0577-T0yTjgW.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0576","name":"lever chest press","category":"chest","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height and position yourself on the machine with your back flat against the pad.","Grasp the handles with an overhand grip and position your elbows at a 90-degree angle.","Push the handles forward until your arms are fully extended, exhaling during the movement.","Pause briefly at the end of the movement, then slowly return to the starting position, inhaling as you do so.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/0576-DOoWcnA.jpg","gif_url":"videos/0576-DOoWcnA.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0578","name":"lever deadlift","category":"upper legs","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height and foot platform to your desired position.","Sit on the machine with your back against the pad and your feet flat on the foot platform.","Grasp the handles or the sides of the seat for stability.","Engage your glutes and hamstrings, and push through your heels to lift the weight up.","Keep your back straight and avoid rounding your shoulders.","Extend your hips fully at the top of the movement, squeezing your glutes.","Lower the weight back down in a controlled manner, keeping tension on your glutes and hamstrings.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps"],"target":"glutes","image":"images/0578-GUT8I22.jpg","gif_url":"videos/0578-GUT8I22.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1300","name":"lever decline chest press","category":"chest","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height and backrest of the leverage machine to a comfortable position.","Sit on the machine with your back against the backrest and your feet flat on the floor.","Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart.","Push the handles forward and away from your body until your arms are fully extended.","Slowly lower the handles back towards your chest, keeping your elbows slightly bent.","Pause for a moment at the bottom, then push the handles back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1300-vsVoPHt.jpg","gif_url":"videos/1300-vsVoPHt.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1253","name":"lever donkey calf raise","category":"lower legs","equipment":"leverage machine","instruction_steps":{"en":["Adjust the leverage machine to the appropriate height for your body.","Position yourself facing the machine, with your toes on the foot platform and your heels hanging off the edge.","Place your hands on the handles or the support bars for stability.","Engage your calves and lift your heels as high as possible, using the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"calves","image":"images/1253-C9LuR4A.jpg","gif_url":"videos/1253-C9LuR4A.gif","attribution":"© Gym visual �� https://gymvisual.com/"},{"id":"0579","name":"lever front pulldown","category":"back","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height and position yourself on the machine with your knees under the pads and your feet flat on the ground.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Sit upright with your chest lifted and your shoulders back, maintaining a slight arch in your lower back.","Engage your lats and pull the handles down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","rhomboids","rear deltoids"],"target":"lats","image":"images/0579-7F1DVzn.jpg","gif_url":"videos/0579-7F1DVzn.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0580","name":"lever gripless shrug","category":"back","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height and position yourself on the leverage machine.","Grasp the handles with your palms facing inwards and your arms fully extended.","Keeping your back straight, exhale and elevate your shoulders as high as possible.","Hold the contraction for a brief moment, then inhale and slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","forearms"],"target":"traps","image":"images/0580-f91FwXG.jpg","gif_url":"videos/0580-f91FwXG.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1439","name":"lever gripless shrug v. 2","category":"back","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height and position yourself on the machine with your back against the pad.","Grasp the handles or bars with an overhand grip, keeping your arms straight.","Keeping your back straight, lift your shoulders up towards your ears as high as possible.","Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","forearms"],"target":"traps","image":"images/1439-cbuFJrn.jpg","gif_url":"videos/1439-cbuFJrn.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2288","name":"lever gripper hands","category":"lower arms","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height and grip the handles of the leverage machine.","Keep your back straight and your feet flat on the ground.","Exhale and squeeze the handles, contracting your forearms.","Hold the contraction for a second, then slowly release and return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","triceps"],"target":"forearms","image":"images/2288-mKwcrHn.jpg","gif_url":"videos/2288-mKwcrHn.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1615","name":"lever hammer grip preacher curl","category":"upper arms","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height and position yourself on the leverage machine.","Place your upper arms on the preacher pad, ensuring your chest is pressed against it.","Grasp the handles with a hammer grip (palms facing each other).","Keeping your upper arms stationary, exhale and curl the handles towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the handles back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1615-OAguZoG.jpg","gif_url":"videos/1615-OAguZoG.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0581","name":"lever high row","category":"back","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height and foot platform to a comfortable position.","Sit on the machine with your chest against the pad and your feet flat on the foot platform.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and engage your core.","Pull the handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","rear deltoids"],"target":"upper back","image":"images/0581-nZZZy9m.jpg","gif_url":"videos/0581-nZZZy9m.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2286","name":"lever hip extension v. 2","category":"upper legs","equipment":"leverage machine","instruction_steps":{"en":["Adjust the machine to fit your body and sit on it with your back against the backrest.","Place your feet on the footrests and grip the handles for stability.","Engage your glutes and hamstrings, then push against the footrests to extend your hips and raise your legs backward.","Pause for a moment at the top, then slowly lower your legs back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"target":"glutes","image":"images/2286-OPqShYN.jpg","gif_url":"videos/2286-OPqShYN.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2611","name":"lever horizontal one leg press","category":"upper legs","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat of the machine so that your knees are at a 90-degree angle when your feet are on the footplate.","Sit on the machine with your back against the backrest and your feet shoulder-width apart on the footplate.","Place your hands on the handles or sides of the machine for stability.","Push the footplate away from your body by extending your leg, keeping your back against the backrest.","Pause for a moment at the fully extended position, then slowly bend your leg to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/2611-9KU9TYF.jpg","gif_url":"videos/2611-9KU9TYF.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1299","name":"lever incline chest press","category":"chest","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat and backrest of the leverage machine to a comfortable position.","Sit on the machine with your back against the backrest and your feet flat on the floor.","Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart.","Push the handles forward and away from your body until your arms are fully extended.","Pause for a moment, then slowly bend your elbows and lower the handles back towards your chest.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/1299-jHAnWmT.jpg","gif_url":"videos/1299-jHAnWmT.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1479","name":"lever incline chest press v. 2","category":"chest","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height and backrest angle on the leverage machine to a comfortable position.","Sit on the machine with your back against the backrest and your feet flat on the floor.","Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart.","Push the handles forward and away from your body until your arms are fully extended, but without locking your elbows.","Pause for a moment at the fully extended position, then slowly bend your elbows and lower the handles back towards your chest.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1479-o17Jfkt.jpg","gif_url":"videos/1479-o17Jfkt.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0582","name":"lever kneeling leg curl","category":"upper legs","equipment":"leverage machine","instruction_steps":{"en":["Adjust the machine to fit your body and select the desired weight.","Kneel on the machine facing downwards, with your knees resting on the pad and your feet secured under the footpads.","Grasp the handles or the sides of the machine for stability.","Keeping your upper body stationary, exhale and curl your legs up towards your glutes by flexing your knees.","Pause for a moment at the top of the movement, squeezing your hamstrings.","Inhale and slowly lower your legs back to the starting position, fully extending your knees.","Repeat for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes"],"target":"hamstrings","image":"images/0582-nnmCTLN.jpg","gif_url":"videos/0582-nnmCTLN.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0583","name":"lever kneeling twist","category":"waist","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height and position yourself on the machine with your knees resting on the pads and your upper body facing forward.","Grasp the handles or the sides of the machine for stability.","Keeping your core engaged, twist your torso to one side as far as comfortably possible.","Pause for a moment, then slowly return to the starting position.","Repeat the twist to the opposite side.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques","lower back"],"target":"abs","image":"images/0583-sZOR9EV.jpg","gif_url":"videos/0583-sZOR9EV.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0584","name":"lever lateral raise","category":"shoulders","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height and position yourself on the machine with your back against the pad.","Grasp the handles with an overhand grip and keep your arms straight.","Exhale and raise your arms out to the sides until they are parallel to the floor.","Pause for a moment at the top, then inhale and slowly lower your arms back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"traps","secondary_muscles":["traps","upper back"],"target":"delts","image":"images/0584-dRTfGZT.jpg","gif_url":"videos/0584-dRTfGZT.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0585","name":"lever leg extension","category":"upper legs","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height and backrest of the machine to fit your body.","Sit on the machine with your back against the backrest and your feet on the footpad.","Grasp the handles or sidebars for stability.","Extend your legs forward by straightening your knees, lifting the weight.","Pause for a moment at the top, then slowly lower the weight back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"target":"quads","image":"images/0585-my33uHU.jpg","gif_url":"videos/0585-my33uHU.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0586","name":"lever lying leg curl","category":"upper legs","equipment":"leverage machine","instruction_steps":{"en":["Adjust the machine to fit your body and select the desired weight.","Lie face down on the machine with your legs straight and your heels against the padded lever.","Grasp the handles or the sides of the machine for stability.","Keeping your upper body stationary, exhale and curl your legs up as far as possible without lifting your hips off the pad.","Hold the contracted position for a brief pause as you squeeze your hamstrings.","Inhale and slowly lower the lever back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"calves","secondary_muscles":["calves"],"target":"hamstrings","image":"images/0586-17lJ1kr.jpg","gif_url":"videos/0586-17lJ1kr.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3195","name":"lever lying two-one leg curl","category":"upper legs","equipment":"leverage machine","instruction_steps":{"en":["Adjust the machine to fit your body and sit on it with your back against the backrest.","Place your legs on the lever pad, just above your ankles.","Grasp the handles on the sides of the machine for support.","Keeping your upper body still, exhale and curl your legs up towards your glutes.","Pause for a moment at the top, then inhale and slowly lower your legs back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes"],"target":"hamstrings","image":"images/3195-UXpKJoq.jpg","gif_url":"videos/3195-UXpKJoq.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0587","name":"lever military press","category":"shoulders","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height and position yourself on the machine with your back against the backrest.","Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart.","Push the handles upward until your arms are fully extended, but do not lock your elbows.","Pause for a moment at the top, then slowly lower the handles back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","upper chest"],"target":"delts","image":"images/0587-CggQhII.jpg","gif_url":"videos/0587-CggQhII.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0588","name":"lever narrow grip seated row","category":"back","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height and footrests to ensure proper form.","Sit on the machine with your feet flat on the footrests and your knees slightly bent.","Grasp the handles with a narrow grip, palms facing each other.","Keep your back straight and lean slightly forward.","Pull the handles towards your torso, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement.","Slowly release the handles and return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0588-IGjKj1v.jpg","gif_url":"videos/0588-IGjKj1v.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0589","name":"lever one arm bent over row","category":"back","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart, knees slightly bent, and hold a barbell with an overhand grip.","Bend forward at the hips, keeping your back straight and your head up.","Let the barbell hang in front of you with your arms fully extended.","Pull the barbell up towards your chest, keeping your elbows close to your body.","Squeeze your shoulder blades together at the top of the movement.","Lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0589-Fhdtwf3.jpg","gif_url":"videos/0589-Fhdtwf3.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1356","name":"lever one arm lateral high row","category":"back","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height and position yourself facing the machine.","Grasp the handle with one hand and keep your back straight.","Pull the handle towards your body, keeping your elbow close to your side.","Squeeze your back muscles at the top of the movement.","Slowly release the handle back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"target":"upper back","image":"images/1356-OIFMAp1.jpg","gif_url":"videos/1356-OIFMAp1.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1347","name":"lever one arm lateral wide pulldown","category":"back","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.","Grasp the handle with an overhand grip and fully extend your arm, keeping a slight bend in your elbow.","Pull the handle down and across your body towards your opposite hip, squeezing your lat muscle at the bottom of the movement.","Slowly return the handle to the starting position, fully extending your arm.","Repeat for the desired number of repetitions, then switch sides."]},"muscle_group":"biceps","secondary_muscles":["biceps","rhomboids","rear deltoids"],"target":"lats","image":"images/1347-tTuZSDT.jpg","gif_url":"videos/1347-tTuZSDT.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0590","name":"lever one arm shoulder press","category":"shoulders","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height and position yourself on the machine with your back against the pad.","Grasp the lever handle with one hand and position your elbow at a 90-degree angle.","Press the lever upward until your arm is fully extended overhead.","Pause for a moment at the top, then slowly lower the lever back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]},"muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0590-2KGnL6M.jpg","gif_url":"videos/0590-2KGnL6M.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0591","name":"lever overhand triceps dip","category":"upper arms","equipment":"leverage machine","instruction_steps":{"en":["Adjust the machine to the appropriate height and secure your body in position.","Grasp the handles with an overhand grip and position your body so that your arms are fully extended.","Lower your body by bending your elbows, keeping your upper arms close to your sides.","Continue lowering until your upper arms are parallel to the floor.","Pause for a moment, then push yourself back up to the starting position by extending your elbows.","Repeat for the desired number of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0591-D5yqP2p.jpg","gif_url":"videos/0591-D5yqP2p.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0592","name":"lever preacher curl","category":"upper arms","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height and position yourself on the leverage machine.","Place your upper arms on the pad and grip the handles with an underhand grip.","Keep your back straight and your elbows positioned on the pad.","Exhale and curl your forearms towards your upper arms, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the handles back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0592-b6hQYMb.jpg","gif_url":"videos/0592-b6hQYMb.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1614","name":"lever preacher curl v. 2","category":"upper arms","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height and position yourself on the machine with your upper arms resting on the pad and your chest against the support.","Grasp the handles with an underhand grip, slightly wider than shoulder-width apart.","Keep your upper arms stationary and exhale as you curl the handles towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale as you slowly lower the handles back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1614-ye84CTU.jpg","gif_url":"videos/1614-ye84CTU.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2285","name":"lever pullover","category":"back","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat and handles of the leverage machine to a comfortable position.","Sit on the machine with your back against the pad and grasp the handles with an overhand grip.","Keep your arms slightly bent and your core engaged.","Slowly pull the handles towards your chest, squeezing your lats.","Pause for a moment at the peak contraction, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"lats","image":"images/2285-4U7iLb5.jpg","gif_url":"videos/2285-4U7iLb5.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2736","name":"lever reverse grip lateral pulldown","category":"back","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height and position yourself on the machine with your knees under the pads and your feet flat on the ground.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Sit upright with your chest out and shoulders back, maintaining a slight arch in your lower back.","Pull the handles down towards your chest, leading with your elbows and squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","rhomboids","rear deltoids"],"target":"lats","image":"images/2736-ky8FLU8.jpg","gif_url":"videos/2736-ky8FLU8.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1616","name":"lever reverse grip preacher curl","category":"upper arms","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height and position yourself on the leverage machine.","Grasp the handles with an underhand grip, palms facing up.","Rest your upper arms on the preacher pad, ensuring your elbows are fully extended.","Keeping your upper arms stationary, exhale and curl the handles towards your shoulders.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the handles back to the starting position, fully extending your elbows.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1616-kj3hy6W.jpg","gif_url":"videos/1616-kj3hy6W.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1348","name":"lever reverse grip vertical row","category":"back","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height and footplate position to ensure proper alignment.","Sit on the machine with your chest against the pad and your feet flat on the footplate.","Grasp the handles with an underhand grip, palms facing up.","Keep your back straight and engage your core.","Pull the handles towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release and extend your arms back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/1348-ZqNOWQ6.jpg","gif_url":"videos/1348-ZqNOWQ6.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0593","name":"lever reverse hyperextension","category":"upper legs","equipment":"leverage machine","instruction_steps":{"en":["Adjust the leverage machine to fit your body and secure your feet in the foot pads.","Lie face down on the machine with your upper body hanging off the edge and your hips resting on the pad.","Cross your arms over your chest or place them behind your head.","Engage your glutes and hamstrings to lift your legs upward until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"target":"glutes","image":"images/0593-Krmb3cB.jpg","gif_url":"videos/0593-Krmb3cB.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1349","name":"lever reverse t-bar row","category":"back","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height and footplate position on the leverage machine.","Sit on the machine with your chest against the pad and your feet flat on the footplate.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and engage your core.","Pull the handles towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release and extend your arms back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/1349-BgljGjd.jpg","gif_url":"videos/1349-BgljGjd.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2315","name":"lever rotary calf","category":"lower legs","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height so that your knees are slightly bent and your feet are flat on the footplate.","Place your toes on the footplate, with your heels hanging off the edge.","Grasp the handles or the sides of the machine for stability.","Push through the balls of your feet, raising your heels as high as possible.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"soleus","secondary_muscles":["soleus","ankle stabilizers"],"target":"calves","image":"images/2315-MrgP9L6.jpg","gif_url":"videos/2315-MrgP9L6.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2335","name":"lever seated calf press","category":"lower legs","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat of the machine so that your shoulders are aligned with the lever pad.","Place your toes on the lower portion of the platform and position your knees under the lever pad.","Grasp the handles on the sides of the seat for stability.","Press the lever pad down by extending your ankles, lifting your heels as high as possible.","Pause for a moment at the top of the movement, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"soleus","secondary_muscles":["soleus","hamstrings"],"target":"calves","image":"images/2335-Ie9UGty.jpg","gif_url":"videos/2335-Ie9UGty.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0594","name":"lever seated calf raise","category":"lower legs","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height so that your knees are slightly bent and your feet are flat on the footplate.","Place your toes on the footplate with your heels hanging off the edge.","Grasp the handles or the sides of the seat for stability.","Push through the balls of your feet to raise your heels as high as possible.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"soleus","secondary_muscles":["soleus","ankle stabilizers"],"target":"calves","image":"images/0594-bOOdeyc.jpg","gif_url":"videos/0594-bOOdeyc.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1452","name":"lever seated crunch","category":"waist","equipment":"leverage machine","instruction_steps":{"en":["Sit on the leverage machine with your back against the pad and your feet flat on the floor.","Grasp the handles or place your hands on the side pads for support.","Engage your abs and slowly lean back, allowing the pad to move with you.","Once your upper body is at a 45-degree angle, contract your abs and crunch forward, bringing your chest towards your knees.","Pause for a moment at the top, then slowly release and return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/1452-Wgaz7pm.jpg","gif_url":"videos/1452-Wgaz7pm.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0595","name":"lever seated crunch (chest pad)","category":"waist","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height and chest pad position according to your comfort.","Sit on the machine with your back against the chest pad and your feet flat on the floor.","Grasp the handles or side bars for stability.","Engage your abs and slowly lean back, allowing the chest pad to move with you.","Pause for a moment at the maximum contraction, feeling the tension in your abs.","Slowly return to the starting position by contracting your abs and pulling yourself back up.","Repeat for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/0595-ZnJHhMk.jpg","gif_url":"videos/0595-ZnJHhMk.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3760","name":"lever seated crunch v. 2","category":"waist","equipment":"leverage machine","instruction_steps":{"en":["Sit on the leverage machine with your back against the pad and your feet secured under the footpads.","Place your hands on the handles or the sides of the seat for support.","Engage your abs and slowly crunch forward, bringing your chest towards your knees.","Pause for a moment at the top of the movement, squeezing your abs.","Slowly return to the starting position, allowing your back to round slightly.","Repeat for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques","hip flexors"],"target":"abs","image":"images/3760-eXFXCY0.jpg","gif_url":"videos/3760-eXFXCY0.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1451","name":"lever seated dip","category":"upper arms","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height so that your feet are flat on the ground and your knees are at a 90-degree angle.","Grasp the handles of the leverage machine with your palms facing down and your arms fully extended.","Slowly lower your body by bending your elbows until your upper arms are parallel to the ground.","Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/1451-BRImeP8.jpg","gif_url":"videos/1451-BRImeP8.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0596","name":"lever seated fly","category":"chest","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height and position yourself on the machine with your back against the pad.","Grasp the handles with a pronated grip and keep your elbows slightly bent.","Exhale and push the handles forward, bringing them together in front of your chest.","Pause for a moment, squeezing your chest muscles.","Inhale and slowly return to the starting position, allowing your chest muscles to stretch.","Repeat for the desired number of repetitions."]},"muscle_group":"deltoids","secondary_muscles":["deltoids","trapezius"],"target":"pectorals","image":"images/0596-v3xmPAR.jpg","gif_url":"videos/0596-v3xmPAR.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3759","name":"lever seated good morning","category":"upper legs","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height so that your hips are slightly higher than your knees.","Sit on the machine with your back against the pad and your feet flat on the footrests.","Grasp the handles or the sides of the seat for stability.","Keeping your back straight, slowly lean forward from your hips until your upper body is parallel to the ground.","Pause for a moment, then slowly return to the starting position by pushing through your glutes and hamstrings.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"target":"glutes","image":"images/3759-XsCcxCC.jpg","gif_url":"videos/3759-XsCcxCC.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0597","name":"lever seated hip abduction","category":"upper legs","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height so that your knees are at a 90-degree angle.","Sit on the machine with your back against the backrest and your feet on the footrests.","Place your hands on the side handles for stability.","Engage your abductors and slowly push your legs apart, away from the midline of your body.","Pause for a moment at the end of the movement, then slowly bring your legs back together to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","hamstrings"],"target":"abductors","image":"images/0597-CHpahtl.jpg","gif_url":"videos/0597-CHpahtl.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0598","name":"lever seated hip adduction","category":"upper legs","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height and position yourself on the machine with your back against the backrest.","Place your feet on the footrests and grasp the handles for stability.","Engage your adductor muscles and slowly bring your legs together, squeezing your inner thighs.","Pause for a moment at the peak contraction, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"adductors","image":"images/0598-oHsrypV.jpg","gif_url":"videos/0598-oHsrypV.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0599","name":"lever seated leg curl","category":"upper legs","equipment":"leverage machine","instruction_steps":{"en":["Adjust the machine to fit your body and sit on it with your back against the backrest.","Place your lower legs under the padded lever, just above your ankles.","Grasp the handles on the sides of the machine for support.","Keeping your upper legs stationary, exhale and curl your legs up as far as possible.","Hold the contracted position for a brief pause as you squeeze your hamstrings.","Inhale and slowly lower the lever back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"calves","secondary_muscles":["calves"],"target":"hamstrings","image":"images/0599-Zg3XY7P.jpg","gif_url":"videos/0599-Zg3XY7P.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0600","name":"lever seated leg raise crunch","category":"waist","equipment":"leverage machine","instruction_steps":{"en":["Sit on the leverage machine with your back against the backrest and your feet on the footrests.","Grasp the handles or sidebars for stability.","Engage your abs and slowly raise your legs up towards your chest, curling your torso forward at the same time.","Pause for a moment at the top, then slowly lower your legs and torso back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0600-PQ2AtC3.jpg","gif_url":"videos/0600-PQ2AtC3.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0602","name":"lever seated reverse fly","category":"shoulders","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.","Grasp the handles with an overhand grip and keep your arms slightly bent.","Exhale and squeeze your shoulder blades together as you pull the handles back and outward, away from your body.","Pause for a moment at the peak contraction, then inhale and slowly return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids"],"target":"delts","image":"images/0602-myfUsKf.jpg","gif_url":"videos/0602-myfUsKf.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0601","name":"lever seated reverse fly (parallel grip)","category":"shoulders","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.","Grasp the handles with a parallel grip, palms facing each other, and keep your arms slightly bent.","Exhale and squeeze your shoulder blades together as you pull the handles back and outward, away from your body.","Pause for a moment at the peak contraction, then inhale and slowly return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids"],"target":"delts","image":"images/0601-xiHiJcA.jpg","gif_url":"videos/0601-xiHiJcA.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1350","name":"lever seated row","category":"back","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height and footrests to a comfortable position.","Sit on the machine with your chest against the pad and your feet on the footrests.","Grasp the handles with an overhand grip, shoulder-width apart.","Keep your back straight and your core engaged.","Pull the handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement.","Slowly release the handles and return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/1350-7I6LNUG.jpg","gif_url":"videos/1350-7I6LNUG.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1385","name":"lever seated squat calf raise on leg press machine","category":"lower legs","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the footplate.","Sit on the machine with your back against the backrest and your feet flat on the footplate, shoulder-width apart.","Place your toes and the balls of your feet on the footplate, keeping your heels off the edge.","Release the safety handles and push the footplate away from you by extending your knees.","Once your knees are fully extended, slowly lower your heels by flexing your calves.","Pause for a moment at the bottom, then push the footplate back up by extending your calves.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","glutes"],"target":"calves","image":"images/1385-IeDEXTe.jpg","gif_url":"videos/1385-IeDEXTe.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0603","name":"lever shoulder press","category":"shoulders","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height and position yourself on the machine with your back against the backrest.","Grasp the handles with an overhand grip and position your hands at shoulder level.","Push the handles upward until your arms are fully extended, but do not lock your elbows.","Pause for a moment at the top, then slowly lower the handles back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","chest"],"target":"delts","image":"images/0603-67n3r98.jpg","gif_url":"videos/0603-67n3r98.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0869","name":"lever shoulder press v. 2","category":"shoulders","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height and backrest of the leverage machine to a comfortable position.","Sit on the machine with your back against the backrest and your feet flat on the floor.","Grasp the handles of the machine with an overhand grip, slightly wider than shoulder-width apart.","Push the handles upward and forward until your arms are fully extended, but not locked.","Pause for a moment at the top, then slowly lower the handles back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","chest"],"target":"delts","image":"images/0869-vqsbmL0.jpg","gif_url":"videos/0869-vqsbmL0.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2318","name":"lever shoulder press v. 3","category":"shoulders","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height and backrest of the leverage machine to a comfortable position.","Sit on the machine with your back against the backrest and your feet flat on the floor.","Grasp the handles of the machine with an overhand grip, slightly wider than shoulder-width apart.","Push the handles upward and forward until your arms are fully extended, but not locked.","Pause for a moment at the top, then slowly lower the handles back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","chest"],"target":"delts","image":"images/2318-dNFYIU1.jpg","gif_url":"videos/2318-dNFYIU1.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0604","name":"lever shrug","category":"back","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height and position yourself on the leverage machine with your back against the pad.","Grasp the handles with an overhand grip and keep your arms straight.","Keeping your back straight, lift your shoulders up towards your ears as high as possible.","Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"traps","image":"images/0604-ZZKbeMw.jpg","gif_url":"videos/0604-ZZKbeMw.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0605","name":"lever standing calf raise","category":"lower legs","equipment":"leverage machine","instruction_steps":{"en":["Adjust the machine to your height and stand with your feet shoulder-width apart.","Place your shoulders under the pads and hold onto the handles for stability.","Raise your heels as high as possible by extending your ankles.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"soleus","secondary_muscles":["soleus","ankle stabilizers"],"target":"calves","image":"images/0605-ykUOVze.jpg","gif_url":"videos/0605-ykUOVze.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3758","name":"lever standing chest press","category":"chest","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height and position yourself on the machine with your feet flat on the ground.","Grasp the handles with an overhand grip and position your hands at chest level.","Push the handles forward until your arms are fully extended, keeping your elbows slightly bent.","Pause for a moment, then slowly bring the handles back towards your chest, maintaining control throughout the movement.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/3758-WbNq5Xu.jpg","gif_url":"videos/3758-WbNq5Xu.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0606","name":"lever t bar row","category":"back","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height and footplate position to ensure proper alignment.","Sit on the machine with your chest against the pad and your feet flat on the footplate.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and engage your core.","Pull the handles towards your torso, squeezing your shoulder blades together.","Pause for a moment at the peak contraction, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/0606-aaXr7ld.jpg","gif_url":"videos/0606-aaXr7ld.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1351","name":"lever t-bar reverse grip row","category":"back","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and engage your core.","Pull the handles towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release and extend your arms back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/1351-FVM1AUZ.jpg","gif_url":"videos/1351-FVM1AUZ.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0607","name":"lever triceps extension","category":"upper arms","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height and position yourself on the machine with your back against the pad.","Grasp the handles with an overhand grip and fully extend your arms in front of you.","Keeping your upper arms stationary, slowly lower the handles towards your forehead by bending your elbows.","Pause for a moment at the bottom, then push the handles back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0607-Ser9eQp.jpg","gif_url":"videos/0607-Ser9eQp.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1313","name":"lever unilateral row","category":"back","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height and position yourself facing the machine.","Grasp the handles with an overhand grip and keep your back straight.","Pull the handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release and extend your arms back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/1313-oROuvrX.jpg","gif_url":"videos/1313-oROuvrX.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0609","name":"london bridge","category":"back","equipment":"rope","instruction_steps":{"en":["Attach the rope to a high anchor point.","Stand facing away from the anchor point with your feet shoulder-width apart.","Grasp the rope with an overhand grip, palms facing down.","Lean forward slightly, keeping your back straight and core engaged.","Pull the rope towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","biceps","forearms"],"target":"upper back","image":"images/0609-bLyQokI.jpg","gif_url":"videos/0609-bLyQokI.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3013","name":"low glute bridge on floor","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your arms by your sides, palms facing down.","Engage your glutes and core, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders.","Pause for a moment at the top, squeezing your glutes.","Slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","core"],"target":"glutes","image":"images/3013-u0cNiij.jpg","gif_url":"videos/3013-u0cNiij.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1352","name":"lower back curl","category":"back","equipment":"body weight","instruction_steps":{"en":["Lie flat on your stomach with your legs extended and your arms by your sides.","Engage your glutes and hamstrings, and slowly lift your upper body off the ground, curling your back upwards.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","hamstrings"],"target":"spine","image":"images/1352-ANbbry2.jpg","gif_url":"videos/1352-ANbbry2.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3582","name":"lunge with jump","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Start by standing with your feet shoulder-width apart.","Take a step forward with your right foot, lowering your body into a lunge position.","Push off with your right foot and jump into the air, switching the position of your feet mid-air.","Land softly with your left foot forward and immediately lower your body into a lunge position.","Continue alternating between lunges and jumps for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/3582-PM1PZjg.jpg","gif_url":"videos/3582-PM1PZjg.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1688","name":"lunge with twist","category":"waist","equipment":"body weight","instruction_steps":{"en":["Start by standing with your feet shoulder-width apart.","Take a step forward with your right foot, lowering your body into a lunge position.","As you lunge, twist your torso to the right, bringing your left elbow towards your right knee.","Pause for a moment, then return to the starting position.","Repeat on the other side, stepping forward with your left foot and twisting your torso to the left.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","glutes","hamstrings"],"target":"abs","image":"images/1688-K9VL0Jq.jpg","gif_url":"videos/1688-K9VL0Jq.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0613","name":"lying (side) quads stretch","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Lie on your side with your legs straight.","Bend your top leg and grab your ankle or foot with your hand.","Gently pull your ankle or foot towards your glutes until you feel a stretch in your quads.","Hold the stretch for 20-30 seconds.","Release the stretch and repeat on the other side."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"target":"quads","image":"images/0613-BWnJR72.jpg","gif_url":"videos/0613-BWnJR72.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2312","name":"lying elbow to knee","category":"waist","equipment":"body weight","instruction_steps":{"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engage your abs and lift your upper body off the ground, bringing your right elbow towards your left knee.","At the same time, extend your right leg straight out and lift it off the ground.","Pause for a moment, then return to the starting position.","Repeat the movement, this time bringing your left elbow towards your right knee and extending your left leg.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors","lower back"],"target":"abs","image":"images/2312-AQIhRjM.jpg","gif_url":"videos/2312-AQIhRjM.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0620","name":"lying leg raise flat bench","category":"waist","equipment":"body weight","instruction_steps":{"en":["Lie flat on a flat bench with your back pressed against it.","Place your hands under your glutes for support.","Keep your legs straight and together, and lift them up towards the ceiling.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0620-WhuFnR7.jpg","gif_url":"videos/0620-WhuFnR7.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0865","name":"lying leg-hip raise","category":"waist","equipment":"body weight","instruction_steps":{"en":["Lie flat on your back with your legs extended and your arms by your sides.","Place your hands under your glutes for support.","Engage your core and lift your legs off the ground, raising them towards the ceiling.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0865-9IxJdtC.jpg","gif_url":"videos/0865-9IxJdtC.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1301","name":"machine inner chest press","category":"chest","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height and position yourself on the machine with your back flat against the pad.","Grasp the handles with an overhand grip and position your elbows at a 90-degree angle.","Push the handles forward until your arms are fully extended, exhaling during the movement.","Pause for a moment at the end of the movement, then slowly return to the starting position, inhaling as you do so.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1301-wDN97Ca.jpg","gif_url":"videos/1301-wDN97Ca.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0624","name":"march sit (wall)","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Stand with your back against a wall and your feet hip-width apart.","Slowly slide your back down the wall until your knees are bent at a 90-degree angle.","Lift your right foot off the ground and bring your knee towards your chest.","Lower your right foot back down and lift your left foot off the ground, bringing your knee towards your chest.","Continue alternating between lifting your right and left foot for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0624-sVQCCeG.jpg","gif_url":"videos/0624-sVQCCeG.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1353","name":"medicine ball catch and overhead throw","category":"back","equipment":"medicine ball","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a medicine ball in both hands at chest level.","Bend your knees slightly and engage your core.","Lower your body into a squat position, keeping your back straight and chest up.","Explosively extend your hips and legs, while simultaneously throwing the medicine ball overhead.","Release the ball at the top of the movement and catch it on the way down.","Lower your body back into the squat position and repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","core"],"target":"lats","image":"images/1353-PsVS1QP.jpg","gif_url":"videos/1353-PsVS1QP.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1302","name":"medicine ball chest pass","category":"chest","equipment":"medicine ball","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding the medicine ball at chest level.","Extend your arms forward, pushing the medicine ball away from your chest with force.","As you release the ball, follow through with your arms and torso, transferring your weight from your back foot to your front foot.","Catch the ball as it rebounds off the wall or partner, and immediately repeat the movement.","Continue for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/1302-aDoFKrE.jpg","gif_url":"videos/1302-aDoFKrE.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1303","name":"medicine ball chest push from 3 point stance","category":"chest","equipment":"medicine ball","instruction_steps":{"en":["Start in a 3 point stance with one hand on the medicine ball and the other hand on the ground.","Extend your legs and position your body in a straight line.","Lower your chest towards the ground while keeping your back straight.","Push the medicine ball away from your body, extending your arm fully.","Return to the starting position and repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/1303-dCJnuVq.jpg","gif_url":"videos/1303-dCJnuVq.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1304","name":"medicine ball chest push multiple response","category":"chest","equipment":"medicine ball","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a medicine ball at chest level.","Extend your arms forward, pushing the medicine ball away from your chest.","Pause for a moment, then slowly bring the medicine ball back to your chest.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1304-7aolH9D.jpg","gif_url":"videos/1304-7aolH9D.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1305","name":"medicine ball chest push single response","category":"chest","equipment":"medicine ball","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding the medicine ball at chest level.","Extend your arms forward, pushing the medicine ball away from your chest.","Pause for a moment, then slowly bring the medicine ball back to your chest.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1305-jeHtrlO.jpg","gif_url":"videos/1305-jeHtrlO.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1312","name":"medicine ball chest push with run release","category":"chest","equipment":"medicine ball","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a medicine ball at chest level.","Step forward with your right foot and simultaneously push the medicine ball forward, extending your arms fully.","As you push the ball forward, release it and let it roll forward.","Quickly run forward and catch the ball before it hits the ground.","Once you catch the ball, bring it back to your chest and repeat the movement with your left foot forward.","Continue alternating legs and repeating the exercise for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders","core"],"target":"pectorals","image":"images/1312-pX9Elbe.jpg","gif_url":"videos/1312-pX9Elbe.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1701","name":"medicine ball close grip push up","category":"upper arms","equipment":"medicine ball","instruction_steps":{"en":["Start in a high plank position with your hands on the medicine ball, shoulder-width apart.","Lower your body towards the ground by bending your elbows, keeping them close to your sides.","Push back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/1701-8K7m2SS.jpg","gif_url":"videos/1701-8K7m2SS.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1354","name":"medicine ball overhead slam","category":"back","equipment":"medicine ball","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a medicine ball with both hands above your head.","Engage your core and keep your back straight.","Bend your knees slightly and forcefully slam the medicine ball down to the ground in front of you.","As you slam the ball down, use your entire body to generate power, including your shoulders and core.","Catch the ball on the bounce and repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","core"],"target":"upper back","image":"images/1354-oHg8eop.jpg","gif_url":"videos/1354-oHg8eop.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1750","name":"medicine ball supine chest throw","category":"upper arms","equipment":"medicine ball","instruction_steps":{"en":["Lie flat on your back on a bench with your knees bent and feet flat on the ground.","Hold the medicine ball with both hands, extending your arms straight up above your chest.","Lower the medicine ball towards your chest, keeping your elbows close to your body.","Explosively push the medicine ball upwards, extending your arms fully and throwing the ball as high as possible.","Catch the medicine ball and repeat for the desired number of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/1750-Al3tP0D.jpg","gif_url":"videos/1750-Al3tP0D.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0627","name":"mixed grip chin-up","category":"back","equipment":"body weight","instruction_steps":{"en":["Grab the pull-up bar with an underhand grip (palms facing towards you) and your hands slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your feet off the ground.","Engage your back muscles and pull your body up towards the bar, leading with your chest.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position with control.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/0627-T8UpLkb.jpg","gif_url":"videos/0627-T8UpLkb.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3217","name":"modified hindu push-up (male)","category":"chest","equipment":"body weight","instruction_steps":{"en":["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet hip-width apart.","Lower your body towards the ground, bending your elbows and keeping your core engaged.","As you lower your body, shift your weight back and lift your hips up towards the ceiling, creating an inverted V shape with your body.","Continue to lower your body until your chest is just above the ground, then reverse the movement, pushing your hips back down and extending your arms to return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders","core"],"target":"pectorals","image":"images/3217-epOSYUZ.jpg","gif_url":"videos/3217-epOSYUZ.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1421","name":"modified push up to lower arms","category":"lower arms","equipment":"body weight","instruction_steps":{"en":["Start in a push-up position with your hands directly under your shoulders and your body in a straight line.","Lower your body down towards the ground by bending your elbows, keeping them close to your sides.","Once your elbows are at a 90-degree angle, lower your forearms to the ground, keeping your elbows directly under your shoulders.","Pause for a moment, then push through your palms to lift your forearms back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","chest","shoulders"],"target":"forearms","image":"images/1421-arvaszz.jpg","gif_url":"videos/1421-arvaszz.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0628","name":"monster walk","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Place a resistance band around your ankles.","Stand with your feet shoulder-width apart and slightly bend your knees.","Take a step to the side with your right foot, maintaining tension on the resistance band.","Follow with your left foot, stepping to the side to return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps"],"target":"glutes","image":"images/0628-O95afRA.jpg","gif_url":"videos/0628-O95afRA.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0630","name":"mountain climber","category":"cardio","equipment":"body weight","instruction_steps":{"en":["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.","Engage your core and bring your right knee towards your chest, then quickly switch and bring your left knee towards your chest.","Continue alternating legs in a running motion, keeping your hips low and your core engaged.","Maintain a steady pace and breathe evenly throughout the exercise.","Repeat for the desired number of repetitions."]},"muscle_group":"core","secondary_muscles":["core","shoulders","triceps"],"target":"cardiovascular system","image":"images/0630-RJgzwny.jpg","gif_url":"videos/0630-RJgzwny.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0631","name":"muscle up","category":"back","equipment":"body weight","instruction_steps":{"en":["Start by hanging from a pull-up bar with your palms facing away from you and your arms fully extended.","Engage your core and pull your body up towards the bar, leading with your chest.","As you reach the top of the movement, transition your grip so that your palms are facing towards you.","Continue pulling yourself up until your chest is above the bar and your arms are fully flexed.","Reverse the movement by slowly lowering yourself back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","triceps","shoulders","chest"],"target":"lats","image":"images/0631-yJUHKTn.jpg","gif_url":"videos/0631-yJUHKTn.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1401","name":"muscle-up (on vertical bar)","category":"back","equipment":"body weight","instruction_steps":{"en":["Start by hanging from a vertical bar with your palms facing away from you and your arms fully extended.","Engage your core and pull your body up towards the bar, leading with your chest.","As you pull yourself up, lean back slightly and bring your elbows towards your sides.","Continue pulling until your chest reaches the bar and your elbows are fully bent.","Pause for a moment at the top, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","triceps","forearms"],"target":"lats","image":"images/1401-Af0EW2I.jpg","gif_url":"videos/1401-Af0EW2I.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2328","name":"narrow push-up on exercise ball","category":"upper arms","equipment":"stability ball","instruction_steps":{"en":["Place the stability ball on the ground and position yourself in a push-up position with your hands on the ball, slightly narrower than shoulder-width apart.","Engage your core and keep your body in a straight line from head to toe.","Lower your chest towards the ball by bending your elbows, keeping them close to your body.","Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/2328-4cWjYEN.jpg","gif_url":"videos/2328-4cWjYEN.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1403","name":"neck side stretch","category":"neck","equipment":"body weight","instruction_steps":{"en":["Stand or sit up straight with your shoulders relaxed.","Tilt your head to one side, bringing your ear towards your shoulder.","Hold the stretch for 15-30 seconds.","Repeat on the other side.","Perform 2-4 sets on each side."]},"muscle_group":"trapezius","secondary_muscles":["trapezius","sternocleidomastoid"],"target":"levator scapulae","image":"images/1403-x2chWLO.jpg","gif_url":"videos/1403-x2chWLO.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0634","name":"negative crunch","category":"waist","equipment":"body weight","instruction_steps":{"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0634-szIn2UK.jpg","gif_url":"videos/0634-szIn2UK.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1495","name":"oblique crunch v. 2","category":"waist","equipment":"body weight","instruction_steps":{"en":["Lie on your back with your knees bent and feet flat on the ground.","Place your hands behind your head or cross them over your chest.","Engage your abs and lift your shoulder blades off the ground, rotating your torso to one side.","Pause for a moment, then lower your shoulder blades back down to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/1495-cJgSTmh.jpg","gif_url":"videos/1495-cJgSTmh.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0635","name":"oblique crunches floor","category":"waist","equipment":"body weight","instruction_steps":{"en":["Lie on your back with your knees bent and feet flat on the floor.","Place your hands behind your head or cross them over your chest.","Engage your abs and lift your shoulder blades off the floor, rotating your torso to one side.","Pause for a moment, then lower your shoulder blades back down to the floor.","Repeat on the other side, alternating sides with each repetition."]},"muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/0635-QUDd8WS.jpg","gif_url":"videos/0635-QUDd8WS.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0636","name":"olympic barbell hammer curl","category":"upper arms","equipment":"olympic barbell","instruction_steps":{"en":["Stand up straight with your feet shoulder-width apart and hold an Olympic barbell with an overhand grip.","Let the barbell hang at arm's length in front of your thighs, with your palms facing your body.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the barbell back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0636-o1ntciW.jpg","gif_url":"videos/0636-o1ntciW.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0637","name":"olympic barbell triceps extension","category":"upper arms","equipment":"olympic barbell","instruction_steps":{"en":["Start by standing with your feet shoulder-width apart and holding the barbell with an overhand grip.","Raise the barbell above your head, fully extending your arms.","Keeping your upper arms close to your head, slowly lower the barbell behind your head by bending your elbows.","Pause for a moment, then extend your arms back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0637-wu5LXwz.jpg","gif_url":"videos/0637-wu5LXwz.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1355","name":"one arm against wall","category":"back","equipment":"body weight","instruction_steps":{"en":["Stand facing a wall with your feet shoulder-width apart.","Extend one arm straight out in front of you and place your palm against the wall.","Engage your core and lean your body forward, keeping your arm straight and your back flat.","Slowly push against the wall with your palm, activating your lat muscles.","Hold the position for a few seconds, then release and repeat with the other arm."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"lats","image":"images/1355-ZZTGMKh.jpg","gif_url":"videos/1355-ZZTGMKh.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0638","name":"one arm chin-up","category":"back","equipment":"body weight","instruction_steps":{"en":["Stand facing a pull-up bar with your feet shoulder-width apart.","Reach up and grab the bar with an underhand grip, with one hand gripping the bar and the other hand holding your wrist for support.","Hang from the bar with your arm fully extended, keeping your body straight and your core engaged.","Pull yourself up towards the bar by bending your elbow and squeezing your back muscles.","Continue pulling until your chin is above the bar, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions, then switch arms and repeat."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/0638-HjdqmZa.jpg","gif_url":"videos/0638-HjdqmZa.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0639","name":"one arm dip","category":"upper arms","equipment":"body weight","instruction_steps":{"en":["Stand facing away from a bench or chair, with your feet shoulder-width apart.","Place one hand on the bench or chair behind you, fingers pointing towards your body.","Extend your legs out in front of you, keeping your heels on the ground.","Bend your elbows and lower your body towards the ground, keeping your back close to the bench or chair.","Pause for a moment at the bottom, then push through your palms to straighten your arms and return to the starting position.","Repeat for the desired number of repetitions, then switch sides and repeat with the other arm."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0639-FAoIFMw.jpg","gif_url":"videos/0639-FAoIFMw.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0640","name":"one arm slam (with medicine ball)","category":"waist","equipment":"medicine ball","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding the medicine ball with one hand in front of your waist.","Bend your knees slightly and engage your core.","Raise the medicine ball above your head, fully extending your arm.","Forcefully slam the medicine ball down to the ground, using your core and shoulders to generate power.","Catch the medicine ball on the bounce and repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","back"],"target":"abs","image":"images/0640-jCrtE9b.jpg","gif_url":"videos/0640-jCrtE9b.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1773","name":"one arm towel row","category":"back","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart, knees slightly bent, and hold a towel with one hand.","Bend forward at the waist, keeping your back straight and your core engaged.","Extend your arm fully, allowing the towel to hang in front of you.","Pull the towel towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the towel back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/1773-bKWbrTA.jpg","gif_url":"videos/1773-bKWbrTA.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1386","name":"one leg donkey calf raise","category":"lower legs","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart, toes pointing forward.","Place your hands on a stable surface for support, such as a wall or a bar.","Lift one leg off the ground, keeping your knee slightly bent.","Raise your heel as high as possible, using your calf muscles.","Pause for a moment at the top, then slowly lower your heel back down.","Repeat for the desired number of repetitions, then switch legs."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"calves","image":"images/1386-A2upspL.jpg","gif_url":"videos/1386-A2upspL.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1387","name":"one leg floor calf raise","category":"lower legs","equipment":"body weight","instruction_steps":{"en":["Stand with your feet hip-width apart and place your hands on a wall or sturdy object for balance.","Lift one foot off the ground and balance on the other foot.","Slowly raise your heel off the ground, lifting your body up onto the ball of your foot.","Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."]},"muscle_group":"ankles","secondary_muscles":["ankles","feet"],"target":"calves","image":"images/1387-0jp9Rlz.jpg","gif_url":"videos/1387-0jp9Rlz.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1476","name":"one leg squat","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart.","Extend one leg forward, keeping it off the ground.","Bend your standing leg and lower your body down as if sitting back into a chair.","Keep your chest up and your back straight.","Push through your heel to return to the starting position.","Repeat with the other leg."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/1476-C31LMnP.jpg","gif_url":"videos/1476-C31LMnP.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0641","name":"otis up","category":"waist","equipment":"weighted","instruction_steps":{"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors","lower back"],"target":"abs","image":"images/0641-UVL20oz.jpg","gif_url":"videos/0641-UVL20oz.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0642","name":"outside leg kick push-up","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.","Lower your body towards the ground by bending your elbows, keeping your back straight and core engaged.","As you push back up, kick one leg out to the side, extending it fully and engaging your glutes.","Return your leg to the starting position and repeat the push-up, alternating legs with each repetition.","Continue alternating leg kicks and push-ups for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0642-jNU1gFQ.jpg","gif_url":"videos/0642-jNU1gFQ.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0643","name":"overhead triceps stretch","category":"upper arms","equipment":"body weight","instruction_steps":{"en":["Stand or sit upright with your feet shoulder-width apart.","Extend one arm overhead, bending at the elbow so that your hand reaches towards the opposite shoulder blade.","With your other hand, gently pull the elbow of the extended arm towards the opposite side of your head, feeling a stretch in your triceps.","Hold the stretch for 15-30 seconds, then release.","Repeat on the other side."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0643-Z5YStHW.jpg","gif_url":"videos/0643-Z5YStHW.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3147","name":"pelvic tilt","category":"waist","equipment":"body weight","instruction_steps":{"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands by your sides.","Engage your abs and tilt your pelvis upward, pressing your lower back into the ground.","Hold this position for a few seconds, focusing on contracting your abs.","Release the tilt and return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"lower back","secondary_muscles":["lower back"],"target":"abs","image":"images/3147-NKJ8o6x.jpg","gif_url":"videos/3147-NKJ8o6x.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1422","name":"pelvic tilt into bridge","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Lie on your back with your knees bent and feet flat on the ground.","Place your arms by your sides with your palms facing down.","Engage your glutes and core muscles.","Tilt your pelvis upward, lifting your hips off the ground.","Hold the bridge position for a few seconds.","Slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","core"],"target":"glutes","image":"images/1422-D9qe7CM.jpg","gif_url":"videos/1422-D9qe7CM.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1388","name":"peroneals stretch","category":"lower legs","equipment":"rope","instruction_steps":{"en":["Sit on the ground with your legs extended in front of you.","Loop the rope around the ball of your foot and hold the ends of the rope with your hands.","Gently pull the rope towards you, flexing your foot and stretching your calf muscles.","Hold the stretch for 15-30 seconds.","Release the tension on the rope and repeat the stretch on the other leg.","Repeat for the desired number of repetitions."]},"muscle_group":"ankles","secondary_muscles":["ankles","feet"],"target":"calves","image":"images/1388-XhfS1DZ.jpg","gif_url":"videos/1388-XhfS1DZ.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3662","name":"pike-to-cobra push-up","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.","Engage your core and lift your hips up towards the ceiling, forming an inverted V shape with your body.","Lower your upper body towards the ground by bending your elbows, keeping them close to your body.","As you lower down, shift your weight forward and transition into a cobra pose by straightening your arms and lifting your chest up.","Reverse the movement by bending your elbows and lowering your chest back down towards the ground.","Push through your hands to return to the inverted V position.","Continue the movement by lowering your hips back down towards the ground, returning to the starting push-up position.","Repeat for the desired number of repetitions."]},"muscle_group":"core","secondary_muscles":["core","shoulders","triceps"],"target":"glutes","image":"images/3662-XPUDTt7.jpg","gif_url":"videos/3662-XPUDTt7.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1306","name":"plyo push up","category":"chest","equipment":"body weight","instruction_steps":{"en":["Start in a high plank position with your hands slightly wider than shoulder-width apart.","Lower your chest towards the ground by bending your elbows, keeping your body in a straight line.","Push explosively off the ground, using your chest muscles to propel your upper body off the ground.","Land softly with your hands back in the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders","core"],"target":"pectorals","image":"images/1306-Snj1wSv.jpg","gif_url":"videos/1306-Snj1wSv.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1687","name":"posterior step to overhead reach","category":"waist","equipment":"body weight","instruction_steps":{"en":["Stand with your feet hip-width apart and your arms by your sides.","Take a step back with your right foot, landing on the ball of your foot.","Bend your left knee and lower your body into a lunge position.","As you lower into the lunge, simultaneously reach your arms overhead.","Pause for a moment at the bottom of the lunge, then return to the starting position by pushing through your left heel and bringing your right foot forward.","Repeat the movement on the other side, stepping back with your left foot and bending your right knee.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","quadriceps","shoulders"],"target":"abs","image":"images/1687-ErqK3UL.jpg","gif_url":"videos/1687-ErqK3UL.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1389","name":"posterior tibialis stretch","category":"lower legs","equipment":"rope","instruction_steps":{"en":["Sit on the ground with your legs extended in front of you.","Loop the rope around the ball of your foot and hold the ends of the rope with your hands.","Gently pull the rope towards you, flexing your foot and stretching your calf muscles.","Hold the stretch for 20-30 seconds.","Release the tension on the rope and relax your foot.","Repeat the stretch on the other leg."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps"],"target":"calves","image":"images/1389-DEEqoI2.jpg","gif_url":"videos/1389-DEEqoI2.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3119","name":"potty squat","category":"waist","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart, toes pointing slightly outward.","Lower your body down by bending your knees and pushing your hips back as if you were sitting on a chair.","Keep your chest up and your back straight throughout the movement.","Lower yourself until your thighs are parallel to the ground or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","glutes"],"target":"abs","image":"images/3119-75Bgtjy.jpg","gif_url":"videos/3119-75Bgtjy.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3132","name":"potty squat with support","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart, toes pointing slightly outward.","Hold onto a stable support, such as a chair or wall, for balance.","Lower your body down into a squat position by bending your knees and pushing your hips back.","Keep your chest up and your back straight throughout the movement.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/3132-b63ZzGe.jpg","gif_url":"videos/3132-b63ZzGe.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0648","name":"power clean","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Start with the barbell on the ground in front of you, with your feet shoulder-width apart.","Bend down and grip the barbell with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and chest up as you lift the barbell off the ground, extending your hips and knees.","As the barbell reaches your mid-thigh, explosively pull it upwards, shrugging your shoulders and pulling your elbows high and to the sides.","As the barbell reaches its highest point, quickly drop underneath it, rotating your elbows around and catching the barbell on your shoulders in a front squat position.","Stand up with the barbell, fully extending your hips and knees.","Lower the barbell back down to the starting position, keeping control of the weight throughout the movement.","Repeat for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","quadriceps","calves"],"target":"hamstrings","image":"images/0648-SiWCcTN.jpg","gif_url":"videos/0648-SiWCcTN.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3665","name":"power point plank","category":"waist","equipment":"body weight","instruction_steps":{"en":["Start in a high plank position with your hands directly under your shoulders and your body in a straight line from head to toe.","Engage your core and squeeze your glutes to maintain a stable position.","Lower your body down onto your forearms, one arm at a time, maintaining a straight line from head to toe.","Hold this position for the desired amount of time, keeping your core and glutes engaged.","To return to the starting position, push through your forearms and lift your body back up into a high plank position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps","glutes"],"target":"abs","image":"images/3665-hCjGsRQ.jpg","gif_url":"videos/3665-hCjGsRQ.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3203","name":"prisoner half sit-up (male)","category":"waist","equipment":"body weight","instruction_steps":{"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/3203-mgejmGP.jpg","gif_url":"videos/3203-mgejmGP.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1707","name":"prone twist on stability ball","category":"waist","equipment":"stability ball","instruction_steps":{"en":["Start by lying face down on a stability ball with your feet shoulder-width apart and your toes touching the ground.","Place your hands behind your head or cross them over your chest.","Engage your core muscles and slowly lift your upper body off the ball, keeping your back straight.","Rotate your torso to one side, bringing your shoulder towards your hip. Keep your hips and legs stable throughout the movement.","Pause for a moment, then return to the starting position.","Repeat the rotation to the other side.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques","lower back"],"target":"abs","image":"images/1707-1IG6gVF.jpg","gif_url":"videos/1707-1IG6gVF.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0651","name":"pull up (neutral grip)","category":"back","equipment":"body weight","instruction_steps":{"en":["Hang from a pull-up bar with a neutral grip (palms facing each other) and your arms fully extended.","Engage your core and squeeze your shoulder blades together.","Pull your body up towards the bar by bending your elbows and driving your elbows down towards your hips.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position with control.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/0651-0V2YQjW.jpg","gif_url":"videos/0651-0V2YQjW.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0650","name":"pull-in (on stability ball)","category":"waist","equipment":"stability ball","instruction_steps":{"en":["Start by sitting on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Place your hands on the sides of the stability ball for support.","Engage your abs and slowly roll your hips forward, bringing your knees towards your chest.","Pause for a moment at the top of the movement, then slowly extend your legs back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0650-UQr48Oi.jpg","gif_url":"videos/0650-UQr48Oi.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0652","name":"pull-up","category":"back","equipment":"body weight","instruction_steps":{"en":["Hang from a pull-up bar with your palms facing away from you and your arms fully extended.","Engage your core and squeeze your shoulder blades together.","Pull your body up towards the bar by bending your elbows and bringing your chest towards the bar.","Pause at the top of the movement, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/0652-lBDjFxJ.jpg","gif_url":"videos/0652-lBDjFxJ.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1689","name":"push and pull bodyweight","category":"chest","equipment":"body weight","instruction_steps":{"en":["Start in a push-up position with your hands slightly wider than shoulder-width apart and your body in a straight line.","Lower your chest towards the ground by bending your elbows, keeping your body straight.","Push through your palms to extend your arms and return to the starting position.","From the push-up position, pull your chest towards the ground by bending your elbows, keeping your body straight.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","deltoids"],"target":"pectorals","image":"images/1689-wXvUZC8.jpg","gif_url":"videos/1689-wXvUZC8.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3638","name":"push to run","category":"cardio","equipment":"body weight","instruction_steps":{"en":["Start in a push-up position with your hands shoulder-width apart and your body in a straight line.","Lower your chest towards the ground by bending your elbows, keeping your body straight.","Push through your hands to extend your arms and return to the starting position.","Quickly bring one knee towards your chest, then quickly switch and bring the other knee towards your chest.","Continue alternating knees as fast as you can while maintaining good form.","Continue for the desired duration or number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"cardiovascular system","image":"images/3638-PrQbjvB.jpg","gif_url":"videos/3638-PrQbjvB.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1307","name":"push up on bosu ball","category":"chest","equipment":"bosu ball","instruction_steps":{"en":["Place the bosu ball on the ground with the flat side facing up.","Position yourself in a push-up position with your hands on the outer edges of the bosu ball.","Engage your core and lower your body down towards the bosu ball by bending your elbows.","Push yourself back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders","core"],"target":"pectorals","image":"images/1307-wVompEp.jpg","gif_url":"videos/1307-wVompEp.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0662","name":"push-up","category":"chest","equipment":"body weight","instruction_steps":{"en":["Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together.","Engage your core and lower your body towards the ground by bending your elbows, keeping your body in a straight line.","Pause for a moment when your chest is just above the ground, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","deltoids","core"],"target":"pectorals","image":"images/0662-I4hDWkc.jpg","gif_url":"videos/0662-I4hDWkc.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0653","name":"push-up (bosu ball)","category":"chest","equipment":"bosu ball","instruction_steps":{"en":["Place the bosu ball on the ground with the flat side facing up.","Position yourself in a push-up position with your hands on the outer edges of the bosu ball.","Engage your core and lower your body down towards the bosu ball by bending your elbows.","Push yourself back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders","core"],"target":"pectorals","image":"images/0653-2kr2lWy.jpg","gif_url":"videos/0653-2kr2lWy.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0655","name":"push-up (on stability ball)","category":"chest","equipment":"stability ball","instruction_steps":{"en":["Place the stability ball on the ground and position yourself facing down with your hands on the ball, shoulder-width apart.","Extend your legs straight out behind you, balancing on your toes.","Engage your core and lower your chest towards the ball by bending your elbows, keeping your body in a straight line.","Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders","core"],"target":"pectorals","image":"images/0655-Y4BRNQF.jpg","gif_url":"videos/0655-Y4BRNQF.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0656","name":"push-up (on stability ball)","category":"chest","equipment":"stability ball","instruction_steps":{"en":["Place the stability ball on the ground and position yourself facing down with your hands on the ball, shoulder-width apart.","Extend your legs straight out behind you, balancing on your toes.","Engage your core and lower your chest towards the ball by bending your elbows, keeping your body in a straight line.","Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders","core"],"target":"pectorals","image":"images/0656-tgryw5Y.jpg","gif_url":"videos/0656-tgryw5Y.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0659","name":"push-up (wall)","category":"chest","equipment":"body weight","instruction_steps":{"en":["Stand facing a wall, about arm's length away.","Place your hands on the wall at shoulder height, slightly wider than shoulder-width apart.","Step back a few feet, keeping your body straight and your feet hip-width apart.","Bend your elbows and lower your chest towards the wall, keeping your body in a straight line.","Push back up to the starting position, straightening your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","deltoids"],"target":"pectorals","image":"images/0659-LEH9jxP.jpg","gif_url":"videos/0659-LEH9jxP.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0658","name":"push-up (wall) v. 2","category":"chest","equipment":"body weight","instruction_steps":{"en":["Stand facing a wall, about arm's length away.","Place your hands on the wall at shoulder height, slightly wider than shoulder-width apart.","Step back with your feet, keeping them hip-width apart.","Engage your core and keep your body in a straight line from head to heels.","Bend your elbows and lower your chest towards the wall, keeping your body straight.","Pause for a moment, then push yourself back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/0658-NCmbLCw.jpg","gif_url":"videos/0658-NCmbLCw.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0660","name":"push-up close-grip off dumbbell","category":"upper arms","equipment":"dumbbell","instruction_steps":{"en":["Start in a push-up position with your hands placed close together, directly under your shoulders.","Hold a dumbbell in each hand, resting them on the ground.","Lower your body towards the ground by bending your elbows, keeping them close to your sides.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0660-KZXAtKQ.jpg","gif_url":"videos/0660-KZXAtKQ.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0661","name":"push-up inside leg kick","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.","Lower your body towards the ground by bending your elbows, keeping your back straight and your core engaged.","As you push back up, lift one leg off the ground and kick it out to the side, keeping it straight.","Lower your leg back down and repeat the push-up, then switch to the other leg.","Continue alternating leg kicks with each push-up repetition."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves","core"],"target":"glutes","image":"images/0661-0br45wL.jpg","gif_url":"videos/0661-0br45wL.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0663","name":"push-up medicine ball","category":"chest","equipment":"medicine ball","instruction_steps":{"en":["Start in a high plank position with your hands on the medicine ball, shoulder-width apart.","Engage your core and lower your body towards the ground by bending your elbows, keeping your back straight.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders","core"],"target":"pectorals","image":"images/0663-W8KAlkI.jpg","gif_url":"videos/0663-W8KAlkI.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1467","name":"push-up on lower arms","category":"upper arms","equipment":"body weight","instruction_steps":{"en":["Start in a plank position with your forearms on the ground and elbows directly below your shoulders.","Engage your core and keep your body in a straight line from head to toe.","Lower your chest towards the ground by bending your elbows, keeping them close to your body.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/1467-4Jt8QsQ.jpg","gif_url":"videos/1467-4Jt8QsQ.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3145","name":"push-up plus","category":"chest","equipment":"body weight","instruction_steps":{"en":["Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line from head to heels.","Lower your body towards the ground by bending your elbows, keeping them close to your sides.","Once your chest is just above the ground, push through your hands to extend your arms and lift your upper body up.","At the top of the movement, protract your shoulder blades by pushing your upper back towards the ceiling.","Pause for a moment, then reverse the movement by retracting your shoulder blades and lowering your body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/3145-pvBMLHA.jpg","gif_url":"videos/3145-pvBMLHA.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0664","name":"push-up to side plank","category":"waist","equipment":"body weight","instruction_steps":{"en":["Start in a push-up position with your hands shoulder-width apart and your body in a straight line.","Lower your body towards the ground by bending your elbows, keeping your core engaged.","Push back up to the starting position.","Shift your weight onto your left hand and rotate your body to the right, lifting your right arm towards the ceiling.","Hold the side plank position for a few seconds, then return to the starting position.","Repeat the push-up and side plank on the opposite side.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","chest","triceps"],"target":"abs","image":"images/0664-KhHJ338.jpg","gif_url":"videos/0664-KhHJ338.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3533","name":"quads","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart.","Lower your body by bending your knees and pushing your hips back as if sitting on a chair.","Keep your chest up and your back straight.","Lower yourself until your thighs are parallel to the ground.","Push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"quads","image":"images/3533-6YUfHPL.jpg","gif_url":"videos/3533-6YUfHPL.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3201","name":"quarter sit-up","category":"waist","equipment":"body weight","instruction_steps":{"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/3201-enxnJcM.jpg","gif_url":"videos/3201-enxnJcM.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3552","name":"quick feet v. 2","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart and your arms by your sides.","Begin by rapidly moving your feet up and down, as if you were running in place.","Keep your movements quick and light, focusing on staying on the balls of your feet.","Continue for the desired duration or number of repetitions."]},"muscle_group":"calves","secondary_muscles":["calves","hamstrings"],"target":"quads","image":"images/3552-mweqJin.jpg","gif_url":"videos/3552-mweqJin.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0666","name":"raise single arm push-up","category":"chest","equipment":"body weight","instruction_steps":{"en":["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.","Extend one arm straight out to the side, parallel to the ground.","Lower your body towards the ground by bending your elbows, keeping your back straight and core engaged.","Push back up to the starting position, using your chest muscles to lift your body.","Repeat with the other arm extended."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders","core"],"target":"pectorals","image":"images/0666-13TpY4H.jpg","gif_url":"videos/0666-13TpY4H.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0668","name":"rear decline bridge","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Lie on your back with your feet flat on the ground and your knees bent.","Place your arms by your sides with your palms facing down.","Engage your glutes and hamstrings, and lift your hips off the ground until your body forms a straight line from your knees to your shoulders.","Hold this position for a few seconds, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"target":"glutes","image":"images/0668-UpAlold.jpg","gif_url":"videos/0668-UpAlold.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0669","name":"rear deltoid stretch","category":"shoulders","equipment":"body weight","instruction_steps":{"en":["Stand tall with your feet shoulder-width apart.","Extend your right arm across your chest, placing your left hand on your right elbow.","Gently pull your right arm towards your left shoulder, feeling a stretch in your right shoulder.","Hold the stretch for 15-30 seconds, then release.","Repeat on the other side."]},"muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids"],"target":"delts","image":"images/0669-xifhB5W.jpg","gif_url":"videos/0669-xifhB5W.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0670","name":"rear pull-up","category":"back","equipment":"body weight","instruction_steps":{"en":["Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your body straight.","Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/0670-CbFSYC1.jpg","gif_url":"videos/0670-CbFSYC1.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1582","name":"reclining big toe pose with rope","category":"upper legs","equipment":"rope","instruction_steps":{"en":["Lie on your back with your legs extended and your arms by your sides.","Loop the rope around the ball of your right foot and hold the ends of the rope with your hands.","Slowly raise your right leg towards your chest, keeping your knee straight and your foot flexed.","Hold the stretch for a few seconds, then slowly lower your leg back down to the starting position.","Repeat with your left leg.","Continue alternating legs for the desired number of repetitions."]},"muscle_group":"calves","secondary_muscles":["calves","glutes"],"target":"hamstrings","image":"images/1582-K5xgdvI.jpg","gif_url":"videos/1582-K5xgdvI.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3236","name":"resistance band hip thrusts on knees (female)","category":"upper legs","equipment":"resistance band","instruction_steps":{"en":["Start by kneeling on the ground with your knees hip-width apart and your feet flexed.","Wrap the resistance band around your thighs, just above your knees.","Place your hands on your hips or extend them out in front of you for balance.","Engage your glutes and core muscles.","Push your hips forward and squeeze your glutes as you lift your knees off the ground, extending your hips until your thighs are parallel to the ground.","Hold the position for a moment, then slowly lower your knees back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps"],"target":"glutes","image":"images/3236-Pjbc0Kt.jpg","gif_url":"videos/3236-Pjbc0Kt.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3007","name":"resistance band leg extension","category":"upper legs","equipment":"resistance band","instruction_steps":{"en":["Attach the resistance band to a sturdy anchor point and secure it around your ankle.","Stand facing the anchor point with your feet shoulder-width apart.","Keeping your core engaged and your upper body stable, extend your leg straight out in front of you.","Pause for a moment at the top, then slowly return your leg to the starting position.","Repeat for the desired number of repetitions, then switch legs."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"target":"quads","image":"images/3007-Y1MsI1l.jpg","gif_url":"videos/3007-Y1MsI1l.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3123","name":"resistance band seated biceps curl","category":"upper arms","equipment":"resistance band","instruction_steps":{"en":["Sit on a chair or bench with your back straight and feet flat on the ground.","Hold the resistance band with an underhand grip, palms facing up, and arms extended down by your sides.","Keeping your upper arms stationary, exhale and curl the resistance band up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the resistance band back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/3123-XFc3vpY.jpg","gif_url":"videos/3123-XFc3vpY.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3124","name":"resistance band seated chest press","category":"chest","equipment":"resistance band","instruction_steps":{"en":["Sit on a chair or bench with your back straight and feet flat on the ground.","Hold the resistance band handles in each hand, with your palms facing down and elbows bent at a 90-degree angle.","Extend your arms forward, pushing the resistance band away from your chest.","Pause for a moment at the end of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/3124-4x5Okof.jpg","gif_url":"videos/3124-4x5Okof.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3006","name":"resistance band seated hip abduction","category":"upper legs","equipment":"resistance band","instruction_steps":{"en":["Sit on a chair or bench with your back straight and feet flat on the ground.","Wrap the resistance band around your thighs, just above your knees.","Place your hands on the sides of the chair or bench for support.","Engage your abductors (outer thigh muscles) and slowly push your knees apart, against the resistance of the band.","Pause for a moment at the end of the movement, then slowly bring your knees back together.","Repeat for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","hamstrings"],"target":"abductors","image":"images/3006-0xDpB4L.jpg","gif_url":"videos/3006-0xDpB4L.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3122","name":"resistance band seated shoulder press","category":"shoulders","equipment":"resistance band","instruction_steps":{"en":["Sit on a chair or bench with your back straight and feet flat on the ground.","Hold the resistance band with both hands, palms facing forward, and bring it up to shoulder level.","Press the band overhead, extending your arms fully.","Pause for a moment at the top, then slowly lower the band back down to shoulder level.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/3122-S93zLTG.jpg","gif_url":"videos/3122-S93zLTG.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3144","name":"resistance band seated straight back row","category":"back","equipment":"resistance band","instruction_steps":{"en":["Sit on the floor with your legs extended and loop the resistance band around your feet.","Hold the ends of the resistance band with your hands, palms facing each other.","Keep your back straight and lean slightly back, engaging your core.","Pull the resistance band towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"target":"upper back","image":"images/3144-Nu7jqFE.jpg","gif_url":"videos/3144-Nu7jqFE.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0872","name":"reverse crunch","category":"waist","equipment":"body weight","instruction_steps":{"en":["Lie flat on your back with your arms extended along your sides.","Bend your knees and lift your feet off the ground, bringing your thighs perpendicular to the floor.","Contract your abs and curl your hips off the floor, bringing your knees towards your chest.","Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0872-nCU1Ekp.jpg","gif_url":"videos/0872-nCU1Ekp.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0672","name":"reverse dip","category":"upper arms","equipment":"body weight","instruction_steps":{"en":["Position yourself between two parallel bars with your arms fully extended and your body straight.","Lower your body by bending your elbows until your upper arms are parallel to the ground.","Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0672-NZ5Qqkz.jpg","gif_url":"videos/0672-NZ5Qqkz.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0673","name":"reverse grip machine lat pulldown","category":"back","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height and position yourself on the machine with your knees under the pads and your feet flat on the ground.","Grasp the handles with an underhand grip, slightly wider than shoulder-width apart.","Sit upright with your chest out and shoulders back, maintaining a slight arch in your lower back.","Pull the handles down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/0673-ecpY0rH.jpg","gif_url":"videos/0673-ecpY0rH.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0674","name":"reverse grip pull-up","category":"back","equipment":"body weight","instruction_steps":{"en":["Grab the pull-up bar with an underhand grip, hands shoulder-width apart.","Hang from the bar with your arms fully extended and your body straight.","Engage your back muscles and pull your body up towards the bar, leading with your chest.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/0674-YAk5dIw.jpg","gif_url":"videos/0674-YAk5dIw.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0675","name":"reverse hyper extension (on stability ball)","category":"upper legs","equipment":"stability ball","instruction_steps":{"en":["Lie face down on a stability ball with your hips resting on the ball and your legs extended straight behind you.","Place your hands on the ground in front of you for stability.","Engaging your glutes and hamstrings, lift your legs up towards the ceiling as high as you can.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"target":"glutes","image":"images/0675-vM5YS2g.jpg","gif_url":"videos/0675-vM5YS2g.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1423","name":"reverse hyper on flat bench","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Lie face down on a flat bench with your hips at the edge and your legs hanging off the bench.","Hold onto the bench for stability.","Keeping your legs straight, raise them up towards the ceiling as high as you can.","Squeeze your glutes at the top of the movement.","Slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"target":"glutes","image":"images/1423-OrETs32.jpg","gif_url":"videos/1423-OrETs32.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3663","name":"reverse plank with leg lift","category":"waist","equipment":"body weight","instruction_steps":{"en":["Sit on the ground with your legs extended in front of you and your hands resting on the ground behind you, fingers pointing towards your feet.","Press through your hands and lift your hips off the ground, coming into a reverse plank position.","Engage your core and lift one leg off the ground, extending it straight up towards the ceiling.","Hold for a moment, then lower your leg back down.","Repeat with the other leg.","Continue alternating legs for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","shoulders"],"target":"abs","image":"images/3663-tFToB7l.jpg","gif_url":"videos/3663-tFToB7l.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0677","name":"ring dips","category":"upper arms","equipment":"body weight","instruction_steps":{"en":["Start by hanging from the rings with your arms fully extended and your body straight.","Lower your body by bending your elbows until your shoulders are below your elbows.","Push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0677-ezTvXcr.jpg","gif_url":"videos/0677-ezTvXcr.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2571","name":"rocking frog stretch","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Start by kneeling on the ground with your knees hip-width apart.","Place your hands on the ground in front of you for support.","Slowly lean forward, shifting your weight onto your hands and extending your legs behind you.","Keep your back straight and engage your glutes as you push your hips back and up towards the ceiling.","Hold this position for a few seconds, feeling a stretch in your glutes.","Slowly return to the starting position by bending your knees and lowering your hips back down.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps"],"target":"glutes","image":"images/2571-2Dk4xQV.jpg","gif_url":"videos/2571-2Dk4xQV.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0678","name":"rocky pull-up pulldown","category":"back","equipment":"body weight","instruction_steps":{"en":["Stand in front of a pull-up bar with your feet shoulder-width apart.","Reach up and grab the bar with an overhand grip, slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your body straight.","Engage your back muscles and pull your body up towards the bar, leading with your chest.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/0678-cQ19bBP.jpg","gif_url":"videos/0678-cQ19bBP.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2208","name":"roller back stretch","category":"back","equipment":"roller","instruction_steps":{"en":["Start by sitting on the ground with your legs extended in front of you.","Place the roller perpendicular to your body, just below your glutes.","Slowly roll your body backwards, allowing the roller to move up your back.","Continue rolling until the roller reaches your upper back.","Pause for a moment, then slowly roll back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"spine","image":"images/2208-isofgzg.jpg","gif_url":"videos/2208-isofgzg.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2204","name":"roller body saw","category":"waist","equipment":"roller","instruction_steps":{"en":["Start in a plank position with your forearms on the roller and your body in a straight line.","Engage your core and slowly roll the roller forward, extending your body as far as you can while maintaining control.","Pause for a moment at the furthest point, then slowly roll the roller back towards your starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps","core"],"target":"abs","image":"images/2204-XeMvLgE.jpg","gif_url":"videos/2204-XeMvLgE.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2205","name":"roller hip lat stretch","category":"upper legs","equipment":"roller","instruction_steps":{"en":["Start by kneeling on the ground with the roller positioned under your hips.","Place your hands on the roller for support.","Slowly roll the roller forward, extending your hips and stretching your glutes.","Hold the stretch for a few seconds, then roll back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps"],"target":"glutes","image":"images/2205-0L2KwtI.jpg","gif_url":"videos/2205-0L2KwtI.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2202","name":"roller hip stretch","category":"upper legs","equipment":"roller","instruction_steps":{"en":["Start by sitting on the ground with your legs extended in front of you.","Place the roller under your glutes, just above your knees.","Lean back and place your hands on the ground behind you for support.","Engage your glutes and slowly roll the roller forward, bending your knees and bringing them towards your chest.","Pause for a moment at the end of the movement, feeling a stretch in your glutes.","Slowly roll the roller back to the starting position, extending your legs.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps"],"target":"glutes","image":"images/2202-oMypNrz.jpg","gif_url":"videos/2202-oMypNrz.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2206","name":"roller reverse crunch","category":"waist","equipment":"roller","instruction_steps":{"en":["Lie flat on your back with your arms extended straight above your head and your legs straight out in front of you.","Place the roller between your feet and grip it with your toes.","Engaging your abs, lift your legs off the ground and curl your knees towards your chest, rolling the roller towards your body.","Pause for a moment at the top, then slowly lower your legs back down to the starting position, rolling the roller away from your body.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/2206-SKXQAx3.jpg","gif_url":"videos/2206-SKXQAx3.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2203","name":"roller seated shoulder flexor depresor retractor","category":"chest","equipment":"roller","instruction_steps":{"en":["Sit on a flat surface with your legs extended in front of you.","Hold the roller with both hands, palms facing down, and place it on your thighs.","Lean forward slightly and roll the roller away from your body, extending your arms straight in front of you.","Pause for a moment, then slowly roll the roller back towards your body, bending your arms and bringing the roller back to your thighs.","Repeat for the desired number of repetitions."]},"muscle_group":"deltoids","secondary_muscles":["deltoids","triceps"],"target":"pectorals","image":"images/2203-8coXSYU.jpg","gif_url":"videos/2203-8coXSYU.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2209","name":"roller seated single leg shoulder flexor depresor retractor","category":"chest","equipment":"roller","instruction_steps":{"en":["Sit on a flat surface with your legs extended in front of you.","Hold the roller with both hands, palms facing down, and place it on your thighs.","Lean back slightly and engage your core muscles.","Raise the roller up to shoulder level, keeping your arms straight.","Slowly lower the roller back down to your thighs.","Repeat for the desired number of repetitions."]},"muscle_group":"deltoids","secondary_muscles":["deltoids","triceps"],"target":"pectorals","image":"images/2209-CjETvlw.jpg","gif_url":"videos/2209-CjETvlw.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2207","name":"roller side lat stretch","category":"back","equipment":"roller","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold the roller with both hands in front of your body.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Extend your arms forward and roll the roller down towards your feet, feeling a stretch in your lats.","Hold the stretch for a few seconds, then slowly roll the roller back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"lats","image":"images/2207-c3Pfhti.jpg","gif_url":"videos/2207-c3Pfhti.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0680","name":"rope climb","category":"back","equipment":"rope","instruction_steps":{"en":["Stand facing the rope with your feet shoulder-width apart.","Grab the rope with both hands, palms facing towards you.","Bend your knees slightly and engage your core.","Begin pulling yourself up the rope by alternating hand-over-hand movements.","Use your legs to assist in the upward movement.","Continue climbing until you reach the desired height or the top of the rope.","To descend, reverse the hand-over-hand movement while controlling your descent.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms","biceps","shoulders"],"target":"upper back","image":"images/0680-yaAxcQr.jpg","gif_url":"videos/0680-yaAxcQr.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0685","name":"run","category":"cardio","equipment":"body weight","instruction_steps":{"en":["Start by standing upright with your feet hip-width apart.","Engage your core and keep your upper body relaxed.","Begin jogging in place, lifting your knees up towards your chest and landing softly on the balls of your feet.","Maintain a steady pace and continue jogging for the desired duration or distance.","Remember to breathe deeply and maintain good posture throughout the exercise."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"cardiovascular system","image":"images/0685-oLrKqDH.jpg","gif_url":"videos/0685-oLrKqDH.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0684","name":"run (equipment)","category":"cardio","equipment":"body weight","instruction_steps":{"en":["Start by standing upright with your feet hip-width apart.","Engage your core and keep your upper body relaxed.","Begin jogging in place, lifting your knees up towards your chest and landing softly on the balls of your feet.","Maintain a steady pace and continue jogging for the desired duration or distance.","Remember to breathe deeply and maintain good posture throughout the exercise."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"cardiovascular system","image":"images/0684-y5p0H8a.jpg","gif_url":"videos/0684-y5p0H8a.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1585","name":"runners stretch","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Stand with your feet hip-width apart.","Take a step forward with your right foot, keeping your left foot planted.","Bend your right knee and lower your body down, keeping your left leg straight.","Place your hands on your right thigh for support.","Hold the stretch for 20-30 seconds, then switch sides and repeat."]},"muscle_group":"calves","secondary_muscles":["calves","quadriceps"],"target":"hamstrings","image":"images/1585-0mB6wHO.jpg","gif_url":"videos/1585-0mB6wHO.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0687","name":"russian twist","category":"waist","equipment":"body weight","instruction_steps":{"en":["Sit on the ground with your knees bent and feet flat on the floor.","Lean back slightly while keeping your back straight and your core engaged.","Hold your hands together in front of your chest or hold a weight if desired.","Lift your feet off the ground, balancing on your sit bones.","Twist your torso to the right, bringing your hands or weight towards the right side of your body.","Pause for a moment, then twist your torso to the left, bringing your hands or weight towards the left side of your body.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/0687-XVDdcoj.jpg","gif_url":"videos/0687-XVDdcoj.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3012","name":"scapula dips","category":"back","equipment":"body weight","instruction_steps":{"en":["Start by standing with your feet shoulder-width apart and your arms extended in front of you.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Lower your body by bending your elbows and retracting your shoulder blades, as if you are trying to squeeze a pencil between them.","Pause for a moment at the bottom, then push through your hands to extend your elbows and return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"rhomboids","secondary_muscles":["rhomboids","deltoids"],"target":"traps","image":"images/3012-7xeukSt.jpg","gif_url":"videos/3012-7xeukSt.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3021","name":"scapula push-up","category":"chest","equipment":"body weight","instruction_steps":{"en":["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.","Lower your chest towards the ground, keeping your elbows close to your body.","As you lower, squeeze your shoulder blades together and push your chest forward.","Pause for a moment at the bottom, then push back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"serratus anterior","image":"images/3021-jV65tKx.jpg","gif_url":"videos/3021-jV65tKx.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0688","name":"scapular pull-up","category":"back","equipment":"body weight","instruction_steps":{"en":["Start by hanging from a pull-up bar with your palms facing away from you and your arms fully extended.","Retract your shoulder blades by pulling them down and back.","Engage your back muscles and pull your body up towards the bar, focusing on squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","rhomboids","rear deltoids"],"target":"traps","image":"images/0688-uTBt1HV.jpg","gif_url":"videos/0688-uTBt1HV.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3219","name":"scissor jumps (male)","category":"cardio","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart.","Jump off the ground and simultaneously cross your right leg in front of your left leg.","As you land, quickly switch legs, crossing your left leg in front of your right leg.","Continue alternating legs and jumping as quickly as possible.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"cardiovascular system","image":"images/3219-Eh2v5Iu.jpg","gif_url":"videos/3219-Eh2v5Iu.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1390","name":"seated calf stretch (male)","category":"lower legs","equipment":"body weight","instruction_steps":{"en":["Sit on the edge of a chair or bench with your feet flat on the ground.","Extend one leg straight out in front of you, keeping your heel on the ground.","Lean forward slightly, feeling a stretch in your calf muscle.","Hold the stretch for 20-30 seconds.","Switch legs and repeat the stretch."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"target":"calves","image":"images/1390-17bqEXD.jpg","gif_url":"videos/1390-17bqEXD.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1424","name":"seated glute stretch","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Sit on the ground with your legs extended in front of you.","Bend your right knee and cross your right ankle over your left thigh.","Place your right hand on the ground behind you for support.","With your left hand, gently press down on your right knee to deepen the stretch.","Hold the stretch for 30 seconds to 1 minute.","Switch sides and repeat."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"target":"glutes","image":"images/1424-DeDThfG.jpg","gif_url":"videos/1424-DeDThfG.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0689","name":"seated leg raise","category":"waist","equipment":"body weight","instruction_steps":{"en":["Sit on a flat bench with your back straight and your feet flat on the ground.","Place your hands on the sides of the bench for support.","Keeping your legs straight, slowly raise them up in front of you until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0689-Hgs6Nl1.jpg","gif_url":"videos/0689-Hgs6Nl1.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0690","name":"seated lower back stretch","category":"back","equipment":"body weight","instruction_steps":{"en":["Sit on the edge of a chair with your feet flat on the ground.","Place your hands on your thighs or on the sides of the chair for support.","Slowly lean forward from your hips, keeping your back straight.","Feel the stretch in your lower back and hold for 20-30 seconds.","Slowly return to the starting position and repeat for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","hamstrings"],"target":"lats","image":"images/0690-QFmz6ch.jpg","gif_url":"videos/0690-QFmz6ch.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2567","name":"seated piriformis stretch","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Sit on the ground with your legs extended in front of you.","Bend your right knee and place your right foot on the outside of your left knee.","Place your left elbow on the outside of your right knee and gently twist your torso to the right.","Hold the stretch for 20-30 seconds, then switch sides and repeat."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"target":"glutes","image":"images/2567-QY39eBr.jpg","gif_url":"videos/2567-QY39eBr.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0691","name":"seated side crunch (wall)","category":"waist","equipment":"body weight","instruction_steps":{"en":["Sit on the floor with your back against a wall and your legs extended in front of you.","Bend your knees and place your feet flat on the floor, hip-width apart.","Place your hands behind your head with your elbows pointing outwards.","Engage your abs and lean to one side, bringing your elbow towards your hip.","Pause for a moment, then return to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/0691-Y9hNPcN.jpg","gif_url":"videos/0691-Y9hNPcN.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1587","name":"seated wide angle pose sequence","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Sit on the ground with your legs extended in a wide angle.","Flex your feet and engage your quadriceps.","Place your hands on the ground behind you for support.","Keeping your back straight, lean forward from your hips.","Continue leaning forward until you feel a stretch in your hamstrings.","Hold this position for a few breaths.","Slowly release the stretch and return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","calves"],"target":"hamstrings","image":"images/1587-HIgYKAB.jpg","gif_url":"videos/1587-HIgYKAB.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0697","name":"self assisted inverse leg curl","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Lie flat on your back on a mat or bench with your legs extended.","Place your hands by your sides or under your glutes for support.","Bend your knees and lift your feet off the ground, bringing your thighs towards your chest.","Pause for a moment at the top, then slowly lower your legs back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","calves"],"target":"hamstrings","image":"images/0697-GwYwElT.jpg","gif_url":"videos/0697-GwYwElT.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1766","name":"self assisted inverse leg curl","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Lie face down on a leg curl machine with your legs extended and your ankles hooked under the padded lever.","Place your hands on the side handles of the machine for support.","Keeping your upper body stationary, exhale and curl your legs upward as far as possible.","Hold the contracted position for a brief pause as you squeeze your hamstrings.","Slowly lower your legs back to the starting position while inhaling.","Repeat for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","calves"],"target":"hamstrings","image":"images/1766-ZSY3MsL.jpg","gif_url":"videos/1766-ZSY3MsL.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0696","name":"self assisted inverse leg curl (on floor)","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Lie flat on your back with your legs extended and your arms by your sides.","Bend your knees and place your feet flat on the ground, hip-width apart.","Lift your hips off the ground, engaging your glutes and hamstrings.","Slowly curl your legs towards your glutes, keeping your hips lifted.","Pause for a moment at the top, then slowly extend your legs back to the starting position.","Lower your hips back down to the ground.","Repeat for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","calves"],"target":"hamstrings","image":"images/0696-E4PwJqI.jpg","gif_url":"videos/0696-E4PwJqI.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3222","name":"semi squat jump (male)","category":"cardio","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart.","Bend your knees and lower your body into a squat position.","Jump explosively, extending your hips and knees while swinging your arms for momentum.","Land softly on the balls of your feet and immediately go into the next repetition.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"cardiovascular system","image":"images/3222-6FMU51h.jpg","gif_url":"videos/3222-6FMU51h.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3656","name":"short stride run","category":"cardio","equipment":"body weight","instruction_steps":{"en":["Find an open space or a treadmill to perform the exercise.","Stand tall with your feet hip-width apart.","Start jogging in place, lifting your knees high and pumping your arms.","After a few seconds, start taking short strides forward, maintaining a quick pace.","Continue running with short strides for the desired duration or distance."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"cardiovascular system","image":"images/3656-CcWEoWV.jpg","gif_url":"videos/3656-CcWEoWV.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1763","name":"shoulder grip pull-up","category":"back","equipment":"body weight","instruction_steps":{"en":["Grab the pull-up bar with a shoulder-width grip, palms facing away from you.","Hang freely with your arms fully extended.","Engage your back muscles and pull your body up towards the bar until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/1763-YtgD7Xq.jpg","gif_url":"videos/1763-YtgD7Xq.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3699","name":"shoulder tap","category":"waist","equipment":"body weight","instruction_steps":{"en":["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.","Engage your core and lift your right hand off the ground, reaching across to tap your left shoulder.","Place your right hand back on the ground and repeat with your left hand tapping your right shoulder.","Continue alternating shoulder taps while keeping your hips and torso stable.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"abs","image":"images/3699-yRpV5TC.jpg","gif_url":"videos/3699-yRpV5TC.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0699","name":"shoulder tap push-up","category":"chest","equipment":"body weight","instruction_steps":{"en":["Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line from head to heels.","Lower your body towards the ground by bending your elbows, keeping them close to your sides.","As you push back up, lift your right hand off the ground and tap your left shoulder.","Return your right hand to the ground and repeat the push-up, this time lifting your left hand and tapping your right shoulder.","Continue alternating shoulder taps with each push-up repetition.","Maintain a stable core and avoid excessive hip rotation throughout the exercise.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","core"],"target":"pectorals","image":"images/0699-qEse6fe.jpg","gif_url":"videos/0699-qEse6fe.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1774","name":"side bridge hip abduction","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Lie on your side with your legs extended and stacked on top of each other.","Prop yourself up on your forearm, keeping your elbow directly below your shoulder.","Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.","While keeping your core engaged, lift your top leg as high as possible without rotating your hips.","Pause for a moment at the top, then lower your leg back down.","Repeat for the desired number of repetitions, then switch sides."]},"muscle_group":"glutes","secondary_muscles":["glutes","obliques"],"target":"abductors","image":"images/1774-WL4EmxJ.jpg","gif_url":"videos/1774-WL4EmxJ.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0705","name":"side bridge v. 2","category":"waist","equipment":"body weight","instruction_steps":{"en":["Lie on your side with your legs extended and stacked on top of each other.","Place your forearm on the ground directly below your shoulder, with your elbow bent at a 90-degree angle.","Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.","Hold this position for the desired amount of time.","Lower your hips back down to the starting position.","Repeat on the other side."]},"muscle_group":"obliques","secondary_muscles":["obliques","glutes"],"target":"abs","image":"images/0705-RKjH6Lt.jpg","gif_url":"videos/0705-RKjH6Lt.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0709","name":"side hip (on parallel bars)","category":"waist","equipment":"body weight","instruction_steps":{"en":["Stand between two parallel bars with your feet shoulder-width apart.","Place your hands on the bars and lift your body off the ground, supporting your weight on your arms.","Engage your abs and slowly lift your legs to the side, keeping them straight.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques","hip flexors"],"target":"abs","image":"images/0709-jTkSc6o.jpg","gif_url":"videos/0709-jTkSc6o.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0710","name":"side hip abduction","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart and your hands on your hips.","Shift your weight to one leg and lift the opposite leg out to the side, keeping it straight.","Pause for a moment at the top, then slowly lower your leg back down to the starting position.","Repeat on the other side.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","quadriceps"],"target":"abductors","image":"images/0710-7WaDzyL.jpg","gif_url":"videos/0710-7WaDzyL.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1358","name":"side lying floor stretch","category":"back","equipment":"body weight","instruction_steps":{"en":["Lie on your side with your legs straight and your bottom arm extended straight overhead.","Bend your top knee and place your foot on the ground in front of your bottom leg.","Reach your top arm over your head and grab onto something stable, like a wall or a piece of furniture.","Slowly lift your bottom leg off the ground, keeping it straight, until you feel a stretch in your side.","Hold the stretch for 20-30 seconds, then slowly lower your leg back down.","Repeat on the other side."]},"muscle_group":"obliques","secondary_muscles":["obliques","glutes"],"target":"lats","image":"images/1358-jDOKRM5.jpg","gif_url":"videos/1358-jDOKRM5.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3667","name":"side lying hip adduction (male)","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Lie on your side with your legs straight and stacked on top of each other.","Place your bottom arm under your head for support.","Engage your adductors and lift your top leg as high as possible without rotating your hips or leaning backward.","Pause for a moment at the top, then slowly lower your leg back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},"muscle_group":"glutes","secondary_muscles":["glutes","hamstrings"],"target":"adductors","image":"images/3667-c8f5cSY.jpg","gif_url":"videos/3667-c8f5cSY.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1775","name":"side plank hip adduction","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Start by lying on your side with your legs extended and stacked on top of each other.","Prop yourself up on your forearm, keeping your elbow directly below your shoulder.","Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.","While maintaining the side plank position, lift your top leg towards the ceiling, keeping it straight.","Slowly lower your leg back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},"muscle_group":"obliques","secondary_muscles":["obliques","glutes"],"target":"adductors","image":"images/1775-VO2qeJg.jpg","gif_url":"videos/1775-VO2qeJg.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0716","name":"side push neck stretch","category":"neck","equipment":"body weight","instruction_steps":{"en":["Stand or sit up straight with your shoulders relaxed.","Tilt your head to the right, bringing your right ear towards your right shoulder.","Place your right hand on the left side of your head and gently apply pressure to increase the stretch.","Hold the stretch for 15-30 seconds.","Repeat on the other side, tilting your head to the left and applying pressure with your left hand.","Repeat the stretch 2-3 times on each side."]},"muscle_group":"trapezius","secondary_muscles":["trapezius","sternocleidomastoid"],"target":"levator scapulae","image":"images/0716-oQRJYkC.jpg","gif_url":"videos/0716-oQRJYkC.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0717","name":"side push-up","category":"upper arms","equipment":"body weight","instruction_steps":{"en":["Start by lying on your side with your legs extended and stacked on top of each other.","Place your bottom hand on the ground directly under your shoulder, fingers pointing forward.","Press through your bottom hand to lift your body off the ground, keeping your legs straight and your core engaged.","Extend your top arm straight up towards the ceiling, creating a straight line from your head to your heels.","Lower your body back down to the starting position with control.","Repeat for the desired number of repetitions, then switch sides."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","chest","core"],"target":"triceps","image":"images/0717-wpbD28t.jpg","gif_url":"videos/0717-wpbD28t.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0721","name":"side wrist pull stretch","category":"lower arms","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart and your arms extended in front of you.","Extend your right arm out to the side, parallel to the ground, with your palm facing down.","With your left hand, grab your right hand and gently pull it towards your body, feeling a stretch in your right forearm.","Hold the stretch for 15-30 seconds, then release.","Repeat on the other side."]},"muscle_group":"wrists","secondary_muscles":["wrists","hands"],"target":"forearms","image":"images/0721-UtmIqcI.jpg","gif_url":"videos/0721-UtmIqcI.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0720","name":"side-to-side chin","category":"back","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your body relaxed.","Pull yourself up by bending your elbows and bringing your chin towards the bar, while keeping your body straight.","Once your chin is above the bar, lower yourself back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/0720-isAAZWA.jpg","gif_url":"videos/0720-isAAZWA.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3213","name":"side-to-side toe touch (male)","category":"waist","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart and your arms extended to the sides.","Bend at the waist to the right, reaching your right hand towards your right foot while keeping your left hand extended to the side.","Return to the starting position and then bend at the waist to the left, reaching your left hand towards your left foot while keeping your right hand extended to the side.","Repeat the side-to-side bending motion for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques","hip flexors"],"target":"abs","image":"images/3213-WCAvOfC.jpg","gif_url":"videos/3213-WCAvOfC.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0725","name":"single arm push-up","category":"chest","equipment":"body weight","instruction_steps":{"en":["Start in a push-up position with your hands shoulder-width apart and one hand placed slightly wider than the other.","Engage your core and lower your body towards the ground by bending your elbows, keeping your back straight.","As you lower yourself, shift your weight to one side and lift the opposite arm off the ground, extending it straight out to the side.","Push through your chest and triceps to raise your body back up to the starting position, while simultaneously lowering your extended arm back to the ground.","Repeat the movement, alternating the arm you extend with each repetition."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders","core"],"target":"pectorals","image":"images/0725-MUic5zN.jpg","gif_url":"videos/0725-MUic5zN.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3645","name":"single leg bridge with outstretched leg","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Lie on your back with your knees bent and feet flat on the ground.","Extend one leg straight out in front of you.","Engage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders.","Hold for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions, then switch legs."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps"],"target":"glutes","image":"images/3645-rmEukuS.jpg","gif_url":"videos/3645-rmEukuS.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0727","name":"single leg calf raise (on a dumbbell)","category":"lower legs","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet hip-width apart and hold a dumbbell in one hand.","Lift one foot off the ground and balance on the other foot.","Slowly raise your heel as high as possible, using your calf muscles.","Pause for a moment at the top, then slowly lower your heel back down.","Repeat for the desired number of repetitions, then switch to the other leg."]},"muscle_group":"ankles","secondary_muscles":["ankles","feet"],"target":"calves","image":"images/0727-fKZgDEO.jpg","gif_url":"videos/0727-fKZgDEO.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0730","name":"single leg platform slide","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Start by standing with one foot on a platform or slide board.","Bend your knee slightly and slide the foot on the platform backward, extending your leg.","Keep your core engaged and maintain a straight posture throughout the movement.","Slowly return to the starting position by sliding your foot back to the initial position.","Repeat the movement for the desired number of repetitions, then switch legs."]},"muscle_group":"glutes","secondary_muscles":["glutes","quadriceps"],"target":"hamstrings","image":"images/0730-LNE3wfo.jpg","gif_url":"videos/0730-LNE3wfo.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1759","name":"single leg squat (pistol) male","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart and arms extended in front of you.","Lift your right foot off the ground and extend it forward.","Slowly lower your body down by bending your left knee and pushing your hips back.","Keep your chest up and your back straight as you lower yourself down.","Lower until your left thigh is parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your left heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/1759-nqs5HGV.jpg","gif_url":"videos/1759-nqs5HGV.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1489","name":"sissy squat","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart and your toes pointing slightly outward.","Hold onto a stable object for balance if needed.","Slowly lower your body by bending your knees and leaning back, keeping your torso upright.","Continue lowering until your thighs are parallel to the ground or as far as you can comfortably go.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"calves","secondary_muscles":["calves","glutes"],"target":"quads","image":"images/1489-xdYPUtE.jpg","gif_url":"videos/1489-xdYPUtE.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0735","name":"sit-up v. 2","category":"waist","equipment":"body weight","instruction_steps":{"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0735-Bn6TXyO.jpg","gif_url":"videos/0735-Bn6TXyO.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3679","name":"sit-up with arms on chest","category":"waist","equipment":"body weight","instruction_steps":{"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Cross your arms over your chest.","Engaging your abs, lift your upper body off the ground towards your knees.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/3679-6ZCiYWQ.jpg","gif_url":"videos/3679-6ZCiYWQ.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3361","name":"skater hops","category":"cardio","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart.","Bend your knees slightly and jump to the right, landing on your right foot.","As you land, swing your left leg behind your right leg and tap the ground with your left toes.","Immediately jump to the left, landing on your left foot.","As you land, swing your right leg behind your left leg and tap the ground with your right toes.","Continue alternating sides, jumping and tapping the ground with each leg.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","glutes","calves"],"target":"cardiovascular system","image":"images/3361-zfNHMN9.jpg","gif_url":"videos/3361-zfNHMN9.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2142","name":"ski ergometer","category":"upper arms","equipment":"skierg machine","instruction_steps":{"en":["Adjust the seat height and footrests to a comfortable position.","Grasp the handles with an overhand grip, palms facing down.","Sit up straight with your feet flat on the footrests.","Extend your arms straight out in front of you, keeping your elbows slightly bent.","Engage your triceps and push the handles down towards your thighs.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","forearms"],"target":"triceps","image":"images/2142-vpQaQkH.jpg","gif_url":"videos/2142-vpQaQkH.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3671","name":"ski step","category":"cardio","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart.","Bend your knees slightly and keep your back straight.","Jump to the right, landing on your right foot while swinging your left leg behind your right leg.","Immediately jump to the left, landing on your left foot while swinging your right leg behind your left leg.","Continue alternating jumps from side to side, mimicking a skiing motion.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","glutes","calves"],"target":"cardiovascular system","image":"images/3671-5MRH8H2.jpg","gif_url":"videos/3671-5MRH8H2.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3304","name":"skin the cat","category":"back","equipment":"body weight","instruction_steps":{"en":["Start by hanging from a bar with your arms fully extended and your body relaxed.","Engage your core and lift your legs up, bringing your knees towards your chest.","Continue to lift your legs up and over your head, allowing your body to pass through the arms.","Once your legs are fully extended over your head, begin to lower them back down towards the starting position.","As you lower your legs, allow your body to pass back through the arms until you are hanging with your arms fully extended again.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","core"],"target":"upper back","image":"images/3304-MSfvriJ.jpg","gif_url":"videos/3304-MSfvriJ.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1425","name":"sled 45 degrees one leg press","category":"upper legs","equipment":"sled machine","instruction_steps":{"en":["Adjust the sled machine to a 45-degree angle.","Sit on the sled machine with your back against the pad and your feet on the footplate.","Place one foot on the footplate and extend your leg, pushing the sled away from you.","Slowly bend your knee and lower the sled back to the starting position.","Repeat with the other leg.","Continue alternating legs for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/1425-WWD6FzI.jpg","gif_url":"videos/1425-WWD6FzI.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0738","name":"sled 45в° calf press","category":"lower legs","equipment":"sled machine","instruction_steps":{"en":["Adjust the sled machine to a 45-degree angle.","Place your feet on the sled platform with your toes pointing forward.","Push the sled platform away from you by extending your ankles and calves.","Pause for a moment at the top, then slowly lower the sled platform back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"target":"calves","image":"images/0738-qCNVnaU.jpg","gif_url":"videos/0738-qCNVnaU.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0739","name":"sled 45в° leg press","category":"upper legs","equipment":"sled machine","instruction_steps":{"en":["Adjust the seat and footplate of the sled machine to a comfortable position.","Sit on the sled machine with your back against the backrest and your feet shoulder-width apart on the footplate.","Grip the handles on the sides of the seat for stability.","Push the footplate away from your body by extending your legs, keeping your heels on the footplate.","Continue pushing until your legs are almost fully extended, but without locking your knees.","Pause for a moment at the top of the movement, then slowly lower the footplate back towards your body by bending your knees.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0739-10Z2DXU.jpg","gif_url":"videos/0739-10Z2DXU.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1464","name":"sled 45в° leg press (back pov)","category":"upper legs","equipment":"sled machine","instruction_steps":{"en":["Adjust the seat of the sled machine so that your knees are at a 45-degree angle.","Sit on the sled machine with your back against the backrest and your feet shoulder-width apart on the footplate.","Grip the handles on the sides of the seat for stability.","Push the footplate away from your body by extending your legs, keeping your heels on the footplate.","Pause for a moment at the fully extended position.","Slowly bend your knees and lower the footplate back towards your body, controlling the movement.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/1464-yn2lLSI.jpg","gif_url":"videos/1464-yn2lLSI.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1463","name":"sled 45° leg press (side pov)","category":"upper legs","equipment":"sled machine","instruction_steps":{"en":["Adjust the seat of the sled machine so that your knees are at a 90-degree angle when your feet are on the footplate.","Sit on the sled machine with your back flat against the backrest and your feet shoulder-width apart on the footplate.","Grip the handles on the sides of the seat for stability.","Push against the footplate to extend your legs, straightening them completely.","Pause for a moment at the top, then slowly bend your knees to lower the footplate back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/1463-2Qh2J1e.jpg","gif_url":"videos/1463-2Qh2J1e.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0740","name":"sled 45в° leg wide press","category":"upper legs","equipment":"sled machine","instruction_steps":{"en":["Adjust the sled machine to a 45-degree angle.","Sit on the sled machine with your back against the pad and your feet on the foot platform.","Position your feet wider than shoulder-width apart.","Push against the foot platform to extend your legs and straighten your knees.","Pause for a moment at the end of the movement, then slowly bend your knees to return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0740-tj41Nu6.jpg","gif_url":"videos/0740-tj41Nu6.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1391","name":"sled calf press on leg press","category":"lower legs","equipment":"sled machine","instruction_steps":{"en":["Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the sled.","Place your feet shoulder-width apart on the sled, with your toes pointing forward.","Release the safety handles and push the sled away from you by extending your knees and ankles.","Pause for a moment at the top of the movement, then slowly lower the sled back down by bending your knees and ankles.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps"],"target":"calves","image":"images/1391-ykHcWme.jpg","gif_url":"videos/1391-ykHcWme.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0741","name":"sled closer hack squat","category":"upper legs","equipment":"sled machine","instruction_steps":{"en":["Adjust the sled machine to a comfortable weight and position yourself with your back against the pad.","Place your feet shoulder-width apart on the platform, toes slightly pointed outwards.","Grip the handles on the sides of the machine for stability.","Engage your core and slowly lower your body by bending your knees and hips, keeping your back straight.","Continue lowering until your thighs are parallel to the ground or slightly below.","Pause for a moment at the bottom, then push through your heels to extend your legs and return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0741-gf3ZjB9.jpg","gif_url":"videos/0741-gf3ZjB9.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0742","name":"sled forward angled calf raise","category":"lower legs","equipment":"sled machine","instruction_steps":{"en":["Adjust the sled machine to a comfortable weight and position yourself on the machine with your toes on the platform and your heels hanging off.","Place your hands on the handles or the sides of the machine for support.","Engage your calves and slowly raise your heels as high as possible, pushing against the resistance of the sled.","Pause for a moment at the top of the movement, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"calves","image":"images/0742-XDOiFns.jpg","gif_url":"videos/0742-XDOiFns.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0743","name":"sled hack squat","category":"upper legs","equipment":"sled machine","instruction_steps":{"en":["Adjust the sled machine to a comfortable position for your height.","Stand with your feet shoulder-width apart on the platform, toes slightly pointed outwards.","Hold onto the handles or bars for stability.","Lower your body by bending your knees and hips, keeping your back straight and chest up.","Continue lowering until your thighs are parallel to the ground or slightly below.","Pause for a moment, then push through your heels to raise your body back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0743-Qa55kX1.jpg","gif_url":"videos/0743-Qa55kX1.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2334","name":"sled lying calf press","category":"lower legs","equipment":"sled machine","instruction_steps":{"en":["Adjust the sled machine to a comfortable weight.","Sit on the sled machine with your back against the pad and your feet on the platform.","Place your toes and the balls of your feet on the edge of the platform, with your heels hanging off.","Push the platform away from you by extending your ankles, keeping your knees slightly bent.","Continue pushing until your calves are fully contracted.","Hold the contraction for a moment, then slowly lower the platform back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"calves","image":"images/2334-g376LuL.jpg","gif_url":"videos/2334-g376LuL.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0744","name":"sled lying squat","category":"upper legs","equipment":"sled machine","instruction_steps":{"en":["Adjust the sled machine to a comfortable weight.","Lie on your back on the sled machine with your feet on the footplate.","Position your feet shoulder-width apart and slightly angled outwards.","Grip the handles of the sled machine for stability.","Engage your glutes and core muscles.","Push through your heels and extend your legs to lift the sled.","Lower the sled back down by bending your knees and hips.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0744-9n2149Z.jpg","gif_url":"videos/0744-9n2149Z.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1392","name":"sled one leg calf press on leg press","category":"lower legs","equipment":"sled machine","instruction_steps":{"en":["Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the sled.","Sit on the machine with your back against the backrest and your feet on the sled, shoulder-width apart.","Place your toes and the balls of your feet on the sled, keeping your heels off.","Push the sled forward by extending your ankles, keeping your knees slightly bent.","Pause for a moment at the top, then slowly lower the sled back down by flexing your ankles.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"calves","image":"images/1392-u0pLNgz.jpg","gif_url":"videos/1392-u0pLNgz.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1496","name":"sledge hammer","category":"waist","equipment":"hammer","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold the sledge hammer with both hands.","Engage your core and keep your back straight.","Swing the sledge hammer down towards the ground, using your core and upper body strength.","As you swing down, pivot your hips and transfer the force to the hammer.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms","shoulders"],"target":"abs","image":"images/1496-REXmfVC.jpg","gif_url":"videos/1496-REXmfVC.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0746","name":"smith back shrug","category":"back","equipment":"smith machine","instruction_steps":{"en":["Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Keep your arms straight and allow the barbell to hang in front of your thighs.","Lift your shoulders straight up towards your ears, squeezing your traps at the top.","Hold for a moment, then lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"traps","image":"images/0746-MzNnwx9.jpg","gif_url":"videos/0746-MzNnwx9.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0747","name":"smith behind neck press","category":"shoulders","equipment":"smith machine","instruction_steps":{"en":["Adjust the seat height of the smith machine so that the bar is at shoulder level.","Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Lift the bar off the rack and step back, maintaining a stable stance.","Lower the bar down to the back of your neck, keeping your elbows pointing forward.","Press the bar up overhead until your arms are fully extended.","Pause for a moment at the top, then slowly lower the bar back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0747-Gpn4ADc.jpg","gif_url":"videos/0747-Gpn4ADc.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0748","name":"smith bench press","category":"chest","equipment":"smith machine","instruction_steps":{"en":["Adjust the height of the smith machine bar to chest level.","Lie flat on the bench with your feet firmly planted on the ground.","Grip the bar with an overhand grip slightly wider than shoulder-width apart.","Unrack the bar and lower it towards your chest, keeping your elbows tucked in.","Pause for a moment when the bar touches your chest.","Push the bar back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/0748-trqKQv2.jpg","gif_url":"videos/0748-trqKQv2.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0749","name":"smith bent knee good morning","category":"upper legs","equipment":"smith machine","instruction_steps":{"en":["Start by standing with your feet shoulder-width apart, toes pointing forward.","Place the barbell across your upper back, resting it on your traps.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.","Engage your glutes and hamstrings to raise your torso back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","lower back"],"target":"glutes","image":"images/0749-1bQkKZK.jpg","gif_url":"videos/0749-1bQkKZK.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1359","name":"smith bent over row","category":"back","equipment":"smith machine","instruction_steps":{"en":["Set up the smith machine with the bar at hip height.","Stand facing the bar with your feet shoulder-width apart.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.","Pull the bar towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the bar back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/1359-ZX9UZmj.jpg","gif_url":"videos/1359-ZX9UZmj.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0750","name":"smith chair squat","category":"upper legs","equipment":"smith machine","instruction_steps":{"en":["Adjust the height of the smith machine bar to a comfortable position.","Stand with your feet shoulder-width apart, toes slightly turned out.","Place the barbell across your upper back, resting it on your traps.","Engage your core and keep your chest up as you slowly lower your body by bending your knees and hips.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves"],"target":"quads","image":"images/0750-Gu2rNJd.jpg","gif_url":"videos/0750-Gu2rNJd.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0751","name":"smith close-grip bench press","category":"upper arms","equipment":"smith machine","instruction_steps":{"en":["Adjust the seat height and position yourself on the bench with your feet flat on the ground.","Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.","Lower the barbell towards your chest, keeping your elbows close to your body.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0751-WcHl7ru.jpg","gif_url":"videos/0751-WcHl7ru.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0752","name":"smith deadlift","category":"upper legs","equipment":"smith machine","instruction_steps":{"en":["Set up the smith machine with the bar at hip height.","Stand with your feet shoulder-width apart, toes pointing slightly outward.","Bend at the hips and knees, keeping your back straight and chest up, and grip the bar with an overhand grip slightly wider than shoulder-width apart.","Engage your core and lift the bar by extending your hips and knees, keeping the bar close to your body.","Stand up straight, fully extending your hips and knees.","Lower the bar back down by bending at the hips and knees, maintaining control and keeping your back straight.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps","lower back"],"target":"glutes","image":"images/0752-UfePqpx.jpg","gif_url":"videos/0752-UfePqpx.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0753","name":"smith decline bench press","category":"chest","equipment":"smith machine","instruction_steps":{"en":["Adjust the decline bench to the desired angle.","Lie down on the bench with your feet secured under the foot pads.","Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/0753-ETZfAbZ.jpg","gif_url":"videos/0753-ETZfAbZ.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0754","name":"smith decline reverse-grip press","category":"chest","equipment":"smith machine","instruction_steps":{"en":["Adjust the smith machine to a decline position.","Lie down on the bench with your feet secured under the foot pads.","Grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart.","Unrack the barbell and lower it towards your chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/0754-MY9P1WA.jpg","gif_url":"videos/0754-MY9P1WA.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1433","name":"smith front squat (clean grip)","category":"upper legs","equipment":"smith machine","instruction_steps":{"en":["Set up the smith machine with the barbell at shoulder height.","Stand facing the barbell with your feet shoulder-width apart.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Step back and position the barbell on your front shoulders, resting it on your collarbone and deltoids.","Keep your chest up, back straight, and core engaged.","Lower your body by bending at the knees and hips, as if sitting back into a chair.","Continue lowering until your thighs are parallel to the ground or slightly below.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves","core"],"target":"glutes","image":"images/1433-lFhb2Rw.jpg","gif_url":"videos/1433-lFhb2Rw.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3281","name":"smith full squat","category":"upper legs","equipment":"smith machine","instruction_steps":{"en":["Set up the smith machine with the barbell at shoulder height.","Stand with your feet shoulder-width apart, toes slightly turned out.","Step under the bar and position it across your upper back, resting on your traps.","Grip the bar with your hands slightly wider than shoulder-width apart.","Unrack the bar and take a step back, maintaining a stable stance.","Keeping your chest up and core engaged, initiate the squat by pushing your hips back and bending your knees.","Lower your body until your thighs are parallel to the ground, or as low as your flexibility allows.","Pause for a moment at the bottom, then drive through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/3281-NNoHCEA.jpg","gif_url":"videos/3281-NNoHCEA.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0755","name":"smith hack squat","category":"upper legs","equipment":"smith machine","instruction_steps":{"en":["Adjust the barbell on the smith machine to an appropriate height for your body.","Stand with your feet shoulder-width apart, toes slightly pointed outwards.","Position yourself under the barbell, resting it on your upper traps and shoulders.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Engage your core and keep your chest up as you unrack the barbell.","Take a step back and position your feet slightly wider than shoulder-width apart.","Bend your knees and lower your body down, keeping your chest up and back straight.","Continue descending until your thighs are parallel to the ground or slightly below.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0755-ZuPXtCK.jpg","gif_url":"videos/0755-ZuPXtCK.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0756","name":"smith hip raise","category":"waist","equipment":"smith machine","instruction_steps":{"en":["Position yourself on the smith machine with your back against the pad and your feet shoulder-width apart.","Place your hands on the barbell, slightly wider than shoulder-width apart.","Engage your core and glutes, then push through your heels to raise your hips off the ground.","Continue lifting until your body forms a straight line from your knees to your shoulders.","Hold for a moment at the top, then slowly lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","hamstrings"],"target":"abs","image":"images/0756-CqhoytW.jpg","gif_url":"videos/0756-CqhoytW.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0757","name":"smith incline bench press","category":"chest","equipment":"smith machine","instruction_steps":{"en":["Adjust the bench to a 30-45 degree incline.","Sit on the bench with your back flat against the pad and feet firmly on the ground.","Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your upper chest, keeping your elbows slightly tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/0757-5v7KYld.jpg","gif_url":"videos/0757-5v7KYld.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0758","name":"smith incline reverse-grip press","category":"chest","equipment":"smith machine","instruction_steps":{"en":["Adjust the seat of the smith machine to a comfortable incline angle.","Sit on the machine with your back against the pad and your feet flat on the ground.","Grasp the bar with an overhand grip that is slightly wider than shoulder-width apart.","Unrack the bar and lower it slowly towards your chest, keeping your elbows tucked in.","Pause for a moment when the bar is just above your chest.","Push the bar back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/0758-78VqWQK.jpg","gif_url":"videos/0758-78VqWQK.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0759","name":"smith incline shoulder raises","category":"chest","equipment":"smith machine","instruction_steps":{"en":["Adjust the smith machine to an incline position.","Stand facing the machine with your feet shoulder-width apart.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and core engaged.","Raise the barbell up towards the ceiling, leading with your elbows.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"deltoids","secondary_muscles":["deltoids","trapezius"],"target":"serratus anterior","image":"images/0759-ayAHcEm.jpg","gif_url":"videos/0759-ayAHcEm.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0760","name":"smith leg press","category":"upper legs","equipment":"smith machine","instruction_steps":{"en":["Adjust the seat and footplate of the smith machine to a comfortable position.","Sit on the machine with your back against the backrest and your feet shoulder-width apart on the footplate.","Grasp the handles or sides of the machine for stability.","Push the footplate away from you by extending your legs, keeping your back against the backrest.","Pause for a moment at the fully extended position.","Slowly bend your knees and lower the footplate back towards you, returning to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0760-7zdxRTl.jpg","gif_url":"videos/0760-7zdxRTl.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1434","name":"smith low bar squat","category":"upper legs","equipment":"smith machine","instruction_steps":{"en":["Set up the smith machine with the barbell at a height that allows you to comfortably rest it on your upper back.","Stand with your feet shoulder-width apart, toes slightly turned outwards.","Step under the bar and position it across your upper back, resting it on your traps.","Grip the bar with your hands slightly wider than shoulder-width apart.","Unrack the bar by straightening your legs and stepping back from the rack.","Take a deep breath and brace your core.","Initiate the squat by pushing your hips back and bending your knees.","Lower your body until your thighs are parallel to the ground or slightly below.","Keep your chest up and your back straight throughout the movement.","Drive through your heels to stand back up, extending your hips and knees.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/1434-RGLscZM.jpg","gif_url":"videos/1434-RGLscZM.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1683","name":"smith machine bicep curl","category":"upper arms","equipment":"smith machine","instruction_steps":{"en":["Adjust the height of the smith machine bar to be at waist level.","Stand facing the smith machine with your feet shoulder-width apart.","Grasp the bar with an underhand grip, hands slightly wider than shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary.","Exhale and curl the bar up towards your shoulders, contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the bar back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/1683-zILLZ98.jpg","gif_url":"videos/1683-zILLZ98.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1625","name":"smith machine decline close grip bench press","category":"upper arms","equipment":"smith machine","instruction_steps":{"en":["Adjust the bench on the smith machine to a decline position.","Lie down on the bench with your feet firmly planted on the ground.","Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows close to your body.","Pause for a moment when the barbell is just above your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/1625-yB9SvIF.jpg","gif_url":"videos/1625-yB9SvIF.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1752","name":"smith machine incline tricep extension","category":"upper arms","equipment":"smith machine","instruction_steps":{"en":["Adjust the seat of the smith machine so that the bar is at shoulder height.","Sit on the bench with your back against the pad and your feet flat on the ground.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Extend your arms fully, lifting the bar off the rack and holding it directly above your chest.","Lower the bar slowly towards your forehead, keeping your elbows close to your head.","Pause for a moment at the bottom, then push the bar back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/1752-o8aOcrz.jpg","gif_url":"videos/1752-o8aOcrz.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1626","name":"smith machine reverse decline close grip bench press","category":"chest","equipment":"smith machine","instruction_steps":{"en":["Adjust the smith machine to a decline position.","Lie down on the bench with your feet secured under the foot pads.","Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the barbell back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1626-QyO6Uma.jpg","gif_url":"videos/1626-QyO6Uma.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0761","name":"smith narrow row","category":"back","equipment":"smith machine","instruction_steps":{"en":["Adjust the seat height and position yourself on the machine with your feet flat on the floor.","Grasp the handles with an overhand grip, slightly narrower than shoulder-width apart.","Keep your back straight and your chest up as you pull the handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","rear deltoids"],"target":"upper back","image":"images/0761-JGKowMS.jpg","gif_url":"videos/0761-JGKowMS.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1360","name":"smith one arm row","category":"back","equipment":"smith machine","instruction_steps":{"en":["Adjust the height of the smith machine bar to waist level.","Stand facing the smith machine with your feet shoulder-width apart.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Grasp the bar with one hand using an overhand grip, with your palm facing down.","Keep your elbow close to your body and pull the bar towards your waist, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly lower the bar back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/1360-Q4DSJPC.jpg","gif_url":"videos/1360-Q4DSJPC.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1393","name":"smith one leg floor calf raise","category":"lower legs","equipment":"smith machine","instruction_steps":{"en":["Position yourself on the floor under the smith machine bar, facing away from the machine.","Place the balls of your feet on a raised surface, such as a weight plate or block.","Position the smith machine bar across your lower legs, just above your ankles.","Hold onto the bar with your hands for stability.","Raise your heels off the ground by extending your ankles, lifting your body up.","Pause at the top of the movement, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"calves","image":"images/1393-9GXrTE6.jpg","gif_url":"videos/1393-9GXrTE6.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0762","name":"smith rear delt row","category":"shoulders","equipment":"smith machine","instruction_steps":{"en":["Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the ground.","Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Keep your back straight and your core engaged as you pull the handles towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"trapezius","secondary_muscles":["trapezius","rhomboids","biceps"],"target":"delts","image":"images/0762-nFUwqG6.jpg","gif_url":"videos/0762-nFUwqG6.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0763","name":"smith reverse calf raises","category":"lower legs","equipment":"smith machine","instruction_steps":{"en":["Adjust the smith machine bar to a height just below your shoulders.","Stand facing the bar with your feet hip-width apart and toes pointing forward.","Place the balls of your feet on the edge of a step or platform, with your heels hanging off.","Hold onto the bar for support, keeping your back straight and core engaged.","Raise your heels as high as possible, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"target":"calves","image":"images/0763-ywaNfuh.jpg","gif_url":"videos/0763-ywaNfuh.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1394","name":"smith reverse calf raises","category":"lower legs","equipment":"smith machine","instruction_steps":{"en":["Adjust the smith machine bar to a height just below your shoulders.","Stand facing the bar with your feet hip-width apart and toes pointing forward.","Place the balls of your feet on the edge of a step or platform, with your heels hanging off.","Hold onto the bar for support.","Raise your heels as high as possible, lifting your body up onto your toes.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"target":"calves","image":"images/1394-Lsqrgh4.jpg","gif_url":"videos/1394-Lsqrgh4.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1361","name":"smith reverse grip bent over row","category":"back","equipment":"smith machine","instruction_steps":{"en":["Set up the smith machine with the bar at hip height.","Stand facing the bar with your feet shoulder-width apart.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Grasp the bar with an underhand grip, hands shoulder-width apart.","Pull the bar towards your lower chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the bar back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"upper back","image":"images/1361-aaxA3cm.jpg","gif_url":"videos/1361-aaxA3cm.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0764","name":"smith reverse-grip press","category":"chest","equipment":"smith machine","instruction_steps":{"en":["Adjust the height of the smith machine bar to chest level.","Stand facing the bar with your feet shoulder-width apart.","Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.","Step back and position yourself with a slight bend in your knees.","Keep your chest up and core engaged throughout the exercise.","Lower the bar towards your chest, keeping your elbows tucked in.","Pause for a moment at the bottom, then push the bar back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/0764-zK8Fu1W.jpg","gif_url":"videos/0764-zK8Fu1W.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1395","name":"smith seated one leg calf raise","category":"lower legs","equipment":"smith machine","instruction_steps":{"en":["Sit on the machine with your back against the pad and your feet on the footrest.","Place one leg on the footrest and keep the other leg off the footrest.","Using your calf muscles, raise your heel as high as possible.","Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings"],"target":"calves","image":"images/1395-0S75mYG.jpg","gif_url":"videos/1395-0S75mYG.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0765","name":"smith seated shoulder press","category":"shoulders","equipment":"smith machine","instruction_steps":{"en":["Adjust the seat height so that the handles are at shoulder level.","Sit on the machine with your back against the pad and your feet flat on the floor.","Grasp the handles with an overhand grip and lift them off the supports, extending your arms fully.","Lower the handles down to shoulder level, keeping your elbows slightly bent.","Press the handles up overhead until your arms are fully extended.","Pause for a moment at the top, then slowly lower the handles back down to shoulder level.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0765-xUwnBMT.jpg","gif_url":"videos/0765-xUwnBMT.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1426","name":"smith seated wrist curl","category":"lower arms","equipment":"smith machine","instruction_steps":{"en":["Sit on a bench in front of a Smith machine with your feet flat on the ground.","Grasp the barbell with an underhand grip, hands shoulder-width apart.","Rest your forearms on your thighs, allowing your wrists to hang off.","Slowly curl your wrists upward, bringing the barbell towards your forearms.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","brachialis"],"target":"forearms","image":"images/1426-B6dAO1t.jpg","gif_url":"videos/1426-B6dAO1t.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0766","name":"smith shoulder press","category":"shoulders","equipment":"smith machine","instruction_steps":{"en":["Adjust the seat height and position yourself on the smith machine with your feet shoulder-width apart.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Lift the bar off the rack and position it at shoulder level, with your elbows bent and palms facing forward.","Press the bar upward until your arms are fully extended overhead.","Pause for a moment at the top, then slowly lower the bar back down to shoulder level.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0766-903mzG8.jpg","gif_url":"videos/0766-903mzG8.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0767","name":"smith shrug","category":"back","equipment":"smith machine","instruction_steps":{"en":["Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Keep your arms straight and your shoulders relaxed.","Lift your shoulders up towards your ears, squeezing your traps at the top.","Hold for a moment, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"traps","image":"images/0767-OUQ0ZyW.jpg","gif_url":"videos/0767-OUQ0ZyW.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0768","name":"smith single leg split squat","category":"upper legs","equipment":"smith machine","instruction_steps":{"en":["Stand in front of the smith machine with your feet shoulder-width apart.","Place one foot behind you on a bench or step, with your toes pointing forward.","Hold onto the smith machine bar for stability.","Bend your front knee and lower your body down into a lunge position, keeping your back straight.","Pause for a moment at the bottom, then push through your front heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."]},"muscle_group":"glutes","secondary_muscles":["glutes","hamstrings"],"target":"quads","image":"images/0768-wWFspEi.jpg","gif_url":"videos/0768-wWFspEi.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0769","name":"smith sprint lunge","category":"upper legs","equipment":"smith machine","instruction_steps":{"en":["Set up the smith machine with the barbell at hip height.","Stand facing away from the machine with your feet shoulder-width apart.","Step back with your right foot and place it on the barbell, resting the top of your foot on the bar.","Bend your left knee and lower your body into a lunge position, keeping your back straight.","Push through your left heel to return to the starting position.","Repeat on the other side, stepping back with your left foot.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0769-HsjbB1z.jpg","gif_url":"videos/0769-HsjbB1z.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0770","name":"smith squat","category":"upper legs","equipment":"smith machine","instruction_steps":{"en":["Set up the smith machine with the barbell at an appropriate height for your squat.","Stand with your feet shoulder-width apart, toes slightly turned out.","Position yourself under the barbell, resting it on your upper traps and shoulders.","Grip the barbell with a wide grip, slightly wider than shoulder-width apart.","Engage your core and unrack the barbell, stepping back to clear the rack.","Keeping your chest up and back straight, initiate the squat by bending at the hips and knees.","Lower your body until your thighs are parallel to the ground or slightly below.","Pause for a moment at the bottom, then drive through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0770-jFtipLl.jpg","gif_url":"videos/0770-jFtipLl.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0771","name":"smith standing back wrist curl","category":"lower arms","equipment":"smith machine","instruction_steps":{"en":["Stand facing the smith machine with your feet shoulder-width apart.","Grasp the barbell with an overhand grip, hands shoulder-width apart.","Keep your back straight and your elbows close to your body.","Slowly curl your wrists upwards, bringing the barbell towards your body.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","triceps"],"target":"forearms","image":"images/0771-hfmQ0Tz.jpg","gif_url":"videos/0771-hfmQ0Tz.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0772","name":"smith standing behind head military press","category":"shoulders","equipment":"smith machine","instruction_steps":{"en":["Adjust the seat height of the smith machine so that the bar is at shoulder level.","Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Lift the bar off the rack and step back, maintaining a stable stance.","Position the bar behind your head, resting on your upper traps.","Keep your core engaged and your chest lifted throughout the exercise.","Press the bar overhead by extending your arms, fully straightening them.","Pause briefly at the top of the movement, then slowly lower the bar back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0772-ht8xDrP.jpg","gif_url":"videos/0772-ht8xDrP.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0773","name":"smith standing leg calf raise","category":"lower legs","equipment":"smith machine","instruction_steps":{"en":["Adjust the smith machine bar to a height that allows you to stand with your feet flat on the ground and your shoulders under the bar.","Position yourself under the bar with your feet shoulder-width apart and your toes pointing forward.","Place your hands on the bar for stability.","Engage your calves and slowly raise your heels off the ground, lifting your body up onto your toes.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"calves","image":"images/0773-6MaEjVA.jpg","gif_url":"videos/0773-6MaEjVA.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0774","name":"smith standing military press","category":"shoulders","equipment":"smith machine","instruction_steps":{"en":["Stand with your feet shoulder-width apart and your knees slightly bent.","Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Lift the barbell off the rack and bring it down to shoulder level, with your palms facing forward.","Press the barbell upward until your arms are fully extended overhead.","Pause for a moment at the top, then slowly lower the barbell back down to shoulder level.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0774-jjUPrze.jpg","gif_url":"videos/0774-jjUPrze.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3142","name":"smith sumo squat","category":"upper legs","equipment":"smith machine","instruction_steps":{"en":["Set up the smith machine with the barbell at hip height.","Stand with your feet wider than shoulder-width apart, toes pointing outwards.","Position yourself under the barbell, resting it on your upper back and shoulders.","Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees.","Lower yourself until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/3142-dzz6BiV.jpg","gif_url":"videos/3142-dzz6BiV.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1396","name":"smith toe raise","category":"lower legs","equipment":"smith machine","instruction_steps":{"en":["Adjust the smith machine bar to a height that allows you to comfortably stand with your feet flat on the ground.","Position yourself under the bar with your shoulders directly below it and your feet shoulder-width apart.","Place the balls of your feet on a raised platform or weight plates, with your heels hanging off the edge.","Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Engage your core and keep your back straight throughout the exercise.","Slowly raise your heels as high as possible, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"ankles","secondary_muscles":["ankles","shins"],"target":"calves","image":"images/1396-Y4QlY8z.jpg","gif_url":"videos/1396-Y4QlY8z.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0775","name":"smith upright row","category":"shoulders","equipment":"smith machine","instruction_steps":{"en":["Stand with your feet shoulder-width apart, facing the smith machine.","Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Keep your back straight and your core engaged.","Pull the barbell up towards your chin, leading with your elbows.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"traps","secondary_muscles":["traps","biceps"],"target":"delts","image":"images/0775-1DN3iz4.jpg","gif_url":"videos/0775-1DN3iz4.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1308","name":"smith wide grip bench press","category":"chest","equipment":"smith machine","instruction_steps":{"en":["Adjust the bench to a comfortable position on the smith machine.","Lie down on the bench with your feet flat on the ground.","Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows out to the sides.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1308-zoOvPcx.jpg","gif_url":"videos/1308-zoOvPcx.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1309","name":"smith wide grip decline bench press","category":"chest","equipment":"smith machine","instruction_steps":{"en":["Adjust the decline bench to the desired angle.","Lie down on the bench with your feet secured under the foot pads.","Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.","Unrack the barbell and lower it slowly towards your chest, keeping your elbows pointed outwards.","Pause for a moment when the barbell touches your chest.","Push the barbell back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1309-wi2H9QX.jpg","gif_url":"videos/1309-wi2H9QX.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0776","name":"snatch pull","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and the barbell on the ground in front of you.","Bend your knees and hinge at the hips to lower into a squat position, gripping the barbell with an overhand grip.","Keep your back straight and chest up as you drive through your heels to lift the barbell off the ground, extending your hips and knees.","As the barbell reaches hip level, explosively pull it upwards, shrugging your shoulders and pulling your elbows high and to the sides.","As the barbell reaches its highest point, quickly drop underneath it, pulling yourself into a deep squat position.","Catch the barbell overhead with your arms fully extended and your knees bent.","Stand up by extending your hips and knees, keeping the barbell overhead.","Lower the barbell back down to the starting position by reversing the movement.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes","calves"],"target":"quads","image":"images/0776-dG5Smob.jpg","gif_url":"videos/0776-dG5Smob.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0777","name":"spell caster","category":"waist","equipment":"dumbbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold a dumbbell in one hand.","Bend your knees slightly and hinge forward at the waist, keeping your back straight.","Extend your arm with the dumbbell towards the opposite foot, rotating your torso as you do so.","Return to the starting position and repeat on the other side.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques","lower back"],"target":"abs","image":"images/0777-p9cCe2r.jpg","gif_url":"videos/0777-p9cCe2r.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1362","name":"sphinx","category":"back","equipment":"body weight","instruction_steps":{"en":["Lie face down on the ground with your forearms flat on the floor, elbows directly under your shoulders.","Engage your core and lift your chest off the ground, keeping your forearms and toes on the floor.","Hold this position for a few seconds, making sure to keep your neck in a neutral position.","Slowly lower your chest back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","hamstrings"],"target":"spine","image":"images/1362-DIVyqrU.jpg","gif_url":"videos/1362-DIVyqrU.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0778","name":"spider crawl push up","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.","Bring your right knee towards your right elbow, keeping it off the ground.","As you bring your right knee back, simultaneously lower your body towards the ground by bending your elbows.","Push back up to the starting position and repeat with your left knee towards your left elbow.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"core","secondary_muscles":["core","chest","shoulders"],"target":"glutes","image":"images/0778-P9GFBME.jpg","gif_url":"videos/0778-P9GFBME.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1363","name":"spine stretch","category":"back","equipment":"body weight","instruction_steps":{"en":["Sit on the ground with your legs extended in front of you.","Place your hands on the ground behind you, fingers pointing towards your body.","Engage your core and slowly lean back, keeping your back straight.","Continue leaning back until you feel a stretch in your spine.","Hold the stretch for a few seconds, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"spine","image":"images/1363-JbC2iaV.jpg","gif_url":"videos/1363-JbC2iaV.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2329","name":"spine twist","category":"waist","equipment":"body weight","instruction_steps":{"en":["Sit on the ground with your legs extended in front of you.","Bend your knees and place your feet flat on the ground, hip-width apart.","Place your hands behind your head with your elbows pointing outwards.","Engage your abs and slowly twist your torso to the right, bringing your right elbow towards your left knee.","Pause for a moment at the end of the twist, then slowly return to the starting position.","Repeat the twist to the left side, bringing your left elbow towards your right knee.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques","lower back"],"target":"abs","image":"images/2329-2jl9K55.jpg","gif_url":"videos/2329-2jl9K55.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2368","name":"split squats","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart.","Take a step forward with one foot and place it about two feet in front of the other foot.","Lower your body by bending your knees and hips, keeping your back straight.","Continue lowering until your front thigh is parallel to the ground, and your back knee is hovering just above the ground.","Pause for a moment, then push through your front heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."]},"muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves"],"target":"quads","image":"images/2368-9E25EOx.jpg","gif_url":"videos/2368-9E25EOx.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0786","name":"squat jerk","category":"upper legs","equipment":"barbell","instruction_steps":{"en":["Start with the barbell resting on your shoulders, with your feet shoulder-width apart.","Lower your body into a squat position, keeping your chest up and your knees tracking over your toes.","As you reach the bottom of the squat, explosively drive through your legs and push the barbell overhead.","As the barbell reaches its peak, quickly drop into a split position, with one foot forward and one foot back.","Catch the barbell overhead with your arms fully extended and your back knee slightly touching the ground.","Stand up from the split position, bringing your feet back together.","Lower the barbell back to your shoulders and repeat for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves","core"],"target":"quads","image":"images/0786-IMRsOCn.jpg","gif_url":"videos/0786-IMRsOCn.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1705","name":"squat on bosu ball","category":"upper legs","equipment":"bosu ball","instruction_steps":{"en":["Place the bosu ball on the ground with the flat side up.","Stand with your feet shoulder-width apart and position yourself on top of the bosu ball.","Lower your body down by bending your knees and hips, as if sitting back into a chair.","Keep your chest up and your weight on your heels.","Lower yourself until your thighs are parallel to the ground.","Pause for a moment, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves"],"target":"quads","image":"images/1705-T2fA5Ir.jpg","gif_url":"videos/1705-T2fA5Ir.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1685","name":"squat to overhead reach","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart and toes slightly turned out.","Lower your body down into a squat position by bending your knees and pushing your hips back.","As you come up from the squat, extend your arms overhead, reaching towards the ceiling.","Return to the starting position by lowering your arms and bending your knees to squat down again.","Repeat for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","core"],"target":"quads","image":"images/1685-QChZi3x.jpg","gif_url":"videos/1685-QChZi3x.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1686","name":"squat to overhead reach with twist","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart and toes slightly turned out.","Lower your body into a squat position by bending your knees and pushing your hips back.","As you come up from the squat, raise your arms overhead and twist your torso to one side.","Return to the starting position and repeat the squat, this time twisting your torso to the opposite side.","Continue alternating sides with each squat repetition."]},"muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","core"],"target":"quads","image":"images/1686-5BZHW9s.jpg","gif_url":"videos/1686-5BZHW9s.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2297","name":"stability ball crunch (full range hands behind head)","category":"waist","equipment":"stability ball","instruction_steps":{"en":["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly curl your upper body forward, bringing your chest towards your knees.","Pause for a moment at the top, then slowly lower your upper body back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/2297-Gn5FwYT.jpg","gif_url":"videos/2297-Gn5FwYT.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3291","name":"stalder press","category":"upper arms","equipment":"body weight","instruction_steps":{"en":["Start by standing with your feet shoulder-width apart and your arms extended overhead.","Bend your knees slightly and engage your core.","Lower your body down into a squat position while keeping your arms extended overhead.","As you squat down, press your arms down towards the ground, engaging your triceps.","Pause for a moment at the bottom of the squat, then push through your heels to stand back up while simultaneously raising your arms back overhead.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","core"],"target":"triceps","image":"images/3291-zd4P4B2.jpg","gif_url":"videos/3291-zd4P4B2.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3669","name":"standing archer","category":"back","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart and your knees slightly bent.","Extend your arms straight out in front of you at shoulder height, parallel to the ground.","Rotate your torso to the right, keeping your arms extended and your back straight.","As you rotate, extend your right arm forward and your left arm back, mimicking the motion of drawing a bowstring.","Hold the position for a moment, then return to the starting position.","Repeat the motion, this time rotating your torso to the left and extending your left arm forward and your right arm back.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","biceps","forearms"],"target":"upper back","image":"images/3669-JF8AkMX.jpg","gif_url":"videos/3669-JF8AkMX.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0788","name":"standing behind neck press","category":"shoulders","equipment":"barbell","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold the barbell behind your neck with an overhand grip.","Keep your back straight and core engaged.","Press the barbell overhead by extending your arms, fully extending your elbows.","Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0788-xDh0lJr.jpg","gif_url":"videos/0788-xDh0lJr.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1490","name":"standing calf raise (on a staircase)","category":"lower legs","equipment":"body weight","instruction_steps":{"en":["Stand on the edge of a step or a sturdy platform with your heels hanging off and your toes on the step.","Hold onto a railing or wall for balance if needed.","Slowly raise your heels as high as possible, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"ankles","secondary_muscles":["ankles","feet"],"target":"calves","image":"images/1490-6HmFgmx.jpg","gif_url":"videos/1490-6HmFgmx.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1397","name":"standing calves","category":"lower legs","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart, toes pointing forward.","Raise your heels off the ground as high as possible, standing on your toes.","Hold the position for a moment, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"calves","image":"images/1397-XIHEoCG.jpg","gif_url":"videos/1397-XIHEoCG.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1398","name":"standing calves calf stretch","category":"lower legs","equipment":"body weight","instruction_steps":{"en":["Stand facing a wall or sturdy object, about an arm's length away.","Place your hands on the wall or object at shoulder height.","Step back with one foot, keeping your heel flat on the ground.","Bend your front knee slightly and lean forward, keeping your back leg straight.","You should feel a stretch in your calf muscle.","Hold the stretch for 20-30 seconds.","Repeat on the other leg."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"calves","image":"images/1398-qOKcgVP.jpg","gif_url":"videos/1398-qOKcgVP.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1599","name":"standing hamstring and calf stretch with strap","category":"upper legs","equipment":"rope","instruction_steps":{"en":["Stand upright with your feet shoulder-width apart.","Hold the strap with both hands and place it around the ball of your foot.","Keep your leg straight and slowly lean forward from your hips, keeping your back straight.","Feel the stretch in your hamstring and calf muscles.","Hold the stretch for 20-30 seconds.","Release the stretch and repeat with the other leg.","Repeat for the desired number of repetitions."]},"muscle_group":"calves","secondary_muscles":["calves"],"target":"hamstrings","image":"images/1599-xTjr103.jpg","gif_url":"videos/1599-xTjr103.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0794","name":"standing lateral stretch","category":"back","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart and your knees slightly bent.","Extend your arms straight out to the sides, parallel to the ground.","Slowly lean your upper body to one side, feeling a stretch in your side and lats.","Hold the stretch for 15-30 seconds.","Return to the starting position and repeat on the other side.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","obliques"],"target":"lats","image":"images/0794-1jXLYEw.jpg","gif_url":"videos/0794-1jXLYEw.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1364","name":"standing pelvic tilt","category":"back","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart and your knees slightly bent.","Place your hands on your hips or let them hang by your sides.","Engage your core muscles and tilt your pelvis forward, pushing your lower back towards the wall behind you.","Hold the position for a few seconds, then release and return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"abdominals","secondary_muscles":["abdominals"],"target":"spine","image":"images/1364-cuKYxhu.jpg","gif_url":"videos/1364-cuKYxhu.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0795","name":"standing single leg curl","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Stand with your feet hip-width apart and your hands on your hips.","Shift your weight onto your left leg and lift your right foot off the ground, bending your knee.","Slowly curl your right heel towards your glutes, squeezing your hamstring.","Pause for a moment at the top, then slowly lower your right foot back down to the starting position.","Repeat for the desired number of repetitions, then switch legs."]},"muscle_group":"glutes","secondary_muscles":["glutes"],"target":"hamstrings","image":"images/0795-C5jncD2.jpg","gif_url":"videos/0795-C5jncD2.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0796","name":"standing wheel rollerout","category":"waist","equipment":"wheel roller","instruction_steps":{"en":["Start by standing tall with your feet shoulder-width apart and the wheel roller in front of you.","Bend at your waist and slowly roll the wheel forward, keeping your back straight and your core engaged.","Continue rolling forward until you feel a stretch in your abs and your body is extended as far as possible.","Pause for a moment, then slowly roll the wheel back towards your body, returning to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"lower back","secondary_muscles":["lower back","shoulders"],"target":"abs","image":"images/0796-KtRomty.jpg","gif_url":"videos/0796-KtRomty.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3223","name":"star jump (male)","category":"cardio","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart and your arms by your sides.","Bend your knees slightly and jump up explosively.","As you jump, spread your legs and extend your arms out to the sides, forming a star shape with your body.","Land softly on the balls of your feet with your knees slightly bent.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"cardiovascular system","image":"images/3223-HtfCpfi.jpg","gif_url":"videos/3223-HtfCpfi.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2138","name":"stationary bike run v. 3","category":"cardio","equipment":"stationary bike","instruction_steps":{"en":["Adjust the seat height and position to ensure proper alignment.","Place your feet on the pedals and secure them with the straps if available.","Start pedaling at a comfortable pace.","Maintain a steady rhythm and increase the resistance as desired.","Engage your core muscles to maintain stability and proper posture.","Continue pedaling for the desired duration of your workout.","Gradually decrease the resistance and slow down before coming to a complete stop.","Stretch your legs and cool down after the workout."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"cardiovascular system","image":"images/2138-H1PESYI.jpg","gif_url":"videos/2138-H1PESYI.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0798","name":"stationary bike walk","category":"cardio","equipment":"leverage machine","instruction_steps":{"en":["Adjust the seat height and position on the stationary bike to ensure proper alignment.","Place your feet on the pedals and secure them with the straps if available.","Start pedaling at a comfortable pace, keeping your back straight and core engaged.","Maintain a steady rhythm and increase the resistance level if desired.","Continue pedaling for the desired duration of your cardio workout.","Cool down by gradually reducing your pace and resistance level.","Stretch your leg muscles after the workout to prevent tightness and promote recovery."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"cardiovascular system","image":"images/0798-a8VDgLw.jpg","gif_url":"videos/0798-a8VDgLw.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3314","name":"straddle maltese","category":"waist","equipment":"body weight","instruction_steps":{"en":["Start by hanging from a pair of rings with your arms fully extended and your body in a straight line.","Spread your legs wide apart, forming a straddle position.","Engage your core and slowly lower your body until your arms are parallel to the ground.","Hold this position for a few seconds, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","chest"],"target":"abs","image":"images/3314-HfqciZF.jpg","gif_url":"videos/3314-HfqciZF.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3298","name":"straddle planche","category":"waist","equipment":"body weight","instruction_steps":{"en":["Start in a push-up position with your hands shoulder-width apart and your feet spread wide apart.","Engage your core and slowly shift your weight forward, bringing your shoulders over your hands.","Bend your elbows and lower your body towards the ground, keeping your elbows close to your sides.","Pause for a moment at the bottom, then push through your hands to straighten your arms and lift your body back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps","chest"],"target":"abs","image":"images/3298-BL3GHeY.jpg","gif_url":"videos/3298-BL3GHeY.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1427","name":"straight leg outer hip abductor","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Lie on your side with your legs straight and stacked on top of each other.","Place your bottom arm under your head for support.","Engage your core and lift your top leg as high as possible without rotating your hips or leaning backward.","Pause for a moment at the top, then slowly lower your leg back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},"muscle_group":"glutes","secondary_muscles":["glutes","hamstrings"],"target":"abductors","image":"images/1427-mQ1tBXn.jpg","gif_url":"videos/1427-mQ1tBXn.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0803","name":"superman push-up","category":"chest","equipment":"body weight","instruction_steps":{"en":["Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together.","Engage your core and lower your body towards the ground, keeping your elbows close to your sides.","As you lower your body, simultaneously lift your right arm and left leg off the ground, extending them straight out.","Pause for a moment at the top, then lower your arm and leg back down while pushing yourself back up to the starting position.","Repeat the movement, this time lifting your left arm and right leg.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"core","secondary_muscles":["core","shoulders"],"target":"pectorals","image":"images/0803-4GqRrAk.jpg","gif_url":"videos/0803-4GqRrAk.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0805","name":"suspended abdominal fallout","category":"waist","equipment":"body weight","instruction_steps":{"en":["Attach a suspension trainer to a high anchor point and adjust the straps to waist height.","Stand facing away from the anchor point and hold the handles with your arms extended in front of you.","Lean forward at the waist, keeping your body straight and your core engaged.","Lower your body as far as you can while maintaining control and tension in your abs.","Pause for a moment at the bottom, then slowly raise your body back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques","hip flexors"],"target":"abs","image":"images/0805-X3TCNEU.jpg","gif_url":"videos/0805-X3TCNEU.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0806","name":"suspended push-up","category":"chest","equipment":"body weight","instruction_steps":{"en":["Find a suspension trainer and adjust it to an appropriate height.","Stand facing away from the anchor point and hold the handles with an overhand grip.","Walk your feet forward, leaning your body forward until your weight is supported by the suspension trainer.","Keep your body straight from head to heels, engage your core, and lower your chest towards the handles.","Push through your chest and arms to return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders","core"],"target":"pectorals","image":"images/0806-IaGQCrC.jpg","gif_url":"videos/0806-IaGQCrC.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0807","name":"suspended reverse crunch","category":"waist","equipment":"body weight","instruction_steps":{"en":["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your knees up towards your chest, curling your pelvis towards your ribcage.","Pause for a moment at the top, then slowly lower your knees back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0807-R1WYG5D.jpg","gif_url":"videos/0807-R1WYG5D.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0808","name":"suspended row","category":"back","equipment":"body weight","instruction_steps":{"en":["Set up a suspension trainer at an appropriate height.","Stand facing the anchor point with your feet shoulder-width apart.","Hold the handles with an overhand grip, palms facing each other.","Lean back, keeping your body straight and your heels on the ground.","Pull your chest towards the handles, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower yourself back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","shoulders"],"target":"upper back","image":"images/0808-4OaumBr.jpg","gif_url":"videos/0808-4OaumBr.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0809","name":"suspended split squat","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Stand facing away from a suspension trainer with your feet shoulder-width apart.","Extend one leg forward and place the top of your foot in the foot cradle of the suspension trainer.","Bend your standing leg and lower your body down into a lunge position, keeping your chest up and your knee in line with your toes.","Push through your heel to return to the starting position.","Repeat for the desired number of repetitions, then switch legs."]},"muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves"],"target":"quads","image":"images/0809-QpXqiq8.jpg","gif_url":"videos/0809-QpXqiq8.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3433","name":"swimmer kicks v. 2 (male)","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Lie face down on a mat with your arms extended overhead.","Engage your core and lift your chest and legs off the ground simultaneously.","Kick your legs up and down in a fluttering motion, as if you were swimming.","Continue kicking for the desired number of repetitions.","Lower your chest and legs back down to the starting position."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps","calves"],"target":"glutes","image":"images/3433-SP3hUez.jpg","gif_url":"videos/3433-SP3hUez.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3318","name":"swing 360","category":"cardio","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart and knees slightly bent.","Hold your arms straight out in front of you, parallel to the ground.","Engage your core and swing your arms in a circular motion, rotating your torso as you do so.","Continue the circular motion, swinging your arms and rotating your torso for the desired number of repetitions.","Remember to breathe throughout the exercise."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","core"],"target":"cardiovascular system","image":"images/3318-tnaj0mT.jpg","gif_url":"videos/3318-tnaj0mT.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1753","name":"three bench dip","category":"upper arms","equipment":"body weight","instruction_steps":{"en":["Sit on a bench with your hands gripping the edge, fingers pointing forward.","Slide your butt off the bench, supporting your weight with your hands.","Bend your elbows and lower your body until your upper arms are parallel to the ground.","Push yourself back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/1753-DQ0cqkT.jpg","gif_url":"videos/1753-DQ0cqkT.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2459","name":"tire flip","category":"upper legs","equipment":"tire","instruction_steps":{"en":["Stand with your feet shoulder-width apart, facing the tire.","Bend your knees and hinge at the hips, lowering into a squat position.","Reach down and grab the bottom edge of the tire with both hands, fingers facing towards you.","Engage your glutes and leg muscles, and explosively drive through your legs to lift the tire off the ground.","As the tire flips over, use your upper body strength to guide it and maintain control.","Once the tire is fully flipped, quickly step back and reset your stance.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps","core"],"target":"glutes","image":"images/2459-oZjMu1t.jpg","gif_url":"videos/2459-oZjMu1t.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0811","name":"trap bar deadlift","category":"upper legs","equipment":"trap bar","instruction_steps":{"en":["Stand with your feet shoulder-width apart and the trap bar on the ground in front of you.","Bend at the hips and knees to lower yourself down and grip the handles of the trap bar with an overhand grip.","Keep your back straight and chest up as you begin to lift the trap bar off the ground by extending your hips and knees.","As you lift, focus on driving through your heels and squeezing your glutes at the top of the movement.","Lower the trap bar back down to the ground by bending at the hips and knees, keeping your back straight throughout the movement.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","quadriceps","lower back"],"target":"glutes","image":"images/0811-jQGwmxN.jpg","gif_url":"videos/0811-jQGwmxN.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0814","name":"triceps dip","category":"upper arms","equipment":"body weight","instruction_steps":{"en":["Sit on the edge of a bench or chair with your hands gripping the edge, fingers pointing forward.","Slide your butt off the bench, supporting your weight with your hands.","Bend your elbows and lower your body towards the ground, keeping your back close to the bench.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0814-X6C6i5Y.jpg","gif_url":"videos/0814-X6C6i5Y.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0812","name":"triceps dip (bench leg)","category":"upper arms","equipment":"body weight","instruction_steps":{"en":["Sit on the edge of a bench with your hands gripping the edge, fingers pointing forward.","Walk your feet forward, sliding your butt off the bench, and straighten your arms.","Bend your elbows and lower your body towards the ground, keeping your back close to the bench.","Push through your palms to straighten your arms and return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0812-VuoerH0.jpg","gif_url":"videos/0812-VuoerH0.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0813","name":"triceps dip (between benches)","category":"upper arms","equipment":"body weight","instruction_steps":{"en":["Sit on a bench with your hands gripping the edge of the bench, fingers pointing forward.","Slide your butt off the bench, supporting your weight with your hands.","Bend your elbows and lower your body towards the ground, keeping your back close to the bench.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0813-Wgbn9qo.jpg","gif_url":"videos/0813-Wgbn9qo.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0815","name":"triceps dips floor","category":"upper arms","equipment":"body weight","instruction_steps":{"en":["Sit on the edge of a chair or bench with your hands next to your hips, fingers pointing forward.","Slide your butt off the front of the chair with your legs extended in front of you.","Straighten your arms, keeping a little bend in your elbows to keep tension on your triceps and off your elbow joints.","Slowly bend your elbows to lower your body toward the floor until your elbows are at about a 90-degree angle.","Once you reach the bottom of the movement, press down into the chair to straighten your elbows, returning to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0815-7aVz15j.jpg","gif_url":"videos/0815-7aVz15j.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0816","name":"triceps press","category":"upper arms","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart and your knees slightly bent.","Extend your arms straight out in front of you, parallel to the ground.","Bend your elbows and lower your body towards the ground, keeping your upper arms close to your sides.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0816-fSrPP6B.jpg","gif_url":"videos/0816-fSrPP6B.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0817","name":"triceps stretch","category":"upper arms","equipment":"body weight","instruction_steps":{"en":["Stand or sit upright with your back straight.","Extend one arm overhead, bending it at the elbow.","Place your opposite hand on the bent elbow and gently pull it towards your head.","Hold the stretch for 15-30 seconds, feeling a gentle stretch in your triceps.","Release the stretch and repeat on the other arm."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"triceps","image":"images/0817-uOV3Itw.jpg","gif_url":"videos/0817-uOV3Itw.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0871","name":"tuck crunch","category":"waist","equipment":"body weight","instruction_steps":{"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, lift your shoulder blades off the ground and bring your knees towards your chest, simultaneously curling your upper body towards your knees.","Pause for a moment at the top, then slowly lower your shoulder blades and extend your legs back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0871-BMMolZ3.jpg","gif_url":"videos/0871-BMMolZ3.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0818","name":"twin handle parallel grip lat pulldown","category":"back","equipment":"cable","instruction_steps":{"en":["Adjust the seat height and position yourself facing the cable machine.","Grasp the handles with an overhand grip, hands shoulder-width apart.","Sit down and position your thighs under the thigh pads, keeping your feet flat on the floor.","Lean back slightly and keep your chest up, maintaining a neutral spine.","Pull the handles down towards your upper chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, feeling the contraction in your lats.","Slowly release the handles and return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","rhomboids","rear deltoids"],"target":"lats","image":"images/0818-rkg41Fb.jpg","gif_url":"videos/0818-rkg41Fb.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1466","name":"twist hip lift","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Lie on your back with your knees bent and feet flat on the ground.","Place your hands by your sides for support.","Engage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders.","While keeping your hips lifted, twist your lower body to the right side, bringing your knees towards the ground.","Return to the starting position and repeat the twist to the left side.","Continue alternating twists for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques","hamstrings"],"target":"glutes","image":"images/1466-AX1kB0o.jpg","gif_url":"videos/1466-AX1kB0o.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2802","name":"twisted leg raise","category":"waist","equipment":"body weight","instruction_steps":{"en":["Lie flat on your back with your legs extended and your arms by your sides.","Place your hands under your glutes for support.","Engage your abs and lift both legs off the ground, keeping them straight.","As you lift your legs, twist your hips to one side, bringing your legs towards your opposite shoulder.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat the movement, this time twisting your hips to the other side.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques","hip flexors"],"target":"abs","image":"images/2802-C0eCeEt.jpg","gif_url":"videos/2802-C0eCeEt.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2801","name":"twisted leg raise (female)","category":"waist","equipment":"body weight","instruction_steps":{"en":["Lie flat on your back with your legs extended and your arms by your sides.","Bend your knees and lift your legs off the ground, bringing them towards your chest.","As you lift your legs, twist your hips to one side, bringing your knees towards your opposite shoulder.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat the movement, this time twisting your hips to the other side.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques","hip flexors"],"target":"abs","image":"images/2801-yT9tk17.jpg","gif_url":"videos/2801-yT9tk17.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3231","name":"two toe touch (male)","category":"back","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart and your arms extended out to the sides.","Bend forward at the waist, keeping your back straight and your knees slightly bent.","Reach down towards your toes with both hands, keeping your legs straight.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"spine","image":"images/3231-p195zsJ.jpg","gif_url":"videos/3231-p195zsJ.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1365","name":"upper back stretch","category":"back","equipment":"body weight","instruction_steps":{"en":["Stand up straight with your feet shoulder-width apart.","Extend your arms straight in front of you, parallel to the ground.","Interlace your fingers and rotate your palms away from your body.","Slowly raise your arms overhead, keeping them straight and parallel to each other.","As you raise your arms, squeeze your shoulder blades together.","Hold the stretch for 15-30 seconds, then release and repeat."]},"muscle_group":"shoulders","secondary_muscles":["shoulders"],"target":"upper back","image":"images/1365-GSDioYu.jpg","gif_url":"videos/1365-GSDioYu.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1366","name":"upward facing dog","category":"back","equipment":"body weight","instruction_steps":{"en":["Lie face down on the floor with your legs extended behind you.","Place your hands on the floor next to your lower ribs, fingers pointing forward.","Press your hands firmly into the floor and straighten your arms, lifting your torso and thighs off the ground.","Roll your shoulders back and down, opening your chest and lifting your gaze towards the ceiling.","Hold this position for a few breaths, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","chest"],"target":"spine","image":"images/1366-01qpYSe.jpg","gif_url":"videos/1366-01qpYSe.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3420","name":"v-sit on floor","category":"waist","equipment":"body weight","instruction_steps":{"en":["Sit on the floor with your legs extended in front of you.","Lean back slightly and lift your legs off the ground, keeping them straight.","Simultaneously, lift your upper body off the ground and reach your arms towards your legs.","Hold this position for a few seconds, then slowly lower your upper body and legs back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/3420-ZuXu4Eq.jpg","gif_url":"videos/3420-ZuXu4Eq.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0826","name":"vertical leg raise (on parallel bars)","category":"waist","equipment":"body weight","instruction_steps":{"en":["Hang from the parallel bars with your arms fully extended and your body straight.","Engage your core and lift your legs up in front of you, keeping them straight.","Continue lifting until your legs are parallel to the ground or slightly higher.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors"],"target":"abs","image":"images/0826-ZNgOYQU.jpg","gif_url":"videos/0826-ZNgOYQU.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2141","name":"walk elliptical cross trainer","category":"cardio","equipment":"elliptical machine","instruction_steps":{"en":["Adjust the resistance level and incline of the elliptical machine to your desired settings.","Step onto the pedals of the machine and grip the handles lightly.","Begin by pushing down with your feet and pulling the handles towards your body.","Continue this motion, alternating between pushing and pulling, to simulate a walking or running motion.","Maintain a steady pace and keep your core engaged throughout the exercise.","Continue for the desired duration of your cardio workout.","Gradually decrease the intensity and speed of the machine before stepping off."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","glutes","calves"],"target":"cardiovascular system","image":"images/2141-rjtuP6X.jpg","gif_url":"videos/2141-rjtuP6X.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3655","name":"walking high knees lunge","category":"cardio","equipment":"body weight","instruction_steps":{"en":["Stand with your feet hip-width apart.","Lift your right knee up towards your chest as high as you can while balancing on your left leg.","Step forward with your right foot and lower your body into a lunge position, bending both knees to a 90-degree angle.","Push off with your right foot and bring your left knee up towards your chest.","Step forward with your left foot and lower your body into a lunge position.","Continue alternating legs and lunging forward, keeping your core engaged and maintaining a steady pace.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","glutes","calves"],"target":"cardiovascular system","image":"images/3655-J9zIWig.jpg","gif_url":"videos/3655-J9zIWig.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1460","name":"walking lunge","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Stand with your feet shoulder-width apart.","Take a step forward with your right leg, lowering your body into a lunge position.","Keep your torso upright and your front knee aligned with your ankle.","Push off with your right foot and bring your left foot forward, stepping into a lunge position with your left leg.","Continue alternating legs and walking forward, maintaining a controlled and steady pace.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/1460-IZVHb27.jpg","gif_url":"videos/1460-IZVHb27.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3666","name":"walking on incline treadmill","category":"cardio","equipment":"leverage machine","instruction_steps":{"en":["Adjust the incline level on the treadmill to your desired intensity.","Stand on the treadmill with your feet shoulder-width apart.","Start walking at a comfortable pace, ensuring that you maintain proper form.","Engage your core muscles and keep your back straight throughout the exercise.","Continue walking on the incline treadmill for the desired duration of your cardio workout.","Gradually decrease the incline and speed of the treadmill to cool down before stopping."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"cardiovascular system","image":"images/3666-rjiM4L3.jpg","gif_url":"videos/3666-rjiM4L3.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2311","name":"walking on stepmill","category":"cardio","equipment":"stepmill machine","instruction_steps":{"en":["Adjust the stepmill machine to a comfortable level.","Step onto the machine and place your hands on the handrails for support.","Start walking by placing one foot on a step and then the other, alternating between legs.","Maintain an upright posture and engage your core muscles.","Continue walking for the desired duration or distance.","Gradually increase the intensity or speed as you become more comfortable with the exercise.","Remember to cool down and stretch after completing the exercise."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","glutes","calves"],"target":"cardiovascular system","image":"images/2311-j9Q5crt.jpg","gif_url":"videos/2311-j9Q5crt.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0830","name":"weighted bench dip","category":"upper arms","equipment":"weighted","instruction_steps":{"en":["Sit on a bench with your hands gripping the edge, fingers pointing forward.","Slide your butt off the bench, supporting your weight with your hands.","Lower your body by bending your elbows until your upper arms are parallel to the floor.","Push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/0830-MU9HnE7.jpg","gif_url":"videos/0830-MU9HnE7.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2987","name":"weighted close grip chin-up on dip cage","category":"back","equipment":"weighted","instruction_steps":{"en":["Stand in front of the dip cage and grab the parallel bars with an underhand grip, hands shoulder-width apart.","Hang from the bars with your arms fully extended, feet off the ground, and body straight.","Engage your back muscles and pull your body up towards the bars, keeping your elbows close to your sides.","Continue pulling until your chin is above the bars, then pause for a moment.","Slowly lower your body back down to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/2987-Gk1r408.jpg","gif_url":"videos/2987-Gk1r408.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3643","name":"weighted cossack squats (male)","category":"upper legs","equipment":"weighted","instruction_steps":{"en":["Stand with your feet wider than shoulder-width apart and toes pointing slightly outward.","Hold a weight in front of your chest with both hands.","Shift your weight to one side and lower your body by bending the knee of the side you shifted towards, while keeping the other leg straight.","Go as low as you can while maintaining balance and keeping your chest up.","Push through the heel of the bent leg to return to the starting position.","Repeat on the other side, alternating between legs."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/3643-GWoKnIm.jpg","gif_url":"videos/3643-GWoKnIm.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0832","name":"weighted crunch","category":"waist","equipment":"weighted","instruction_steps":{"en":["Lie flat on your back with your knees bent and feet flat on the ground.","Hold a weight plate or dumbbell on your chest.","Engage your abs and lift your upper body off the ground, curling forward until your shoulder blades are off the ground.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques"],"target":"abs","image":"images/0832-s8nrDXF.jpg","gif_url":"videos/0832-s8nrDXF.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3670","name":"weighted decline sit-up","category":"waist","equipment":"weighted","instruction_steps":{"en":["Lie flat on a decline bench with your feet secured under the foot pads.","Place your hands behind your head or across your chest.","Engage your abs and slowly lift your upper body off the bench, curling forward until your torso is perpendicular to the ground.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors","lower back"],"target":"abs","image":"images/3670-EZeDVzO.jpg","gif_url":"videos/3670-EZeDVzO.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0833","name":"weighted donkey calf raise","category":"lower legs","equipment":"weighted","instruction_steps":{"en":["Stand on a raised platform with your toes on the edge and your heels hanging off.","Hold onto a stable object for support.","Raise your heels as high as possible by extending your ankles.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hamstrings","secondary_muscles":["hamstrings","glutes"],"target":"calves","image":"images/0833-LmaFNZS.jpg","gif_url":"videos/0833-LmaFNZS.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1310","name":"weighted drop push up","category":"chest","equipment":"weighted","instruction_steps":{"en":["Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together.","Lower your chest towards the ground, keeping your elbows close to your body.","Once your chest is just above the ground, explosively push yourself up, lifting your hands off the ground.","As you push up, quickly move your hands out to the sides and slightly forward, allowing your body to drop down towards the ground.","Catch yourself with your hands in the wider position and immediately lower your chest towards the ground again.","Repeat the push-up motion, dropping down and catching yourself with your hands in the narrower position.","Continue alternating between the wider and narrower hand positions for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1310-PSlvNMs.jpg","gif_url":"videos/1310-PSlvNMs.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2135","name":"weighted front plank","category":"waist","equipment":"weighted","instruction_steps":{"en":["Start by lying face down on the floor.","Place your forearms on the ground, with your elbows directly under your shoulders.","Extend your legs straight out behind you, with your toes on the ground.","Engage your core and lift your body off the ground, balancing on your forearms and toes.","Keep your body in a straight line from your head to your heels.","Hold this position for the desired amount of time.","Lower your body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","lower back"],"target":"abs","image":"images/2135-VBAWRPG.jpg","gif_url":"videos/2135-VBAWRPG.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0834","name":"weighted front raise","category":"shoulders","equipment":"weighted","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your thighs.","Keeping your arms straight, exhale and lift the dumbbells in front of you until they are at shoulder level.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"delts","image":"images/0834-e4aFmFY.jpg","gif_url":"videos/0834-e4aFmFY.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0866","name":"weighted hanging leg-hip raise","category":"waist","equipment":"weighted","instruction_steps":{"en":["Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Engage your core and lift your legs up in front of you, keeping them straight.","Continue lifting until your legs are parallel to the ground or slightly higher.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"hip flexors","secondary_muscles":["hip flexors","lower back"],"target":"abs","image":"images/0866-QOA0FD0.jpg","gif_url":"videos/0866-QOA0FD0.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0835","name":"weighted hyperextension (on stability ball)","category":"back","equipment":"weighted","instruction_steps":{"en":["Position yourself face down on a stability ball with your hips resting on the ball and your feet against a wall for stability.","Place your hands behind your head or cross them over your chest.","Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","hamstrings"],"target":"spine","image":"images/0835-8urJS9b.jpg","gif_url":"videos/0835-8urJS9b.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3641","name":"weighted kneeling step with swing","category":"shoulders","equipment":"weighted","instruction_steps":{"en":["Start in a kneeling position with your knees hip-width apart and your back straight.","Hold a weight in each hand, with your arms extended straight down in front of you.","Engage your core and swing the weights up and overhead, keeping your arms straight.","Lower the weights back down to the starting position and repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","core"],"target":"delts","image":"images/3641-7uFJuXp.jpg","gif_url":"videos/3641-7uFJuXp.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3644","name":"weighted lunge with swing","category":"upper legs","equipment":"weighted","instruction_steps":{"en":["Stand with your feet shoulder-width apart, holding a weight in each hand.","Take a step forward with your right foot, lowering your body into a lunge position.","As you lunge forward, swing the weights forward and upward, keeping your arms straight.","Push off with your right foot and return to the starting position, swinging the weights back down.","Repeat with your left foot and continue alternating legs for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/3644-5WiFcYk.jpg","gif_url":"videos/3644-5WiFcYk.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3286","name":"weighted muscle up","category":"back","equipment":"weighted","instruction_steps":{"en":["Start by hanging from a pull-up bar with your palms facing away from you and your hands slightly wider than shoulder-width apart.","Engage your core and pull your body up towards the bar, leading with your chest.","As you reach the top of the movement, transition your grip so that your palms are facing towards you.","Continue pulling yourself up until your chest reaches the bar, then pause for a moment.","Slowly lower yourself back down to the starting position, maintaining control throughout the movement.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","triceps","shoulders","chest"],"target":"lats","image":"images/3286-JsOV1SU.jpg","gif_url":"videos/3286-JsOV1SU.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3312","name":"weighted muscle up (on bar)","category":"back","equipment":"weighted","instruction_steps":{"en":["Start by hanging from a pull-up bar with your palms facing away from you and your hands slightly wider than shoulder-width apart.","Engage your core and pull your shoulder blades down and back.","Bend your elbows and pull your chest towards the bar, keeping your body straight.","Once your chest reaches the bar, push down with your hands and drive your elbows back, lifting your body above the bar.","Pause at the top of the movement, then slowly lower yourself back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","triceps","shoulders","forearms"],"target":"lats","image":"images/3312-MCkqdKE.jpg","gif_url":"videos/3312-MCkqdKE.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3290","name":"weighted one hand pull up","category":"back","equipment":"weighted","instruction_steps":{"en":["Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Hang from the bar with your arm fully extended and your body straight.","Engage your core and pull your body up towards the bar by bending your elbow and squeezing your back muscles.","Continue pulling until your chin is above the bar.","Lower your body back down to the starting position with control.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/3290-fXfqg1E.jpg","gif_url":"videos/3290-fXfqg1E.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0840","name":"weighted overhead crunch (on stability ball)","category":"waist","equipment":"weighted","instruction_steps":{"en":["Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold a weight plate or dumbbell with both hands and extend your arms overhead.","Engage your abs and slowly curl your torso forward, bringing your chest towards your knees.","Pause for a moment at the top, then slowly lower your torso back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques","lower back"],"target":"abs","image":"images/0840-xmM75XG.jpg","gif_url":"videos/0840-xmM75XG.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0841","name":"weighted pull-up","category":"back","equipment":"weighted","instruction_steps":{"en":["Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your body straight.","Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/0841-HMzLjXx.jpg","gif_url":"videos/0841-HMzLjXx.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0844","name":"weighted round arm","category":"shoulders","equipment":"weighted","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Raise your arms out to the sides, keeping a slight bend in your elbows.","Continue lifting your arms until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","upper back"],"target":"delts","image":"images/0844-VLYXo8S.jpg","gif_url":"videos/0844-VLYXo8S.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0846","name":"weighted russian twist","category":"waist","equipment":"weighted","instruction_steps":{"en":["Sit on the ground with your knees bent and your feet flat on the floor.","Hold a weight or medicine ball with both hands in front of your chest.","Lean back slightly, keeping your back straight and your core engaged.","Slowly twist your torso to the right, bringing the weight or medicine ball towards the floor on your right side.","Pause for a moment, then twist your torso to the left, bringing the weight or medicine ball towards the floor on your left side.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques","lower back"],"target":"abs","image":"images/0846-fZFZ704.jpg","gif_url":"videos/0846-fZFZ704.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0845","name":"weighted russian twist (legs up)","category":"waist","equipment":"weighted","instruction_steps":{"en":["Sit on the ground with your knees bent and feet lifted off the ground, keeping your legs together.","Hold the weight with both hands in front of your chest, keeping your elbows slightly bent.","Lean back slightly to engage your core muscles.","Twist your torso to the right, bringing the weight towards the ground on your right side.","Pause for a moment, then twist your torso to the left, bringing the weight towards the ground on your left side.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques","hip flexors"],"target":"abs","image":"images/0845-WU9BLIs.jpg","gif_url":"videos/0845-WU9BLIs.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2371","name":"weighted russian twist v. 2","category":"waist","equipment":"weighted","instruction_steps":{"en":["Sit on the ground with your knees bent and feet flat on the floor.","Hold the weight with both hands in front of your chest.","Lean back slightly to engage your core muscles.","Twist your torso to the right, bringing the weight towards the right side of your body.","Pause for a moment, then twist your torso to the left, bringing the weight towards the left side of your body.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques","lower back"],"target":"abs","image":"images/2371-YIUAtYf.jpg","gif_url":"videos/2371-YIUAtYf.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0847","name":"weighted seated bicep curl (on stability ball)","category":"upper arms","equipment":"medicine ball","instruction_steps":{"en":["Sit on a stability ball with your feet flat on the ground and your back straight.","Hold a medicine ball with an underhand grip, palms facing up, and let your arms hang down by your sides.","Keeping your upper arms stationary, exhale and curl the medicine ball up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the medicine ball back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0847-b4b6afT.jpg","gif_url":"videos/0847-b4b6afT.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0849","name":"weighted seated twist (on stability ball)","category":"waist","equipment":"weighted","instruction_steps":{"en":["Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold a weight plate or dumbbell with both hands close to your chest.","Engage your core and slowly rotate your torso to one side, keeping your hips stable.","Pause for a moment at the end of the rotation, then slowly return to the starting position.","Repeat the rotation to the other side.","Continue alternating sides for the desired number of repetitions."]},"muscle_group":"obliques","secondary_muscles":["obliques","lower back"],"target":"abs","image":"images/0849-s34Y4LR.jpg","gif_url":"videos/0849-s34Y4LR.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0850","name":"weighted side bend (on stability ball)","category":"waist","equipment":"weighted","instruction_steps":{"en":["Sit on a stability ball with your feet shoulder-width apart and flat on the ground.","Hold a weight in one hand and place your other hand on your hip.","Engage your core and slowly bend sideways towards the weighted side, keeping your back straight.","Pause for a moment at the bottom, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides."]},"muscle_group":"obliques","secondary_muscles":["obliques","lower back"],"target":"abs","image":"images/0850-6bOA1Oi.jpg","gif_url":"videos/0850-6bOA1Oi.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0851","name":"weighted sissy squat","category":"upper legs","equipment":"weighted","instruction_steps":{"en":["Stand with your feet shoulder-width apart and your toes pointing slightly outward.","Hold a weight in front of your chest with both hands, or place a barbell across your upper back.","Keeping your chest up and your core engaged, slowly lower your body down by bending at the knees and hips.","Continue lowering until your thighs are parallel to the ground or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"glutes","secondary_muscles":["glutes","hamstrings","calves"],"target":"quads","image":"images/0851-0lQnxMZ.jpg","gif_url":"videos/0851-0lQnxMZ.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0852","name":"weighted squat","category":"upper legs","equipment":"weighted","instruction_steps":{"en":["Stand with your feet shoulder-width apart, toes pointing slightly outward.","Hold a weight in front of your chest or on your shoulders.","Engage your core and keep your chest up as you lower your hips down and back, as if sitting into a chair.","Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Push through your heels to stand back up, squeezing your glutes at the top.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/0852-JZuApnB.jpg","gif_url":"videos/0852-JZuApnB.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0853","name":"weighted standing curl","category":"upper arms","equipment":"weighted","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.","Keep your elbows close to your torso and exhale as you curl the weights up to shoulder level.","Pause for a moment at the top, then inhale as you slowly lower the weights back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"forearms","secondary_muscles":["forearms"],"target":"biceps","image":"images/0853-M5Y7GPg.jpg","gif_url":"videos/0853-M5Y7GPg.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0854","name":"weighted standing hand squeeze","category":"lower arms","equipment":"weighted","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold a weight in each hand.","Extend your arms straight in front of you, palms facing each other.","Squeeze your hands together as hard as you can, engaging your forearms.","Hold the squeeze for a few seconds, then release.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","triceps"],"target":"forearms","image":"images/0854-bjqbauy.jpg","gif_url":"videos/0854-bjqbauy.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3313","name":"weighted straight bar dip","category":"chest","equipment":"weighted","instruction_steps":{"en":["Position yourself between parallel bars with your arms fully extended and your body straight.","Lower your body by bending your elbows until your upper arms are parallel to the ground.","Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/3313-Ff18ItA.jpg","gif_url":"videos/3313-Ff18ItA.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3642","name":"weighted stretch lunge","category":"upper legs","equipment":"weighted","instruction_steps":{"en":["Stand with your feet shoulder-width apart.","Take a step forward with your right foot, keeping your back straight.","Lower your body by bending your knees until your right thigh is parallel to the ground.","Push through your right heel to return to the starting position.","Repeat with your left leg.","Continue alternating legs for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"glutes","image":"images/3642-13VW2VO.jpg","gif_url":"videos/3642-13VW2VO.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0856","name":"weighted svend press","category":"chest","equipment":"weighted","instruction_steps":{"en":["Stand with your feet shoulder-width apart and hold a weight plate in front of your chest with both hands.","Keep your elbows slightly bent and your palms facing each other.","Press the weight plate straight out in front of you, fully extending your arms.","Pause for a moment at the end of the movement, then slowly bring the weight plate back to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"shoulders","secondary_muscles":["shoulders","triceps"],"target":"pectorals","image":"images/0856-I1OBLnn.jpg","gif_url":"videos/0856-I1OBLnn.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1754","name":"weighted three bench dips","category":"upper arms","equipment":"weighted","instruction_steps":{"en":["Sit on the edge of a bench with your hands gripping the edge, fingers pointing forward.","Walk your feet forward, sliding your butt off the bench and supporting your weight with your arms.","Lower your body by bending your elbows, keeping your back close to the bench.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/1754-gtO1ErP.jpg","gif_url":"videos/1754-gtO1ErP.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1755","name":"weighted tricep dips","category":"upper arms","equipment":"weighted","instruction_steps":{"en":["Sit on the edge of a bench or chair with your hands gripping the edge next to your hips.","Slide your butt off the front of the bench with your legs extended in front of you.","Keep your back close to the bench and your elbows slightly bent.","Lower your body by bending your elbows until your upper arms are parallel to the floor.","Push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/1755-bZq4bwK.jpg","gif_url":"videos/1755-bZq4bwK.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1767","name":"weighted triceps dip on high parallel bars","category":"upper arms","equipment":"weighted","instruction_steps":{"en":["Position yourself between two parallel bars with your hands gripping the bars and your arms fully extended.","Bend your elbows and lower your body until your upper arms are parallel to the ground.","Pause for a moment, then push through your palms to straighten your arms and return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"chest","secondary_muscles":["chest","shoulders"],"target":"triceps","image":"images/1767-K1vlode.jpg","gif_url":"videos/1767-K1vlode.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0857","name":"wheel rollerout","category":"waist","equipment":"wheel roller","instruction_steps":{"en":["Kneel on the floor and place the wheel roller in front of you.","Place your hands on the handles of the wheel roller and extend your arms straight out in front of you.","Engage your core muscles and slowly roll the wheel forward, keeping your back straight and your abs tight.","Continue rolling forward until your body is fully extended and your arms are overhead.","Pause for a moment, then slowly roll the wheel back towards your knees, maintaining control and keeping your abs engaged.","Repeat for the desired number of repetitions."]},"muscle_group":"lower back","secondary_muscles":["lower back"],"target":"abs","image":"images/0857-NAgVB3t.jpg","gif_url":"videos/0857-NAgVB3t.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"3637","name":"wheel run","category":"cardio","equipment":"body weight","instruction_steps":{"en":["Start in a plank position with your hands on the wheel and your body straight.","Engage your core and start rolling the wheel forward by extending your arms.","Continue rolling until your body is fully extended and your arms are overhead.","Reverse the movement by pulling the wheel back towards your body, using your core and arms.","Repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"cardiovascular system","image":"images/3637-km2Ljzj.jpg","gif_url":"videos/3637-km2Ljzj.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1429","name":"wide grip pull-up","category":"back","equipment":"body weight","instruction_steps":{"en":["Hang from a pull-up bar with your palms facing away from you and your hands wider than shoulder-width apart.","Engage your core and squeeze your shoulder blades together.","Pull your body up towards the bar until your chin is above the bar.","Lower your body back down to the starting position with control.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/1429-Qqi7bko.jpg","gif_url":"videos/1429-Qqi7bko.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1367","name":"wide grip rear pull-up","category":"back","equipment":"body weight","instruction_steps":{"en":["Grab the pull-up bar with a wide overhand grip, hands slightly wider than shoulder-width apart.","Hang from the bar with your arms fully extended and your body straight.","Engage your back muscles and pull your body up towards the bar, leading with your chest.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","forearms"],"target":"lats","image":"images/1367-OYFhXVD.jpg","gif_url":"videos/1367-OYFhXVD.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1311","name":"wide hand push up","category":"chest","equipment":"body weight","instruction_steps":{"en":["Start in a high plank position with your hands wider than shoulder-width apart.","Keep your body in a straight line from head to toe.","Lower your chest towards the ground by bending your elbows, keeping them close to your sides.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/1311-JmMVpR3.jpg","gif_url":"videos/1311-JmMVpR3.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"2363","name":"wide-grip chest dip on high parallel bars","category":"chest","equipment":"body weight","instruction_steps":{"en":["Position yourself on the parallel bars with your arms fully extended and your body suspended in the air.","Lean forward slightly and lower your body by bending your elbows until your chest is just above the bars.","Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]},"muscle_group":"triceps","secondary_muscles":["triceps","shoulders"],"target":"pectorals","image":"images/2363-O2K9Vb5.jpg","gif_url":"videos/2363-O2K9Vb5.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0858","name":"wind sprints","category":"waist","equipment":"body weight","instruction_steps":{"en":["Find an open space or a track to perform the exercise.","Start by standing with your feet shoulder-width apart.","Begin running as fast as you can, pumping your arms and driving your knees up.","Continue sprinting for a specific distance or time period.","Rest and repeat for the desired number of repetitions."]},"muscle_group":"quadriceps","secondary_muscles":["quadriceps","hamstrings","calves"],"target":"abs","image":"images/0858-Qoujh3Q.jpg","gif_url":"videos/0858-Qoujh3Q.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1604","name":"world greatest stretch","category":"upper legs","equipment":"body weight","instruction_steps":{"en":["Start in a lunge position with your right foot forward and your left foot back.","Place your hands on the ground on either side of your right foot.","Lower your left knee to the ground and extend your right leg, keeping your right foot flat on the ground.","Rotate your torso to the right, reaching your right arm up towards the ceiling.","Hold this position for a few seconds, then return to the starting position.","Switch sides and repeat the stretch with your left foot forward."]},"muscle_group":"glutes","secondary_muscles":["glutes","quadriceps","calves"],"target":"hamstrings","image":"images/1604-DFGXwZr.jpg","gif_url":"videos/1604-DFGXwZr.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"1428","name":"wrist circles","category":"lower arms","equipment":"body weight","instruction_steps":{"en":["Extend your arms straight out in front of you.","Make a fist with both hands.","Rotate your wrists in a circular motion, keeping your arms still.","Continue the wrist circles for the desired number of repetitions."]},"muscle_group":"hands","secondary_muscles":["hands","wrists"],"target":"forearms","image":"images/1428-2zNKRUB.jpg","gif_url":"videos/1428-2zNKRUB.gif","attribution":"© Gym visual — https://gymvisual.com/"},{"id":"0859","name":"wrist rollerer","category":"lower arms","equipment":"weighted","instruction_steps":{"en":["Attach a weight to one end of a rope or bar.","Hold the other end of the rope or bar with both hands, palms facing down.","Stand with your feet shoulder-width apart and your arms fully extended in front of you.","Slowly roll the weight up towards your hands by flexing your wrists.","Pause for a moment at the top, then slowly lower the weight back down to the starting position.","Repeat for the desired number of repetitions."]},"muscle_group":"biceps","secondary_muscles":["biceps","triceps"],"target":"forearms","image":"images/0859-bd5b860.jpg","gif_url":"videos/0859-bd5b860.gif","attribution":"© Gym visual — https://gymvisual.com/"}];

