  orange:{base:'#ff9f0a',rgb:'255,159,10',ink:'#131314'},
  purple:{base:'#bf5af2',rgb:'191,90,242',ink:'#ffffff'},
  pink:{base:'#ff375f',rgb:'255,55,95',ink:'#ffffff'}
